CARDIO.register({"item":"231","meta":{"num":231,"short":"ECG","title":"Électrocardiogramme","section":"III","chapter":15,"pages":"367-417","sdd":[{"num":4,"label":"Douleur abdominale"},{"num":21,"label":"Asthénie"},{"num":42,"label":"Hypertension artérielle"},{"num":43,"label":"Découverte d'une hypotension artérielle"},{"num":50,"label":"Malaise/perte de connaissance"},{"num":121,"label":"Déficit neurologique sensitif et/ou moteur"},{"num":159,"label":"Bradycardie"},{"num":160,"label":"Détresse respiratoire aiguë"},{"num":161,"label":"Douleur thoracique"},{"num":162,"label":"Dyspnée"},{"num":165,"label":"Palpitations"},{"num":166,"label":"Tachycardie"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":200,"label":"Dyscalcémie"},{"num":201,"label":"Dyskaliémie"},{"num":204,"label":"Élévation des enzymes cardiaques"},{"num":266,"label":"Consultation de suivi d'un patient polymédiqué"},{"num":287,"label":"Consultation de suivi et éducation thérapeutique d'un patient insuffisant cardiaque"}]},"objectives":[{"id":"231-obj-01","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités d'interprétation d'un ECG normal","desc":"Morphologies normales et paramètres numériques"},{"id":"231-obj-02","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes de gravité de l'ECG","desc":"Anomalies électrocardiographiques devant amener une réponse thérapeutique urgente"},{"id":"231-obj-03","rank":"B","rubric":"Diagnostic positif","title":"Identifier les hypertrophies atriales","desc":"Reconnaître formes droites et gauches"},{"id":"231-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Identifier les hypertrophies ventriculaires droites","desc":"Reconnaître les différents aspects y compris dans l'embolie pulmonaire"},{"id":"231-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Identifier les hypertrophies ventriculaires gauches","desc":"Reconnaître les deux formes principales"},{"id":"231-obj-06","rank":"A","rubric":"Diagnostic positif","title":"Identifier les blocs complets de branche, les hémiblocs et les blocs bifasciculaires","desc":"Reconnaître BBD, BBG complets, HBAG, HBPG et associations"},{"id":"231-obj-07","rank":"B","rubric":"Diagnostic positif","title":"Identifier les blocs incomplets de branche et les blocs fonctionnels","desc":"Reconnaître le BBD ou le BBG incomplet, les aberrations de conduction"},{"id":"231-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Identifier les blocs atrioventriculaires en rythme sinusal","desc":"Reconnaître les BAV de 3e degré et de tous types, blocs de haut degré et blocs rythmés"},{"id":"231-obj-09","rank":"B","rubric":"Diagnostic positif","title":"Identifier les blocs atrioventriculaires associés aux troubles du rythme","desc":"Reconnaître les BAV du 3e degré associés à la FA ou aux flutters"},{"id":"231-obj-10","rank":"A","rubric":"Diagnostic positif","title":"Identifier la dysfonction sinusale","desc":"Reconnaître une dysfonction sinusale"},{"id":"231-obj-11","rank":"B","rubric":"Diagnostic positif","title":"Connaître les mécanismes et les variantes de dysfonction sinusale","desc":"BSA du 2e degré et maladie de l'oreillette"},{"id":"231-obj-12","rank":"A","rubric":"Diagnostic positif","title":"Savoir différencier une tachycardie sinusale d'une tachycardie supraventriculaire non sinusale","desc":"Savoir faire le diagnostic positif et différencier tachycardie sinusale et troubles du rythme supraventriculaire"},{"id":"231-obj-13","rank":"A","rubric":"Diagnostic positif","title":"Identifier la fibrillation atriale","desc":""},{"id":"231-obj-14","rank":"A","rubric":"Diagnostic positif","title":"Identifier les flutters atriaux","desc":"Reconnaître un flutter atrial"},{"id":"231-obj-15","rank":"A","rubric":"Diagnostic positif","title":"Tachycardies jonctionnelles","desc":""},{"id":"231-obj-16","rank":"B","rubric":"Diagnostic positif","title":"Connaître l'intérêt des manœuvres vagales dans les troubles du rythme","desc":"Réalisation et apport des manœuvres vagales et médicaments purinergiques"},{"id":"231-obj-17","rank":"A","rubric":"Diagnostic positif","title":"Identifier les extrasystoles","desc":"Reconnaître une extrasystole atriale ou ventriculaire"},{"id":"231-obj-18","rank":"A","rubric":"Diagnostic positif","title":"Identifier la tachycardie ventriculaire","desc":"Reconnaître une TV"},{"id":"231-obj-19","rank":"A","rubric":"Diagnostic positif","title":"Identifier la fibrillation ventriculaire","desc":"Reconnaître une FV"},{"id":"231-obj-20","rank":"B","rubric":"Diagnostic positif","title":"Identifier les torsades de pointes","desc":"Reconnaître une torsade de pointes et un allongement de QT hors hypokaliémie"},{"id":"231-obj-21","rank":"A","rubric":"Diagnostic positif","title":"Identifier les dyskaliémies","desc":"Reconnaître les anomalies ECG des dyskaliémies y compris QT long"},{"id":"231-obj-22","rank":"A","rubric":"Diagnostic positif","title":"Identifier l'allongement de QT","desc":"Médicamenteuse, congénitale, ionique, etc."},{"id":"231-obj-23","rank":"B","rubric":"Diagnostic positif","title":"Identifier les péricardites aiguës","desc":"Différences ECG entre péricardites aiguës et syndromes coronariens aigus"},{"id":"231-obj-24","rank":"A","rubric":"Diagnostic positif","title":"Identifier la maladie coronarienne et les syndromes coronariens aigus","desc":"Ondes Q, territoires, anomalies du segment ST et de l'onde T, séquelles"},{"id":"231-obj-25","rank":"B","rubric":"Diagnostic positif","title":"Identifier le Wolff-Parkinson-White","desc":""},{"id":"231-obj-26","rank":"B","rubric":"Diagnostic positif","title":"Identifier la présence d'un électroentraînement atrial, ventriculaire ou séquentiel","desc":"Savoir reconnaître la présence d'un électroentraînement atrial, ventriculaire ou séquentiel"},{"id":"231-obj-27","rank":"A","rubric":"Diagnostic positif","title":"Connaître les indications d'un ECG","desc":"Principales indications des cardioscopes et des ECG de repos (12-15 ou 18 dérivations) ; indications en urgence : défaillance(s) d'organe(s), douleur thoracique, palpitations, syncope, troubles hydroélectrolytiques (K, Ca) ; savoir réaliser un ECG 12 dérivations"},{"id":"231-obj-28","rank":"B","rubric":"Examens complémentaires","title":"Connaître la méthode Holter","desc":"Indications des enregistrements externes de longue durée"}],"course":{"sections":[{"id":"231-sec-01","title":"Conduction et genèse du signal ECG","rank":"A","objectives":["231-obj-01"],"content":"### Conduction atrioventriculaire\n- Physiologiquement, le **NAV est le seul passage électrique** entre oreillettes et ventricules : le reste du plan de l'anneau isole totalement l'oreillette du ventricule [B].\n- QRS **fins** quand l'influx emprunte les voies de conduction ; QRS **larges** quand il chemine **de proche en proche** (bloc de branche, stimulation ventriculaire, tachycardie ventriculaire).\n\n### Rythmes d'échappement\n- Dysfonction sinusale marquée : **échappement jonctionnel** (onde P absente devant le QRS, parfois rétrograde).\n- BAV complet : rythme d'échappement automatique, **lent et régulier** ; à **QRS fins** il traduit un bloc **nodal** (suprahissien), à QRS larges un bloc **bas situé**.\n\n### Électrogenèse\n- L'ECG enregistre sur le thorax la **somme des potentiels d'action** suivant un front de dépolarisation : **P** (oreillettes) puis **QRS** (ventricules) ; **T** = repolarisation graduelle.\n- Dépolarisation **vers** l'électrode → **positive** ; s'en **éloignant** → **négative** ; perpendiculaire → **isodiphasique** (positive puis négative).\n- T est **concordante** au QRS sur l'ECG normal, car la dépolarisation ventriculaire va de l'endocarde vers l'épicarde et la repolarisation en sens inverse.","keyPoints":["Le NAV est le seul passage physiologique entre oreillettes et ventricules (le reste du plan de l'anneau est isolant).","QRS fins = influx passant par les voies de conduction ; QRS larges = conduction de proche en proche (bloc de branche, stimulation ventriculaire, TV).","Front de dépolarisation vers l'électrode = onde positive ; s'en éloignant = onde négative.","Ondes T normalement concordantes aux QRS (dépolarisation endocarde → épicarde, repolarisation en sens inverse).","Échappement à QRS fins = bloc nodal (suprahissien) ; à QRS larges = bloc bas situé."],"pitfalls":["Une onde T de même polarité que le QRS est normale (concordance) : ne pas la prendre pour une anomalie."],"src":"p. 371, 387-388, 392, 398, 404, 410, 414"},{"id":"231-sec-02","title":"Dérivations, territoires et axe du QRS","rank":"A","objectives":["231-obj-01","231-obj-27"],"content":"### Dérivations\n- **Frontales** (plan vertical) : D1, D2, D3 (I, II, III) obtenues à partir des membres, complétées par les unipolaires **aVR, aVL, aVF**.\n- **Précordiales** (plan horizontal) : **V1 à V9**, complétées par **V3R et V4R** chez l'enfant ou en cas de suspicion de SCA.\n- Placement : électrodes précordiales **équidistantes**.\n\n> **Piège de pose** : V1 et V2 sont trop souvent placées trop haut et trop écartées (confusion avec les foyers auscultatoires aortique et pulmonaire) → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.\n\n- **Dérivations de Lewis** : pour démasquer une activité atriale peu visible. Électrode rouge (bras droit) sur la fourchette sternale, électrode jaune (bras gauche) au 5e espace intercostal droit ; l'activité atriale est alors bien lue en **D1**.\n\n### Territoires explorés (utiles à la localisation des infarctus)\n| Territoire | Dérivations | Paroi |\n|---|---|---|\n| Antéroseptal | V1, V2, V3 | paroi antérieure du VG et septum |\n| Apical | V4 | apex |\n| Latéral haut | D1, aVL | paroi latérale |\n| Latéral bas | V5, V6 | paroi latérale |\n| Inférieur (diaphragmatique) | D2, D3, aVF | face inférieure du VG |\n| Postérieur | V7, V8, V9 | face basale et inférieure du VG |\n| Ventricule droit | V1, V2, V3R, V4R | VD |\n\n### Axe du QRS\n- Mesuré dans le plan frontal sur le **double triaxe de Bailey** : dérivations graduées de 30° en 30° dans le sens horaire, D1 à l'horizontale (0°).\n- Méthode rapide par la polarité de D1 et aVF :\n\n| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si D2 positif (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n- **Axe normal : –30° à +90°** (de aVL à aVF ; valeurs théoriques –45° à +110°).\n- Variations anatomiques : cœur **vertical** du sujet filiforme → axe proche de 90° ; cœur **horizontal** de l'obèse ou de la cardiomégalie → axe proche de 0°.\n- Axe anormal en cas d'**hémibloc** gauche ou d'anomalie morphologique marquée d'un ventricule.\n- Onde **isodiphasique** : composantes positive et négative d'égale importance (aspect sinusoïdal).","keyPoints":["Frontales D1-D2-D3 + aVR-aVL-aVF ; précordiales V1–V9 (+ V3R, V4R pour le VD).","Antéroseptal V1-V3, apical V4, latéral D1-aVL (haut) et V5-V6 (bas), inférieur D2-D3-aVF, postérieur V7-V9.","Axe normal du QRS : –30° à +90° ; D1+ et aVF+ = axe normal.","D1+ aVF– : normal si D2 positif, hypergauche sinon ; D1– aVF+ = hyperdroit.","Dérivations de Lewis : mieux voir l'activité atriale en D1."],"pitfalls":["V1-V2 posées trop haut → pseudonécrose antérieure ou repolarisation atypique.","Un D1 négatif fait d'abord évoquer une inversion des électrodes des bras (P alors négative en D1)."],"src":"p. 371-375"},{"id":"231-sec-03","title":"ECG normal : valeurs de référence et lecture systématique","rank":"A","objectives":["231-obj-01"],"content":"### Étalonnage\n- Vitesse **25 mm/s** : 1 mm = **40 ms**, un grand carreau (5 mm) = **200 ms**. Amplitude : 1 mm = **0,1 mV**.\n\n### Valeurs normales\n| Paramètre | Normale |\n|---|---|\n| Fréquence cardiaque | 60–100 bpm |\n| Durée de P | < 120 ms (théorique < 110 ms) |\n| Axe de P | 60° (maximum en D2) |\n| Amplitude de P | < 2,5 mm en D2 |\n| PR (début P → début QRS) | 120–200 ms inclus |\n| Durée QRS | 70–110 ms |\n| Axe QRS | –30° à +90° |\n| Onde Q physiologique | < 1/3 du QRS et < 40 ms |\n| QT corrigé | < 450 ms à 60 bpm (en pratique 470–480 ms) |\n\n### Rythme sinusal\n- Le nœud sinusal est en haut à droite de l'OD : activation atriale de haut à droite vers bas à gauche → P **positive en D1 et en inférieur**.\n- Rythme sinusal = chaque P suivie d'un QRS **et** chaque QRS précédé d'une P. Des P sinusales régulières non conduites (BAV3) ne sont **plus** un rythme sinusal.\n- Le rythme peut naître de tout étage (atrial, jonctionnel, ventriculaire) ou être électroentraîné.\n- Bradycardie < 60 bpm, tachycardie > 100 bpm (valeurs de l'adulte, attention au nouveau-né). Bradycardie sinusale physiologique de l'athlète (tonus vagal) ; variation respiratoire chez le jeune.\n- FC = 60 / RR (s) ; en pratique FC = **300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…).\n\n### Genèse du QRS [B]\nTrois phases : septale (avant, droite, haut → petite **q** latérale et petit **r** en V1), puis vers la jambe gauche et l'avant (grande **R** en V3-V4 et D2), puis vers le haut et l'arrière (petite **S** inférieure et latérale) : d'où le caractère polyphasique.\n\n### PR et QT\n- Le **PR** explore toute la conduction, de la sortie du nœud sinusal au réseau de Purkinje, pas seulement le NAV.\n- **QT** : du début de Q à la fin de T, mesuré dans la dérivation où T est la plus ample et la plus longue (souvent V2-V3), par la **tangente** à l'onde T. Ne jamais inclure une **onde U**.\n- **Bazett** : QTc = QT mesuré / √RR (RR en secondes) → une seule norme, celle de 60 bpm (RR = 1 s).\n\n### Affirmer qu'un ECG est normal : être systématique\n1. **Rythme** : sinusal (P + en D1, D2, un QRS après chaque P, une P avant chaque QRS), 60–100 bpm.\n2. **Conduction** : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe –30° à +90° (positif en D1 et D2).\n3. **Repolarisation** : point J (fin du QRS) et ST isoélectriques ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale de V1 à V6 (R croît, S décroît — vérifie aussi la bonne pose des électrodes), pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n> Chez le jeune, surtout l'homme, un point J sus-décalé de V1 à V4 avec ST jonctionnel ascendant est une **repolarisation physiologique**.","keyPoints":["25 mm/s : 1 mm = 40 ms, grand carreau = 200 ms ; 1 mm = 0,1 mV.","FC 60–100, P < 120 ms, PR 120–200 ms, QRS 70–110 ms, axe –30/+90°, QTc < 450 ms.","Rythme sinusal : P positive en D1 et en inférieur, une P par QRS et un QRS par P.","FC = 300 / nombre de grands carreaux entre deux QRS.","QTc de Bazett = QT / √RR ; mesure par la tangente, en V2-V3, sans l'onde U.","Lecture systématique : rythme, conduction, repolarisation, morphologie.","T normalement négatives possibles en aVR, V1, parfois D3 et aVL."],"pitfalls":["Des P régulières sans conduction (BAV3) ne définissent pas un rythme sinusal.","Inclure l'onde U dans le QT le surestime.","Point J sus-décalé V1–V4 chez le jeune homme : repolarisation physiologique, pas un SCA."],"src":"p. 375-378"},{"id":"231-sec-04","title":"Blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","objectives":["231-obj-06","231-obj-07"],"content":"Un bloc de branche = interruption ou ralentissement marqué de la conduction dans une branche. **Toujours décrire d'abord le rythme atrial** : l'association TSV + bloc de branche n'est pas rare.\n\n### Blocs complets (QRS > 120 ms)\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | QRS globalement **positif**, aspect **RsR'** | QRS globalement **négatif**, aspect **rS ou QS** |\n| V6 (et D1, aVL pour le BBG) | **qRs** avec S traînante, arrondie | **notch** (double pic : septum puis paroi latérale tardive), R souvent exclusive |\n\nOrdre de lecture : rythme sinusal ? → QRS > 120 ms ? → V1 positif (BBD probable) ou négatif (BBG probable) → aspect inverse en V6.\n\n### Discordance appropriée\nQRS larges → trouble de repolarisation secondaire : T **discordante** du QRS. QRS négatif → T positive avec petit sus-ST ; QRS positif → T négative avec petit sous-ST. Dans le BBG, le ST ascendant en V1-V2 peut mimer un SCA ST+.\n\n> Douleur thoracique persistante + BBG : évoquer l'**infarctus antérieur** et obtenir une évaluation cardiologique rapide **sans attendre la troponine** (sémiologie de la douleur, effet de la TNT, signes de choc, ETT).\n\n### Blocs incomplets et fonctionnels [B]\n- Incomplets : mêmes anomalies avec QRS **110–120 ms**, faible intérêt sémiologique.\n- Fonctionnel : bloc n'existant qu'à partir d'une fréquence donnée — apparition d'un BBG ou d'un BBD lors d'une **tachycardie** ou d'une **bradycardie**.\n\n### Hémiblocs (blocs fasciculaires)\n- QRS peu élargi (**> 110 ms**, > 120 ms si bloc de branche associé ou cardiopathie marquée) + **déviation axiale**.\n- **HBAG** : axe au-delà de **–30°** (D2 négatif). **Fréquent** : branche superficielle et fine.\n- **HBPG** : axe > **+90°** (D1 négatif, aspect S1Q3) en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral. **Rare** : branche profonde.\n\n> D1 négatif : penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1) avant l'HBPG.\n\n### Blocs bifasciculaires\nSémiologie additive : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n\n### Pourquoi diagnostiquer les blocs ? [B]\n- Hémibloc isolé ou bloc incomplet : atteinte débutante, risque de BAV infrahissien faible.\n- Bloc bifasciculaire (BBG complet, ou BBD + hémibloc) : risque de BAV complet infrahissien intermittent (syncope, mort subite). **Syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie.**\n- BBG complet → **désynchronisation** du VG pouvant créer ou aggraver une cardiopathie ; sa correction est indiquée si insuffisance cardiaque.","keyPoints":["Bloc complet : QRS > 120 ms ; V1 positif (RsR') = BBD, V1 négatif (rS/QS, notch latéral) = BBG.","Discordance appropriée : avec un QRS large, T et ST s'inversent par rapport au QRS.","BBG + douleur thoracique persistante : suspecter un infarctus antérieur sans attendre la troponine.","Hémibloc = QRS > 110 ms + déviation axiale : HBAG < –30° (fréquent), HBPG > +90° (rare).","Bifasciculaire = HBAG ou HBPG + BBD (QRS > 120 ms).","Syncope + bloc bifasciculaire = hospitalisation avec télémétrie (risque de BAV infrahissien).","BBG complet : désynchronisation du VG pouvant aggraver une cardiopathie (correction si insuffisance cardiaque)."],"pitfalls":["Décrire un bloc de branche sans avoir analysé le rythme atrial (TSV + bloc fréquents).","Prendre la discordance appropriée du BBG pour un sus-décalage ischémique.","Conclure à un HBPG devant un D1 négatif sans vérifier l'inversion des électrodes.","Les blocs de branche ne donnent pas de bradycardie."],"src":"p. 378-383"},{"id":"231-sec-05","title":"Blocs atrioventriculaires, dysfonction sinusale et bradycardie","rank":"A","objectives":["231-obj-08","231-obj-10","231-obj-11"],"content":"### Sémiologie des BAV (détail au chapitre 14)\nDans un BAV, les ondes P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| BAV2 Mobitz 1 (Luciani-Wenckebach) | PR s'allonge progressivement puis une P est bloquée | suprahissien |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| BAV2 Mobitz 2 | PR constant puis P bloquée inopinée | infrahissien |\n| BAV3 | dissociation atrioventriculaire complète, P dissociées (bien vues en V1) | échappement à QRS fins = bloc nodal (suprahissien) |\n\n> Une P « bloquée » plus précoce que les autres est en fait une **extrasystole atriale bloquée**.\n\n### Dysfonction sinusale\n- Cas simples : **asystole** (tracé plat) ; **pauses** par absence intermittente d'une onde P = **bloc sinoatrial du 2e degré** [B], la pause correspondant au double de l'intervalle PP (RR) normal, avec absence complète de P-QRS-T.\n- Dysfonction marquée : **échappement jonctionnel** ; P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2** (activation atriale de bas en haut).\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- Des T négatives dans toutes les précordiales sont pathologiques : éliminer d'abord une **ischémie**.\n\n### Algorithme devant une bradycardie (FC des QRS < 50 bpm)\nSeules deux structures défaillantes donnent une bradycardie : le nœud sinusal ou le NAV.\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale, ou activité atriale rapide (FA, flutter, TAF), avec **plus de P que de QRS** → le problème est le passage au ventricule → **BAV**.\n3. P **trop lentes ou absentes** → le problème est le nœud sinusal → **dysfonction sinusale**.","keyPoints":["BAV1 : PR > 200 ms constant. Mobitz 1 : PR croissant puis P bloquée (suprahissien). Mobitz 2 : PR fixe puis P bloquée (infrahissien).","BAV 2/1 : infrahissien si QRS larges, suprahissien si QRS fins avec Mobitz 1 ailleurs.","BAV3 : dissociation AV complète ; échappement à QRS fins = bloc nodal.","BSA du 2e degré : pause = 2 × PP, sans aucune onde P.","Échappement jonctionnel : pas de P avant le QRS, P' rétrograde négative en D2 possible.","Bradycardie : plus de P que de QRS = BAV ; P lentes ou absentes = dysfonction sinusale."],"pitfalls":["Dans le BAV les P restent régulières et à fréquence normale ; des P absentes orientent vers le nœud sinusal.","Une ESA bloquée peut simuler une onde P bloquée de BAV2."],"src":"p. 385-389"},{"id":"231-sec-06","title":"Tachycardies supraventriculaires : filtre du NAV, manœuvres vagales, tachycardie sinusale, FA","rank":"A","objectives":["231-obj-12","231-obj-13","231-obj-09","231-obj-16"],"content":"### Généralités\n- TSV = activation trop rapide des oreillettes ou de la jonction (NAV, His) ; au-delà de la bifurcation hissienne = trouble du rythme **ventriculaire**. Mécanismes : réentrée, hyperautomatisme, mécanismes complexes.\n- QRS **fins (< 120 ms)** le plus souvent ; larges si bloc de branche associé.\n- Sémantique : « trouble du rythme » = tachycardie ; les bradycardies sont des **troubles de la conduction**.\n\n### Filtre du NAV (conduction décrémentielle)\nAu-delà d'une certaine fréquence atriale, le ventricule ne suit plus en 1/1 : passage en 2/1, alternance 1/1-2/1 ou 2/1-3/1 (conduction variable) selon la fréquence atriale et l'intensité du filtre (âge, tonus vagal, ralentisseurs du NAV). Sans ce filtre, toute FA donnerait une FV et un flutter à 300 bpm une tachycardie ventriculaire à 300 bpm.\n\n### Créer un BAV transitoire [B]\n- **Manœuvres vagales** : Valsalva (expiration forcée à glotte fermée) ; compression carotidienne **unilatérale** (contre-indiquée si athérome important ou souffle carotidien) ; grand verre d'eau froide. La compression oculaire bilatérale n'est plus recommandée (décollement de rétine du myope).\n- **Adénosine IV** si échec : vagomimétique via les récepteurs purinergiques, en **flash IV**, effet d'une **dizaine de secondes**. Contre-indications : **asthme** (bronchospasme intense transitoire possible même chez le non asthmatique), **hypotension**, et FA préexcitée (super-Wolff).\n- Intérêt : diagnostic différentiel des tachycardies, réduction des tachycardies jonctionnelles.\n\n### Tachycardie sinusale vs TSV\n- P sinusales : positives en **D1, D2, D3 et aVF**.\n- FC **variable progressivement** (courbe de scope, télémétrie, holter, ou massage sinocarotidien) ; une TSV varie par **« marches d'escalier »**.\n- Contexte : au repos, une tachycardie marquée sans cause d'hypermétabolisme (fièvre, stress, douleur) n'est pas sinusale.\n\n### Fibrillation atriale\n- Activation atriale **anarchique** (état fibrillatoire). Tachycardie fréquente **100–200 bpm**, QRS **« irrégulièrement irréguliers »** (RR non multiples d'une valeur commune).\n- QRS fins sans bloc associé ; ligne de base : **mailles amples** ou **fine trémulation**. Manœuvres vagales si l'activité atriale est difficile à analyser.\n- Formes difficiles [B] :\n  - **FA + BAV complet** : rythme ventriculaire **lent et régulier** (échappement automatique) ;\n  - **maladie de l'oreillette** (maladie rythmique atriale, syndrome tachycardie-bradycardie) : alternance FA / bradycardie sinusale, **pauses de régularisation** à l'arrêt de la FA ;\n  - **FA + bloc de branche** (fréquent), préexistant ou fonctionnel : tachycardie **irrégulière à QRS larges**.","keyPoints":["TSV : QRS fins < 120 ms sauf bloc de branche associé.","Le NAV filtre (conduction décrémentielle) : 1/1, 2/1, conduction variable.","Manœuvres vagales : Valsalva, compression carotidienne unilatérale, eau froide ; adénosine IV flash si échec (effet ≈ 10 s).","Adénosine contre-indiquée : asthme, hypotension, FA sur voie accessoire.","Tachycardie sinusale : P positives D1-D2-D3-aVF, fréquence variant progressivement, contexte.","FA : 100–200 bpm, RR irrégulièrement irréguliers, mailles ou trémulation.","FA lente et régulière = FA + BAV3 ; FA irrégulière à QRS larges = FA + bloc de branche."],"pitfalls":["Une FA devenue régulière et lente signe un BAV complet associé.","Compression carotidienne interdite si souffle carotidien ou athérome important ; compression oculaire abandonnée."],"src":"p. 389-393"},{"id":"231-sec-07","title":"Flutters, tachycardies atriales focales, tachycardies jonctionnelles et extrasystoles","rank":"A","objectives":["231-obj-14","231-obj-15","231-obj-17","231-obj-16"],"content":"### Flutters atriaux\n- Boucle d'activation atriale se répétant à l'identique autour d'un obstacle (modèle de la **réentrée**), activation « organisée » ≠ FA fibrillatoire. Flutters **droits ≫ gauches** (zones propices dans l'OD même sans cardiopathie ; flutters gauches après remodelage ou intervention). Facteurs prédisposants communs à la FA.\n- ECG : activité atriale **monomorphe**, ≈ **300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation ; ondes **F** en toit d'usine / dents de scie, parfois démasquées par manœuvre vagale.\n- **Flutter typique (commun) antihoraire** : circuit de l'OD par l'**isthme cavotricuspide** (entre tricuspide et veine cave inférieure) ; 300 bpm (plus lent si dilatation) ; F **négatives en D2, D3, aVF, positives en V1, négatives en V6**. Typique horaire : polarités inversées.\n- **Flutters atypiques** : isthme non impliqué, droits, gauches ou biatriaux, **120–320 bpm**, F variables. Parler de flutter « d'aspect » typique/atypique ; diagnostic formel par la fréquence ou l'exploration électrophysiologique avant ablation par radiofréquence.\n- Ventricule : classiquement **150 bpm (2/1)**, ou 100 (3/1), 75… ; régulier le plus souvent, sinon **conduction variable** ; la manœuvre vagale ralentit et démasque les F (utile en 1/1 ou 2/1).\n\n### Tachycardies atriales focales (TAF)\nSur l'algorithme devant une tachycardie, les manœuvres vagales ou l'adénosine **démasquent l'activité atriale** des tachycardies atriales (dont la TAF) **sans les arrêter**, car elles ne dépendent pas du NAV.\n\n### Tachycardies jonctionnelles (maladie de Bouveret)\nFréquentes, **très régulières**, ≈ **200 bpm (130–260)**. Deux formes :\n- **réentrée intranodale** : mécanisme de réentrée dans le NAV ; activité atriale invisible ou devinée dans le ST (activation atriale et ventriculaire quasi synchrone) ;\n- **rythme réciproque** : réentrée par une **voie accessoire** (faisceau de Kent).\n- [B] Réduites par les manœuvres vagales ou l'adénosine IV.\n\n### Extrasystoles\nActivation prématurée d'une cavité. Fréquentes, physiologiques sur cœur sain ; charge/24 h croissant avec l'âge et la cardiopathie ; **fréquentes ou polymorphes → rechercher une cardiopathie**.\n- **Atriale** : P précoce de morphologie différente puis QRS fin ; P parfois cachée dans la T précédente (dont elle modifie la polarité).\n- **Jonctionnelle** : QRS fin ± P' rétrograde ; rare, traduit une atteinte de la jonction nodohissienne.\n- **Ventriculaire** : QRS large ± P' rétrograde (trouble du rythme ventriculaire).\n- Répétitives : doublets, triplets, salves. Rythmées : **bigéminisme** (1 battement sur 2), **trigéminisme** (1 sur 3).","keyPoints":["Flutter : ondes F monomorphes ≈ 300 bpm sans retour à la ligne isoélectrique ; ventricule à 150 (2/1) le plus souvent.","Flutter typique antihoraire : isthme cavotricuspide, F négatives en D2-D3-aVF, positives en V1, négatives en V6.","Tachycardie atriale (flutter, TAF) : la manœuvre vagale démasque l'activité atriale sans arrêter la tachycardie.","Tachycardie jonctionnelle : très régulière ≈ 200 bpm ; réentrée intranodale (P invisible ou devinée dans le ST) ou par voie accessoire (faisceau de Kent).","Manœuvres vagales et adénosine réduisent les tachycardies jonctionnelles.","ESA : P précoce différente + QRS fin ; ESV : QRS large ; bigéminisme = 1 sur 2."],"pitfalls":["Flutter 2/1 à 150 bpm : QRS serrés masquant les F → manœuvre vagale.","L'aspect ECG typique/atypique du flutter n'est pas parfaitement fiable.","Une ESA peut se cacher dans l'onde T précédente."],"src":"p. 393-398"},{"id":"231-sec-08","title":"Troubles du rythme ventriculaire et algorithme devant une tachycardie","rank":"A","objectives":["231-obj-18","231-obj-19","231-obj-20","231-obj-02"],"content":"> Objectif prioritaire : mort subite et syncopes. Ces tachycardies naissent **sous la bifurcation hissienne**, court-circuitent les voies de conduction → conduction lente de proche en proche → **QRS large**.\n\n### Tachycardie ventriculaire\n- Mécanismes : **réentrée** (le plus fréquent sur cardiopathie, autour d'une fibrose post-infarctus) ; **automatisme anormal** (cœur sain).\n- **Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.** État instable prémonitoire de l'arrêt cardiaque (> la moitié des morts subites) : TV → FV → asystolie.\n- Suspicion : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n- **TV non soutenue** : 3 battements à 30 s ; **soutenue** : > 30 s. Préciser **monomorphe** / **polymorphe**.\n- **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P ⇒ origine ventriculaire ; ≠ dissociation AV du BAV3) ; complexes de **capture** (QRS fin précédé d'une P) et de **fusion** (QRS intermédiaire), possibles seulement s'il y a dissociation.\n- **En faveur** : cardiopathie sous-jacente +++ ; **concordance** positive ou négative de V1 à V6 ; **axe extrême** (QRS positif en aVR, jamais vu dans un BBD/BBG) ; QRS larges d'aspect atypique de bloc de branche.\n\n### Fibrillation ventriculaire\n**Urgence absolue** : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant. Perte de connaissance en quelques secondes (débit nul), pouls carotidien aboli = arrêt cardiaque. ECG : tachycardie **irrégulière à QRS larges polymorphes**.\n\n### Torsades de pointes [B]\n- TV **polymorphe** s'arrêtant spontanément ou dégénérant en FV ; installée, elle est indiscernable d'une FV → diagnostic sur le **QT long préalable** et le contexte (FV surtout sur ischémie ou cardiopathie évoluée).\n- Causes de QT long : **bradycardie extrême** (échappements des BAV bas situés, intoxication aux bradycardisants), **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- Tout QT allongé → vérifier médicaments et ionogramme. Prise en charge : corriger les ions, **accélérer la fréquence cardiaque**, arrêter les médicaments en cause.\n- Torsade possible à QT normal, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re.\n\n### Algorithme devant une tachycardie (FC > 100 bpm)\n1. **Irrégulière** → **FA** (diagnostic différentiel : ESA).\n2. **Régulière à QRS larges** → ventriculaire jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → supraventriculaire.\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe.**\n- Bonne tolérance → manœuvres vagales ± adénosine (BAV transitoire) dès que le diagnostic n'est pas évident :\n  - **démasque l'activité atriale** → sinusale, flutter, TAF ;\n  - **arrête la tachycardie** → jonctionnelle (réentrée dépendante du NAV) ;\n  - **aucun effet** → TV (indépendante du NAV) ; certitude si dissociation AV.","keyPoints":["Tachycardie régulière à QRS larges = TV jusqu'à preuve du contraire.","TV : FC > 100, QRS > 120 ms, ≥ 3 battements ; non soutenue ≤ 30 s, soutenue > 30 s.","Certitude de TV : dissociation VA (plus de QRS que de P), captures, fusions.","En faveur de TV : cardiopathie, concordance V1–V6, aVR positif, aspect atypique de bloc.","FV = choc électrique immédiat, massage cardiaque en attendant.","Torsade = TV polymorphe sur QT long : ions (K, Ca, Mg), bradycardie, médicaments, congénital ; accélérer la FC.","Tachycardie mal tolérée = cardioversion électrique ; bien tolérée = manœuvres vagales ± adénosine."],"pitfalls":["Confondre bloc de branche (bénin immédiatement) et TV (mortelle) devant un QRS large.","Confondre dissociation ventriculoatriale de la TV et dissociation AV du BAV3.","Torsade installée = aspect de FV : chercher le QT long sur les tracés antérieurs."],"src":"p. 398-405"},{"id":"231-sec-09","title":"Hypertrophies atriales et ventriculaires","rank":"A","objectives":["231-obj-03","231-obj-04","231-obj-05"],"content":"« Hypertrophie » (terme historique) = augmentation de la quantité de myocytes d'une cavité, par **dilatation** et/ou **épaississement** ; parfois corrélée au degré de fibrose.\n\n### Hypertrophies atriales [B]\n| | Onde P |\n|---|---|\n| **HAD** (surtout par dilatation) | amplitude **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2** |\n| **HAG** | durée **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1** |\n\n### Hypertrophie ventriculaire gauche\n- Dilatation ou épaississement du VG (volume myocardique augmenté).\n- **Indice de Sokolow** = S (V1 ou V2) + R (V5 ou V6) ; normal **< 35 mm**.\n- **Forme sévère** (historiquement « surcharge systolique ») : T **négative** ± **sous-ST** dans les latérales (D1, aVL, V5, V6) par anomalie secondaire de repolarisation, et **disparition de la q septale** dans ces dérivations. Forme modérée dite « diastolique » (termes sans valeur mécanistique).\n- Déviation axiale gauche modeste ; QRS un peu élargis (masse, fibrose) mais le plus souvent **< 120 ms**.\n- Étiologies : **HTA** en premier, puis **rétrécissement aortique**.\n\n> Pièges : aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-décalage du ST** en V1-V2 mimant une séquelle d'infarctus ou un SCA.\n\n### Hypertrophie ventriculaire droite [B]\n- Intérêt modeste à l'ère de l'échographie ; utile chez les patients **BPCO** ou à atteinte pulmonaire sévère.\n- Signe le plus précoce : **axe > 110°** (90° en pratique). Autres : **R > 6 mm en V1**, **S > 7 mm en V5-V6**, association fréquente à une **HAD** et à un **microvoltage** (BPCO) ; BBD souvent associé.\n- T négative asymétrique en V1 (parfois V2-V3) dans les formes sévères : ne pas confondre avec une ischémie.\n- Même aspect possible dans l'**HBPG** ou comme variante du sujet **longiligne**.\n- **Embolie pulmonaire** : hypertrophie aiguë → aspect **S1Q3T3** (S en D1, Q en D3, T négative en D3), déviation axiale droite, FA possible.","keyPoints":["HAD : P > 2,5 mm en D2 ou > 2 mm en V1-V2 ; HAG : P > 120 ms avec négativité > 40 ms en V1.","Sokolow = S V1/V2 + R V5/V6 ; HVG si ≥ 35 mm.","HVG sévère : T négatives et sous-ST latéraux, disparition de la q septale.","HVG : étiologies HTA puis rétrécissement aortique ; QRS restent < 120 ms.","HVD : axe > 110° (90° en pratique), R V1 > 6 mm, S V5-V6 > 7 mm, HAD, microvoltage, BBD.","Embolie pulmonaire : S1Q3T3."],"pitfalls":["HVG importante : QS et sus-ST en V1-V2 = pseudonécrose, pas un infarctus.","T négatives asymétriques V1-V3 de l'HVD : pas forcément une ischémie.","HBPG et sujet longiligne miment l'HVD."],"src":"p. 406-408"},{"id":"231-sec-10","title":"Dyskaliémies, QT long, péricardite aiguë et préexcitation","rank":"A","objectives":["231-obj-21","231-obj-22","231-obj-23","231-obj-25"],"content":"### Dyskaliémies\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | **plate ou négative**, diffuse, avec **sous-ST** | **ample, pointue, symétrique** (géante) |\n| PR | – | **allongé** |\n| QRS | normal | **élargi** |\n| QT / U | **QT allongé**, apparition d'une **onde U** (exclue du QT) | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | **BAV**, TV, **dysfonction sinusale** (échappement jonctionnel) |\n\n### Allongement du QT\nUn QT long expose à la torsade de pointes : causes **médicamenteuses** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **ioniques** (hypoK, hypoCa, hypoMg), **bradycardie extrême**, **congénitale** (syndrome du QT long). Conduite : vérifier les médicaments et le ionogramme, corriger.\n\n### Péricardite aiguë : 4 phases [B]\n1. Phase 1, brève : **microvoltage** (proportionnel à l'épanchement), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)**.\n2. T plates partout, ST isoélectrique.\n3. T **négatives** persistantes.\n4. Retour progressif à la normale.\n\n> Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.\n\n### Préexcitation et Wolff-Parkinson-White [B]\n- Physiologiquement le NAV est l'unique passage AV. Une **voie accessoire (faisceau de Kent)** = fibre musculaire ectopique atrioventriculaire conduisant typiquement dans les deux sens, en compétition avec le NAV.\n- Si elle conduit vite en antérograde : **préexcitation** — **PR court < 120 ms**, **élargissement du QRS par empâtement de son pied = onde delta** (zone préexcitée), **troubles de repolarisation** dans le territoire de la voie.\n- Bloquer le NAV (massage, adénosine) force le passage par la voie accessoire et démasque une préexcitation minime — **jamais en cas de FA**.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- **Risque de mort subite** si période réfractaire courte : la voie n'a pas de propriété décrémentielle ; en FA, tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** (super-Wolff) → FV. C'est la seule autre contre-indication de l'adénosine avec l'asthme.","keyPoints":["HypoK : T plates/négatives + sous-ST, QT long, onde U, risque de torsade.","HyperK : T amples pointues symétriques, PR long, QRS large, BAV, dysfonction sinusale.","QT long : médicaments, hypoK/hypoCa/hypoMg, bradycardie, congénital → vérifier ionogramme et traitements.","Péricardite : sus-ST diffus concave sans miroir + sous-PQ + microvoltage, puis T plates, T négatives, normalisation.","Préexcitation : PR < 120 ms, onde delta, repolarisation anormale.","FA + voie accessoire = tachycardie irrégulière à QRS larges variables : pas d'adénosine."],"pitfalls":["Inclure l'onde U de l'hypokaliémie dans la mesure du QT.","Un SCA ST+ peut être sans miroir visible : ne pas l'étiqueter péricardite.","Manœuvre vagale ou adénosine chez un patient préexcité en FA."],"src":"p. 408-411"},{"id":"231-sec-11","title":"Maladie coronarienne et syndromes coronariens aigus","rank":"A","objectives":["231-obj-24","231-obj-02"],"content":"### Analyse de la repolarisation\n- La polarité des T suit celle des QRS ; T positives partout sauf **aVR**, parfois **V1, aVL ou D3** selon l'orientation du cœur.\n- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → territoire inférieur).\n\n### SCA avec sus-décalage de ST\n- **Traquer le sus-décalage** (il indique le territoire de la coronaire occluse), **puis** chercher le **miroir** (sous-décalage), pas l'inverse.\n- Un sous-ST en V1-V3 peut être le miroir d'un sus-ST **postérieur (V7-V9)** → **ECG 18 dérivations** devant toute douleur thoracique.\n- Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**. S'il englobe la T : **onde de Pardee**.\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie ± coronarographie).\n- Évolution : régression rapide si reperfusion ; plusieurs jours sans reperfusion ; persistance indéfinie si **anévrisme** de la paroi infarcie. Après 48 h, **T négative « ischémique »**, parfois très prolongée.\n\n### Cinq étiologies de sus-décalage du ST\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après un infarctus à séquelle marquée).\n3. **Repolarisation précoce** (dérivations inférolatérales).\n4. **Angor de Prinzmetal** (spasme coronarien).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\nDiagnostics différentiels : **BBG ou stimulation ventriculaire** (sus-ST approprié dans les dérivations à QRS négatif) ; **HVG marquée** (sus-ST en V1-V2).\n\n### Ondes Q de nécrose\n- Apparaissent en principe vers la **6e heure**, parfois plus tôt au cours du SCA ST+ ; leur présence ne signifie pas qu'une reperfusion serait inutile.\n- Critères : **≥ 1/3 (ou 1/4) de l'amplitude du QRS** et **> 30–40 ms**. Équivalent : **rabotage (écrêtement) de l'onde R**, surtout en V2-V3.\n\n### SCA sans sus-décalage de ST\nPossibles : **sous-ST** (lésion sous-endocardique), **inversion des T** (ischémie sous-épicardique), **pseudo-normalisation** de T auparavant négatives, **aplatissement** des T, ou **ECG normal**. Un pacemaker peut masquer ces anomalies.","keyPoints":["Deux T négatives dans un même territoire signent une pathologie.","Sus-ST significatif : ≥ 2 mm V1-V3, ≥ 1 mm ailleurs, ≥ 2 dérivations adjacentes ; miroir cherché ensuite.","Sous-ST V1-V3 = possible miroir postérieur → ECG 18 dérivations.","Cinq causes de sus-ST : SCA, anévrisme, repolarisation précoce, Prinzmetal, péricardite.","Onde Q de nécrose : ≥ 1/3 du QRS, > 30–40 ms, vers la 6e heure ; équivalent = rabotage de R en V2-V3.","SCA non ST+ : sous-ST, T inversées, pseudo-normalisation, T plates ou ECG normal."],"pitfalls":["Confondre la lésion et son miroir.","Prendre un élargissement du QRS (BBG, stimulation) pour une onde de Pardee.","Étiqueter péricardite un SCA ST+ dont le miroir est absent.","Des ondes Q ne rendent pas la reperfusion inutile."],"src":"p. 411-412"},{"id":"231-sec-12","title":"ECG et stimulateur cardiaque, prothèses rythmiques","rank":"B","objectives":["231-obj-26"],"content":"### Indications du pacemaker\n- **Bradycardies symptomatiques** : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale.\n- **BAV infrahissiens** (BAV2 Mobitz 2, BAV3) : **même sans symptôme**.\n\n### Les prothèses cardiaques\n| Problème | Prothèse |\n|---|---|\n| Bradycardie | **pacemaker** (stimulation locale de quelques myocytes puis conduction de proche en proche) |\n| TV / FV | **défibrillateur** (champ électrique réinitialisant tous les myocytes) ; fait toujours pacemaker, sauf sous-cutané |\n| BBG désynchronisant le VG avec insuffisance cardiaque | **resynchronisation cardiaque** (stimulateur, donc toujours pacemaker) |\n\nLes trois fonctions peuvent être associées : défibrillateur de resynchronisation.\n\n### Reconnaître l'électroentraînement\n- **Spike** de stimulation : impulsion de **0,4 à 1 ms**, plus courte que tout phénomène physiologique → **pathognomonique** d'une stimulation (pacemaker ou sonde d'entraînement électrosystolique).\n- **Unipolaire** (bout de sonde ↔ boîtier) : spike bien visible ; **bipolaire** (bout de sonde ↔ électrode proche) : spike peu visible.\n- **Dysfonction sinusale** → stimulation atriale : une **onde P suit le spike**.\n- **BAV** → le pacemaker écoute l'oreillette et stimule le ventricule après un **délai AV programmé** (synchronisation AV) : **QRS large d'aspect BBG** après le spike (stimulation du VD transmise de proche en proche).\n- Les anomalies ischémiques peuvent être masquées par un pacemaker.","keyPoints":["Pacemaker : bradycardies symptomatiques (DS, Mobitz 1, bradycardie sinusale) ; BAV infrahissien (Mobitz 2, BAV3) même asymptomatique.","Spike de 0,4–1 ms = pathognomonique d'une stimulation.","Stimulation atriale : P après le spike ; stimulation ventriculaire : QRS large type BBG après le spike.","Unipolaire = spike bien visible ; bipolaire = peu visible.","Défibrillateur et resynchronisation assurent aussi la fonction pacemaker (sauf défibrillateur sous-cutané)."],"pitfalls":["Un pacemaker masque les anomalies de repolarisation d'un SCA.","Le spike bipolaire peut passer inaperçu sur l'ECG de surface."],"src":"p. 412-414"},{"id":"231-sec-13","title":"Indications de l'ECG : monitorage, ECG 12 dérivations, Holter","rank":"A","objectives":["231-obj-27","231-obj-28"],"content":"### Monitorage ECG (cardioscope)\n- Toute **urgence**, réanimation et **transfert médicalisé**.\n- Surveillance en **soins intensifs cardiologiques** pour pathologie aiguë (ex. syndrome coronarien).\n- **Syncope** avec cause rythmique suspectée.\n- **Peropératoire** et salle de réveil postanesthésique.\n- Certains exercices de **réadaptation cardiaque**.\n\n### ECG conventionnel 12 dérivations ou plus\n- Systématique dans les centres de santé (bilans de santé).\n- **Aptitude** professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, professionnels).\n- **Bilan préopératoire** : patients **> 65 ans**, patients à risque, interventions à risque.\n- **Enquêtes familiales** de certaines cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée aiguë ou chronique, malaise, perte de connaissance, syncope.\n- **Obligatoire dans le bilan de l'HTA**.\n- Bilan initial et surveillance des pathologies cardiaques, ou non cardiaques à risque de complications cardiovasculaires (diabète, AVC).\n- Rappel : ECG **18 dérivations** (V7-V9, V3R-V4R) devant une douleur thoracique.\n\n### Méthode Holter [B]\n- ECG de longue durée, **2 à 12 dérivations** simultanées, **24 à 96 h maximum**, support numérique, lecture différée.\n- Indications : malaises, syncopes, pertes de connaissance ou palpitations **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (outils dédiés, montres connectées ECG).\n- **Holter implantable** (moniteur sous-cutané) : suivi **jusqu'à 3 ans** ; syncopes inexpliquées, FA silencieuse.\n- Holter de 24 h aussi pour : efficacité des **bradycardisants**, surveillance et réglage des **pacemakers**, évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).","keyPoints":["Scope : urgences/réa/transferts, USIC, syncope rythmique suspectée, bloc opératoire et réveil, réadaptation.","ECG 12 dérivations : bilans de santé, aptitude, préop > 65 ans ou à risque, enquêtes familiales, symptômes, HTA (obligatoire), suivi des cardiopathies, diabète, AVC.","Holter : 2–12 dérivations, 24–96 h, si symptômes épisodiques probables pendant l'enregistrement.","Symptômes rares : enregistrement jusqu'à 21 jours, enregistreurs d'événements ; implantable jusqu'à 3 ans.","Holter 24 h : bradycardisants, réglage de pacemaker, TV asymptomatiques post-infarctus."],"pitfalls":["Holter de 24 h inutile si les symptômes sont trop rares pour survenir pendant l'enregistrement."],"src":"p. 414-415"}],"essentials":[{"id":"231-ess-01","rank":"A","text":"À 25 mm/s, un petit carreau (1 mm) vaut 40 ms et un grand carreau (5 mm) vaut 200 ms ; 1 mm d'amplitude vaut 0,1 mV.","src":"p. 375"},{"id":"231-ess-02","rank":"A","text":"Le rythme sinusal se définit par une onde P positive en D1 et dans les dérivations inférieures, suivie d'un QRS, chaque QRS étant précédé d'une P.","src":"p. 376"},{"id":"231-ess-03","rank":"A","text":"L'axe normal du QRS va de –30° à +90° : D1 et aVF positifs suffisent à l'affirmer entre 0 et 90°.","src":"p. 375"},{"id":"231-ess-04","rank":"A","text":"Le QTc de Bazett se calcule en divisant le QT mesuré par la racine carrée de l'intervalle RR en secondes, sans inclure l'onde U.","src":"p. 377"},{"id":"231-ess-05","rank":"A","text":"Les ondes T sont normalement positives partout sauf en aVR et V1, parfois en D3 et aVL ; deux T négatives dans un même territoire sont pathologiques.","src":"p. 377"},{"id":"231-ess-06","rank":"A","text":"Un ECG normal s'affirme par une lecture systématique : rythme, conduction, repolarisation, morphologie.","src":"p. 377"},{"id":"231-ess-07","rank":"A","text":"Bloc complet de branche : QRS > 120 ms ; V1 positif avec RsR' = BBD, V1 négatif (rS/QS) avec notch latéral = BBG.","src":"p. 378-380"},{"id":"231-ess-08","rank":"A","text":"Discordance appropriée : avec un QRS large, l'onde T prend la polarité inverse du QRS, ce qui peut mimer un SCA ST+ dans le BBG.","src":"p. 381"},{"id":"231-ess-09","rank":"A","text":"Douleur thoracique persistante avec BBG : évoquer un infarctus antérieur et solliciter le cardiologue sans attendre la troponine.","src":"p. 381"},{"id":"231-ess-10","rank":"A","text":"L'hémibloc antérieur gauche dévie l'axe au-delà de –30° (D2 négatif) ; l'hémibloc postérieur gauche le dévie au-delà de +90° (D1 négatif, S1Q3).","src":"p. 382"},{"id":"231-ess-11","rank":"B","text":"Syncope associée à un bloc bifasciculaire impose l'hospitalisation en cardiologie sous télémétrie en raison du risque de BAV complet infrahissien.","src":"p. 383"},{"id":"231-ess-12","rank":"B","text":"Les BAV infrahissiens (Mobitz 2, BAV3) justifient un pacemaker même en l'absence de symptôme.","src":"p. 412"},{"id":"231-ess-13","rank":"A","text":"Dans un BAV, les ondes P restent régulières à fréquence normale ; le BAV1 est un PR constant supérieur à 200 ms sans P bloquée.","src":"p. 385-386"},{"id":"231-ess-14","rank":"A","text":"Mobitz 1 : allongement progressif du PR puis P bloquée (suprahissien) ; Mobitz 2 : PR constant puis P bloquée inopinée (infrahissien).","src":"p. 385"},{"id":"231-ess-15","rank":"A","text":"Devant une bradycardie, plus de P que de QRS signe un BAV ; des P trop lentes ou absentes signent une dysfonction sinusale.","src":"p. 389"},{"id":"231-ess-16","rank":"B","text":"Le bloc sinoatrial du 2e degré se traduit par une pause sans P-QRS-T égale au double de l'intervalle PP normal.","src":"p. 387"},{"id":"231-ess-17","rank":"A","text":"En échappement jonctionnel, l'onde P disparaît devant le QRS et peut apparaître rétrograde derrière lui, négative en D2.","src":"p. 388"},{"id":"231-ess-18","rank":"A","text":"La tachycardie sinusale a des P positives en D1, D2, D3, aVF et une fréquence qui varie progressivement, contrairement aux marches d'escalier des TSV.","src":"p. 390-391"},{"id":"231-ess-19","rank":"B","text":"Manœuvres vagales (Valsalva, compression carotidienne unilatérale, eau froide) puis adénosine IV en flash créent un BAV transitoire à visée diagnostique.","src":"p. 390"},{"id":"231-ess-20","rank":"B","text":"L'adénosine est contre-indiquée en cas d'asthme, d'hypotension et de FA conduite par une voie accessoire.","src":"p. 390-411"},{"id":"231-ess-21","rank":"A","text":"La fibrillation atriale est le seul diagnostic devant une tachycardie complètement irrégulière à QRS fins.","src":"p. 392-415"},{"id":"231-ess-22","rank":"B","text":"Une FA dont les QRS deviennent lents et réguliers traduit un BAV complet associé avec rythme d'échappement.","src":"p. 392"},{"id":"231-ess-23","rank":"A","text":"Le flutter donne une activité atriale monomorphe vers 300 bpm sans retour à la ligne isoélectrique, avec des ventricules le plus souvent à 150 bpm (2/1).","src":"p. 393-394"},{"id":"231-ess-24","rank":"A","text":"Le flutter typique antihoraire emprunte l'isthme cavotricuspide : ondes F négatives en D2, D3, aVF, positives en V1, négatives en V6.","src":"p. 394"},{"id":"231-ess-25","rank":"A","text":"La tachycardie jonctionnelle (Bouveret) est très régulière, autour de 200 bpm, par réentrée intranodale ou par voie accessoire.","src":"p. 395-396"},{"id":"231-ess-26","rank":"A","text":"Une extrasystole atriale est une P prématurée de morphologie différente suivie d'un QRS fin ; l'extrasystole ventriculaire est un QRS large prématuré.","src":"p. 397"},{"id":"231-ess-27","rank":"A","text":"Toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.","src":"p. 398"},{"id":"231-ess-28","rank":"A","text":"La dissociation ventriculoatriale (plus de QRS que de P), les captures et les fusions sont les arguments de certitude d'une TV.","src":"p. 400"},{"id":"231-ess-29","rank":"A","text":"La fibrillation ventriculaire est une tachycardie irrégulière à QRS larges polymorphes imposant un choc électrique immédiat, massage cardiaque en attendant.","src":"p. 402-403"},{"id":"231-ess-30","rank":"B","text":"La torsade de pointes est une TV polymorphe survenant sur QT long ; son traitement corrige les ions, accélère la fréquence et arrête les médicaments en cause.","src":"p. 403-404"},{"id":"231-ess-31","rank":"A","text":"Une tachycardie mal tolérée sur le plan hémodynamique impose une cardioversion électrique externe.","src":"p. 405"},{"id":"231-ess-32","rank":"A","text":"L'indice de Sokolow (S en V1-V2 + R en V5-V6) est le marqueur d'HVG à retenir, avec ses anomalies de repolarisation associées.","src":"p. 406"},{"id":"231-ess-33","rank":"B","text":"L'embolie pulmonaire peut donner un aspect S1Q3T3 par hypertrophie ventriculaire droite aiguë.","src":"p. 407"},{"id":"231-ess-34","rank":"A","text":"Hypokaliémie : T plates ou négatives, sous-ST, QT long et onde U ; hyperkaliémie : T amples pointues symétriques, PR long, QRS large.","src":"p. 408"},{"id":"231-ess-35","rank":"B","text":"La péricardite aiguë débute par un sus-ST diffus concave vers le haut sans miroir, un sous-décalage de PQ et un microvoltage.","src":"p. 409"},{"id":"231-ess-36","rank":"B","text":"La préexcitation associe PR court < 120 ms, onde delta empâtant le pied du QRS et troubles de repolarisation.","src":"p. 410"},{"id":"231-ess-37","rank":"A","text":"Dans un SCA ST+, on repère d'abord le sus-décalage qui désigne l'artère occluse, puis son miroir ; un sous-ST V1-V3 impose de chercher un sus-ST postérieur en V7-V9.","src":"p. 411"},{"id":"231-ess-38","rank":"A","text":"Les cinq causes de sus-décalage du ST sont le SCA, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite.","src":"p. 412"},{"id":"231-ess-39","rank":"B","text":"Le spike de stimulation, long de 0,4 à 1 ms, est pathognomonique d'un pacemaker ; la stimulation ventriculaire droite donne un QRS large d'aspect BBG.","src":"p. 413-414"},{"id":"231-ess-40","rank":"A","text":"L'ECG 12 dérivations est obligatoire dans le bilan de l'HTA et indiqué en préopératoire après 65 ans ou en cas de risque.","src":"p. 414"}],"numbers":[{"id":"231-num-01","rank":"A","label":"Vitesse de déroulement standard","value":"25 mm/s : 1 mm = 40 ms, grand carreau (5 mm) = 200 ms","src":"p. 375"},{"id":"231-num-02","rank":"A","label":"Étalonnage d'amplitude","value":"1 mm = 0,1 mV","src":"p. 375"},{"id":"231-num-03","rank":"A","label":"Fréquence cardiaque normale de repos (adulte)","value":"60–100 bpm (bradycardie < 60, tachycardie > 100)","src":"p. 375-376"},{"id":"231-num-04","rank":"A","label":"Durée normale de l'onde P","value":"< 120 ms (théorique < 110 ms)","src":"p. 375"},{"id":"231-num-05","rank":"A","label":"Axe et amplitude normaux de P","value":"Axe 60° (positivité maximale en D2) ; amplitude < 2,5 mm en D2","src":"p. 375"},{"id":"231-num-06","rank":"A","label":"Intervalle PR normal","value":"120–200 ms (inclus)","src":"p. 375-376"},{"id":"231-num-07","rank":"A","label":"Durée normale du QRS","value":"70–110 ms","src":"p. 375"},{"id":"231-num-08","rank":"A","label":"Axe normal du QRS","value":"–30° à +90° (théorique –45° à +110°)","src":"p. 375"},{"id":"231-num-09","rank":"A","label":"Onde Q physiologique","value":"< 1/3 de l'amplitude du QRS et < 40 ms","src":"p. 375"},{"id":"231-num-10","rank":"A","label":"QT corrigé normal","value":"< 450 ms à 60 bpm (en pratique 470–480 ms)","src":"p. 375"},{"id":"231-num-12","rank":"A","label":"Calcul rapide de la FC","value":"FC = 300 / nombre de grands carreaux entre deux QRS (1 carreau = 300 bpm, 2 = 150 bpm)","src":"p. 376"},{"id":"231-num-13","rank":"A","label":"Graduation du double triaxe de Bailey","value":"Dérivations de 30° en 30°, sens horaire, D1 = 0°","src":"p. 375"},{"id":"231-num-14","rank":"A","label":"Durée du QRS dans un bloc complet de branche","value":"> 120 ms (bloc incomplet : 110–120 ms)","src":"p. 378-381"},{"id":"231-num-15","rank":"A","label":"Hémiblocs : durée et axe","value":"QRS > 110 ms ; HBAG axe < –30° ; HBPG axe > +90°","src":"p. 382"},{"id":"231-num-16","rank":"A","label":"Définition du BAV1","value":"PR constant > 200 ms sans onde P bloquée","src":"p. 386"},{"id":"231-num-17","rank":"A","label":"Seuil de bradycardie de l'algorithme diagnostique","value":"FC des QRS < 50 bpm","src":"p. 389"},{"id":"231-num-18","rank":"B","label":"Pause du bloc sinoatrial du 2e degré","value":"Égale au double de l'intervalle PP (RR) normal","src":"p. 387"},{"id":"231-num-19","rank":"B","label":"Durée d'effet de l'adénosine IV","value":"Une dizaine de secondes (flash IV)","src":"p. 390"},{"id":"231-num-20","rank":"A","label":"Fréquence ventriculaire de la FA","value":"100–200 bpm, QRS irrégulièrement irréguliers","src":"p. 392"},{"id":"231-num-21","rank":"A","label":"Fréquence atriale du flutter","value":"≈ 300 bpm (240–340) ; flutter atypique 120–320 bpm","src":"p. 393-394"},{"id":"231-num-22","rank":"A","label":"Fréquence ventriculaire du flutter","value":"150 bpm en 2/1, 100 bpm en 3/1, 75 bpm en 4/1","src":"p. 394"},{"id":"231-num-23","rank":"A","label":"Fréquence des tachycardies jonctionnelles","value":"≈ 200 bpm (130–260 bpm)","src":"p. 395"},{"id":"231-num-25","rank":"A","label":"Critères de suspicion de TV","value":"FC > 100 bpm et QRS > 120 ms sur ≥ 3 battements consécutifs","src":"p. 399"},{"id":"231-num-26","rank":"A","label":"TV non soutenue vs soutenue","value":"Non soutenue : 3 battements à 30 s ; soutenue : > 30 s","src":"p. 399"},{"id":"231-num-27","rank":"A","label":"Part de la TV dans les morts subites","value":"Prémonitoire de l'arrêt cardiaque dans plus de la moitié des morts subites","src":"p. 398"},{"id":"231-num-28","rank":"A","label":"Indice de Sokolow","value":"S (V1 ou V2) + R (V5 ou V6) < 35 mm","src":"p. 406"},{"id":"231-num-29","rank":"B","label":"Hypertrophie atriale droite","value":"P > 2,5 mm en D2 ou > 2 mm en V1-V2","src":"p. 406"},{"id":"231-num-30","rank":"B","label":"Hypertrophie atriale gauche","value":"P > 110 ms (120 ms en pratique), composante négative > 40 ms en V1","src":"p. 406"},{"id":"231-num-31","rank":"B","label":"Hypertrophie ventriculaire droite","value":"Axe > 110° (90° en pratique) ; R > 6 mm en V1 ; S > 7 mm en V5-V6","src":"p. 407"},{"id":"231-num-32","rank":"B","label":"PR de la préexcitation","value":"< 120 ms","src":"p. 410"},{"id":"231-num-33","rank":"A","label":"Sus-décalage du ST significatif","value":"≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes","src":"p. 412"},{"id":"231-num-34","rank":"A","label":"Onde Q de nécrose","value":"≥ 1/3 (ou 1/4) du QRS et > 30–40 ms ; apparaît vers la 6e heure","src":"p. 412"},{"id":"231-num-35","rank":"A","label":"Délai d'apparition de l'onde T négative ischémique","value":"Après 48 heures","src":"p. 412"},{"id":"231-num-36","rank":"B","label":"Durée du spike de stimulation","value":"0,4 à 1 ms","src":"p. 413"},{"id":"231-num-37","rank":"B","label":"Paramètres du Holter ECG","value":"2 à 12 dérivations, 24 à 96 h maximum","src":"p. 415"},{"id":"231-num-38","rank":"B","label":"Enregistrements de très longue durée","value":"ECG ambulatoire jusqu'à 21 jours ; holter implantable jusqu'à 3 ans","src":"p. 415"},{"id":"231-num-39","rank":"A","label":"Âge de l'ECG préopératoire systématique","value":"> 65 ans (ou patient / intervention à risque)","src":"p. 414"},{"id":"231-num-40","rank":"A","label":"Dérivations précordiales","value":"V1 à V9, plus V3R et V4R (enfant, suspicion de SCA)","src":"p. 371"}],"mnemonics":[{"id":"231-mn-01","rank":"A","title":"Lecture systématique de l'ECG normal","mnemonic":"« Regarde Chaque Rythme Méthodiquement »","expansion":"- **R**ythme : sinusal, 60–100 bpm\n- **C**onduction : P < 120 ms, PR 120–200 ms, QRS 70–110 ms, axe –30° à +90°\n- **R**epolarisation : point J et ST isoélectriques, T positives sauf aVR/V1 (± D3, aVL), QT < 450 ms\n- **M**orphologie : amplitudes normales (Sokolow < 35 mm), transition V1→V6, pas de Q de nécrose","src":"p. 377"},{"id":"231-mn-02","rank":"A","title":"BBD ou BBG : la polarité de V1","mnemonic":"« Droit = V1 Dressé, Gauche = V1 Gisant »","expansion":"- **D**roit : QRS **d**ressé (globalement positif) en V1, aspect RsR', S traînante en V6\n- **G**auche : QRS **g**isant (globalement négatif) en V1, aspect rS/QS, notch et R exclusive en V6-D1-aVL\n- Dans les deux cas QRS > 120 ms et aspect inverse en V6","src":"p. 378-381"},{"id":"231-mn-03","rank":"A","title":"Arguments ECG de tachycardie ventriculaire","mnemonic":"« Des Cœurs Cassés Cognent Avec Ardeur »","expansion":"Certitude :\n- **D**issociation ventriculoatriale (plus de QRS que de P)\n- **C**aptures et fusions\n\nEn faveur :\n- **C**ardiopathie sous-jacente\n- **C**oncordance positive ou négative de V1 à V6\n- **A**xe extrême (QRS positif en aVR)\n- **A**spect des QRS larges différent d'un bloc de branche habituel","src":"p. 400"},{"id":"231-mn-04","rank":"B","title":"Causes d'allongement du QT (torsades de pointes)","mnemonic":"« Bébé Koala Calme Mange Mes Cookies »","expansion":"- **B**radycardie extrême (échappements des BAV bas situés, intoxication aux bradycardisants)\n- **K** : hypo**k**aliémie\n- **Ca** : hypo**ca**lcémie\n- **M**g : hypo**m**agnésémie\n- **M**édicaments allongeant le QT (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens)\n- **C**ongénital : syndrome du QT long","src":"p. 404"},{"id":"231-mn-05","rank":"A","title":"Les cinq étiologies de sus-décalage du ST","mnemonic":"« Ses Amis Reprennent un Petit Pain »","expansion":"- **S**CA avec sus-décalage du ST (onde de Pardee avec miroir)\n- **A**névrisme ventriculaire (sus-ST persistant après l'infarctus)\n- **R**epolarisation précoce (dérivations inférolatérales)\n- **P**rinzmetal (spasme coronarien)\n- **P**éricardite (diffus, concave vers le haut, sans miroir)","src":"p. 412"},{"id":"231-mn-06","rank":"B","title":"Les quatre phases ECG de la péricardite aiguë","mnemonic":"« Sa Péricardite N'est Normale qu'à la fin »","expansion":"1. **S**us-décalage diffus concave sans miroir + sous-PQ + microvoltage\n2. T **P**lates, ST isoélectrique\n3. T **N**égatives persistantes\n4. Retour à la **N**ormale","src":"p. 409"},{"id":"231-mn-07","rank":"B","title":"Les manœuvres vagales du livre","mnemonic":"« Vite Calme Et détendu »","expansion":"- **V**alsalva (expiration forcée à glotte fermée)\n- **C**ompression carotidienne unilatérale (contre-indiquée si athérome important ou souffle carotidien)\n- **E**au froide : boire un grand verre\n\nEn cas d'échec : adénosine IV en flash (contre-indiquée si asthme, hypotension, FA préexcitée). La compression oculaire n'est plus recommandée.","src":"p. 390"},{"id":"231-mn-08","rank":"A","title":"Indications du monitorage ECG (scope)","mnemonic":"« Un Scope Surveille les Patients Réanimés »","expansion":"- **U**rgences, réanimation, transferts médicalisés\n- **S**oins intensifs cardiologiques (pathologie aiguë, ex. syndrome coronarien)\n- **S**yncope de cause rythmique suspectée\n- **P**eropératoire et salle de réveil\n- **R**éadaptation cardiaque (certains exercices)","src":"p. 414"},{"id":"231-mn-09","rank":"B","title":"Indications du pacemaker","mnemonic":"Pacemaker « SI » : Symptomatique ou Infrahissien","expansion":"- **S**ymptomatique : bradycardies symptomatiques par dysfonction sinusale, BAV2 Mobitz 1 ou bradycardie sinusale\n- **I**nfrahissien : BAV2 Mobitz 2 et BAV3, **même sans symptôme**","src":"p. 412"},{"id":"231-mn-10","rank":"A","title":"Signes ECG de l'hyperkaliémie","mnemonic":"« Toujours Plus Que Bien »","expansion":"- **T** : onde T ample, pointue, symétrique\n- **P** : PR allongé\n- **Q** : QRS élargi\n- **B** : BAV (et aussi TV, dysfonction sinusale)","src":"p. 408"},{"id":"231-mn-11","rank":"A","title":"Territoires des dérivations précordiales","mnemonic":"« Septe, Pointe, Côté, Dos »","expansion":"- V1-V2-V3 → **septe** : antéroseptal (paroi antérieure du VG et septum)\n- V4 → **pointe** : apical\n- V5-V6 → **côté** : latéral bas (D1, aVL = latéral haut)\n- V7-V8-V9 → **dos** : postérieur (face basale et inférieure du VG)\n- D2, D3, aVF → inférieur ; V1, V2, V3R, V4R → ventricule droit","src":"p. 374"}]},"questions":[{"id":"231-qcm-001","type":"QRM","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Parmi les valeurs suivantes, lesquelles correspondent à des paramètres normaux de l'ECG de l'adulte au repos ?","options":[{"t":"La durée du QRS est comprise entre 70 et 110 ms","ok":true,"why":"C'est la fourchette normale donnée par le livre pour la durée du QRS."},{"t":"L'espace PR est compris entre 120 et 200 ms","ok":true,"why":"C'est la norme rappelée dans le tableau récapitulatif des valeurs normales."},{"t":"La fréquence cardiaque de repos normale est comprise entre 60 et 100 bpm","ok":true,"why":"En deçà on parle de bradycardie, au-delà de tachycardie."},{"t":"Le QT corrigé normal doit être supérieur à 450 ms à 60 bpm","ok":false,"why":"C'est l'inverse : le QTc normal est inférieur à 450 ms (en pratique jusqu'à 470-480 ms)."},{"t":"L'axe normal du QRS se situe entre 90° et 180°","ok":false,"why":"L'axe normal du QRS est situé entre -30° et +90°, pas entre 90° et 180° qui correspond à un axe hyperdroit."}],"explanation":"Le tableau des valeurs normales doit être connu par cœur : FC 60-100 bpm, PR 120-200 ms, QRS 70-110 ms, axe -30 à +90°, QTc < 450 ms à 60 bpm.","src":"p. 375-376"},{"id":"231-qcm-004","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Quelle association dérivation(s)-territoire cardiaque est exacte ?","options":[{"t":"V1, V2 et V3 explorent le territoire antéroseptal","ok":true,"why":"C'est la définition donnée par le livre du territoire antéroseptal."},{"t":"D2, D3 et aVF explorent un territoire latéral","ok":false,"why":"D2, D3 et aVF explorent le territoire inférieur (diaphragmatique), pas latéral."},{"t":"V7, V8 et V9 explorent un territoire antérieur","ok":false,"why":"V7 à V9 explorent le territoire postérieur (basal et inférieur du VG)."},{"t":"D1 et aVL explorent un territoire inférieur","ok":false,"why":"D1 et aVL explorent le territoire latéral haut, avec V5-V6 pour le latéral bas."},{"t":"V4 explore uniquement le territoire septal profond","ok":false,"why":"V4 explore le territoire apical, pas septal profond."}],"explanation":"Seule l'association V1-V2-V3 = antéroseptal est correcte ici ; les autres inversent les territoires (D2-D3-aVF = inférieur, V7-V9 = postérieur, D1-aVL = latéral haut).","src":"p. 373-374"},{"id":"231-qcm-005","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","pièges"],"difficulty":1,"stem":"Concernant une erreur fréquente de positionnement des électrodes précordiales, quelle proposition est exacte ?","options":[{"t":"V1 et V2 sont souvent placées trop haut et trop écartées, ce qui peut simuler une pseudonécrose antérieure","ok":true,"why":"Le livre signale explicitement ce piège car V1-V2 sont confondues avec les foyers auscultatoires aortique et pulmonaire."},{"t":"Cette erreur de position n'a aucune conséquence sur l'interprétation de l'ECG","ok":false,"why":"Elle peut au contraire créer un aspect de pseudonécrose ou d'atypie de repolarisation dans le territoire antérieur."},{"t":"Cette erreur concerne exclusivement les dérivations des membres","ok":false,"why":"Il s'agit d'une erreur de positionnement des électrodes précordiales, pas des membres."},{"t":"Elle est corrigée en utilisant systématiquement les dérivations de Lewis","ok":false,"why":"Les dérivations de Lewis servent à mieux voir l'activité atriale, pas à corriger un mauvais positionnement précordial."},{"t":"Elle ne peut jamais affecter le territoire antérieur","ok":false,"why":"C'est précisément le territoire antérieur qui peut être faussement anormal dans ce cas."}],"explanation":"Le placement trop haut de V1-V2 est un piège classique source de faux aspects pathologiques en antérieur : bien vérifier l'équidistance des électrodes précordiales.","trap":"Ne pas confondre le bon positionnement des électrodes avec les repères auscultatoires (foyers aortique et pulmonaire), qui sont trop hauts.","src":"p. 373"},{"id":"231-qcm-006","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant l'onde P sinusale normale, quelles propositions sont exactes ?","options":[{"t":"Elle est positive en D1","ok":true,"why":"L'onde P sinusale normale est positive en D1 comme dans les dérivations inférieures."},{"t":"Elle est positive dans les dérivations inférieures","ok":true,"why":"Le nœud sinusal étant en haut à droite de l'oreillette droite, l'activation se propage vers le bas et la gauche, donnant une onde P positive en D2, D3, aVF."},{"t":"En rythme sinusal, chaque onde P est suivie d'un complexe QRS","ok":true,"why":"C'est un des deux critères définissant la conduction sinusale normale."},{"t":"Son axe normal est proche de 60°","ok":true,"why":"L'onde P normale a un axe à 60°, avec une positivité maximale en D2."},{"t":"Sa durée normale est supérieure à 120 ms","ok":false,"why":"La durée normale de l'onde P est inférieure à 120 ms, pas supérieure."}],"explanation":"L'onde P sinusale est positive en D1 et dans les dérivations inférieures, d'axe proche de 60°, de durée < 120 ms, et chaque P est suivie d'un QRS en rythme sinusal normal.","src":"p. 375-376"},{"id":"231-qcm-007","type":"QRM","rank":"A","objective":"231-obj-01","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la séquence normale de dépolarisation ventriculaire, quelle proposition est exacte ?","options":[{"t":"La première phase, septale, explique la présence d'une petite onde positive en V1","ok":true,"why":"La dépolarisation septale initiale, orientée vers l'avant et la droite, génère une petite onde positive en V1 et une onde Q fine en latéral."},{"t":"La deuxième phase est orientée vers l'arrière et le haut","ok":false,"why":"C'est la troisième phase qui est orientée vers le haut et l'arrière ; la deuxième est orientée vers la jambe gauche et l'avant."},{"t":"La troisième phase génère la plus grande amplitude du QRS","ok":false,"why":"C'est la deuxième phase qui donne la grande onde R en V3, V4 et D2 ; la troisième ne donne qu'une petite onde S."},{"t":"Cette séquence rend le QRS strictement monophasique","ok":false,"why":"Au contraire, cette succession de trois phases explique le caractère polyphasique du QRS."},{"t":"La phase septale est absente chez le sujet sain","ok":false,"why":"Elle est au contraire physiologique et constante chez le sujet sain, expliquant l'onde Q fine latérale normale."}],"explanation":"Le QRS normal résulte de trois phases successives (septale, pariétale principale, basale postérieure) qui expliquent son caractère polyphasique.","src":"p. 375-376"},{"id":"231-qcm-008","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Quel aspect en V1 est évocateur d'un bloc complet de branche droite ?","options":[{"t":"Un QRS globalement positif avec un aspect RsR'","ok":true,"why":"C'est l'aspect typique du BBD complet en V1, avec un QRS supérieur à 120 ms."},{"t":"Un QRS globalement négatif en rS","ok":false,"why":"C'est l'aspect attendu en V1 dans le bloc de branche gauche, pas dans le BBD."},{"t":"Un aspect QS profond","ok":false,"why":"L'aspect QS profond en V1 n'est pas caractéristique du BBD."},{"t":"Un sus-décalage isolé et majeur du segment ST","ok":false,"why":"Le sus-décalage n'est pas un critère du BBD, qui se définit par la morphologie du QRS."},{"t":"Une onde delta","ok":false,"why":"L'onde delta est un signe de préexcitation (Wolff-Parkinson-White), pas de bloc de branche droit."}],"explanation":"Le BBD complet associe une durée de QRS > 120 ms, un aspect RsR' positif en V1 et un aspect qRs avec onde S traînante en V6.","src":"p. 378-379"},{"id":"231-qcm-009","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la méthode rapide de détermination de l'axe du QRS à partir de la polarité de D1 et aVF, quelles propositions sont exactes ?","options":[{"t":"D1 et aVF positifs correspondent à un axe normal entre 0 et 90°","ok":true,"why":"C'est le premier cadran défini par le livre pour un axe normal."},{"t":"D1 négatif et aVF positif correspondent à un axe hyperdroit","ok":true,"why":"Ce cadran (D1-, aVF+) correspond à un axe entre 90° et 180°, dit hyperdroit."},{"t":"Un axe hypergauche s'accompagne d'une négativité de D2","ok":true,"why":"Lorsque D1 positif et aVF négatif avec D2 également négatif, l'axe est hypergauche."},{"t":"L'axe normal du QRS se situe entre -90° et -180°","ok":false,"why":"L'axe normal est entre -30° et +90°, pas dans la zone extrême -90°/-180°."},{"t":"D1 et aVF négatifs correspondent à un axe extrême","ok":true,"why":"Ce cadran correspond à un axe extrême entre -90° et -180°."}],"explanation":"La méthode des quadrants D1/aVF permet de classer rapidement l'axe : normal, hyperdroit, hypergauche (selon D2) ou extrême.","src":"p. 375"},{"id":"231-qcm-011","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"stem":"Concernant les dérivations de l'ECG, quelle proposition est exacte ?","options":[{"t":"Les dérivations précordiales sont numérotées de V1 à V9","ok":true,"why":"Le livre précise que les dérivations précordiales vont de V1 à V9, avec V3R/V4R en complément possible."},{"t":"Les dérivations frontales explorent le plan horizontal","ok":false,"why":"Ce sont les dérivations précordiales qui explorent le plan horizontal ; les dérivations frontales explorent le plan vertical."},{"t":"aVR, aVL et aVF sont des dérivations bipolaires des membres","ok":false,"why":"aVR, aVL et aVF sont des dérivations unipolaires des membres, associées aux dérivations bipolaires D1, D2, D3."},{"t":"V3R et V4R remplacent systématiquement V1 et V2","ok":false,"why":"V3R et V4R sont des dérivations complémentaires utilisées chez l'enfant ou en cas de suspicion de SCA, elles ne remplacent pas V1-V2."},{"t":"Le plan horizontal est exploré par D1, D2 et D3","ok":false,"why":"D1, D2 et D3 explorent le plan frontal (vertical), pas le plan horizontal."}],"explanation":"Seules les dérivations précordiales V1 à V9 explorent le plan horizontal ; D1-D2-D3 et les dérivations unipolaires aVR/aVL/aVF explorent le plan frontal.","src":"p. 371"},{"id":"231-qcm-012","type":"QRM","rank":"A","objective":"231-obj-01","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la polarité du signal électrocardiographique, quelles propositions sont exactes ?","options":[{"t":"Une onde de dépolarisation qui se dirige vers l'électrode s'inscrit comme une positivité","ok":true,"why":"C'est le principe de base de la genèse du signal ECG rappelé par le livre."},{"t":"Une onde de dépolarisation qui s'éloigne de l'électrode s'inscrit comme une négativité","ok":true,"why":"C'est le principe symétrique du précédent."},{"t":"Un courant perpendiculaire à l'électrode donne une déflexion isodiphasique","ok":true,"why":"Le livre décrit ce cas particulier comme positif puis négatif."},{"t":"L'onde T normale a une polarité opposée à celle du QRS sur une même dérivation","ok":false,"why":"Au contraire, l'onde T est normalement concordante avec le QRS (T positive si QRS positif, et inversement)."},{"t":"Cette concordance T-QRS s'explique par le sens inverse de la dépolarisation et de la repolarisation transmurales","ok":true,"why":"La dépolarisation va de l'endocarde vers l'épicarde alors que la repolarisation va de l'épicarde vers l'endocarde, ce qui explique la concordance."}],"explanation":"Le signal ECG dépend de l'orientation du front de dépolarisation par rapport à l'électrode ; la concordance T-QRS normale s'explique par le sens opposé de la dépolarisation et de la repolarisation transmurales.","src":"p. 371"},{"id":"231-qcm-013","type":"QRM","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Concernant l'étalonnage standard de l'enregistrement ECG, quelle proposition est exacte ?","options":[{"t":"La vitesse standard est de 25 mm/s, soit un grand carreau pour 200 ms","ok":true,"why":"C'est la vitesse standard rappelée par le livre, avec un grand carreau (5 mm) valant 200 ms."},{"t":"La vitesse standard est de 50 mm/s","ok":false,"why":"La vitesse standard habituelle est de 25 mm/s, pas 50 mm/s."},{"t":"Un grand carreau correspond à 40 ms","ok":false,"why":"Un grand carreau (5 mm) correspond à 200 ms ; c'est un petit carreau (1 mm) qui vaut 40 ms."},{"t":"1 mm d'amplitude correspond à 1 mV","ok":false,"why":"En amplitude normale, 1 mm correspond à 0,1 mV, pas 1 mV."},{"t":"Un petit carreau correspond à 200 ms","ok":false,"why":"Un petit carreau (1 mm) correspond à 40 ms ; 200 ms correspond à un grand carreau."}],"explanation":"L'étalonnage standard est 25 mm/s (grand carreau = 200 ms, petit carreau = 40 ms) et 1 mm = 0,1 mV en amplitude.","src":"p. 375"},{"id":"231-qcm-014","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant l'onde Q physiologique et les critères d'amplitude normaux, quelles propositions sont exactes ?","options":[{"t":"Une onde Q physiologique dure moins de 40 ms","ok":true,"why":"C'est un des deux critères de l'onde Q physiologique donnés par le livre."},{"t":"Une onde Q physiologique représente moins d'1/3 de l'amplitude du QRS","ok":true,"why":"C'est le second critère de l'onde Q physiologique."},{"t":"Le critère de Sokolov normal est inférieur à 35 mm","ok":true,"why":"Le livre indique ce seuil comme critère d'amplitude normale des ondes lors de la vérification morphologique de l'ECG."},{"t":"Une onde Q large (> 40 ms) et profonde (> 1/3 du QRS) évoque une séquelle de nécrose","ok":true,"why":"C'est la définition de l'onde Q pathologique de nécrose donnée par le livre."},{"t":"Une onde Q physiologique est toujours présente en V1","ok":false,"why":"Aucune règle du livre n'impose la présence systématique d'une onde Q physiologique en V1."}],"explanation":"L'onde Q physiologique est fine (< 40 ms) et peu profonde (< 1/3 du QRS) ; au-delà, elle évoque une séquelle de nécrose. Le critère de Sokolov normal est < 35 mm.","src":"p. 375-377"},{"id":"231-qcm-015","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant la repolarisation normale, quelle proposition est exacte ?","options":[{"t":"Les ondes T sont positives dans toutes les dérivations sauf en aVR et V1","ok":true,"why":"C'est le critère de repolarisation normale rappelé pour affirmer qu'un ECG est normal (avec parfois D3 et aVL isolément)."},{"t":"Le QT normal doit être supérieur à 450 ms","ok":false,"why":"C'est l'inverse : le QT normal doit être inférieur à 450 ms."},{"t":"Le segment ST doit être nettement sous-décalé au point J chez le sujet normal","ok":false,"why":"Le segment ST doit être isoélectrique au point J chez le sujet normal, pas sous-décalé."},{"t":"Une onde T négative isolée en D3 est toujours pathologique","ok":false,"why":"Une négativité isolée de l'onde T en D3 (et parfois aVL) peut être observée chez le sujet normal."},{"t":"Le point J ne peut jamais être sus-décalé chez le sujet sain","ok":false,"why":"Chez le sujet jeune, un sus-décalage physiologique du point J de V1 à V4 est possible (repolarisation précoce physiologique)."}],"explanation":"La repolarisation normale se caractérise par un point J et un ST isoélectriques, des ondes T positives partout sauf aVR/V1 (et parfois D3/aVL), et un QT < 450 ms.","src":"p. 377"},{"id":"231-qru-001","type":"QRU","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":1,"stem":"Quelle est la fréquence cardiaque de repos considérée comme normale chez l'adulte ?","options":[{"t":"Moins de 60 bpm","ok":false,"why":"En dessous de 60 bpm, on parle de bradycardie, pas de fréquence normale."},{"t":"Entre 60 et 100 bpm","ok":true,"why":"C'est la valeur normale rappelée par le livre pour la fréquence cardiaque de repos de l'adulte."},{"t":"Entre 100 et 150 bpm","ok":false,"why":"Au-delà de 100 bpm, on parle de tachycardie."},{"t":"Plus de 150 bpm","ok":false,"why":"C'est une fréquence largement tachycarde, très éloignée de la normale."},{"t":"Elle varie sans aucune limite définie","ok":false,"why":"Le livre donne une fourchette précise (60-100 bpm) qui définit la normalité."}],"explanation":"La fréquence cardiaque de repos normale de l'adulte est comprise entre 60 et 100 bpm ; en dessous c'est une bradycardie, au-dessus une tachycardie.","src":"p. 376"},{"id":"231-qru-002","type":"QRU","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Quel est l'axe normal de l'onde P sinusale ?","options":[{"t":"0°","ok":false,"why":"Ce n'est pas l'axe normal de l'onde P ; à 0° la positivité maximale serait en D1."},{"t":"30°","ok":false,"why":"Ce n'est pas la valeur retenue par le livre pour l'axe de l'onde P normale."},{"t":"60°","ok":true,"why":"L'onde P normale a un axe à 60°, avec une positivité maximale en D2, car le nœud sinusal est situé en haut à droite de l'oreillette droite."},{"t":"90°","ok":false,"why":"Un axe à 90° correspondrait à une positivité maximale en aVF, ce n'est pas la valeur normale de l'onde P."},{"t":"120°","ok":false,"why":"Cette valeur est trop élevée pour l'axe normal de l'onde P sinusale."}],"explanation":"L'onde P sinusale normale a un axe de 60°, avec une positivité maximale en D2, du fait de la position du nœud sinusal en haut à droite de l'oreillette.","src":"p. 375"},{"id":"231-qru-003","type":"QRU","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"stem":"Pour mesurer l'intervalle QT, quelles dérivations le livre recommande-t-il de privilégier ?","options":[{"t":"D1","ok":false,"why":"D1 n'est pas la dérivation recommandée, l'onde T y est rarement la plus ample."},{"t":"aVR","ok":false,"why":"aVR n'est pas adaptée, l'onde T y est habituellement négative et peu ample."},{"t":"V2-V3","ok":true,"why":"Le livre recommande de choisir les dérivations où l'onde T est la plus ample et la plus longue, souvent V2-V3."},{"t":"V6","ok":false,"why":"V6 n'est pas la dérivation privilégiée par le livre pour cette mesure."},{"t":"aVL","ok":false,"why":"aVL n'est pas la dérivation recommandée pour mesurer le QT."}],"explanation":"Pour mesurer le QT, il faut choisir la dérivation où l'onde T est la plus ample et la plus longue, souvent V2-V3, et tracer la tangente à l'onde T.","src":"p. 376"},{"id":"231-qru-004","type":"QRU","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"stem":"Quelle formule permet de calculer le QT corrigé (QTc) selon Bazett ?","options":[{"t":"QTc = QT mesuré / racine carrée de l'intervalle RR (en secondes)","ok":true,"why":"C'est la formule de Bazett rappelée par le livre pour normaliser le QT à une fréquence cardiaque de 60 bpm."},{"t":"QTc = QT mesuré × fréquence cardiaque","ok":false,"why":"Ce n'est pas la formule de Bazett donnée par le livre."},{"t":"QTc = QT mesuré − intervalle RR","ok":false,"why":"La formule de Bazett est une division par la racine carrée du RR, pas une soustraction."},{"t":"QTc = QT mesuré / fréquence cardiaque","ok":false,"why":"La formule utilise l'intervalle RR en secondes sous racine carrée, pas la fréquence cardiaque directement."},{"t":"QTc = QT mesuré × intervalle RR","ok":false,"why":"Ce n'est pas la formule de Bazett, qui est une division et non une multiplication."}],"explanation":"La formule de Bazett normalise le QT mesuré en le divisant par la racine carrée de l'intervalle RR (en secondes), pour obtenir une valeur comparable à une fréquence de 60 bpm.","src":"p. 377"},{"id":"231-qru-005","type":"QRU","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":3,"stem":"Un homme de 58 ans a un ECG systématique : QRS à 140 ms, en V1 un aspect globalement positif de type RsR', en V6 un aspect qRs avec une onde S traînante. Quel est le diagnostic le plus probable ?","options":[{"t":"Bloc complet de branche droite","ok":true,"why":"L'association QRS > 120 ms, RsR' positif en V1 et qRs avec onde S traînante en V6 est la définition du bloc complet de branche droite."},{"t":"Bloc complet de branche gauche","ok":false,"why":"Le BBG donne un QRS globalement négatif en V1 (rS ou QS), pas un aspect RsR' positif."},{"t":"Hémibloc antérieur gauche isolé","ok":false,"why":"Un hémibloc isolé n'élargit que modérément le QRS et ne donne pas cet aspect RsR' en V1."},{"t":"Bloc atrioventriculaire du 1er degré","ok":false,"why":"Un BAV1 se définit par un allongement du PR, pas par la morphologie du QRS décrite ici."},{"t":"Extrasystole ventriculaire isolée","ok":false,"why":"Rien dans l'énoncé n'évoque un battement prématuré isolé, il s'agit d'un aspect stable et systématique du QRS."}],"explanation":"L'aspect RsR' positif en V1 associé à un qRs avec onde S traînante en V6 et un QRS > 120 ms définit le bloc complet de branche droite.","src":"p. 378-379"},{"id":"231-qroc-002","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle formule pratique permet d'estimer la fréquence cardiaque à partir du nombre de grands carreaux séparant deux QRS ?","answer":"FC = 300 / nombre de grands carreaux","accept":["300 divisé par le nombre de grands carreaux"],"keywords":["300","grands carreaux"],"explanation":"Un intervalle RR d'un grand carreau correspond à 300 bpm, de deux grands carreaux à 150 bpm, etc., d'où la formule FC = 300/nombre de grands carreaux.","src":"p. 376"},{"id":"231-qroc-003","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":1,"question":"Quel intervalle explore la totalité de la conduction depuis la sortie du nœud sinusal jusqu'aux extrémités du réseau de Purkinje ?","answer":"L'intervalle PR","accept":["intervalle PR","espace PR"],"keywords":["pr"],"explanation":"L'intervalle PR (du début de l'onde P au début du QRS) explore toute la conduction, pas seulement la traversée du NAV.","src":"p. 376"},{"id":"231-qroc-004","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"question":"Quelle formule est utilisée pour corriger l'intervalle QT en fonction de la fréquence cardiaque ?","answer":"La formule de Bazett","accept":["Bazett","formule de Bazett"],"keywords":["bazett"],"explanation":"La formule de Bazett normalise le QT à une fréquence de référence de 60 bpm en divisant le QT mesuré par la racine carrée du RR en secondes.","src":"p. 377"},{"id":"231-qroc-005","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel est l'axe normal du QRS en pratique clinique ?","answer":"Entre -30° et +90°","accept":["-30 à 90 degrés","de -30° à +90°"],"keywords":["-30","90"],"explanation":"L'axe normal du QRS, en valeurs arrondies utilisées en pratique, est situé entre -30° et +90°.","src":"p. 375"},{"id":"231-qroc-006","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"question":"Quelles sont les deux dérivations utilisées dans la méthode rapide de détermination de l'axe du QRS ?","answer":"D1 et aVF","accept":["DI et aVF","D1-aVF"],"keywords":["d1","avf"],"explanation":"La méthode rapide regarde la polarité de D1 et aVF pour situer l'axe dans l'un des quatre cadrans possibles.","src":"p. 375"},{"id":"231-qroc-007","type":"QROC","rank":"B","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"question":"Comment se nomment les dérivations obtenues par un repositionnement particulier des électrodes pour mieux visualiser l'activité atriale ?","answer":"Les dérivations de Lewis","accept":["dérivations de Lewis","Lewis leads"],"keywords":["lewis"],"explanation":"Les dérivations de Lewis, avec un positionnement particulier de l'électrode rouge et jaune, démasquent l'activité atriale en D1.","src":"p. 373"},{"id":"231-qroc-009","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel territoire cardiaque est exploré par les dérivations V7, V8 et V9 ?","answer":"Le territoire postérieur du ventricule gauche","accept":["postérieur","territoire postérieur basal et inférieur"],"keywords":["posterieur"],"explanation":"V7 à V9 explorent la face basale et inférieure (postérieure) du ventricule gauche.","src":"p. 374"},{"id":"231-qroc-010","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"question":"À partir de quelle durée de QRS parle-t-on de bloc de branche complet plutôt qu'incomplet ?","answer":"120 ms","accept":["> 120 ms","120 millisecondes"],"keywords":["120"],"explanation":"Un bloc de branche est dit complet lorsque le QRS dépasse 120 ms ; entre 110 et 120 ms, il est qualifié d'incomplet.","src":"p. 378"},{"id":"231-qroc-011","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"question":"Quel aspect caractéristique retrouve-t-on en V1 dans le bloc complet de branche droite ?","answer":"Un aspect RsR' avec QRS globalement positif","accept":["RsR'","aspect RSR prime"],"keywords":["rsr","v1"],"explanation":"Le BBD complet se définit en V1 par un QRS globalement positif avec un aspect RsR', et en V6 par un aspect qRs avec onde S traînante.","src":"p. 378-379"},{"id":"231-qroc-012","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle est la valeur seuil normale du critère de Sokolov utilisée pour vérifier la morphologie de l'ECG ?","answer":"Moins de 35 mm","accept":["< 35 mm","inférieur à 35 mm"],"keywords":["35"],"explanation":"Le critère de Sokolov doit rester inférieur à 35 mm pour que l'amplitude des ondes soit considérée comme normale.","src":"p. 377"},{"id":"231-open-01","type":"OPEN","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Un homme de 45 ans, asymptomatique, réalise un ECG systématique dans le cadre d'un bilan préopératoire. Le tracé montre un rythme régulier à 72 bpm avec une onde P positive en D1, D2 et aVF précédant chaque QRS, un espace PR à 160 ms, des QRS fins à 90 ms d'axe +45°, un segment ST isoélectrique, des ondes T positives sauf en aVR, et un QT à 400 ms. Décrivez la démarche systématique permettant d'affirmer que cet ECG est normal, en analysant successivement le rythme, la conduction, la repolarisation et la morphologie.","rubric":[{"point":"Rythme : onde P positive en D1/D2/aVF, un QRS après chaque P et une P avant chaque QRS, fréquence 60-100 bpm → rythme sinusal normal","weight":2},{"point":"Conduction : durée de P < 120 ms, PR 120-200 ms (ici 160 ms, normal)","weight":1.5},{"point":"Conduction : QRS fins 70-110 ms (ici 90 ms) avec axe entre -30° et +90° (ici +45°, normal)","weight":1.5},{"point":"Repolarisation : point J et segment ST isoélectriques, ondes T positives sauf aVR/V1, QT < 450 ms (ici 400 ms)","weight":2},{"point":"Morphologie : amplitude des ondes P et QRS normale (Sokolov < 35 mm), transition R/S normale en précordial, absence d'onde Q de nécrose","weight":1.5},{"point":"Conclusion explicite : ECG normal car les quatre étapes (rythme, conduction, repolarisation, morphologie) sont toutes normales","weight":1.5}],"model":"**Rythme** : l'onde P est positive en D1, D2 et aVF, chaque QRS est précédé d'une onde P et chaque onde P est suivie d'un QRS, à une fréquence de 72 bpm (60-100 bpm) : il s'agit d'un rythme sinusal normal.\n\n**Conduction** : le PR à 160 ms est dans la norme (120-200 ms) et les QRS fins à 90 ms respectent la fourchette normale (70-110 ms) avec un axe à +45°, compris entre -30° et +90°.\n\n**Repolarisation** : le segment ST est isoélectrique au point J, les ondes T sont positives dans toutes les dérivations sauf en aVR (physiologique), et le QT à 400 ms est inférieur à 450 ms.\n\n**Morphologie** : en l'absence de précision contraire, on vérifie l'amplitude des ondes P et des QRS (Sokolov < 35 mm), une transition R/S normale de V1 à V6, et l'absence d'onde Q de nécrose (large > 40 ms et profonde > 1/3 du QRS).\n\n**Conclusion** : les quatre étapes systématiques étant toutes normales, cet ECG est normal.","src":"p. 376-378"},{"id":"231-open-02","type":"OPEN","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Expliquez la méthode rapide de détermination de l'axe du QRS à partir de la polarité de D1 et aVF, puis appliquez-la au cas suivant : D1 positif, aVF négatif, D2 négatif.","rubric":[{"point":"Principe : regarder la polarité de D1 et aVF pour situer l'axe dans l'un des quatre cadrans","weight":2},{"point":"Cadran D1+/aVF+ : axe normal entre 0 et 90°","weight":1},{"point":"Cadran D1+/aVF- : axe entre 0 et -90°, à préciser avec D2 (normal si D2+, hypergauche si D2-)","weight":2},{"point":"Cadran D1-/aVF+ : axe hyperdroit entre 90 et 180°","weight":1},{"point":"Cadran D1-/aVF- : axe extrême entre -90 et -180°","weight":1},{"point":"Application au cas donné : D1+, aVF-, D2- → axe hypergauche","weight":2}],"model":"La méthode rapide consiste à regarder la polarité de D1 et aVF pour situer l'axe du QRS dans l'un des quatre cadrans du plan frontal :\n- D1 et aVF positifs → axe normal entre 0 et 90° ;\n- D1 positif et aVF négatif → axe entre 0 et -90° ; on précise alors avec D2 : si D2 est positif, l'axe reste normal (entre 0 et -30°), sinon l'axe est hypergauche ;\n- D1 négatif et aVF positif → axe hyperdroit entre 90 et 180° ;\n- D1 et aVF négatifs → axe extrême entre -90° et -180°.\n\n**Application** : D1 positif et aVF négatif place l'axe dans le cadran 0 à -90°. Comme D2 est négatif, l'axe n'est pas simplement normal mais **hypergauche** (au-delà de -30°).","src":"p. 375"},{"id":"231-open-04","type":"OPEN","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Énumérez les critères électrocardiographiques du bloc complet de branche droite et expliquez pourquoi ce diagnostic peut, à tort, faire évoquer une autre pathologie si l'analyse est trop rapide.","rubric":[{"point":"Critère 1 : durée du QRS > 120 ms","weight":1.5},{"point":"Critère 2 : aspect RsR' globalement positif en V1","weight":1.5},{"point":"Critère 3 : aspect qRs avec onde S traînante en V6","weight":1.5},{"point":"Nécessité de vérifier d'abord le rythme atrial avant de décrire un trouble de conduction","weight":1.5},{"point":"Risque de méconnaître une tachycardie supraventriculaire associée si l'analyse se limite au QRS large","weight":2}],"model":"Le bloc complet de branche droite se reconnaît sur trois critères : une durée de QRS supérieure à 120 ms, un aspect globalement positif de type RsR' en V1, et un aspect qRs avec une onde S traînante et arrondie en V6.\n\nAvant de décrire ce trouble de conduction, il faut toujours commencer par analyser le rythme atrial : l'association d'une tachycardie supraventriculaire et d'un bloc de branche n'est pas rare, et une analyse trop rapide centrée sur le seul élargissement du QRS risquerait de faire passer à côté d'un trouble du rythme supraventriculaire sous-jacent.","src":"p. 378"},{"id":"231-qcm-101","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant le bloc complet de branche gauche (BBG), quelles propositions sont exactes ?","options":[{"t":"La durée du QRS est supérieure à 120 ms","ok":true,"why":"C'est le critère de durée commun à tous les blocs de branche complets."},{"t":"En V1, le QRS est globalement négatif, en aspect rS ou QS","ok":true,"why":"C'est l'aspect typique du BBG en V1, à l'opposé du BBD."},{"t":"En V6, D1 et aVL, on observe un notch avec le plus souvent une onde R exclusive","ok":true,"why":"Le notch correspond à l'activation successive du septum puis de la paroi latérale tardive."},{"t":"En V1, le QRS est globalement positif avec un aspect RsR'","ok":false,"why":"Cet aspect RsR' positif en V1 est celui du bloc de branche droite, pas du BBG."},{"t":"Le BBG ne modifie jamais l'analyse de la repolarisation","ok":false,"why":"Au contraire, le BBG induit un trouble de la repolarisation avec discordance appropriée, rendant l'interprétation du territoire antérieur difficile."}],"explanation":"Le BBG complet associe QRS > 120 ms, aspect rS/QS négatif en V1, et notch avec onde R exclusive en V6, D1, aVL ; il s'accompagne d'un trouble secondaire de la repolarisation.","src":"p. 380"},{"id":"231-qcm-102","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Concernant l'interprétation d'un ECG avec des QRS larges suspects de bloc de branche, quelle proposition est exacte ?","options":[{"t":"Il faut vérifier dans l'ordre : rythme sinusal, durée du QRS, aspect en V1, aspect en V6","ok":true,"why":"C'est la démarche d'interprétation systématique proposée par le livre pour les blocs de branche."},{"t":"Un QRS globalement positif en V1 oriente vers un bloc de branche gauche","ok":false,"why":"Un QRS positif en V1 oriente au contraire vers un bloc de branche droit."},{"t":"Un QRS globalement négatif en V1 oriente vers un bloc de branche droit","ok":false,"why":"Un QRS négatif en V1 oriente au contraire vers un bloc de branche gauche."},{"t":"L'aspect en V6 doit être identique à celui de V1","ok":false,"why":"L'aspect en V6 doit être inverse (en miroir) de celui observé en V1."},{"t":"Il n'est pas nécessaire de vérifier le rythme atrial avant de décrire le trouble de conduction","ok":false,"why":"Il faut au contraire toujours commencer par décrire le rythme atrial pour ne pas passer à côté d'une tachycardie supraventriculaire associée."}],"explanation":"La démarche systématique est : rythme sinusal, durée QRS > 120 ms, aspect en V1 (positif = BBD probable, négatif = BBG probable), puis vérification de l'aspect inverse en V6.","src":"p. 381"},{"id":"231-qcm-103","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","urgence","pièges"],"difficulty":3,"stem":"Concernant la discordance appropriée observée dans les blocs de branche, quelles propositions sont exactes ?","options":[{"t":"Elle correspond à une polarité opposée entre le QRS et l'onde T","ok":true,"why":"C'est la définition de la discordance appropriée : la polarité des ondes T et des QRS n'est plus concordante lorsque le QRS est large."},{"t":"Si le QRS est positif, l'onde T est négative avec un petit sous-décalage de ST","ok":true,"why":"C'est l'aspect décrit par le livre dans cette situation."},{"t":"Si le QRS est négatif, l'onde T est positive avec un petit sus-décalage de ST","ok":true,"why":"C'est l'aspect symétrique décrit par le livre."},{"t":"Cette discordance appropriée ne peut jamais faire évoquer à tort un syndrome coronarien aigu","ok":false,"why":"Au contraire, associée à un ST ascendant en V1-V2 dans le BBG, elle peut faire évoquer à tort un SCA avec sus-décalage."},{"t":"Devant une douleur thoracique persistante avec BBG, le diagnostic d'infarctus antérieur doit être évoqué sans attendre la troponine","ok":true,"why":"Le livre recommande une évaluation cardiologique rapide sans attendre le dosage de troponine dans ce contexte."}],"explanation":"La discordance appropriée (T de polarité opposée au QRS large) est normale dans les blocs de branche, mais rend l'interprétation du territoire antérieur difficile en cas de BBG, imposant une évaluation clinique rapide devant une douleur thoracique.","trap":"Ne pas confondre discordance appropriée physiologique (due au trouble de dépolarisation) avec une authentique ischémie ; la clinique prime.","src":"p. 381"},{"id":"231-qcm-104","type":"QRM","rank":"B","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant les hémiblocs (blocs fasciculaires), quelles propositions sont exactes ?","options":[{"t":"L'hémibloc antérieur gauche (HBAG) est plus fréquent que l'hémibloc postérieur gauche (HBPG)","ok":true,"why":"La branche antérieure gauche est superficielle et de petite taille donc plus fragile, ce qui rend l'HBAG plus fréquent que l'HBPG."},{"t":"L'HBAG se traduit par une déviation axiale du QRS à gauche au-delà de -30°","ok":true,"why":"C'est le critère de déviation axiale de l'HBAG donné par le livre, avec négativité de D2."},{"t":"L'HBPG se traduit par une déviation axiale du QRS à droite au-delà de +90° avec un aspect S1Q3","ok":true,"why":"C'est le critère de l'HBPG, en l'absence de pathologie du ventricule droit ou d'infarctus latéral."},{"t":"Les hémiblocs entraînent classiquement un élargissement majeur du QRS au-delà de 140 ms","ok":false,"why":"L'élargissement est très modéré (> 110 ms), sauf association à un autre bloc de branche ou cardiopathie marquée."},{"t":"Devant un DI négatif, le premier diagnostic à évoquer est toujours l'HBPG","ok":false,"why":"Le livre précise qu'il faut d'abord éliminer une inversion de positionnement des électrodes frontales, plus fréquente que l'HBPG."}],"explanation":"HBAG (fréquent) : axe gauche au-delà de -30°, négativité de D2 ; HBPG (rare) : axe droit au-delà de +90°, aspect S1Q3, après avoir éliminé une inversion d'électrodes.","trap":"Un DI négatif doit d'abord faire suspecter une inversion des électrodes des membres avant d'évoquer un HBPG.","src":"p. 382-383"},{"id":"231-qcm-105","type":"QRM","rank":"B","objective":"231-obj-06","tags":["diagnostic","complications","urgence"],"difficulty":3,"stem":"Concernant le bloc bifasciculaire, quelles propositions sont exactes ?","options":[{"t":"Il associe un hémibloc (antérieur ou postérieur gauche) à un bloc de branche droit","ok":true,"why":"C'est la définition sémiologique du bloc bifasciculaire donnée par le livre : HBAG + BBD ou HBPG + BBD."},{"t":"Le QRS est alors typiquement supérieur à 120 ms","ok":true,"why":"L'addition de la sémiologie des deux troubles donne un QRS supérieur à 120 ms."},{"t":"Il fait craindre un risque accru de bloc atrioventriculaire complet infrahissien","ok":true,"why":"Le bloc bifasciculaire attire l'attention sur le risque que la troisième branche restante dysfonctionne, avec risque de BAV complet infrahissien."},{"t":"Une syncope associée à un bloc bifasciculaire ne nécessite pas d'hospitalisation en urgence","ok":false,"why":"Au contraire, syncope + bloc bifasciculaire impose une hospitalisation en cardiologie avec télémétrie selon le livre."},{"t":"Un BBG complet isolé peut contribuer à une désynchronisation ventriculaire aggravant une cardiopathie","ok":true,"why":"Le BBG complet peut altérer l'efficacité hémodynamique par désynchronisation, ce qui justifie sa correction en cas de signes d'insuffisance cardiaque."}],"explanation":"Le bloc bifasciculaire (hémibloc + BBD) traduit une atteinte de deux des trois branches, avec un risque de BAV complet infrahissien justifiant une hospitalisation en urgence en cas de syncope.","trap":"Toute syncope chez un patient porteur d'un bloc bifasciculaire est une urgence cardiologique avec télémétrie.","src":"p. 383"},{"id":"231-qcm-106","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant le bloc atrioventriculaire du premier degré (BAV1), quelle proposition est exacte ?","options":[{"t":"Il correspond à un allongement fixe et constant de l'espace PR au-delà de 200 ms, sans onde P bloquée","ok":true,"why":"C'est la définition du BAV1 illustrée dans le livre : PR long et constant, toutes les ondes P sont conduites."},{"t":"Il se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée","ok":false,"why":"C'est la définition du BAV2 Mobitz 1 (Wenckebach), pas du BAV1."},{"t":"Il se caractérise par une dissociation atrioventriculaire complète","ok":false,"why":"C'est la définition du BAV3 (complet), pas du BAV1."},{"t":"Une onde P sur deux y est bloquée","ok":false,"why":"C'est la définition du BAV2 2/1, pas du BAV1 où toutes les ondes P sont conduites."},{"t":"Le PR y est variable d'un cycle à l'autre","ok":false,"why":"Dans le BAV1, le PR est au contraire fixe et constant, seulement allongé."}],"explanation":"Le BAV1 se définit par un allongement fixe et constant du PR (> 200 ms) sans aucune onde P bloquée : toutes les ondes P sont conduites, mais avec retard.","src":"p. 385-386"},{"id":"231-qcm-107","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant le bloc atrioventriculaire du 2e degré Mobitz 1 (Luciani-Wenckebach), quelles propositions sont exactes ?","options":[{"t":"Il se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée","ok":true,"why":"C'est la définition classique du phénomène de Wenckebach."},{"t":"Il est habituellement de siège suprahissien","ok":true,"why":"Le livre le classe parmi les BAV2 suprahissiens, par opposition au Mobitz 2 infrahissien."},{"t":"Il se caractérise par un PR constant puis une onde P bloquée de façon inopinée","ok":false,"why":"C'est la définition du BAV2 Mobitz 2, pas du Mobitz 1."},{"t":"Une onde P prématurée peut parfois être bloquée en raison d'une extrasystole atriale et non d'un vrai trouble conductif","ok":true,"why":"Le livre signale ce piège d'interprétation sur un exemple de bloc du 2e degré."},{"t":"Il correspond à une dissociation atrioventriculaire complète","ok":false,"why":"La dissociation complète caractérise le BAV3, pas le Mobitz 1."}],"explanation":"Le BAV2 Mobitz 1 (Wenckebach) est un allongement progressif du PR jusqu'à une onde P bloquée, habituellement suprahissien ; attention à ne pas confondre une onde P bloquée avec une extrasystole atriale bloquée.","trap":"Une onde P bloquée plus précoce que les autres peut être une extrasystole atriale bloquée, et non un vrai BAV2.","src":"p. 385-386"},{"id":"231-qcm-108","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Concernant le bloc atrioventriculaire complet (BAV3), quelles propositions sont exactes ?","options":[{"t":"Il existe une dissociation atrioventriculaire complète","ok":true,"why":"C'est la définition du BAV3 : aucune onde P n'est conduite aux ventricules."},{"t":"Les ondes P restent régulières et à une fréquence normale","ok":true,"why":"Le livre précise que dans le BAV, les ondes P sont régulières et à une fréquence normale, contrairement à l'activité ventriculaire."},{"t":"Un échappement à QRS fins traduit un bloc de siège nodal (suprahissien)","ok":true,"why":"Un rythme d'échappement à QRS fins, régulier et lent traduit un échappement jonctionnel, donc un bloc nodal."},{"t":"Le rythme ventriculaire d'échappement est toujours rapide et irrégulier","ok":false,"why":"Au contraire, le rythme d'échappement en cas de BAV3 est régulier et lent."},{"t":"Toutes les ondes P sont suivies d'un QRS","ok":false,"why":"C'est l'inverse : dans le BAV3, aucune onde P n'est suivie d'un QRS, du fait de la dissociation complète."}],"explanation":"Le BAV3 associe une dissociation atrioventriculaire complète, des ondes P régulières non conduites, et un rythme d'échappement régulier dont la largeur du QRS oriente vers le siège du bloc (fin = nodal, large = infrahissien).","src":"p. 387"},{"id":"231-qcm-109","type":"QRM","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant la dysfonction sinusale, quelles propositions sont exactes ?","options":[{"t":"Elle peut se manifester par une asystole avec un tracé plat sans activité cardiaque visible","ok":true,"why":"C'est un des aspects les plus évidents de dysfonction sinusale décrits par le livre."},{"t":"Elle peut se manifester par une pause correspondant au double de l'intervalle PP ou RR normal","ok":true,"why":"C'est l'aspect du bloc sinoatrial du 2e degré, avec un manque complet d'un cycle P-QRS-T."},{"t":"En cas de dysfonction marquée, un rythme d'échappement jonctionnel peut apparaître","ok":true,"why":"Lorsque le nœud sinusal défaille fortement, un pacemaker jonctionnel de réserve prend le relais."},{"t":"L'onde P rétrograde d'un échappement jonctionnel est positive en D2","ok":false,"why":"Elle est au contraire négative en D2, car l'activation atriale rétrograde se fait de bas en haut à partir de la jonction."},{"t":"La dysfonction sinusale ne peut jamais s'accompagner d'ondes T négatives dans les précordiales","ok":false,"why":"Le livre montre un exemple de bloc sinoatrial avec ondes T négatives précordiales, nécessitant d'éliminer une ischémie myocardique en premier lieu."}],"explanation":"La dysfonction sinusale regroupe l'asystole, les pauses par bloc sinoatrial (durée double du cycle normal) et, si marquée, l'échappement jonctionnel avec onde P rétrograde négative en D2.","src":"p. 387-388"},{"id":"231-qcm-110","type":"QRM","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Devant une bradycardie (FC des QRS < 50 bpm), quelle proposition concernant l'algorithme diagnostique est exacte ?","options":[{"t":"Il faut analyser les ondes P pour orienter le diagnostic étiologique","ok":true,"why":"Le livre propose un algorithme centré sur l'analyse des ondes P devant une bradycardie."},{"t":"Des ondes P trop lentes ou inexistantes orientent vers une dysfonction sinusale","ok":true,"why":"C'est la branche « problème = nœud sinusal » de l'algorithme du livre."},{"t":"Des ondes P régulières à fréquence normale mais plus nombreuses que les QRS orientent vers un bloc atrioventriculaire","ok":true,"why":"C'est la branche « problème = passage au ventricule » de l'algorithme, correspondant à un BAV."},{"t":"Seul le nœud atrioventriculaire peut être responsable d'une bradycardie","ok":false,"why":"Deux structures peuvent être en cause : le nœud sinusal (dysfonction sinusale) ou le nœud atrioventriculaire (BAV2 ou 3)."},{"t":"Une fibrillation atriale ne peut jamais coexister avec une bradycardie","ok":false,"why":"Le livre évoque au contraire des ondes P tachycardes (FA, flutter) avec plus d'ondes P que de QRS en cas de BAV associé."}],"explanation":"Devant une bradycardie, seules deux structures peuvent être en cause : le nœud sinusal (dysfonction sinusale, P trop lentes ou absentes) ou le nœud atrioventriculaire (BAV, plus de P que de QRS).","src":"p. 389"},{"id":"231-qcm-111","type":"QRM","rank":"B","objective":"231-obj-16","tags":["traitement","ECG"],"difficulty":2,"stem":"Concernant les manœuvres vagales et l'adénosine utilisées pour l'analyse des tachycardies, quelles propositions sont exactes ?","options":[{"t":"La manœuvre de Valsalva consiste en une expiration forcée à glotte fermée","ok":true,"why":"C'est la description de la manœuvre de Valsalva donnée par le livre."},{"t":"La compression carotidienne unilatérale est contre-indiquée en cas d'athérome important ou de souffle carotidien","ok":true,"why":"C'est une contre-indication explicitement mentionnée par le livre."},{"t":"L'adénosine intraveineuse est contre-indiquée en cas d'asthme en raison d'un risque de bronchospasme","ok":true,"why":"L'adénosine peut provoquer un bronchospasme intense transitoire, même chez un sujet non asthmatique, d'où la contre-indication en cas d'asthme."},{"t":"La compression oculaire bilatérale reste recommandée en première intention","ok":false,"why":"Cette manœuvre n'est plus recommandée en raison d'un risque de décollement de rétine chez le myope."},{"t":"Ces manœuvres agissent en intensifiant le filtre atrioventriculaire du NAV","ok":true,"why":"Elles créent un bloc atrioventriculaire transitoire en intensifiant la conduction décrémentielle du NAV."}],"explanation":"Les manœuvres vagales (Valsalva, compression carotidienne unilatérale sauf contre-indication, eau froide) et l'adénosine IV intensifient transitoirement le filtre du NAV ; la compression oculaire bilatérale n'est plus recommandée.","src":"p. 390"},{"id":"231-qcm-112","type":"QRM","rank":"A","objective":"231-obj-12","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant la différenciation entre tachycardie sinusale et tachycardie supraventriculaire non sinusale, quelles propositions sont exactes ?","options":[{"t":"Dans la tachycardie sinusale, les ondes P sont positives en D1, D2, D3 et aVF","ok":true,"why":"C'est le premier critère électrocardiographique donné par le livre pour la tachycardie sinusale."},{"t":"Dans la tachycardie sinusale, la fréquence varie progressivement, contrairement à la tachycardie supraventriculaire qui varie « en marches d'escalier »","ok":true,"why":"C'est un critère évolutif décrit par le livre pour distinguer les deux mécanismes."},{"t":"Le contexte clinique (fièvre, douleur, stress) est utile pour orienter vers une tachycardie sinusale","ok":true,"why":"Une personne au repos ne doit pas être très tachycarde sans cause évidente d'augmentation du métabolisme."},{"t":"Une tachycardie sinusale se définit toujours par des QRS larges","ok":false,"why":"La tachycardie sinusale n'a pas de définition liée à la largeur du QRS ; elle se définit par l'origine sinusale du rythme rapide."},{"t":"Un massage sinocarotidien ne peut jamais aider à ce diagnostic différentiel","ok":false,"why":"Le livre indique au contraire que le massage sinocarotidien permet de mettre en évidence la variabilité de fréquence typique de la tachycardie sinusale."}],"explanation":"La tachycardie sinusale se distingue par des ondes P sinusales, une fréquence qui varie progressivement (et non en « marches d'escalier »), et un contexte clinique expliquant l'accélération.","src":"p. 390-391"},{"id":"231-qcm-113","type":"QRM","rank":"A","objective":"231-obj-13","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant la fibrillation atriale (FA), quelles propositions sont exactes ?","options":[{"t":"Elle correspond à une activation atriale anarchique","ok":true,"why":"C'est la définition physiopathologique de la FA donnée par le livre."},{"t":"Les QRS sont typiquement « irrégulièrement irréguliers »","ok":true,"why":"Les intervalles RR ne sont pas multiples d'une valeur commune, contrairement au flutter par exemple."},{"t":"La fréquence ventriculaire habituelle en l'absence de traitement est comprise entre 100 et 200 bpm","ok":true,"why":"C'est la fourchette de fréquence typique de la FA donnée par le livre pour une forme fréquente."},{"t":"En l'absence de trouble de conduction associé, les QRS sont classiquement larges","ok":false,"why":"En l'absence de bloc de branche ou de trouble de conduction intraventriculaire, les QRS sont fins dans la FA."},{"t":"L'activité atriale peut se traduire par des mailles amples ou une fine trémulation de la ligne de base","ok":true,"why":"Le livre décrit ces deux aspects possibles de l'activité atriale fibrillatoire."}],"explanation":"La FA se caractérise par une activation atriale anarchique, des QRS fins irrégulièrement irréguliers (sauf trouble de conduction associé), une fréquence ventriculaire souvent entre 100 et 200 bpm, et une activité atriale en mailles ou trémulation.","src":"p. 391-392"},{"id":"231-qcm-114","type":"QRM","rank":"B","objective":"231-obj-13","tags":["diagnostic","complications","ECG"],"difficulty":3,"stem":"Concernant les aspects complexes de la fibrillation atriale associée à un trouble de la conduction atrioventriculaire, quelle proposition est exacte ?","options":[{"t":"L'association FA et bloc atrioventriculaire complet doit être évoquée lorsque l'activité ventriculaire devient lente et régulière","ok":true,"why":"En cas de BAV complet associé à une FA, la dépolarisation ventriculaire se fait par un rythme d'échappement automatique, donc régulier et lent."},{"t":"En cas de FA associée à un BAV3, le rythme ventriculaire reste rapide et irrégulier","ok":false,"why":"C'est l'inverse : le rythme d'échappement rend l'activité ventriculaire lente et régulière malgré la FA atriale."},{"t":"Le rythme d'échappement observé dans ce contexte est de mécanisme automatique","ok":true,"why":"Le livre précise que ce rythme d'échappement est de mécanisme automatique et de fréquence régulière."},{"t":"Une FA à conduction normale présente un RR parfaitement constant","ok":false,"why":"C'est au contraire l'irrégularité du RR qui caractérise la conduction normale de la FA aux ventricules, contrairement à l'association avec un BAV3."},{"t":"La trémulation de la ligne de base en D2, D3, aVF peut être associée à ce tableau","ok":true,"why":"Le livre illustre ce cas par une FA à petites mailles avec trémulation visible en D2, D3, aVF et activité ventriculaire régulière lente."}],"explanation":"Devant une FA dont l'activité ventriculaire devient régulière et lente, il faut évoquer un BAV3 associé, avec un rythme d'échappement automatique régulier remplaçant la conduction irrégulière habituelle de la FA.","trap":"Une FA à RR régulier n'est pas une FA « normale » : elle doit faire suspecter un BAV complet associé.","src":"p. 392"},{"id":"231-qcm-115","type":"QRM","rank":"B","objective":"231-obj-16","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la fonction de « filtre » du nœud atrioventriculaire (NAV), quelles propositions sont exactes ?","options":[{"t":"Le NAV présente une conduction dite « décrémentielle »","ok":true,"why":"C'est le terme utilisé par le livre pour décrire cette fonction de filtre du NAV."},{"t":"Sans cette fonction de filtre, un flutter atrial à 300 bpm entraînerait une tachycardie ventriculaire à 300 bpm","ok":true,"why":"Le livre l'indique explicitement comme conséquence en l'absence de filtre."},{"t":"Le passage atrioventriculaire peut se faire en 1/1, 2/1, ou en alternance selon l'intensité du filtre","ok":true,"why":"Selon la fréquence atriale et l'intensité du filtre (âge, tonus vagal, médicaments), le passage peut varier de cette façon."},{"t":"L'intensité du filtre du NAV est indépendante du tonus vagal","ok":false,"why":"Le livre indique au contraire que l'intensité du filtre dépend notamment du tonus vagal, en plus de l'âge et des médicaments ralentisseurs."},{"t":"Cette fonction de filtre protège contre le risque de fibrillation ventriculaire en cas de passage en FA","ok":true,"why":"Sans ce filtre, chaque passage en FA entraînerait une fibrillation ventriculaire selon le livre."}],"explanation":"Le NAV a une fonction de filtre à conduction décrémentielle, protectrice, qui limite la transmission ventriculaire des tachycardies atriales (FA, flutter) ; son intensité dépend de l'âge, du tonus vagal et des médicaments ralentisseurs.","src":"p. 390"},{"id":"231-qru-101","type":"QRU","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Une patiente présente en V1 un aspect rS avec un QRS à 150 ms, et en V6 un notch avec onde R exclusive. Quel est le diagnostic le plus probable ?","options":[{"t":"Bloc complet de branche gauche","ok":true,"why":"L'association QRS large, aspect rS en V1 et notch avec R exclusive en V6 définit le bloc complet de branche gauche."},{"t":"Bloc complet de branche droite","ok":false,"why":"Le BBD donne un aspect RsR' positif en V1, pas un aspect rS négatif."},{"t":"Hémibloc antérieur gauche isolé","ok":false,"why":"Un hémibloc isolé n'entraîne pas cet aspect en V1/V6 ni un élargissement aussi marqué du QRS."},{"t":"Bloc atrioventriculaire du 2e degré","ok":false,"why":"Un BAV2 se définit par la relation P-QRS, pas par la morphologie du QRS décrite ici."},{"t":"Rythme jonctionnel","ok":false,"why":"Rien dans l'énoncé n'évoque l'absence d'onde P ou une origine jonctionnelle du rythme."}],"explanation":"L'aspect rS/QS négatif en V1 associé à un notch avec onde R exclusive en V6/D1/aVL et un QRS > 120 ms définit le bloc complet de branche gauche.","src":"p. 380"},{"id":"231-qru-102","type":"QRU","rank":"B","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Quelle déviation axiale caractérise l'hémibloc antérieur gauche (HBAG) ?","options":[{"t":"Une déviation axiale gauche au-delà de -30°, avec négativité de D2","ok":true,"why":"C'est le critère exact de l'HBAG donné par le livre."},{"t":"Une déviation axiale droite au-delà de +90°, avec aspect S1Q3","ok":false,"why":"C'est le critère de l'hémibloc postérieur gauche (HBPG), pas de l'HBAG."},{"t":"Un axe normal entre -30° et +90°","ok":false,"why":"Un axe normal exclut par définition un hémibloc, qui se caractérise justement par une déviation axiale pathologique."},{"t":"Un axe hyperdroit avec positivité de D2","ok":false,"why":"Ce n'est pas la définition de l'HBAG, qui est au contraire un axe hypergauche."},{"t":"Une absence totale de modification de l'axe du QRS","ok":false,"why":"L'hémibloc se définit précisément par une déviation axiale, sans laquelle le diagnostic ne peut être retenu."}],"explanation":"L'HBAG se traduit par une déviation axiale gauche au-delà de -30° avec négativité de D2, contrairement à l'HBPG qui dévie l'axe à droite au-delà de +90° avec aspect S1Q3.","src":"p. 382"},{"id":"231-qru-103","type":"QRU","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Quel type de bloc atrioventriculaire se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée ?","options":[{"t":"BAV1","ok":false,"why":"Le BAV1 est un allongement fixe et constant du PR, sans onde P bloquée."},{"t":"BAV2 Mobitz 1 (Wenckebach)","ok":true,"why":"C'est la définition exacte du phénomène de Luciani-Wenckebach : allongement progressif du PR puis onde P bloquée."},{"t":"BAV2 Mobitz 2","ok":false,"why":"Le Mobitz 2 se caractérise par un PR constant puis une onde P bloquée de façon inopinée, sans allongement progressif."},{"t":"BAV3","ok":false,"why":"Le BAV3 correspond à une dissociation atrioventriculaire complète, pas à un allongement progressif du PR."},{"t":"BAV 2/1","ok":false,"why":"Le BAV 2/1 correspond à une onde P bloquée sur deux, de façon régulière, sans notion d'allongement progressif."}],"explanation":"Le BAV2 Mobitz 1 (Wenckebach) se définit par un allongement progressif du PR jusqu'à une onde P bloquée, généralement de siège suprahissien.","src":"p. 385-386"},{"id":"231-qru-104","type":"QRU","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Chez un patient en échappement jonctionnel par dysfonction sinusale marquée, quelle est la caractéristique attendue de l'onde P rétrograde en D2 ?","options":[{"t":"Positive","ok":false,"why":"L'onde P rétrograde est négative en D2, pas positive."},{"t":"Négative","ok":true,"why":"L'activation atriale rétrograde se fait de bas en haut à partir de la jonction, ce qui donne une onde P négative en D2."},{"t":"Absente de façon constante","ok":false,"why":"L'onde P rétrograde peut être visible, notamment derrière le QRS, même si elle n'est pas toujours facile à identifier."},{"t":"Biphasique dans toutes les dérivations","ok":false,"why":"Le livre décrit une négativité en D2, pas un aspect biphasique généralisé."},{"t":"Identique à l'onde P sinusale antérograde","ok":false,"why":"Elle est au contraire de polarité opposée à l'onde P sinusale, du fait du sens rétrograde de l'activation."}],"explanation":"En cas d'échappement jonctionnel, l'activation atriale rétrograde (de la jonction vers l'oreillette, donc de bas en haut) donne une onde P négative en D2.","src":"p. 388"},{"id":"231-qru-105","type":"QRU","rank":"A","objective":"231-obj-12","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Quel élément évolutif permet de différencier une tachycardie sinusale d'une tachycardie supraventriculaire non sinusale sur une courbe de fréquence de scope ou de holter ?","options":[{"t":"Une variation progressive de la fréquence dans la tachycardie sinusale, contre des « marches d'escalier » dans la tachycardie supraventriculaire","ok":true,"why":"C'est le critère évolutif décrit par le livre pour ce diagnostic différentiel."},{"t":"Une fréquence toujours strictement identique dans les deux cas","ok":false,"why":"Les deux entités se distinguent justement par leur profil évolutif de fréquence, qui n'est pas identique."},{"t":"Une accélération brutale uniquement dans la tachycardie sinusale","ok":false,"why":"C'est au contraire la tachycardie supraventriculaire non sinusale qui débute et se termine de façon brutale, en « marches d'escalier »."},{"t":"L'absence totale d'onde P dans la tachycardie sinusale","ok":false,"why":"La tachycardie sinusale présente au contraire des ondes P sinusales bien visibles, positives en D1, D2, D3, aVF."},{"t":"Une fréquence toujours supérieure à 200 bpm dans la tachycardie sinusale","ok":false,"why":"Rien dans le livre n'impose une fréquence aussi élevée pour la tachycardie sinusale, qui est généralement plus modérée."}],"explanation":"Sur la courbe de fréquence, la tachycardie sinusale varie progressivement alors que la tachycardie supraventriculaire non sinusale varie brutalement, en « marches d'escalier ».","src":"p. 390-391"},{"id":"231-qroc-101","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quel aspect du QRS en V1 est caractéristique du bloc complet de branche gauche ?","answer":"Un aspect rS ou QS globalement négatif","accept":["rS","QS","aspect négatif en V1"],"keywords":["v1","negatif"],"explanation":"Le BBG complet se traduit en V1 par un QRS globalement négatif, en aspect rS ou QS, à l'opposé de l'aspect RsR' positif du BBD.","src":"p. 380"},{"id":"231-qroc-102","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":1,"question":"Dans le bloc de branche complet, quel ordre de vérification est recommandé pour l'interprétation (après le rythme) ?","answer":"Durée du QRS, puis aspect en V1, puis aspect en V6","accept":["QRS puis V1 puis V6"],"keywords":["qrs","v1","v6"],"explanation":"Après avoir vérifié le rythme sinusal, il faut vérifier la durée du QRS (> 120 ms), l'aspect en V1, puis l'aspect inverse attendu en V6.","src":"p. 381"},{"id":"231-qroc-103","type":"QROC","rank":"B","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"question":"Comment se nomme le phénomène par lequel la polarité de l'onde T devient opposée à celle du QRS en cas de bloc de branche ?","answer":"La discordance appropriée","accept":["discordance appropriée"],"keywords":["discordance"],"explanation":"Lorsque les QRS sont larges, la repolarisation ventriculaire est secondairement modifiée, donnant une polarité T opposée au QRS : c'est la discordance appropriée.","src":"p. 381"},{"id":"231-qroc-104","type":"QROC","rank":"B","objective":"231-obj-06","tags":["diagnostic"],"difficulty":2,"question":"Quelle branche du réseau de conduction, fragile car superficielle et de petite taille, est le plus souvent atteinte dans les hémiblocs ?","answer":"La branche antérieure gauche (fascicule antérieur gauche)","accept":["branche antérieure gauche","HBAG"],"keywords":["anterieur","gauche"],"explanation":"L'hémibloc antérieur gauche (HBAG) est fréquent car cette branche est fragile, superficielle et de petite taille, contrairement à la branche postérieure gauche, profonde et donc protégée.","src":"p. 383"},{"id":"231-qroc-105","type":"QROC","rank":"B","objective":"231-obj-06","tags":["complications","urgence"],"difficulty":2,"question":"Quelle association clinico-électrique impose une hospitalisation en cardiologie avec télémétrie selon le livre ?","answer":"Syncope associée à un bloc bifasciculaire","accept":["syncope et bloc bifasciculaire"],"keywords":["syncope","bifasciculaire"],"explanation":"Le bloc bifasciculaire fait craindre un risque de BAV complet infrahissien ; toute syncope dans ce contexte impose une hospitalisation avec télémétrie.","src":"p. 383"},{"id":"231-qroc-106","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quel type de bloc atrioventriculaire correspond à une dissociation atrioventriculaire complète ?","answer":"Le bloc atrioventriculaire du 3e degré (BAV3)","accept":["BAV3","BAV complet"],"keywords":["bav3","complet"],"explanation":"Le BAV3 (complet) se définit par une dissociation atrioventriculaire totale, aucune onde P n'étant conduite aux ventricules.","src":"p. 387"},{"id":"231-qroc-107","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic"],"difficulty":2,"question":"Dans un BAV3, quel type de QRS d'échappement oriente vers un bloc de siège nodal (suprahissien) ?","answer":"Un échappement à QRS fins","accept":["QRS fins","échappement fin"],"keywords":["fins"],"explanation":"Un échappement à QRS fins, régulier et lent traduit un bloc nodal (suprahissien) ; un échappement à QRS larges oriente vers un siège infrahissien.","src":"p. 387"},{"id":"231-qroc-108","type":"QROC","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quelle est la durée de la pause observée dans un bloc sinoatrial du 2e degré, par rapport au cycle PP ou RR normal ?","answer":"Le double de l'intervalle PP ou RR normal","accept":["double du PP","double du RR"],"keywords":["double"],"explanation":"La pause du bloc sinoatrial du 2e degré correspond à un manque complet d'un cycle P-QRS-T, soit le double de l'intervalle PP ou RR habituel.","src":"p. 387"},{"id":"231-qroc-109","type":"QROC","rank":"A","objective":"231-obj-10","tags":["diagnostic"],"difficulty":2,"question":"Devant une bradycardie, quelles sont les deux structures dont le dysfonctionnement peut être en cause ?","answer":"Le nœud sinusal et le nœud atrioventriculaire","accept":["nœud sinusal, NAV"],"keywords":["sinusal","atrioventriculaire"],"explanation":"Seules deux structures peuvent entraîner une bradycardie en dysfonctionnant : le nœud sinusal (dysfonction sinusale) ou le nœud atrioventriculaire (BAV2 ou 3).","src":"p. 389"},{"id":"231-qroc-110","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":2,"question":"Quelle molécule administrée en flash intraveineux permet de créer un bloc atrioventriculaire transitoire en cas d'échec des manœuvres vagales ?","answer":"L'adénosine","accept":["adénosine IV"],"keywords":["adenosine"],"explanation":"L'adénosine IV, administrée en flash, a un effet vagomimétique via les récepteurs purinergiques et un effet de courte durée (une dizaine de secondes).","src":"p. 390"},{"id":"231-qroc-111","type":"QROC","rank":"A","objective":"231-obj-13","tags":["diagnostic","ECG"],"difficulty":1,"question":"Comment qualifie-t-on classiquement les intervalles RR au cours d'une fibrillation atriale ?","answer":"Irrégulièrement irréguliers","accept":["RR irrégulièrement irréguliers"],"keywords":["irregulierement","irreguliers"],"explanation":"Dans la FA, les intervalles RR ne sont pas multiples d'une valeur commune : on parle de QRS irrégulièrement irréguliers.","src":"p. 392"},{"id":"231-qroc-112","type":"QROC","rank":"B","objective":"231-obj-13","tags":["diagnostic","complications"],"difficulty":3,"question":"Quel élément électrocardiographique doit faire évoquer une fibrillation atriale associée à un bloc atrioventriculaire complet ?","answer":"Une activité ventriculaire devenue lente et régulière","accept":["rythme ventriculaire lent et régulier"],"keywords":["lent","regulier"],"explanation":"En cas de BAV complet associé à une FA, la dépolarisation ventriculaire se fait par un rythme d'échappement automatique, donc régulier et lent, contrastant avec l'irrégularité habituelle de la FA.","src":"p. 392"},{"id":"231-open-11","type":"OPEN","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Comparez le bloc complet de branche droite et le bloc complet de branche gauche selon trois axes : la durée du QRS, l'aspect en V1, et l'aspect en V6. Précisez également en quoi le bloc de branche gauche complique l'interprétation d'une douleur thoracique.","rubric":[{"point":"Point commun : durée de QRS > 120 ms dans les deux blocs","weight":1.5},{"point":"BBD : aspect RsR' globalement positif en V1","weight":1.5},{"point":"BBD : aspect qRs avec onde S traînante en V6","weight":1},{"point":"BBG : aspect rS ou QS globalement négatif en V1","weight":1.5},{"point":"BBG : notch avec onde R exclusive en V6, D1, aVL","weight":1},{"point":"BBG : discordance appropriée T/QRS rendant le territoire antérieur difficile à interpréter, imposant une évaluation cardiologique rapide devant une douleur thoracique persistante sans attendre la troponine","weight":2.5}],"model":"**Durée du QRS** : dans les deux blocs, le QRS dépasse 120 ms.\n\n**Bloc de branche droite** : en V1, le QRS est globalement positif avec un aspect RsR' ; en V6, on observe un aspect qRs avec une onde S traînante, arrondie.\n\n**Bloc de branche gauche** : en V1, le QRS est globalement négatif, en aspect rS ou QS ; en V6 (ainsi qu'en D1 et aVL), on observe un notch, correspondant à l'activation successive du septum puis de la paroi latérale, avec le plus souvent une onde R exclusive.\n\n**Difficulté diagnostique du BBG** : les QRS larges du BBG s'accompagnent d'une discordance appropriée, où la polarité de l'onde T est opposée à celle du QRS. Associée à un segment ST parfois ascendant en V1-V2, cette discordance peut simuler à tort un syndrome coronarien aigu avec sus-décalage. Devant une douleur thoracique persistante chez un patient porteur d'un BBG, le diagnostic d'infarctus antérieur doit donc être évoqué et conduire à une évaluation cardiologique rapide, sans attendre le dosage de troponine.","src":"p. 378-381"},{"id":"231-open-12","type":"OPEN","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Décrivez les principaux types de blocs atrioventriculaires en rythme sinusal (BAV1, BAV2 Mobitz 1, BAV2 Mobitz 2, BAV2 2/1, BAV3) en précisant pour chacun la relation entre onde P et complexe QRS.","rubric":[{"point":"BAV1 : allongement fixe et constant du PR, sans onde P bloquée","weight":1.5},{"point":"BAV2 Mobitz 1 (Wenckebach) : allongement progressif du PR puis une onde P bloquée, siège suprahissien","weight":1.5},{"point":"BAV2 Mobitz 2 : PR constant puis onde P bloquée de façon inopinée, siège infrahissien","weight":1.5},{"point":"BAV2 2/1 : une onde P bloquée sur deux, siège suprahissien ou infrahissien selon le contexte","weight":1.5},{"point":"BAV3 : dissociation atrioventriculaire complète, aucune onde P conduite, ondes P régulières et à fréquence normale","weight":2},{"point":"Orientation vers le siège du bloc selon la largeur du QRS et la présence d'un Mobitz 1 à d'autres moments","weight":2}],"model":"**BAV1** : allongement fixe et constant de l'espace PR au-delà de 200 ms, sans aucune onde P bloquée.\n\n**BAV2 Mobitz 1 (Luciani-Wenckebach)** : allongement progressif du PR cycle après cycle, jusqu'à une onde P qui n'est pas suivie de QRS (onde P bloquée). Ce type est habituellement de siège suprahissien.\n\n**BAV2 Mobitz 2** : le PR reste constant, puis une onde P est bloquée de façon inopinée, sans allongement préalable. Ce type est de siège infrahissien.\n\n**BAV2 2/1** : une onde P sur deux est bloquée de façon régulière ; le siège (suprahissien ou infrahissien) s'oriente selon la largeur du QRS (fin = plutôt suprahissien, large = plutôt infrahissien) et la présence ou non d'un Mobitz 1 à d'autres moments du tracé.\n\n**BAV3 (complet)** : dissociation atrioventriculaire complète ; les ondes P restent régulières et à une fréquence normale, mais aucune n'est suivie d'un QRS, un rythme d'échappement (jonctionnel ou ventriculaire) prenant le relais.","src":"p. 385-387"},{"id":"231-open-13","type":"OPEN","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Une patiente de 70 ans présente sur son holter des pauses sinusales avec, par moments, un rythme lent régulier à QRS fins sans onde P visible devant le QRS. Expliquez le mécanisme évoqué et la manière de le reconnaître sur l'ECG, en distinguant les différents aspects possibles de dysfonction sinusale.","rubric":[{"point":"Mécanisme : dysfonction sinusale marquée avec échappement jonctionnel de secours","weight":2},{"point":"Aspect 1 : asystole, tracé plat sans activité visible","weight":1},{"point":"Aspect 2 : pause par bloc sinoatrial du 2e degré, durée double du cycle PP/RR normal","weight":1.5},{"point":"Aspect 3 : échappement jonctionnel, onde P absente devant le QRS ou rétrograde négative en D2","weight":2},{"point":"Lien avec le cas présenté : QRS fins réguliers sans P visible devant = échappement jonctionnel évocateur de dysfonction sinusale marquée","weight":1.5}],"model":"Chez cette patiente, l'absence d'onde P devant des QRS fins, réguliers et lents évoque un **rythme d'échappement jonctionnel** compliquant une **dysfonction sinusale marquée** : lorsque le nœud sinusal ne remplit plus sa fonction de pacemaker dominant, un foyer jonctionnel de secours prend le relais.\n\nLa dysfonction sinusale peut se manifester sous plusieurs aspects : une asystole (tracé plat sans aucune activité), une pause par bloc sinoatrial du 2e degré (absence complète d'un cycle P-QRS-T, de durée égale au double de l'intervalle PP ou RR normal), ou, comme ici, un échappement jonctionnel où l'onde P n'est plus visible devant le QRS — elle peut être rétrograde, visible derrière le QRS et négative en D2 du fait du sens rétrograde de l'activation atriale à partir de la jonction.","src":"p. 387-389"},{"id":"231-open-14","type":"OPEN","rank":"A","objective":"231-obj-13","tags":["diagnostic","physiopathologie"],"difficulty":2,"prompt":"Un homme de 68 ans présente des palpitations. Son ECG montre des QRS fins à une fréquence ventriculaire de 140 bpm, avec des intervalles RR irrégulièrement irréguliers et une absence d'onde P identifiable, remplacée par une trémulation de la ligne de base. Expliquez le diagnostic évoqué, son mécanisme électrophysiologique global, et le rôle protecteur du nœud atrioventriculaire dans cette situation.","rubric":[{"point":"Diagnostic : fibrillation atriale (activation atriale anarchique)","weight":2},{"point":"Argument QRS fins et irrégulièrement irréguliers (RR non multiples d'une valeur commune)","weight":1.5},{"point":"Argument trémulation de la ligne de base remplaçant l'activité sinusale","weight":1},{"point":"Rôle de filtre décrémentiel du NAV empêchant une conduction 1/1","weight":2},{"point":"Conséquence : sans ce filtre, risque de fibrillation ventriculaire ou de tachycardie extrême","weight":1.5},{"point":"Mention que le passage AV peut se faire en 1/1, 2/1 ou en alternance selon le tonus vagal, l'âge et les médicaments","weight":1.5}],"model":"Le tableau (QRS fins, RR irrégulièrement irréguliers, absence d'onde P remplacée par une trémulation de la ligne de base, fréquence ventriculaire à 140 bpm) est celui d'une **fibrillation atriale**, correspondant à une activation atriale anarchique.\n\nLe nœud atrioventriculaire (NAV) joue ici un rôle protecteur essentiel grâce à sa fonction de « filtre » à conduction décrémentielle : au-delà d'une certaine fréquence atriale, les ventricules ne suivent plus en 1 pour 1. Sans ce filtre, chaque épisode de FA entraînerait une fibrillation ventriculaire.\n\nSelon la fréquence atriale et l'intensité du filtre (qui dépend de l'âge, du tonus vagal et des médicaments ralentisseurs du NAV), le passage aux ventricules peut se faire en 1/1, en 2/1, en alternance 1/1-2/1, ou selon un bloc à conduction variable, ce qui explique la fréquence ventriculaire observée chez ce patient.","src":"p. 390-392"},{"id":"231-qcm-201","type":"QRM","rank":"A","objective":"231-obj-14","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Un homme de 70 ans consulte pour des palpitations régulières. L'ECG montre une activité atriale organisée à environ 300/min, en dents de scie dans les dérivations inférieures. Concernant le flutter atrial :","options":[{"t":"Le mécanisme est une réentrée organisée autour d'un obstacle anatomique ou fonctionnel","ok":true,"why":"Le flutter correspond au modèle des arythmies par réentrée, avec une boucle d'activation qui se répète à l'identique."},{"t":"L'activité atriale est fibrillatoire, sans onde F identifiable","ok":false,"why":"C'est la fibrillation atriale qui est « fibrillatoire » (anarchique) ; le flutter a au contraire une activité organisée en circuit, avec des ondes F monomorphes."},{"t":"Dans la forme typique (commune) antihoraire, les ondes F sont négatives en D2, D3 et aVF","ok":true,"why":"C'est la polarité classique décrite pour le flutter typique antihoraire empruntant l'isthme cavotricuspide."},{"t":"La fréquence atriale peut être plus lente en cas de dilatation atriale","ok":true,"why":"Le front de dépolarisation met plus de temps à parcourir un circuit dilaté, ce qui ralentit la fréquence atriale."},{"t":"Le diagnostic de certitude repose toujours sur la seule morphologie des ondes F à l'ECG","ok":false,"why":"La distinction typique/atypique à l'ECG n'est pas parfaitement fiable ; le diagnostic formel repose sur un argument de fréquence ou sur l'exploration électrophysiologique."}],"explanation":"Le flutter atrial est une arythmie par réentrée organisée, le plus souvent autour de l'isthme cavotricuspide pour la forme typique, avec une fréquence atriale habituelle proche de 300/min et une polarité caractéristique des ondes F.","src":"p. 393-394"},{"id":"231-qcm-202","type":"QRM","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la conduction ventriculaire au cours d'un flutter atrial :","options":[{"t":"La conduction 2/1 donne une cadence ventriculaire proche de 150/min","ok":true,"why":"Elle correspond à une division par deux de la fréquence atriale habituelle à 300/min."},{"t":"La cadence ventriculaire est toujours parfaitement régulière","ok":false,"why":"Le filtrage du nœud atrioventriculaire peut lui-même être variable, réalisant un flutter « à conduction variable » (alternance 2/1, 3/1, 4/1...)."},{"t":"Une manœuvre vagale peut ralentir transitoirement la cadence ventriculaire et démasquer les ondes F","ok":true,"why":"Elle est utile notamment en cas de flutter 1/1 ou 2/1, où les QRS proches laissent peu de place à la visualisation de l'activité atriale."},{"t":"La conduction 1/1 est le mode de transmission habituel du flutter","ok":false,"why":"La forme usuelle est une transmission 2/1 ; d'autres rapports (3/1, etc.) peuvent aussi être observés."},{"t":"Une conduction 3/1 correspond à une fréquence ventriculaire proche de 100/min","ok":true,"why":"C'est la cadence citée pour une transmission 3/1 d'un flutter à 300/min atrial."}],"explanation":"La cadence ventriculaire du flutter dépend du degré de filtrage nodal (2/1 le plus souvent, parfois 3/1 ou variable) ; les manœuvres vagales aident à démasquer l'activité atriale sous-jacente.","src":"p. 394-395"},{"id":"231-qcm-203","type":"QRM","rank":"A","objective":"231-obj-15","tags":["ECG","diagnostic"],"difficulty":2,"stem":"À propos des tachycardies jonctionnelles :","options":[{"t":"La réentrée intranodale est un mécanisme de réentrée au sein du nœud atrioventriculaire","ok":true,"why":"C'est la première des deux formes de tachycardie jonctionnelle."},{"t":"Dans la réentrée intranodale, l'activité atriale rétrograde est habituellement bien visible avant le QRS","ok":false,"why":"Elle n'est souvent pas visible, ou seulement devinée dans le segment ST, car l'activation atriale et ventriculaire y est quasi synchrone."},{"t":"La tachycardie par rythme réciproque correspond à une réentrée par une voie accessoire (faisceau de Kent)","ok":true,"why":"C'est la seconde forme de tachycardie jonctionnelle."},{"t":"Les tachycardies jonctionnelles sont rares","ok":false,"why":"Elles sont fréquentes, couramment synonymes en France de la maladie de Bouveret."},{"t":"Ces tachycardies sont volontiers très régulières, souvent autour de 200/min","ok":true,"why":"Leur fréquence peut néanmoins varier de 130 à 260/min selon le mécanisme et le tonus sympathique."}],"explanation":"Les tachycardies jonctionnelles, fréquentes et très régulières (souvent autour de 200/min), relèvent d'une réentrée intranodale (activité atriale souvent invisible) ou d'un rythme réciproque par voie accessoire (faisceau de Kent).","src":"p. 395-396"},{"id":"231-qcm-204","type":"QRM","rank":"B","objective":"231-obj-16","tags":["diagnostic","traitement"],"difficulty":2,"stem":"Concernant l'intérêt des manœuvres vagales et de l'adénosine devant une tachycardie :","options":[{"t":"Elles bloquent transitoirement le nœud atrioventriculaire","ok":true,"why":"C'est le mécanisme d'action commun, qui permet de ralentir ou d'interrompre une arythmie dépendant du nœud atrioventriculaire."},{"t":"Elles arrêtent la tachycardie jonctionnelle en interrompant la réentrée dépendante du nœud atrioventriculaire","ok":true,"why":"Le blocage nodal transitoire coupe la boucle de réentrée, qu'elle soit intranodale ou par voie accessoire."},{"t":"Elles n'ont habituellement aucun effet sur la fréquence ventriculaire d'un flutter","ok":false,"why":"Elles peuvent au contraire ralentir transitoirement la conduction et démasquer l'activité atriale sous-jacente en dents de scie."},{"t":"Elles sont utiles pour préciser le diagnostic lorsque celui-ci n'est pas évident","ok":true,"why":"Elles permettent, dans la majorité des cas, de faire le diagnostic précis de la tachycardie."},{"t":"Elles sont indiquées en première intention en cas de mauvaise tolérance hémodynamique","ok":false,"why":"En cas de mauvaise tolérance hémodynamique, c'est la cardioversion électrique externe qui est indiquée en priorité."}],"explanation":"Les manœuvres vagales et l'adénosine bloquent transitoirement le nœud atrioventriculaire : elles démasquent l'activité atriale (flutter, TAF) ou arrêtent la tachycardie si elle en dépend (jonctionnelle), mais ne remplacent pas la cardioversion en cas de mauvaise tolérance.","src":"p. 396-397, 405"},{"id":"231-qcm-205","type":"QRM","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Concernant les extrasystoles :","options":[{"t":"Elles correspondent à une activation prématurée d'une cavité cardiaque par rapport à l'activation attendue","ok":true,"why":"C'est la définition même de l'extrasystole."},{"t":"Une extrasystole atriale se traduit par une onde P précoce, de morphologie différente de la P sinusale, suivie d'un QRS fin","ok":true,"why":"L'onde P ectopique précède un QRS fin, sauf conduction aberrante ; elle peut être masquée par l'onde T précédente."},{"t":"Une extrasystole ventriculaire se traduit par un QRS fin précédé d'une onde P normale","ok":false,"why":"Une extrasystole ventriculaire donne au contraire un QRS large, avec parfois une onde P' rétrograde."},{"t":"Leur charge (nombre par 24 heures) augmente avec l'âge et la présence d'une cardiopathie","ok":true,"why":"C'est une notion explicitement rapportée pour la fréquence des extrasystoles."},{"t":"Des extrasystoles fréquentes ou polymorphes ne doivent jamais faire rechercher de cardiopathie sous-jacente","ok":false,"why":"Au contraire, des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie."}],"explanation":"Les extrasystoles sont fréquentes et souvent physiologiques sur cœur sain, mais leur caractère fréquent, polymorphe ou leur charge élevée doit faire rechercher une cardiopathie sous-jacente.","src":"p. 397"},{"id":"231-qcm-206","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Une patiente de 55 ans, connue coronarienne, présente une tachycardie régulière à QRS larges (140 ms) à 160/min, mal tolérée. Concernant le diagnostic et la conduite à tenir :","options":[{"t":"Toute tachycardie régulière à QRS larges doit être considérée comme une tachycardie ventriculaire jusqu'à preuve du contraire","ok":true,"why":"C'est la règle de sécurité à retenir devant ce tableau."},{"t":"L'existence d'une cardiopathie sous-jacente est un argument en faveur d'une TV","ok":true,"why":"La plupart des tachycardies ventriculaires sont favorisées par une cardiopathie."},{"t":"Il s'agit certainement d'une tachycardie supraventriculaire car la patiente est symptomatique et mal tolérée","ok":false,"why":"La tolérance clinique n'est pas un critère fiable de diagnostic différentiel entre TV et tachycardie supraventriculaire avec bloc de branche."},{"t":"Le mécanisme le plus fréquent de TV sur cardiopathie est une réentrée autour d'une zone de fibrose","ok":true,"why":"La fibrose, souvent séquellaire d'un infarctus, constitue le substrat de réentrée le plus fréquent."},{"t":"Une TV ne peut jamais dégénérer en fibrillation ventriculaire","ok":false,"why":"La TV est un état électrique instable, prémonitoire de l'arrêt cardiaque, qui peut dégénérer en FV puis en asystolie."}],"explanation":"Devant une tachycardie régulière à QRS larges, le diagnostic de TV doit être retenu par défaut, en particulier sur cardiopathie connue, car il s'agit d'un état instable pouvant se compliquer d'arrêt cardiaque.","src":"p. 398-400","trap":"La bonne tolérance clinique initiale n'élimine pas le diagnostic de TV."},{"id":"231-qcm-207","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":3,"stem":"Concernant les arguments électrocardiographiques en faveur du diagnostic de tachycardie ventriculaire :","options":[{"t":"La dissociation ventriculo-atriale, avec plus de QRS que d'ondes P, est un argument de certitude","ok":true,"why":"C'est un argument de certitude : s'il y a plus de QRS que d'ondes P, la tachycardie vient forcément du ventricule."},{"t":"Les complexes de capture et de fusion ne peuvent exister qu'en l'absence de dissociation ventriculo-atriale","ok":false,"why":"C'est l'inverse : ces complexes ne peuvent être présents que s'il y a dissociation ventriculo-atriale."},{"t":"Une concordance positive ou négative de V1 à V6 est en faveur d'une TV","ok":true,"why":"Un QRS entièrement positif (R) ou entièrement négatif (QS) de V1 à V6 est un argument en faveur d'une TV."},{"t":"Une déviation axiale extrême, avec QRS positif en aVR, est en faveur d'une TV","ok":true,"why":"L'axe extrême traduit une dépolarisation ventriculaire anormale, non expliquée par un bloc de branche droit ou gauche."},{"t":"Un aspect de bloc de branche typique élimine formellement le diagnostic de TV","ok":false,"why":"C'est au contraire un QRS large avec un aspect DIFFÉRENT d'un bloc de branche habituel qui est en faveur de la TV."}],"explanation":"Les arguments de certitude de TV sont la dissociation ventriculo-atriale et les complexes de capture/fusion ; la concordance et l'axe extrême en aVR sont des arguments en faveur, tout comme la cardiopathie sous-jacente.","src":"p. 400-402"},{"id":"231-qcm-208","type":"QRM","rank":"B","objective":"231-obj-18","tags":["ECG","pièges"],"difficulty":2,"stem":"Concernant les complexes de capture et de fusion observés au cours d'une tachycardie ventriculaire :","options":[{"t":"Un complexe de capture correspond à un QRS fin, entièrement dépolarisé par l'influx sinusal via les voies de conduction normales","ok":true,"why":"L'influx sinusal capture le ventricule avant que la TV ne puisse l'activer, donnant un QRS fin."},{"t":"Un complexe de fusion résulte de la compétition entre l'activation ventriculaire par la TV et par l'influx sinusal","ok":true,"why":"Le QRS obtenu est alors de morphologie intermédiaire entre le rythme normal et la TV."},{"t":"Ces complexes sont précédés d'une onde P","ok":true,"why":"Ils marquent le fait qu'une onde P a pu passer par les voies de conduction et capturer le ventricule."},{"t":"Ils traduisent l'absence de toute activité atriale résiduelle pendant la TV","ok":false,"why":"À l'inverse, ils prouvent qu'une onde P a été capable de capturer le ventricule, ce qui suppose une dissociation ventriculo-atriale avec activité atriale persistante."},{"t":"Ils ne s'observent que dans les torsades de pointes","ok":false,"why":"Ils s'observent au cours des tachycardies ventriculaires, en particulier monomorphes sur cardiopathie."}],"explanation":"Les complexes de capture (QRS fin) et de fusion (QRS intermédiaire) sont des arguments de certitude de TV, car ils supposent qu'une onde P a pu, ponctuellement, dépolariser le ventricule par les voies normales.","src":"p. 400-401"},{"id":"231-qcm-209","type":"QRM","rank":"A","objective":"231-obj-19","tags":["urgence","ECG"],"difficulty":2,"stem":"Concernant la fibrillation ventriculaire :","options":[{"t":"Elle se traduit à l'ECG par une tachycardie régulière à QRS fins","ok":false,"why":"Elle se traduit au contraire par une tachycardie IRRÉGULIÈRE à QRS larges et polymorphes."},{"t":"La perte de connaissance survient habituellement après quelques secondes, du fait d'un débit cardiaque nul","ok":true,"why":"Le débit cardiaque étant nul, la perte de connaissance et l'abolition du pouls carotidien surviennent rapidement."},{"t":"Elle peut être bien tolérée dans tous les cas et ne nécessite pas de prise en charge urgente","ok":false,"why":"C'est une urgence absolue nécessitant une cardioversion électrique immédiate, avant tout autre geste."},{"t":"Le pouls carotidien reste perçu malgré la perte de connaissance","ok":false,"why":"Le pouls carotidien est aboli, ce qui définit l'arrêt cardiaque."},{"t":"Elle correspond à un arrêt cardiaque","ok":true,"why":"La perte de connaissance et l'abolition du pouls carotidien en font un arrêt cardiaque."}],"explanation":"La fibrillation ventriculaire est une tachycardie irrégulière à QRS larges polymorphes qui entraîne un arrêt cardiaque en quelques secondes et impose un choc électrique immédiat.","src":"p. 402-403"},{"id":"231-qcm-210","type":"QRM","rank":"B","objective":"231-obj-20","tags":["ECG","biologie","étiologie"],"difficulty":2,"stem":"Parmi les situations suivantes, lesquelles favorisent la survenue de torsades de pointes par allongement de l'intervalle QT ?","options":[{"t":"Hypokaliémie","ok":true,"why":"L'hypokaliémie est explicitement citée comme cause d'allongement du QT favorisant les torsades."},{"t":"Hypercalcémie","ok":false,"why":"C'est l'HYPOcalcémie qui allonge le QT et favorise les torsades, non l'hypercalcémie."},{"t":"Hypomagnésémie","ok":true,"why":"Elle fait partie des situations citées d'allongement du QT."},{"t":"Bradycardie extrême","ok":true,"why":"Une bradycardie extrême (échappement à QRS larges d'un BAV bas situé, bradycardisants) favorise les torsades."},{"t":"Association de médicaments allongeant l'intervalle QT","ok":true,"why":"De nombreuses classes (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens) peuvent allonger le QT."}],"explanation":"Les torsades de pointes surviennent sur un terrain d'allongement du QT : hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, médicaments allongeant le QT ou QT long congénital.","src":"p. 403-404"},{"id":"231-qcm-211","type":"QRM","rank":"B","objective":"231-obj-20","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant la prise en charge d'une torsade de pointes :","options":[{"t":"Elle consiste à corriger les troubles ioniques en cause","ok":true,"why":"Corriger l'ionogramme (kaliémie, calcémie, magnésémie) fait partie de la prise en charge."},{"t":"Elle consiste à ralentir la fréquence cardiaque","ok":false,"why":"Au contraire, il faut ACCÉLÉRER la fréquence cardiaque pour raccourcir le QT."},{"t":"Elle impose l'arrêt des médicaments allongeant le QT","ok":true,"why":"C'est une étape explicite de la prise en charge."},{"t":"Un allongement isolé du QT sur l'ECG ne justifie jamais de vérifier l'ordonnance du patient","ok":false,"why":"Une mesure allongée du QT doit au contraire alerter et faire vérifier les médicaments responsables."},{"t":"Elle peut dégénérer spontanément en fibrillation ventriculaire","ok":true,"why":"Une fois installée, la torsade est indiscernable d'une fibrillation ventriculaire et peut y dégénérer."}],"explanation":"La torsade de pointes impose de corriger les troubles ioniques, d'arrêter les médicaments responsables et d'accélérer la fréquence cardiaque ; elle peut s'arrêter spontanément ou dégénérer en fibrillation ventriculaire.","src":"p. 404"},{"id":"231-qcm-212","type":"QRM","rank":"B","objective":"231-obj-17","tags":["ECG"],"difficulty":1,"stem":"Concernant la description des extrasystoles :","options":[{"t":"Un battement sur deux définit un bigéminisme","ok":true,"why":"C'est la définition donnée pour les extrasystoles rythmées."},{"t":"Un battement sur trois définit un trigéminisme","ok":true,"why":"C'est la définition symétrique du bigéminisme."},{"t":"Une salve désigne une extrasystole strictement isolée","ok":false,"why":"Une salve désigne au contraire plusieurs extrasystoles successives, au même titre que les doublets et triplets (forme répétitive)."},{"t":"Un doublet correspond à deux extrasystoles consécutives","ok":true,"why":"C'est la forme répétitive la plus simple, avant le triplet et la salve."},{"t":"Les extrasystoles jonctionnelles sont les plus fréquentes des trois types (atriales, jonctionnelles, ventriculaires)","ok":false,"why":"Les extrasystoles jonctionnelles sont au contraire rares et traduisent le plus souvent une pathologie de la jonction nodohissienne."}],"explanation":"Les extrasystoles peuvent être répétitives (doublets, triplets, salves) ou rythmées (bigéminisme, trigéminisme) ; les formes jonctionnelles sont les plus rares des trois topographies.","src":"p. 397-398"},{"id":"231-qcm-214","type":"QRM","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Devant une tachycardie régulière à QRS fins bien tolérée, selon la démarche décisionnelle proposée :","options":[{"t":"Les manœuvres vagales (ou l'adénosine en cas d'échec) permettent, dans la majorité des cas, de préciser le diagnostic","ok":true,"why":"C'est l'intérêt principal de ces manœuvres devant une tachycardie non évidente."},{"t":"Si elles démasquent une activité atriale organisée en dents de scie, le diagnostic est un flutter","ok":true,"why":"Le ralentissement transitoire de la conduction démasque l'activité atriale sous-jacente et permet le diagnostic."},{"t":"Si elles arrêtent la tachycardie, le diagnostic le plus probable est une tachycardie jonctionnelle","ok":true,"why":"Cela traduit l'interruption d'une réentrée dépendante du nœud atrioventriculaire."},{"t":"Une tachycardie complètement irrégulière à QRS fins oriente en premier lieu vers une fibrillation atriale","ok":true,"why":"C'est le diagnostic à évoquer en priorité, avec l'extrasystolie atriale comme diagnostic différentiel."},{"t":"La cardioversion électrique externe est le traitement de première intention en cas de bonne tolérance hémodynamique","ok":false,"why":"En cas de bonne tolérance, on utilise en premier les manœuvres vagales ± adénosine ; la cardioversion est réservée à la mauvaise tolérance."}],"explanation":"L'algorithme distingue d'abord tachycardie régulière/irrégulière, puis QRS fins/larges ; les manœuvres vagales/adénosine sont l'outil diagnostique et parfois thérapeutique de première intention en bonne tolérance hémodynamique.","src":"p. 405"},{"id":"231-qru-201","type":"QRU","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"stem":"Quelle définition correspond à une tachycardie ventriculaire non soutenue (TVNS) ?","options":[{"t":"Une tachycardie ventriculaire durant entre 3 battements consécutifs et 30 secondes","ok":true,"why":"C'est la définition retenue pour la TVNS, au-delà de laquelle on parle de TV soutenue."},{"t":"Une tachycardie ventriculaire durant plus de 30 secondes","ok":false,"why":"Cette durée définit au contraire une TV soutenue."},{"t":"Une tachycardie ventriculaire durant plus d'une minute","ok":false,"why":"Ce seuil n'est pas celui retenu ; c'est 30 secondes qui sépare TVNS et TV soutenue."},{"t":"Une tachycardie ventriculaire de n'importe quelle durée, dès qu'elle est asymptomatique","ok":false,"why":"La distinction repose sur la durée (3 battements à 30 secondes), pas sur la présence de symptômes."},{"t":"Une tachycardie ventriculaire durant moins de 3 battements","ok":false,"why":"Moins de 3 battements consécutifs ne définit pas une TV (il faut au moins 3 battements consécutifs à QRS > 120 ms)."}],"explanation":"La TVNS dure entre 3 battements et 30 secondes ; au-delà de 30 secondes, on parle de TV soutenue.","src":"p. 399"},{"id":"231-qru-202","type":"QRU","rank":"A","objective":"231-obj-19","tags":["urgence","ECG"],"difficulty":1,"stem":"Quelle est la conduite à tenir immédiate devant une fibrillation ventriculaire ?","options":[{"t":"Massage cardiaque en attendant un choc électrique en urgence absolue","ok":true,"why":"La cardioversion électrique immédiate est prioritaire ; le massage cardiaque est pratiqué en attendant ce choc."},{"t":"Manœuvre vagale en première intention","ok":false,"why":"Les manœuvres vagales n'ont pas d'indication ici ; c'est un arrêt cardiaque justifiant un choc électrique immédiat."},{"t":"Surveillance simple sans geste immédiat","ok":false,"why":"C'est une urgence absolue imposant un geste immédiat (choc électrique), pas une simple surveillance."},{"t":"Administration d'adénosine intraveineuse","ok":false,"why":"L'adénosine est utilisée pour les tachycardies dépendantes du nœud atrioventriculaire, pas pour la fibrillation ventriculaire."},{"t":"Cardioversion électrique différée après bilan biologique complet","ok":false,"why":"Le choc électrique doit être immédiat, avant tout autre geste, sans attendre un bilan."}],"explanation":"La fibrillation ventriculaire est une urgence absolue : choc électrique immédiat, massage cardiaque en attendant le choc.","src":"p. 402"},{"id":"231-qru-203","type":"QRU","rank":"B","objective":"231-obj-20","tags":["ECG","pièges"],"difficulty":2,"stem":"Quel élément permet le mieux de différencier une torsade de pointes déjà installée d'une fibrillation ventriculaire ?","options":[{"t":"La présence d'un QT long avant le trouble du rythme, associée au contexte clinique","ok":true,"why":"Une fois installée, la torsade est indiscernable de la FV à l'ECG seul ; seuls le QT long préalable et le contexte orientent le diagnostic."},{"t":"La fréquence cardiaque pendant l'arythmie","ok":false,"why":"La fréquence ne permet pas de différencier les deux arythmies une fois installées."},{"t":"La présence d'un pouls carotidien perçu","ok":false,"why":"Les deux arythmies entraînent une perte de connaissance et une abolition du pouls."},{"t":"La durée du QRS mesurée pendant l'arythmie","ok":false,"why":"Ce n'est pas un critère de différenciation cité dans le texte."},{"t":"La régularité du rythme ventriculaire","ok":false,"why":"Une fois la torsade installée, son aspect est indiscernable de celui de la FV."}],"explanation":"La torsade de pointes installée peut être indiscernable d'une FV ; le QT long préexistant et le contexte (FV plutôt sur ischémie/cardiopathie évoluée, torsade dans les situations d'allongement du QT) orientent le diagnostic.","src":"p. 403-404"},{"id":"231-qru-204","type":"QRU","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"stem":"Quelle est la fréquence atriale habituelle d'un flutter atrial typique sur cœur sain ?","options":[{"t":"300/min (entre 240 et 340/min)","ok":true,"why":"C'est la fréquence atriale la plus souvent rapportée pour le flutter."},{"t":"150/min","ok":false,"why":"150/min correspond à la cadence VENTRICULAIRE usuelle (conduction 2/1), pas à la fréquence atriale."},{"t":"100/min","ok":false,"why":"Cette fréquence correspond à une cadence ventriculaire en conduction 3/1, pas à la fréquence atriale."},{"t":"500/min","ok":false,"why":"Cette fréquence est trop élevée pour un flutter, qui reste entre 240 et 340/min."},{"t":"60/min","ok":false,"why":"Cette fréquence correspond à un rythme normal, sans rapport avec le flutter."}],"explanation":"L'activité atriale du flutter est rapide, le plus souvent autour de 300/min (240 à 340/min).","src":"p. 393"},{"id":"231-qru-205","type":"QRU","rank":"B","objective":"231-obj-15","tags":["ECG"],"difficulty":2,"stem":"Comment nomme-t-on la tachycardie jonctionnelle par réentrée empruntant une voie accessoire de type faisceau de Kent ?","options":[{"t":"Une tachycardie par rythme réciproque","ok":true,"why":"C'est le terme employé pour la réentrée empruntant une voie accessoire."},{"t":"Une tachycardie par réentrée intranodale","ok":false,"why":"Ce terme désigne la réentrée au sein du nœud atrioventriculaire, non par une voie accessoire."},{"t":"Une tachycardie atriale focale","ok":false,"why":"Ce terme désigne un hyperautomatisme atrial, mécanisme distinct de la réentrée par voie accessoire."},{"t":"Un flutter atypique","ok":false,"why":"Le flutter est une réentrée atriale organisée, sans rapport avec la jonction ou une voie accessoire."},{"t":"Une extrasystole jonctionnelle répétitive","ok":false,"why":"Il s'agit d'un mécanisme d'extrasystolie, pas d'une tachycardie soutenue par réentrée."}],"explanation":"La réentrée par voie accessoire (faisceau de Kent) définit les tachycardies par rythme réciproque, à distinguer de la réentrée intranodale.","src":"p. 396"},{"id":"231-qroc-201","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"question":"Quel terme désigne les ondes d'activité atriale caractéristiques du flutter atrial à l'ECG ?","answer":"Ondes F","accept":["onde F"],"keywords":["onde","f"],"explanation":"Les ondes F du flutter donnent un aspect sinusoïdal, en toit d'usine ou en dents de scie, sans retour à la ligne isoélectrique.","src":"p. 393"},{"id":"231-qroc-202","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":2,"question":"Quelle structure anatomique est empruntée par la boucle de réentrée du flutter atrial typique (commun) ?","answer":"L'isthme cavotricuspide","accept":["isthme cavo-tricuspide"],"keywords":["isthme","cavotricuspide"],"explanation":"L'isthme cavotricuspide est la région trabéculée entre la valve tricuspide et la veine cave inférieure empruntée par le flutter typique antihoraire.","src":"p. 394"},{"id":"231-qroc-203","type":"QROC","rank":"B","objective":"231-obj-15","tags":["ECG"],"difficulty":1,"question":"Quel est le nom de la voie accessoire responsable des tachycardies jonctionnelles par rythme réciproque ?","answer":"Le faisceau de Kent","accept":["voie accessoire de Kent","Kent"],"keywords":["kent"],"explanation":"Le faisceau de Kent est une voie accessoire musculaire reliant l'oreillette au ventricule, à l'origine de la réentrée par rythme réciproque.","src":"p. 396"},{"id":"231-qroc-204","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG"],"difficulty":1,"question":"Quel terme, couramment employé en France, est quasi synonyme de tachycardie jonctionnelle par réentrée ?","answer":"Maladie de Bouveret","accept":["Bouveret"],"keywords":["bouveret"],"explanation":"Les tachycardies jonctionnelles sont couramment appelées, en France, maladie de Bouveret.","src":"p. 395"},{"id":"231-qroc-205","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":1,"question":"Par quels moyens réduit-on (fait-on revenir en rythme sinusal) une tachycardie jonctionnelle ?","answer":"Manœuvres vagales ou adénosine intraveineuse","accept":["adénosine IV","manœuvre vagale"],"keywords":["vagale","adenosine"],"explanation":"Le blocage transitoire du nœud atrioventriculaire, par manœuvre vagale ou adénosine, interrompt la réentrée dépendante de ce nœud.","src":"p. 397"},{"id":"231-qroc-206","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG"],"difficulty":1,"question":"Comment définit-on une extrasystole ?","answer":"La survenue d'une activation prématurée d'une cavité cardiaque par rapport à l'activation attendue","accept":["activation prématurée"],"keywords":["prematuree","activation"],"explanation":"L'extrasystole est une dépolarisation trop précoce par rapport au rythme de base, d'origine atriale, jonctionnelle ou ventriculaire.","src":"p. 397"},{"id":"231-qroc-207","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"question":"Au-delà de quelle durée de QRS (pour au moins 3 battements consécutifs) suspecte-t-on une tachycardie ventriculaire ?","answer":"120 ms","accept":["> 120 ms","120 millisecondes"],"keywords":["120"],"explanation":"La suspicion de TV repose sur une fréquence > 100/min associée à un QRS > 120 ms pour au moins 3 battements consécutifs.","src":"p. 399"},{"id":"231-qroc-208","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"question":"Quelle durée sépare une tachycardie ventriculaire non soutenue d'une tachycardie ventriculaire soutenue ?","answer":"30 secondes","accept":["30 s"],"keywords":["30","secondes"],"explanation":"Au-delà de 30 secondes, une tachycardie ventriculaire est dite soutenue.","src":"p. 399"},{"id":"231-qroc-209","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":2,"question":"Quel signe électrocardiographique, correspondant à davantage de QRS que d'ondes P, affirme avec certitude le diagnostic de tachycardie ventriculaire ?","answer":"La dissociation ventriculo-atriale","accept":["dissociation AV"],"keywords":["dissociation","ventriculoatriale"],"explanation":"S'il y a plus de QRS que d'ondes P, la tachycardie vient forcément du ventricule ; il ne faut pas confondre ce signe avec la dissociation atrioventriculaire du bloc complet.","src":"p. 400"},{"id":"231-qroc-210","type":"QROC","rank":"A","objective":"231-obj-19","tags":["urgence"],"difficulty":1,"question":"Quel geste doit être réalisé en urgence absolue devant une fibrillation ventriculaire, avant tout autre geste ?","answer":"Une cardioversion électrique (choc électrique) immédiate","accept":["choc électrique"],"keywords":["choc","electrique"],"explanation":"La fibrillation ventriculaire impose une cardioversion électrique immédiate, un massage cardiaque étant pratiqué en attendant le choc.","src":"p. 402"},{"id":"231-qroc-211","type":"QROC","rank":"B","objective":"231-obj-20","tags":["ECG"],"difficulty":2,"question":"Quel élément ECG, présent avant le trouble du rythme, aide à distinguer une torsade de pointes d'une fibrillation ventriculaire ?","answer":"Un intervalle QT long","accept":["QT long"],"keywords":["qt","long"],"explanation":"Le QT long préexistant, associé au contexte clinique, oriente vers une torsade de pointes plutôt que vers une FV.","src":"p. 403-404"},{"id":"231-qroc-212","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins ?","answer":"La fibrillation atriale","accept":["FA"],"keywords":["fibrillation","atriale"],"explanation":"La fibrillation atriale est, par définition, le seul diagnostic de tachycardie irrégulière à QRS fins (le diagnostic différentiel étant l'extrasystolie atriale).","src":"p. 405"},{"id":"231-open-21","type":"OPEN","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Un patient de 65 ans consulte pour des palpitations régulières rapides à 150/min. Décrivez la démarche électrocardiographique permettant de distinguer un flutter atrial d'une tachycardie jonctionnelle, en précisant l'apport des manœuvres vagales.","rubric":[{"point":"Décrire le mécanisme du flutter : réentrée organisée en circuit, activité atriale monomorphe en dents de scie","weight":2},{"point":"Décrire le(s) mécanisme(s) de la tachycardie jonctionnelle : réentrée intranodale ou par voie accessoire, activité atriale souvent peu visible","weight":2},{"point":"Préciser l'effet attendu des manœuvres vagales/adénosine dans le flutter : ralentissement transitoire de la conduction démasquant les ondes F, sans arrêt de l'arythmie","weight":2},{"point":"Préciser l'effet attendu dans la tachycardie jonctionnelle : arrêt de la tachycardie car la réentrée dépend du nœud atrioventriculaire","weight":2},{"point":"Conclure sur l'intérêt diagnostique et parfois thérapeutique de ces manœuvres en cas de doute","weight":1}],"model":"**Flutter atrial** : réentrée organisée en circuit (le plus souvent autour de l'isthme cavotricuspide), donnant une activité atriale monomorphe rapide (ondes F, environ 300/min) sans retour à la ligne isoélectrique.\n\n**Tachycardie jonctionnelle** : réentrée intranodale ou par voie accessoire (rythme réciproque), avec une activité atriale souvent invisible ou devinée dans le segment ST.\n\n**Manœuvres vagales/adénosine** : en bloquant transitoirement le nœud atrioventriculaire, elles démasquent l'activité atriale sous-jacente du flutter (les ondes F apparaissent alors que la cadence ventriculaire ralentit) sans arrêter l'arythmie, alors qu'elles interrompent la tachycardie jonctionnelle en coupant la boucle de réentrée dépendante du nœud atrioventriculaire. Elles sont donc utiles au diagnostic dans les deux cas, et parfois curatives dans la tachycardie jonctionnelle.","src":"p. 393-397, 405"},{"id":"231-open-22","type":"OPEN","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic","urgence"],"difficulty":3,"prompt":"Détaillez les arguments électrocardiographiques permettant d'affirmer le diagnostic de tachycardie ventriculaire devant une tachycardie régulière à QRS larges.","rubric":[{"point":"Rappeler la règle de base : toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire","weight":1},{"point":"Citer les critères de suspicion simples : fréquence > 100/min, QRS > 120 ms pour au moins 3 battements consécutifs","weight":2},{"point":"Citer les arguments de certitude : dissociation ventriculo-atriale, complexes de capture ou de fusion","weight":3},{"point":"Citer les arguments en faveur : cardiopathie sous-jacente, concordance positive/négative de V1 à V6, déviation axiale extrême (QRS positif en aVR)","weight":3},{"point":"Mentionner la nécessité de décrire le caractère monomorphe ou polymorphe, qui conditionne l'étiologie et la tolérance hémodynamique","weight":1}],"model":"**Règle de base** : toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.\n\n**Suspicion** : fréquence > 100/min et QRS > 120 ms sur au moins 3 battements consécutifs.\n\n**Arguments de certitude** : dissociation ventriculo-atriale (plus de QRS que d'ondes P, à ne pas confondre avec la dissociation atrioventriculaire du bloc complet) ; complexes de capture (QRS fin précédé d'une onde P, correspondant à une capture ventriculaire par l'influx sinusal) ou de fusion (QRS de morphologie intermédiaire).\n\n**Arguments en faveur** : cardiopathie sous-jacente ; concordance positive ou négative des précordiales (V1 à V6) ; déviation axiale extrême avec QRS positif en aVR ; aspect de QRS large différent d'un bloc de branche habituel.\n\n**Description complémentaire** : préciser le caractère monomorphe ou polymorphe, qui oriente l'étiologie et conditionne les conséquences hémodynamiques.","src":"p. 398-402"},{"id":"231-open-23","type":"OPEN","rank":"A","objective":"231-obj-19","tags":["ECG","urgence"],"difficulty":2,"prompt":"Comparez, sur le plan électrocardiographique et sur le plan de la prise en charge, la fibrillation ventriculaire et la torsade de pointes.","rubric":[{"point":"Décrire l'aspect ECG de la FV : tachycardie irrégulière à QRS larges polymorphes","weight":2},{"point":"Décrire l'aspect ECG de la torsade de pointes : forme particulière de TV polymorphe, pouvant s'arrêter spontanément ou dégénérer en FV","weight":2},{"point":"Préciser l'élément différentiel une fois l'arythmie installée : présence d'un QT long préalable et le contexte","weight":2},{"point":"Décrire la prise en charge immédiate commune : cardioversion électrique en urgence, massage cardiaque en attendant le choc","weight":2},{"point":"Préciser la prise en charge spécifique de la torsade : correction des troubles ioniques, arrêt des médicaments allongeant le QT, accélération de la fréquence cardiaque","weight":2}],"model":"**Fibrillation ventriculaire** : tachycardie irrégulière à QRS larges et polymorphes, urgence absolue entraînant un arrêt cardiaque (perte de connaissance, pouls carotidien aboli) en quelques secondes, nécessitant une cardioversion électrique immédiate, précédée d'un massage cardiaque en attendant le choc.\n\n**Torsade de pointes** : forme particulière de TV polymorphe, pouvant s'arrêter spontanément ou dégénérer en FV. Une fois installée, elle est indiscernable de la FV à l'ECG ; seuls la présence d'un QT long avant le trouble du rythme et le contexte (hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, médicaments allongeant le QT, QT long congénital) permettent de l'évoquer plutôt qu'une FV.\n\n**Prise en charge spécifique de la torsade** : correction des troubles ioniques, arrêt des médicaments allongeant le QT, accélération de la fréquence cardiaque.","src":"p. 402-404"},{"id":"231-open-24","type":"OPEN","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Expliquez comment différencier, sur l'ECG, une extrasystole ventriculaire isolée d'un début de tachycardie ventriculaire, et précisez les formes rythmées ou répétitives des extrasystoles.","rubric":[{"point":"Rappeler la définition commune : activation prématurée par rapport au rythme attendu","weight":1},{"point":"Décrire l'aspect de l'extrasystole ventriculaire : QRS large, ± onde P' rétrograde, isolée","weight":2},{"point":"Préciser le critère de nombre qui distingue l'extrasystolie répétitive d'une TV naissante : au moins 3 battements consécutifs à QRS large > 120 ms pour parler de TV","weight":2},{"point":"Citer les formes répétitives : doublet, triplet, salve","weight":1},{"point":"Citer les formes rythmées : bigéminisme (1 battement sur 2), trigéminisme (1 battement sur 3)","weight":1}],"model":"**Extrasystole ventriculaire** : activation prématurée naissant sous la bifurcation hissienne, donnant un QRS large, parfois suivi d'une onde P' rétrograde, isolée au sein d'un rythme de base.\n\n**Critère de distinction avec la TV** : dès que 3 battements consécutifs ou plus à QRS large (> 120 ms) et à fréquence > 100/min se succèdent, on ne parle plus d'extrasystoles répétitives mais de tachycardie ventriculaire (non soutenue si ≤ 30 secondes, soutenue au-delà).\n\n**Formes répétitives** : doublet (deux extrasystoles consécutives), triplet, salve (plusieurs extrasystoles successives).\n\n**Formes rythmées** : bigéminisme (une extrasystole toutes les deux systoles), trigéminisme (une extrasystole toutes les trois systoles).","src":"p. 397-399"},{"id":"231-qcm-301","type":"QRM","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'hypertrophie ventriculaire gauche (HVG) électrique :","options":[{"t":"L'indice de Sokolow additionne l'amplitude de l'onde S en V1 ou V2 et l'amplitude de l'onde R en V5 ou V6","ok":true,"why":"C'est la définition de l'indice de Sokolow, l'indice le plus utilisé pour le diagnostic d'HVG."},{"t":"Une valeur de Sokolow inférieure à 35 mm est considérée comme normale","ok":true,"why":"35 mm est le seuil normal habituellement retenu pour cet indice."},{"t":"Dans les formes sévères, on observe une onde T positive ample dans les dérivations latérales","ok":false,"why":"On observe au contraire une onde T négative, souvent associée à un sous-décalage du ST, par anomalie secondaire de la repolarisation."},{"t":"L'HVG électrique peut mimer une séquelle d'infarctus (pseudonécrose) en V1-V2","ok":true,"why":"Un aspect QS trompeur peut apparaître en V1-V2, associé parfois à un sus-décalage trompeur du ST."},{"t":"La déviation axiale associée est habituellement extrême, vers la droite","ok":false,"why":"La déviation axiale de l'HVG est modeste et orientée vers la GAUCHE."}],"explanation":"L'HVG électrique se traduit par un indice de Sokolow élevé (≥ 35 mm), une déviation axiale modeste vers la gauche, et, dans les formes sévères, des anomalies de repolarisation (onde T négative, sous-décalage ST) pouvant mimer une pseudonécrose.","src":"p. 406-407"},{"id":"231-qcm-302","type":"QRM","rank":"A","objective":"231-obj-05","tags":["étiologie","ECG"],"difficulty":1,"stem":"Concernant l'étiologie et certaines particularités de l'HVG à l'ECG :","options":[{"t":"L'hypertension artérielle est l'étiologie la plus fréquente","ok":true,"why":"C'est l'étiologie la plus fréquemment citée pour l'HVG."},{"t":"Le rétrécissement aortique est cité comme deuxième étiologie","ok":true,"why":"Il est cité juste après l'HTA parmi les causes d'HVG."},{"t":"La durée du QRS dépasse habituellement très largement 160 ms","ok":false,"why":"Le QRS peut être un peu élargi du fait de la masse myocardique et de la fibrose, mais il reste souvent inférieur à 120 ms."},{"t":"Un sus-décalage trompeur du segment ST peut être observé en V1-V2 associé à un aspect de pseudonécrose","ok":true,"why":"C'est un piège explicitement signalé sur les dérivations V1-V2 en cas d'HVG électrique importante."},{"t":"Le terme historique « surcharge diastolique » désigne la forme sévère","ok":false,"why":"C'est au contraire le terme « surcharge systolique » qui désigne la forme sévère, la forme modérée étant dite diastolique."}],"explanation":"L'HTA puis le rétrécissement aortique sont les principales étiologies de l'HVG ; le QRS reste le plus souvent < 120 ms malgré un possible élargissement modéré, et des pièges de pseudonécrose/pseudo-sus-décalage existent en V1-V2.","src":"p. 406-407"},{"id":"231-qcm-303","type":"QRM","rank":"B","objective":"231-obj-04","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'hypertrophie ventriculaire droite (HVD) à l'ECG :","options":[{"t":"Le signe le plus précoce est une déviation axiale droite supérieure à 90-110°","ok":true,"why":"C'est le signe précoce cité, en pratique retenu au-delà de 90°."},{"t":"On observe en V1 une onde R ample supérieure à 6 mm","ok":true,"why":"C'est l'un des signes cités d'HVD en V1."},{"t":"Un bloc de branche gauche est fréquemment associé à l'HVD","ok":false,"why":"C'est un bloc de branche DROIT qui est fréquemment associé à l'HVD, et non un bloc de branche gauche."},{"t":"Elle est fréquemment associée à une hypertrophie atriale droite et à un microvoltage chez le patient BPCO","ok":true,"why":"Cette association est explicitement décrite chez les patients atteints de bronchopneumopathie chronique obstructive."},{"t":"L'onde S en V5-V6 est habituellement de faible amplitude, inférieure à 2 mm","ok":false,"why":"L'onde S y est au contraire ample, supérieure à 7 mm."}],"explanation":"L'HVD associe déviation axiale droite, onde R ample en V1, onde S ample en V5-V6, et souvent bloc de branche droit et hypertrophie atriale droite (notamment chez le patient BPCO).","src":"p. 407"},{"id":"231-qcm-304","type":"QRM","rank":"B","objective":"231-obj-04","tags":["ECG","étiologie"],"difficulty":2,"stem":"Une patiente présente une dyspnée aiguë ; l'ECG montre une onde S en D1, une onde Q en D3 et une onde T négative en D3. Concernant ce tableau :","options":[{"t":"Il s'agit d'un aspect S1Q3T3","ok":true,"why":"C'est la description même de l'aspect S1Q3T3 décrit dans le texte."},{"t":"Cet aspect peut traduire une hypertrophie aiguë du ventricule droit au cours d'une embolie pulmonaire","ok":true,"why":"L'aspect S1Q3T3 correspond à une hypertrophie aiguë du VD, observée notamment dans l'embolie pulmonaire."},{"t":"Cet aspect élimine formellement une atteinte du ventricule droit","ok":false,"why":"Au contraire, il l'évoque, en traduisant une surcharge aiguë du ventricule droit."},{"t":"Une fibrillation atriale peut être associée sur le même tracé","ok":true,"why":"Le texte illustre un ECG d'embolie pulmonaire associant déviation axiale droite, S1Q3 et fibrillation atriale."},{"t":"L'onde T négative en V1 à V3 ne peut jamais être observée dans ce contexte","ok":false,"why":"Une onde T négative et asymétrique en V1, parfois V2-V3, peut au contraire s'observer dans les formes sévères d'HVD."}],"explanation":"L'aspect S1Q3T3 (S en D1, Q et T négative en D3) est un signe électrique de surcharge aiguë du ventricule droit, classiquement décrit au cours de l'embolie pulmonaire, pouvant s'associer à une fibrillation atriale.","src":"p. 407-408"},{"id":"231-qcm-305","type":"QRM","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"stem":"Concernant les anomalies ECG de l'hypokaliémie :","options":[{"t":"Onde T plate ou négative, diffuse, avec sous-décalage du ST","ok":true,"why":"C'est le premier signe décrit pour l'hypokaliémie."},{"t":"Allongement de l'intervalle QT","ok":true,"why":"L'hypokaliémie s'accompagne d'un allongement du QT."},{"t":"Raccourcissement de l'intervalle QT","ok":false,"why":"C'est l'inverse : l'hypokaliémie ALLONGE le QT."},{"t":"Apparition possible d'une onde U, à ne pas intégrer dans la mesure du QT","ok":true,"why":"L'onde U est une onde supplémentaire décrite en cas d'hypokaliémie."},{"t":"Élargissement constant et majeur du QRS","ok":false,"why":"Le QRS reste normal dans l'hypokaliémie ; c'est l'hyperkaliémie qui élargit le QRS."}],"explanation":"L'hypokaliémie associe onde T plate ou négative, sous-décalage du ST, allongement du QT et apparition possible d'une onde U, avec un QRS normal ; elle expose au risque de torsades de pointes.","src":"p. 408"},{"id":"231-qcm-306","type":"QRM","rank":"A","objective":"231-obj-21","tags":["ECG","biologie","urgence"],"difficulty":2,"stem":"Concernant les anomalies ECG de l'hyperkaliémie :","options":[{"t":"Onde T ample, pointue et symétrique","ok":true,"why":"C'est le signe le plus caractéristique de l'hyperkaliémie."},{"t":"Allongement de l'intervalle PR","ok":true,"why":"L'hyperkaliémie peut allonger le PR."},{"t":"Élargissement du QRS","ok":true,"why":"Un élargissement du QRS fait partie des anomalies décrites."},{"t":"Elle ne s'associe jamais à un bloc atrioventriculaire","ok":false,"why":"Elle peut au contraire s'associer à un BAV, une tachycardie ventriculaire ou une dysfonction sinusale."},{"t":"L'onde U est le signe le plus précoce et le plus spécifique de l'hyperkaliémie","ok":false,"why":"L'onde U est décrite comme un signe d'HYPOkaliémie ; le signe précoce de l'hyperkaliémie est l'onde T ample et pointue."}],"explanation":"L'hyperkaliémie associe onde T ample et pointue, allongement du PR, élargissement du QRS, et peut se compliquer de BAV, de tachycardie ventriculaire ou de dysfonction sinusale.","src":"p. 408"},{"id":"231-qcm-307","type":"QRM","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant les anomalies ECG de la péricardite aiguë en phase initiale :","options":[{"t":"Le sus-décalage de ST est concave vers le haut, diffus et concordant","ok":true,"why":"C'est l'aspect typique décrit pour la phase initiale."},{"t":"Il existe habituellement une image en miroir franche, comme dans le SCA avec sus-décalage de ST","ok":false,"why":"Le sus-décalage de la péricardite est typiquement diffus et concordant, SANS image en miroir."},{"t":"On observe un sous-décalage du segment PQ (PR)","ok":true,"why":"C'est un signe décrit dans la phase initiale, bien visible en V5-V6 et en inférieur."},{"t":"Le microvoltage est d'autant plus marqué que l'épanchement est liquidien abondant","ok":true,"why":"Le microvoltage est corrélé à l'importance de l'épanchement liquidien."},{"t":"L'évolution se fait toujours directement vers un ST isoélectrique, sans phase d'onde T négative","ok":false,"why":"L'évolution classique comporte 4 phases, dont une phase d'onde T négative persistante avant le retour progressif à la normale."}],"explanation":"La péricardite aiguë évolue en 4 phases : microvoltage et sus-décalage de ST diffus concave sans miroir avec sous-décalage de PQ, puis onde T plate, puis onde T négative persistante, puis normalisation.","src":"p. 409"},{"id":"231-qcm-308","type":"QRM","rank":"B","objective":"231-obj-25","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la préexcitation ventriculaire par voie accessoire (faisceau de Kent) :","options":[{"t":"Elle se traduit par un PR court, inférieur à 120 ms","ok":true,"why":"C'est l'un des signes cardinaux de la préexcitation."},{"t":"Elle se traduit par un élargissement du QRS avec empâtement du pied de QRS, appelé onde delta","ok":true,"why":"L'onde delta correspond à la partie du ventricule préexcitée par la voie accessoire."},{"t":"Des anomalies de repolarisation sont fréquemment associées, dans le territoire de la voie accessoire","ok":true,"why":"La dépolarisation anormale de cette zone s'accompagne souvent d'anomalies de repolarisation associées."},{"t":"Le blocage du nœud atrioventriculaire par manœuvre vagale ou adénosine est recommandé pour démasquer la voie accessoire, y compris en cas de fibrillation atriale","ok":false,"why":"C'est au contraire contre-indiqué en cas de FA, car cela peut favoriser une conduction exclusive et rapide par la voie accessoire."},{"t":"Un syndrome de Wolff-Parkinson-White désigne une voie accessoire antérograde occasionnant des palpitations par tachycardie jonctionnelle","ok":true,"why":"C'est la définition donnée du syndrome de Wolff-Parkinson-White."}],"explanation":"La préexcitation associe PR court, onde delta et anomalies de repolarisation ; le blocage du nœud atrioventriculaire est utile pour la démasquer, sauf en cas de fibrillation atriale associée.","src":"p. 410-411"},{"id":"231-qcm-309","type":"QRM","rank":"B","objective":"231-obj-25","tags":["ECG","urgence","pièges"],"difficulty":3,"stem":"Concernant le risque rythmique du syndrome de Wolff-Parkinson-White :","options":[{"t":"Le risque de mort subite est lié à une bonne perméabilité de la voie accessoire (période réfractaire courte)","ok":true,"why":"Une voie accessoire très perméable laisse passer un grand nombre d'influx atriaux en cas de FA associée."},{"t":"La voie accessoire possède, comme le nœud atrioventriculaire, une propriété « décrémentielle » qui filtre efficacement les influx","ok":false,"why":"À l'inverse, la voie accessoire NE possède PAS de propriété décrémentielle, contrairement au nœud atrioventriculaire."},{"t":"Le passage en fibrillation atriale rapide chez un patient à voie accessoire très perméable est appelé « super-Wolff »","ok":true,"why":"C'est le terme employé pour cette association à haut risque."},{"t":"L'adénosine est contre-indiquée dans ce contexte, comme dans l'asthme","ok":true,"why":"Le « super-Wolff » constitue, avec l'asthme, l'autre contre-indication à l'adénosine citée."},{"t":"La fibrillation atriale sur voie accessoire très perméable donne une tachycardie régulière à QRS fins","ok":false,"why":"Elle donne au contraire une tachycardie IRRÉGULIÈRE à QRS larges de taille variable, dite « en accordéon »."}],"explanation":"Le WPW à voie accessoire très perméable expose au « super-Wolff » en cas de FA (tachycardie irrégulière à QRS larges variables, potentiellement dégénérant en FV), l'adénosine y étant contre-indiquée.","src":"p. 411"},{"id":"231-qcm-310","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Concernant le diagnostic électrocardiographique d'un syndrome coronarien aigu avec sus-décalage du segment ST :","options":[{"t":"Un sus-décalage de 1,5 mm en V2 est considéré comme significatif","ok":false,"why":"Le seuil exigé de V1 à V3 est d'au moins 2 mm ; 1,5 mm n'atteint pas ce seuil."},{"t":"Le sus-décalage doit être retrouvé sur au moins 2 dérivations adjacentes","ok":true,"why":"C'est un critère explicite de significativité."},{"t":"Un sus-décalage englobant l'onde T réalise l'onde de Pardee","ok":true,"why":"C'est la définition de l'onde de Pardee."},{"t":"Il faut chercher le miroir sous forme de sous-décalage seulement après avoir identifié le sus-décalage","ok":true,"why":"Le texte insiste sur cet ordre : traquer d'abord le sus-décalage, puis chercher le miroir, et non l'inverse."},{"t":"L'apparition d'ondes Q de nécrose élimine toute indication de reperfusion","ok":false,"why":"La présence d'ondes Q ne doit pas faire considérer à tort qu'une reperfusion serait inutile car trop tardive."}],"explanation":"Le diagnostic de SCA ST+ repose sur un sus-décalage ≥ 2 mm en V1-V3 (≥ 1 mm ailleurs) sur au moins 2 dérivations adjacentes, avec recherche du miroir après identification du sus-décalage ; les ondes Q ne contre-indiquent pas la reperfusion.","src":"p. 411-412"},{"id":"231-qcm-311","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","pièges","diagnostic"],"difficulty":3,"stem":"Concernant les pièges diagnostiques d'un sus-décalage du segment ST :","options":[{"t":"Un bloc de branche gauche complet en contexte de douleur thoracique aiguë doit faire éliminer un SCA avec sus-décalage de ST","ok":true,"why":"Le texte impose d'éliminer ce diagnostic (échographie ± coronarographie) devant cette association."},{"t":"Un sous-décalage isolé en V1-V3 peut correspondre au miroir d'un sus-décalage postérieur (V7-V9)","ok":true,"why":"C'est un piège classique justifiant la réalisation d'un ECG 18 dérivations devant toute douleur thoracique."},{"t":"La repolarisation précoce ne donne jamais de sus-décalage du segment ST","ok":false,"why":"La repolarisation précoce est au contraire l'une des étiologies citées de sus-décalage du ST, dans les dérivations inférolatérales."},{"t":"L'angor de Prinzmetal peut mimer un sus-décalage de type SCA, par spasme coronarien","ok":true,"why":"C'est une des étiologies citées de sus-décalage du ST par spasme coronarien."},{"t":"Un anévrisme ventriculaire peut expliquer la persistance d'un sus-décalage bien après la phase aiguë","ok":true,"why":"Le sus-décalage peut persister indéfiniment en cas d'évolution anévrismale de la paroi infarcie."}],"explanation":"Cinq étiologies de sus-décalage du ST sont à connaître : SCA ST+, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite ; le bloc de branche gauche et l'HVG marquée sont des diagnostics différentiels à connaître.","src":"p. 412"},{"id":"231-qcm-312","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant les syndromes coronariens aigus sans sus-décalage du segment ST :","options":[{"t":"On peut observer un sous-décalage du segment ST","ok":true,"why":"C'est l'une des présentations possibles, correspondant à un courant de lésion sous-endocardique."},{"t":"Une inversion des ondes T peut traduire une ischémie sous-épicardique","ok":true,"why":"C'est une des présentations citées."},{"t":"Une pseudo-normalisation d'ondes T antérieurement négatives est possible","ok":true,"why":"C'est une présentation explicitement citée."},{"t":"L'ECG est nécessairement anormal","ok":false,"why":"Le texte précise qu'un ECG normal est possible en cas de SCA sans sus-décalage du ST."},{"t":"Les anomalies ne peuvent jamais être masquées par un pacemaker","ok":false,"why":"Le texte précise au contraire que les anomalies peuvent être masquées par un pacemaker."}],"explanation":"Les SCA sans sus-décalage du ST peuvent donner un sous-décalage du ST, une inversion ou un aplatissement des ondes T, une pseudo-normalisation d'ondes T négatives, voire un ECG normal ; un pacemaker peut masquer ces anomalies.","src":"p. 412-413"},{"id":"231-qcm-313","type":"QRM","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":2,"stem":"Concernant les indications d'implantation d'un pacemaker :","options":[{"t":"Les bradycardies symptomatiques par dysfonction sinusale sont une indication","ok":true,"why":"C'est une indication citée de pacemaker."},{"t":"Le BAV2 Mobitz 1 symptomatique est une indication","ok":true,"why":"Il est cité parmi les bradycardies symptomatiques justifiant un pacemaker."},{"t":"Les BAV infrahissiens (Mobitz 2, BAV3) sont une indication même en l'absence de symptôme","ok":true,"why":"Contrairement aux bradycardies « hautes », ces BAV infrahissiens sont une indication même asymptomatiques."},{"t":"Un défibrillateur implantable n'assure jamais la fonction pacemaker","ok":false,"why":"Le défibrillateur fait toujours fonction de pacemaker, sauf s'il est sous-cutané."},{"t":"La resynchronisation cardiaque peut être associée à la fonction défibrillateur","ok":true,"why":"Il est possible d'associer les trois fonctions au sein d'un défibrillateur de resynchronisation."}],"explanation":"Les indications de pacemaker sont les bradycardies symptomatiques (dysfonction sinusale, Mobitz 1, bradycardie sinusale) et les BAV infrahissiens même asymptomatiques ; défibrillateur et resynchronisation intègrent presque toujours la fonction pacemaker.","src":"p. 412-413"},{"id":"231-qcm-314","type":"QRM","rank":"B","objective":"231-obj-26","tags":["ECG"],"difficulty":2,"stem":"Concernant l'ECG d'un patient porteur d'un stimulateur cardiaque (pacemaker) :","options":[{"t":"Le spike de stimulation dure entre 0,4 et 1 ms","ok":true,"why":"C'est la durée décrite pour l'impulsion de pacemaker."},{"t":"En cas de dysfonction sinusale, le pacemaker stimule le ventricule sans stimuler l'oreillette","ok":false,"why":"En cas de dysfonction sinusale, le pacemaker stimule au contraire l'OREILLETTE (une onde P apparaît après le spike)."},{"t":"En cas de BAV, le QRS stimulé après le spike a un aspect de bloc de branche gauche","ok":true,"why":"La stimulation ventriculaire droite se propage de proche en proche vers le reste des ventricules, donnant cet aspect."},{"t":"La stimulation bipolaire est habituellement bien visible sur l'ECG de surface, contrairement à l'unipolaire","ok":false,"why":"C'est l'inverse : la stimulation unipolaire est bien visible sur l'ECG de surface, la bipolaire est peu visible."},{"t":"Le spike est pathognomonique de la présence d'une stimulation cardiaque","ok":true,"why":"Rien de physiologique n'est aussi bref sur un ECG."}],"explanation":"Le spike de stimulation (0,4 à 1 ms) est pathognomonique d'une stimulation cardiaque ; selon le mode (oreillette en cas de dysfonction sinusale, ventricule en cas de BAV avec aspect de BBG), et selon le montage (unipolaire bien visible, bipolaire peu visible).","src":"p. 413-414"},{"id":"231-qcm-315","type":"QRM","rank":"A","objective":"231-obj-27","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Parmi les situations suivantes, lesquelles constituent une indication à un ECG conventionnel (12 dérivations ou plus) ?","options":[{"t":"Bilan préopératoire chez un patient de plus de 65 ans","ok":true,"why":"C'est une indication explicitement citée."},{"t":"Bilan initial de l'hypertension artérielle, de façon obligatoire","ok":true,"why":"L'ECG est obligatoire dans le cadre du bilan de l'HTA."},{"t":"Palpitations ou douleur thoracique","ok":true,"why":"Ces symptômes constituent une indication explicite à l'ECG."},{"t":"Seulement chez les patients symptomatiques, jamais dans un bilan de santé systématique","ok":false,"why":"L'ECG est au contraire indiqué systématiquement dans les centres de santé, au moment des bilans de santé."},{"t":"Enquête familiale pour certaines cardiopathies héréditaires","ok":true,"why":"C'est une indication explicitement citée."}],"explanation":"L'ECG conventionnel est indiqué systématiquement en bilan de santé, en bilan préopératoire après 65 ans, dans les aptitudes professionnelles/sportives, en enquête familiale, devant tout symptôme cardiovasculaire, et obligatoirement dans le bilan de l'HTA.","src":"p. 414"},{"id":"231-qru-301","type":"QRU","rank":"B","objective":"231-obj-03","tags":["ECG"],"difficulty":1,"stem":"Quelle définition correspond à l'hypertrophie atriale gauche à l'ECG ?","options":[{"t":"Une onde P de durée supérieure à 110 ms (en pratique 120 ms), avec une composante négative > 40 ms en V1","ok":true,"why":"C'est la définition retenue pour l'hypertrophie atriale gauche."},{"t":"Une onde P d'amplitude supérieure à 2,5 mm en D2","ok":false,"why":"Ce critère d'amplitude définit l'hypertrophie atriale DROITE, non gauche."},{"t":"Un PR raccourci inférieur à 120 ms","ok":false,"why":"Ce signe est celui de la préexcitation, sans rapport avec l'hypertrophie atriale."},{"t":"Un indice de Sokolow supérieur à 35 mm","ok":false,"why":"Cet indice concerne l'hypertrophie VENTRICULAIRE gauche, pas atriale."},{"t":"Une onde P pointue en V1 supérieure à 2 mm","ok":false,"why":"Ce critère d'amplitude pointue concerne l'hypertrophie atriale DROITE."}],"explanation":"L'hypertrophie atriale gauche se traduit par un allongement de la durée de l'onde P (> 110-120 ms) avec une composante négative terminale en V1 supérieure à 40 ms.","src":"p. 406"},{"id":"231-qru-302","type":"QRU","rank":"B","objective":"231-obj-04","tags":["ECG"],"difficulty":1,"stem":"Quel critère définit l'hypertrophie atriale droite à l'ECG ?","options":[{"t":"Une onde P d'amplitude supérieure à 2,5 mm en D2, ou supérieure à 2 mm en V1/V2","ok":true,"why":"C'est le critère d'amplitude défini pour l'hypertrophie atriale droite."},{"t":"Une onde P de durée supérieure à 120 ms","ok":false,"why":"Ce critère de durée définit l'hypertrophie atriale GAUCHE, pas droite."},{"t":"Un axe de QRS inférieur à 0°","ok":false,"why":"L'axe de QRS n'est pas le critère de l'hypertrophie atriale ; c'est un critère d'HVD ventriculaire."},{"t":"Un QT supérieur à 0,44 seconde","ok":false,"why":"Ce critère concerne l'allongement du QT, sans rapport avec l'hypertrophie atriale."},{"t":"Une onde delta au pied du QRS","ok":false,"why":"L'onde delta est le signe d'une préexcitation, non d'une hypertrophie atriale."}],"explanation":"L'hypertrophie atriale droite se traduit par une onde P ample (> 2,5 mm en D2 ou > 2 mm en V1-V2), souvent pointue.","src":"p. 406"},{"id":"231-qru-303","type":"QRU","rank":"B","objective":"231-obj-23","tags":["ECG"],"difficulty":1,"stem":"Combien de phases classiques décrit-on dans l'évolution électrocardiographique d'une péricardite aiguë ?","options":[{"t":"Quatre phases","ok":true,"why":"L'évolution classique de la péricardite aiguë comporte 4 phases successives."},{"t":"Deux phases","ok":false,"why":"Ce nombre est insuffisant ; il en existe quatre."},{"t":"Six phases","ok":false,"why":"Ce nombre est trop élevé ; il en existe quatre."},{"t":"Une seule phase, stable jusqu'à guérison","ok":false,"why":"L'évolution est au contraire dynamique, en plusieurs phases successives."},{"t":"Trois phases","ok":false,"why":"Ce nombre est insuffisant ; il en existe quatre."}],"explanation":"L'évolution ECG de la péricardite aiguë comporte 4 phases : sus-décalage diffus concave avec sous-décalage de PQ, onde T plate, onde T négative persistante, puis normalisation.","src":"p. 409"},{"id":"231-qru-304","type":"QRU","rank":"A","objective":"231-obj-27","tags":["diagnostic"],"difficulty":1,"stem":"Dans quel contexte l'ECG conventionnel est-il décrit comme systématiquement obligatoire ?","options":[{"t":"Dans le bilan initial de l'hypertension artérielle","ok":true,"why":"Le texte précise que l'ECG est obligatoire dans le cadre du bilan de l'HTA."},{"t":"Dans le bilan initial d'une dyslipidémie isolée","ok":false,"why":"Ce contexte n'est pas cité comme rendant l'ECG obligatoire dans le texte."},{"t":"Avant toute prescription d'antalgique simple","ok":false,"why":"Ce contexte n'est pas une indication citée à l'ECG."},{"t":"Systématiquement avant tout vaccin","ok":false,"why":"Ce contexte n'est pas une indication citée à l'ECG."},{"t":"Uniquement chez le sujet de plus de 80 ans","ok":false,"why":"L'âge n'est pas le critère cité ; c'est le bilan de l'HTA qui rend l'ECG obligatoire."}],"explanation":"L'ECG conventionnel est explicitement indiqué comme obligatoire dans le cadre du bilan de l'hypertension artérielle.","src":"p. 414"},{"id":"231-qru-305","type":"QRU","rank":"A","objective":"231-obj-24","tags":["ECG"],"difficulty":2,"stem":"Quel seuil de sus-décalage du segment ST est exigé dans les dérivations V1 à V3 pour être considéré comme significatif ?","options":[{"t":"Au moins 2 mm","ok":true,"why":"C'est le seuil exigé de V1 à V3, contre 1 mm dans les autres dérivations."},{"t":"Au moins 0,5 mm","ok":false,"why":"Ce seuil est insuffisant ; il faut au moins 2 mm en V1-V3."},{"t":"Au moins 1 mm","ok":false,"why":"Ce seuil s'applique aux dérivations autres que V1-V3, qui exigent 2 mm."},{"t":"Au moins 5 mm","ok":false,"why":"Ce seuil est trop élevé ; le seuil retenu en V1-V3 est de 2 mm."},{"t":"Aucun seuil n'est requis en V1-V3","ok":false,"why":"Un seuil précis est au contraire exigé : au moins 2 mm en V1-V3."}],"explanation":"Le sus-décalage du ST est considéré comme significatif à partir de 2 mm de V1 à V3, et de 1 mm dans les autres dérivations, retrouvé sur au moins 2 dérivations adjacentes.","src":"p. 412"},{"id":"231-qroc-301","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG"],"difficulty":1,"question":"Quel indice ECG, comparant l'onde S en V1/V2 et l'onde R en V5/V6, sert au diagnostic d'hypertrophie ventriculaire gauche ?","answer":"L'indice de Sokolow","accept":["Sokolow"],"keywords":["sokolow"],"explanation":"L'indice de Sokolow additionne l'amplitude de l'onde S en V1 ou V2 et de l'onde R en V5 ou V6 ; il est normal en dessous de 35 mm.","src":"p. 406"},{"id":"231-qroc-302","type":"QROC","rank":"A","objective":"231-obj-05","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie la plus fréquente d'une hypertrophie ventriculaire gauche électrique ?","answer":"L'hypertension artérielle","accept":["HTA"],"keywords":["hta","hypertension"],"explanation":"L'HTA est citée comme la première étiologie de l'HVG, suivie du rétrécissement aortique.","src":"p. 407"},{"id":"231-qroc-303","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","étiologie"],"difficulty":1,"question":"Quel aspect ECG triphasique (S-Q-T) évoque une hypertrophie aiguë du ventricule droit au cours d'une embolie pulmonaire ?","answer":"L'aspect S1Q3T3","accept":["S1Q3T3"],"keywords":["s1q3t3"],"explanation":"L'aspect S1Q3T3 associe une onde S en D1, une onde Q en D3 et une onde T négative en D3.","src":"p. 407"},{"id":"231-qroc-304","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quelle anomalie ionique se caractérise par une onde T ample, pointue et symétrique, un allongement du PR et un élargissement du QRS ?","answer":"L'hyperkaliémie","accept":["hyperK"],"keywords":["hyperkaliemie"],"explanation":"Ces signes, associés à un risque de BAV, de tachycardie ventriculaire et de dysfonction sinusale, caractérisent l'hyperkaliémie.","src":"p. 408"},{"id":"231-qroc-305","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quelle onde ECG supplémentaire, à ne pas intégrer dans la mesure du QT, peut apparaître en cas d'hypokaliémie ?","answer":"L'onde U","accept":["onde U"],"keywords":["onde","u"],"explanation":"L'onde U est une onde supplémentaire, décrite derrière l'onde T, associée à l'hypokaliémie.","src":"p. 408"},{"id":"231-qroc-306","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG"],"difficulty":1,"question":"Quel segment est typiquement sous-décalé lors de la phase initiale d'une péricardite aiguë ?","answer":"Le segment PQ (PR)","accept":["segment PR"],"keywords":["pq","pr"],"explanation":"Le sous-décalage du segment PQ (PR) est un des signes de la phase initiale, bien visible en V5, V6 et en inférieur.","src":"p. 409"},{"id":"231-qroc-307","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG"],"difficulty":1,"question":"Quel intervalle est raccourci (inférieur à 120 ms) en cas de préexcitation ventriculaire ?","answer":"L'intervalle PR","accept":["PR court"],"keywords":["pr"],"explanation":"Le PR court traduit le passage rapide de l'influx par la voie accessoire, court-circuitant le délai physiologique du nœud atrioventriculaire.","src":"p. 410"},{"id":"231-qroc-308","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG"],"difficulty":1,"question":"Quel nom est donné à l'empâtement du pied du QRS observé en cas de préexcitation ventriculaire ?","answer":"L'onde delta","accept":["onde delta"],"keywords":["onde","delta"],"explanation":"L'onde delta correspond à la partie du ventricule préexcitée par la voie accessoire, à l'origine de l'élargissement du QRS.","src":"p. 410"},{"id":"231-qroc-309","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG"],"difficulty":1,"question":"Comment nomme-t-on un sus-décalage du segment ST qui englobe l'onde T ?","answer":"L'onde de Pardee","accept":["Pardee"],"keywords":["pardee"],"explanation":"L'onde de Pardee désigne un sus-décalage du ST tellement marqué qu'il englobe l'onde T.","src":"p. 412"},{"id":"231-qroc-310","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG"],"difficulty":1,"question":"Comment appelle-t-on l'impulsion électrique très brève, pathognomonique d'une stimulation cardiaque, visible sur l'ECG ?","answer":"Le spike de stimulation","accept":["spike"],"keywords":["spike"],"explanation":"Le spike dure entre 0,4 et 1 ms ; rien de physiologique n'étant aussi court sur un ECG, il est pathognomonique d'une stimulation cardiaque.","src":"p. 413"},{"id":"231-qroc-311","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique"],"difficulty":1,"question":"Quelle est la durée maximale de suivi permise par un moniteur ECG implantable (holter sous-cutané) ?","answer":"3 ans","accept":["trois ans"],"keywords":["3","ans"],"explanation":"Les holters sous-cutanés permettent un suivi jusqu'à 3 ans, utile pour le diagnostic étiologique de syncopes inexpliquées ou de FA silencieuse.","src":"p. 415"},{"id":"231-qroc-312","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique"],"difficulty":2,"question":"Quelle est la durée maximale d'enregistrement ECG ambulatoire, non implantable, utilisée en cas de symptômes rares (jusqu'à combien de jours) ?","answer":"21 jours","accept":["3 semaines"],"keywords":["21","jours"],"explanation":"En cas de symptômes rares, on peut utiliser des méthodes d'ECG ambulatoire de très longue durée, jusqu'à 21 jours, ou des enregistreurs d'événements.","src":"p. 415"},{"id":"231-open-31","type":"OPEN","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Décrivez la démarche diagnostique électrocardiographique de l'hypertrophie ventriculaire gauche, les anomalies observées dans les formes sévères, et les pièges d'interprétation associés.","rubric":[{"point":"Définir l'indice de Sokolow et son seuil normal (< 35 mm)","weight":2},{"point":"Décrire la déviation axiale associée : modeste, vers la gauche","weight":1},{"point":"Décrire les anomalies de repolarisation des formes sévères : onde T négative et sous-décalage du ST en latéral, disparition de l'onde Q septale","weight":2},{"point":"Citer le piège de pseudonécrose/pseudo-sus-décalage en V1-V2","weight":2},{"point":"Citer les principales étiologies : HTA puis rétrécissement aortique","weight":1}],"model":"**Diagnostic** : l'indice de Sokolow (somme de l'onde S en V1/V2 et de l'onde R en V5/V6) est l'indice le plus utilisé, normal sous 35 mm. La déviation axiale associée est modeste, orientée vers la gauche, et les QRS restent le plus souvent inférieurs à 120 ms malgré un possible élargissement lié à la masse myocardique.\n\n**Formes sévères** : anomalie secondaire de la repolarisation avec onde T négative et sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6), et disparition de l'onde Q septale dans ces mêmes dérivations.\n\n**Pièges** : une HVG électrique importante peut donner en V1-V2 un aspect QS mimant une séquelle d'infarctus (pseudonécrose) et/ou un sus-décalage trompeur du segment ST.\n\n**Étiologies** : l'hypertension artérielle est la plus fréquente, suivie du rétrécissement aortique.","src":"p. 406-407"},{"id":"231-open-32","type":"OPEN","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":2,"prompt":"Comparez les anomalies électrocardiographiques de l'hypokaliémie et de l'hyperkaliémie, ainsi que leurs principaux risques rythmiques.","rubric":[{"point":"Décrire les signes ECG de l'hypokaliémie : onde T plate/négative, sous-décalage du ST, QT allongé, onde U","weight":3},{"point":"Décrire les signes ECG de l'hyperkaliémie : onde T ample et pointue, PR allongé, QRS élargi","weight":3},{"point":"Citer les risques rythmiques de l'hypokaliémie : extrasystoles, TV, torsades de pointes, FV","weight":2},{"point":"Citer les risques rythmiques de l'hyperkaliémie : BAV, TV, dysfonction sinusale","weight":2}],"model":"**Hypokaliémie** : onde T plate ou négative diffuse avec sous-décalage du ST, QRS normal, allongement du QT avec apparition possible d'une onde U (à ne pas intégrer à la mesure du QT). Elle expose à l'extrasystolie, à la tachycardie ventriculaire, à la torsade de pointes et à la fibrillation ventriculaire.\n\n**Hyperkaliémie** : onde T ample, pointue et symétrique, allongement du PR, élargissement du QRS. Elle expose au bloc atrioventriculaire, à la tachycardie ventriculaire et à la dysfonction sinusale.\n\nCes deux dyskaliémies imposent une correction ionique urgente devant toute anomalie ECG évocatrice.","src":"p. 408"},{"id":"231-open-33","type":"OPEN","rank":"A","objective":"231-obj-24","tags":["ECG","urgence","pièges"],"difficulty":3,"prompt":"Détaillez les critères électrocardiographiques du syndrome coronarien aigu avec sus-décalage du segment ST, ainsi que les principaux pièges diagnostiques à connaître.","rubric":[{"point":"Citer les seuils de sus-décalage significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes","weight":2},{"point":"Décrire l'onde de Pardee (sus-décalage englobant l'onde T)","weight":1},{"point":"Décrire la démarche : traquer le sus-décalage puis chercher le miroir (sous-décalage), pas l'inverse","weight":1},{"point":"Citer au moins 3 des 5 étiologies de sus-décalage du ST (SCA ST+, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite)","weight":2},{"point":"Citer les diagnostics différentiels/pièges : bloc de branche gauche complet, HVG marquée, sous-décalage antérieur miroir d'un sus-décalage postérieur (justifiant un ECG 18 dérivations)","weight":2},{"point":"Préciser que les ondes Q de nécrose n'excluent pas une indication de reperfusion","weight":1}],"model":"**Critères** : sus-décalage ≥ 2 mm de V1 à V3 et ≥ 1 mm dans les autres dérivations, retrouvé sur au moins 2 dérivations adjacentes ; lorsqu'il englobe l'onde T, il réalise l'onde de Pardee. La démarche consiste à identifier le sus-décalage puis à chercher son miroir, et non l'inverse.\n\n**Cinq étiologies de sus-décalage du ST** : SCA avec sus-décalage (onde de Pardee avec miroir), anévrisme ventriculaire (persistance après infarctus séquellaire marqué), repolarisation précoce (inférolatérale), angor de Prinzmetal (spasme coronarien), péricardite (diffus, concave, sans miroir).\n\n**Pièges** : un bloc de branche gauche complet en contexte de douleur thoracique aiguë doit faire éliminer un SCA ST+ ; une HVG marquée peut donner un sous-décalage dans les dérivations où le QRS est négatif et un sus-décalage en V1-V2 ; un sous-décalage antérieur (V1-V3) peut être le miroir d'un sus-décalage postérieur (V7-V9), justifiant un ECG 18 dérivations devant toute douleur thoracique. Enfin, la présence d'ondes Q de nécrose ne doit pas faire renoncer à tort à une reperfusion jugée trop tardive.","src":"p. 411-412"},{"id":"231-open-34","type":"OPEN","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":2,"prompt":"Expliquez comment reconnaître, sur l'ECG, la présence d'une stimulation cardiaque (pacemaker), et précisez les principales indications à son implantation.","rubric":[{"point":"Décrire le spike de stimulation : impulsion très brève (0,4-1 ms), pathognomonique","weight":2},{"point":"Décrire l'aspect en cas de stimulation atriale (dysfonction sinusale) : onde P après le spike","weight":1},{"point":"Décrire l'aspect en cas de stimulation ventriculaire (BAV) : QRS large d'aspect de bloc de branche gauche après le spike","weight":2},{"point":"Opposer stimulation unipolaire (bien visible) et bipolaire (peu visible) sur l'ECG de surface","weight":1},{"point":"Citer les indications : bradycardies symptomatiques (dysfonction sinusale, Mobitz 1, bradycardie sinusale) et BAV infrahissiens (Mobitz 2, BAV3) même asymptomatiques","weight":2}],"model":"**Reconnaissance** : le spike de stimulation est une impulsion électrique très brève (0,4 à 1 ms), pathognomonique d'une stimulation cardiaque, rien de physiologique n'étant aussi court sur un ECG. En cas de dysfonction sinusale, le pacemaker stimule l'oreillette (onde P après le spike). En cas de BAV, il stimule le ventricule avec un délai AV programmé, donnant un QRS large après le spike, d'aspect de bloc de branche gauche (la stimulation ventriculaire droite se propageant de proche en proche vers le reste des ventricules). La stimulation unipolaire (entre le bout de la sonde et le boîtier) est bien visible sur l'ECG de surface, la bipolaire (entre le bout de la sonde et une électrode proche) est peu visible.\n\n**Indications** : bradycardies symptomatiques (dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale) et BAV infrahissiens (BAV2 Mobitz 2, BAV3), ces derniers même en l'absence de symptôme.","src":"p. 412-414"},{"id":"231-qroc-401","type":"QROC","rank":"A","objective":"231-obj-01","tags":["examens"],"difficulty":1,"question":"À 25 mm/s, quelle durée représente un petit carreau (1 mm) de l'ECG ?","answer":"40 ms","accept":["40 ms","0,04 s","0.04"],"keywords":["40"],"explanation":"À 25 mm/s, 1 mm = 40 ms et un grand carreau de 5 mm = 200 ms.","src":"p. 375"},{"id":"231-qroc-402","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":1,"question":"Quelles sont les bornes normales de l'intervalle PR ?","answer":"120 à 200 ms","accept":["120-200","120 a 200"],"keywords":["120","200"],"explanation":"Le PR normal, du début de P au début du QRS, est compris entre 120 et 200 ms inclus.","src":"p. 375"},{"id":"231-qroc-403","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":2,"question":"Quelle est la limite supérieure normale du QT corrigé à 60 bpm ?","answer":"450 ms","accept":["450"],"keywords":["450"],"explanation":"Le QTc normal est < 450 ms à 60 bpm (en pratique 470-480 ms).","src":"p. 375"},{"id":"231-qroc-404","type":"QROC","rank":"A","objective":"231-obj-24","tags":["diagnostic"],"difficulty":2,"question":"Quelle amplitude minimale de sus-décalage du ST est significative en V1-V3 ?","answer":"2 mm (≥ 2 mm)","accept":["2 mm","≥ 2"],"keywords":["2"],"explanation":"Le sus-ST est significatif s'il atteint ≥ 2 mm en V1-V3 et ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes.","src":"p. 412"},{"id":"231-qroc-406","type":"QROC","rank":"A","objective":"231-obj-08","tags":["définition","diagnostic"],"difficulty":1,"question":"Comment se définit le BAV du 1er degré ?","answer":"PR constant > 200 ms sans onde P bloquée","accept":["pr > 200","pr allonge","pr long"],"keywords":["200"],"explanation":"Le BAV1 est un PR constant supérieur à 200 ms, toutes les P étant conduites.","src":"p. 386"},{"id":"231-qroc-407","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic"],"difficulty":2,"question":"Quel est le siège habituel d'un BAV2 Mobitz 2 ?","answer":"Infrahissien","accept":["infrahissien","infra-hissien","sous-hissien"],"keywords":["infra"],"explanation":"Le Mobitz 2 (PR constant puis P bloquée inopinée) est infrahissien, alors que le Mobitz 1 est suprahissien.","src":"p. 385"},{"id":"231-qroc-408","type":"QROC","rank":"A","objective":"231-obj-21","tags":["diagnostic","urgence"],"difficulty":2,"question":"Quelle TV polymorphe peut compliquer l'allongement du QT de l'hypokaliémie ?","answer":"La torsade de pointes","accept":["torsade","tdp"],"keywords":["torsade"],"explanation":"L'hypokaliémie allonge le QT et expose aux ESV, TV, torsades de pointes et FV.","src":"p. 408"},{"id":"231-qroc-409","type":"QROC","rank":"A","objective":"231-obj-14","tags":["diagnostic"],"difficulty":1,"question":"Quelle est la fréquence ventriculaire classique d'un flutter atrial conduit en 2/1 ?","answer":"150 bpm","accept":["150"],"keywords":["150"],"explanation":"Avec une activité atriale à 300 bpm, la conduction 2/1 donne classiquement 150 bpm (100 en 3/1, 75 en 4/1).","src":"p. 394"},{"id":"231-qroc-410","type":"QROC","rank":"A","objective":"231-obj-15","tags":["diagnostic"],"difficulty":2,"question":"Quelle est la fréquence habituelle d'une tachycardie jonctionnelle ?","answer":"Environ 200 bpm (130-260)","accept":["200"],"keywords":["200"],"explanation":"La tachycardie jonctionnelle (Bouveret) est très régulière, autour de 200 bpm (130-260).","src":"p. 395"},{"id":"231-qroc-411","type":"QROC","rank":"A","objective":"231-obj-12","tags":["diagnostic"],"difficulty":2,"question":"Comment varie la fréquence d'une TSV non sinusale, par opposition à la variation progressive de la tachycardie sinusale ?","answer":"Par « marches d'escalier »","accept":["marche d'escalier","marches d'escalier","escalier"],"keywords":["escalier"],"explanation":"La tachycardie sinusale varie progressivement, une TSV varie brutalement par marches d'escalier.","src":"p. 390-391"},{"id":"231-qroc-412","type":"QROC","rank":"A","objective":"231-obj-18","tags":["diagnostic"],"difficulty":3,"question":"Outre la dissociation ventriculoatriale, quels complexes affirment avec certitude une TV ?","answer":"Les complexes de capture et de fusion","accept":["capture et fusion","captures et fusions"],"keywords":["captur","fusion"],"explanation":"Les captures (QRS fin précédé d'une P) et les fusions (QRS intermédiaire) ne sont possibles qu'en cas de dissociation et signent la TV.","src":"p. 400"},{"id":"231-qroc-413","type":"QROC","rank":"A","objective":"231-obj-02","tags":["urgence","traitement"],"difficulty":1,"question":"Quel traitement s'impose devant une tachycardie mal tolérée sur le plan hémodynamique ?","answer":"La cardioversion électrique externe","accept":["cardioversion","choc electrique","cee"],"keywords":["electri"],"explanation":"Toute tachycardie avec mauvaise tolérance hémodynamique impose une cardioversion électrique externe.","src":"p. 405"},{"id":"231-qroc-414","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic"],"difficulty":2,"question":"Au-delà de quelle valeur d'axe du QRS parle-t-on d'hémibloc antérieur gauche ?","answer":"Au-delà de –30° (D2 négatif)","accept":["-30","–30"],"keywords":["30"],"explanation":"L'HBAG dévie l'axe au-delà de –30° (D2 négatif), l'HBPG au-delà de +90° (D1 négatif).","src":"p. 382"},{"id":"231-qroc-415","type":"QROC","rank":"A","objective":"231-obj-24","tags":["diagnostic"],"difficulty":1,"question":"Quelles dérivations explorent le territoire inférieur du VG ?","answer":"D2, D3, aVF","accept":["d2 d3 avf","ii, iii, avf","ii iii avf"],"keywords":["avf"],"explanation":"Le territoire inférieur (diaphragmatique) est exploré par D2, D3 et aVF.","src":"p. 371"},{"id":"231-qroc-416","type":"QROC","rank":"B","objective":"231-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Quelle amplitude de l'onde P en D2 définit une hypertrophie atriale droite ?","answer":"Plus de 2,5 mm","accept":["2,5","2.5"],"keywords":["2"],"explanation":"L'HAD donne une P > 2,5 mm en D2 (souvent pointue) ou > 2 mm en V1-V2.","src":"p. 406"},{"id":"231-qroc-417","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":2,"question":"Quelle pathologie respiratoire contre-indique l'adénosine IV ?","answer":"L'asthme","accept":["asthme"],"keywords":["asthm"],"explanation":"L'adénosine peut provoquer un bronchospasme intense transitoire ; elle est contre-indiquée en cas d'asthme, d'hypotension et de FA préexcitée.","src":"p. 390"},{"id":"231-qroc-418","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens"],"difficulty":2,"question":"Quelle est la durée d'enregistrement d'un Holter ECG classique ?","answer":"24 à 96 heures","accept":["24 a 96","24-96","24 h"],"keywords":["24"],"explanation":"Le Holter enregistre 2 à 12 dérivations sur 24 à 96 h au maximum, avec lecture différée.","src":"p. 415"},{"id":"231-qroc-419","type":"QROC","rank":"B","objective":"231-obj-25","tags":["diagnostic","urgence"],"difficulty":3,"question":"Quel aspect des QRS caractérise une FA conduite par une voie accessoire (super-Wolff) ?","answer":"QRS de largeur variable « en accordéon », très rapides et irréguliers","accept":["accordeon"],"keywords":["accord"],"explanation":"En FA, une voie accessoire à période réfractaire courte donne une tachycardie irrégulière très rapide à QRS en accordéon, pouvant dégénérer en FV.","src":"p. 410-411"},{"id":"231-qroc-420","type":"QROC","rank":"B","objective":"231-obj-26","tags":["diagnostic"],"difficulty":2,"question":"Quel aspect de QRS suit le spike d'une stimulation ventriculaire droite par pacemaker ?","answer":"QRS large d'aspect BBG","accept":["bbg","branche gauche"],"keywords":["gauche"],"explanation":"La stimulation du VD se propage de proche en proche et donne un QRS large d'aspect bloc de branche gauche.","src":"p. 413-414"},{"id":"231-qcm-501","type":"QRM","rank":"B","objective":"231-obj-01","tags":["électrophysiologie","physiologie"],"difficulty":1,"stem":"Concernant la genèse du signal ECG et la conduction atrioventriculaire, quelles propositions sont exactes ?","options":[{"t":"L'activité enregistrée par l'ECG provient de la somme des potentiels d'action cellulaires.","ok":true,"why":"Elle suit la propagation d'un front de dépolarisation."},{"t":"Un front de dépolarisation qui se dirige vers l'électrode inscrit une onde positive.","ok":true,"why":"S'il s'éloigne de l'électrode, l'onde est négative."},{"t":"Sur l'ECG normal, les ondes T sont discordantes par rapport aux QRS.","ok":false,"why":"Elles sont concordantes : T positive si QRS positif, T négative si QRS négatif."},{"t":"La dépolarisation ventriculaire progresse de l'endocarde vers l'épicarde, la repolarisation en sens inverse.","ok":true,"why":"C'est ce qui explique la concordance des ondes T."},{"t":"Il existe physiologiquement plusieurs passages électriques entre oreillettes et ventricules.","ok":false,"why":"Le NAV est le seul passage physiologique ; le reste du plan de l'anneau est isolant."}],"explanation":"L'ECG enregistre la somme des potentiels d'action ; un front qui se dirige vers l'électrode est positif ; les T sont concordantes car la repolarisation progresse de l'épicarde vers l'endocarde ; le NAV est le seul passage atrioventriculaire physiologique.","src":"p. 371, 410"},{"id":"231-qcm-502","type":"QRM","rank":"A","objective":"231-obj-01","tags":["axe","ECG normal"],"difficulty":2,"stem":"Concernant l'axe du QRS dans le plan frontal, quelles propositions sont exactes ?","options":[{"t":"Le double triaxe de Bailey gradue les dérivations de 30° en 30° dans le sens horaire, D1 étant à 0°.","ok":true,"why":"C'est la construction décrite : dérivations graduées de 30° en 30°, sens horaire, D1 à l'horizontale (0°)."},{"t":"Chez le sujet filiforme au cœur vertical, l'axe est proche de 90°.","ok":true,"why":"Le cours cite le cœur vertical du sujet filiforme avec un axe proche de 90°."},{"t":"Chez l'obèse au cœur horizontal, l'axe est proche de 0°.","ok":true,"why":"Cœur horizontal de l'obèse ou de la cardiomégalie : axe proche de 0°."},{"t":"Un hémibloc gauche peut rendre l'axe du QRS anormal.","ok":true,"why":"L'axe est anormal en cas d'hémibloc gauche ou d'anomalie morphologique marquée d'un ventricule."},{"t":"Une onde isodiphasique a une composante positive nettement prédominante.","ok":false,"why":"Une onde isodiphasique a des composantes positive et négative d'égale importance."}],"explanation":"L'axe se mesure sur le double triaxe de Bailey ; il varie avec la morphologie (cœur vertical ≈ 90°, horizontal ≈ 0°) et devient anormal en cas d'hémibloc gauche ou d'anomalie ventriculaire marquée.","src":"p. 375"},{"id":"231-qcm-503","type":"QRM","rank":"A","objective":"231-obj-01","tags":["repolarisation","piège"],"difficulty":2,"stem":"Concernant l'interprétation de la repolarisation, quelles propositions sont exactes ?","options":[{"t":"Chez l'homme jeune, un point J sus-décalé de V1 à V4 avec un ST jonctionnel ascendant peut correspondre à une repolarisation physiologique.","ok":true,"why":"Le cours décrit cet aspect comme une repolarisation physiologique chez le jeune, surtout l'homme."},{"t":"Des ondes T négatives dans toutes les précordiales sont pathologiques et doivent d'abord faire éliminer une ischémie.","ok":true,"why":"C'est la consigne du cours : T négatives dans toutes les précordiales = pathologique, éliminer d'abord une ischémie."},{"t":"Une onde T négative en aVR est pathologique.","ok":false,"why":"Les T sont normalement positives partout sauf en aVR et V1 (parfois D3 et aVL)."},{"t":"Des ondes T négatives en D2 et D3 sont pathologiques.","ok":true,"why":"Deux T négatives dans un même territoire (ici inférieur) sont pathologiques."},{"t":"L'onde U doit être incluse dans la mesure du QT.","ok":false,"why":"Il ne faut jamais inclure une onde U dans la mesure du QT."}],"explanation":"T négative physiologique en aVR et V1 (parfois D3, aVL) ; deux T négatives dans un même territoire ou dans toutes les précordiales sont pathologiques. Le sus-décalage du point J V1-V4 du sujet jeune est une variante physiologique.","src":"p. 377-378, 388, 411"},{"id":"231-qcm-504","type":"QRM","rank":"B","objective":"231-obj-07","tags":["blocs de branche","bloc fonctionnel"],"difficulty":2,"stem":"Concernant les blocs de branche incomplets et fonctionnels, quelles propositions sont exactes ?","options":[{"t":"Un bloc incomplet reproduit les anomalies du bloc complet avec un QRS de 110 à 120 ms.","ok":true,"why":"Blocs incomplets : mêmes anomalies avec QRS de 110-120 ms."},{"t":"Le bloc incomplet a un intérêt sémiologique majeur.","ok":false,"why":"Le cours lui attribue un faible intérêt sémiologique."},{"t":"Un bloc fonctionnel n'existe qu'à partir d'une fréquence cardiaque donnée.","ok":true,"why":"C'est la définition du bloc fonctionnel."},{"t":"Un bloc de branche fonctionnel peut n'apparaître que lors d'une tachycardie.","ok":true,"why":"Il n'existe qu'à partir d'une fréquence cardiaque donnée (tachycardie ou bradycardie)."},{"t":"Un bloc fonctionnel est présent quelle que soit la fréquence cardiaque.","ok":false,"why":"Il n'existe qu'à partir d'une fréquence cardiaque donnée."}],"explanation":"Bloc incomplet : mêmes anomalies avec un QRS de 110-120 ms, faible intérêt sémiologique. Bloc fonctionnel : n'existe qu'à partir d'une fréquence donnée, en tachycardie ou en bradycardie.","src":"p. 380-381"},{"id":"231-qcm-506","type":"QRM","rank":"A","objective":"231-obj-08","tags":["BAV","piège"],"difficulty":2,"stem":"Concernant la sémiologie des blocs atrioventriculaires, quelles propositions sont exactes ?","options":[{"t":"Dans un BAV, les ondes P sont régulières et à fréquence normale.","ok":true,"why":"C'est la règle rappelée par le cours pour les BAV."},{"t":"Un BAV 2/1 avec des QRS larges oriente vers un siège infrahissien.","ok":true,"why":"BAV 2/1 : infrahissien si QRS larges."},{"t":"Un BAV 2/1 à QRS fins avec des périodes de Mobitz 1 à d'autres moments oriente vers un siège suprahissien.","ok":true,"why":"BAV 2/1 : suprahissien si QRS fins et Mobitz 1 à d'autres moments."},{"t":"Une onde P « bloquée » survenant plus précocement que les autres correspond en fait à une extrasystole atriale bloquée.","ok":true,"why":"Le cours signale ce piège : P bloquée plus précoce = extrasystole atriale bloquée."},{"t":"Le BAV2 Mobitz 2 se caractérise par un allongement progressif du PR avant l'onde P bloquée.","ok":false,"why":"Dans le Mobitz 2 le PR est constant avant la P bloquée inopinée ; l'allongement progressif définit le Mobitz 1."}],"explanation":"Dans un BAV, les P sont régulières à fréquence normale. Le siège d'un BAV 2/1 s'oriente sur la largeur des QRS et l'existence de Mobitz 1 ; une P bloquée prématurée est une ESA bloquée.","src":"p. 385-386"},{"id":"231-qcm-507","type":"QRM","rank":"A","objective":"231-obj-14","tags":["flutter","flutter atypique"],"difficulty":2,"stem":"Concernant les différentes formes de flutter atrial, quelles propositions sont exactes ?","options":[{"t":"Les flutters droits sont beaucoup plus fréquents que les flutters gauches.","ok":true,"why":"Le cours indique flutters droits ≫ gauches (zones propices dans l'OD même sans cardiopathie)."},{"t":"Les flutters gauches surviennent surtout après un remodelage ou une intervention.","ok":true,"why":"Les flutters gauches apparaissent après remodelage ou intervention."},{"t":"Les flutters atypiques n'impliquent pas l'isthme cavotricuspide.","ok":true,"why":"Flutters atypiques : isthme non impliqué, droits, gauches ou biatriaux."},{"t":"La fréquence atriale d'un flutter atypique est toujours comprise entre 280 et 320/min.","ok":false,"why":"Les flutters atypiques ont une fréquence de 120 à 320 bpm."},{"t":"Dans le flutter typique horaire, les ondes F sont négatives en D2, D3 et aVF comme dans la forme antihoraire.","ok":false,"why":"Dans le flutter typique horaire, les polarités sont inversées par rapport à la forme antihoraire."}],"explanation":"Le flutter typique emprunte l'isthme cavotricuspide (antihoraire : F négatives en inférieur ; horaire : polarités inversées). Les flutters atypiques n'impliquent pas l'isthme et ont une fréquence de 120 à 320 bpm.","src":"p. 393-394"},{"id":"231-qcm-508","type":"QRM","rank":"A","objective":"231-obj-02","tags":["tachycardie","algorithme","urgence"],"difficulty":2,"stem":"Devant une tachycardie (FC > 100 bpm), selon l'algorithme proposé, quelles propositions sont exactes ?","options":[{"t":"Une tachycardie irrégulière oriente d'abord vers une fibrillation atriale, le diagnostic différentiel étant les extrasystoles atriales.","ok":true,"why":"Irrégulière → FA (diagnostic différentiel : ESA)."},{"t":"Une tachycardie régulière à QRS fins est d'origine supraventriculaire.","ok":true,"why":"Régulière à QRS fins → supraventriculaire."},{"t":"Une tachycardie régulière à QRS larges peut correspondre à une tachycardie supraventriculaire avec bloc de branche.","ok":true,"why":"Régulière à QRS larges → ventriculaire jusqu'à preuve du contraire, ou TSV + bloc de branche."},{"t":"En cas de mauvaise tolérance hémodynamique, les manœuvres vagales doivent précéder toute cardioversion.","ok":false,"why":"Mauvaise tolérance hémodynamique → cardioversion électrique externe ; les manœuvres vagales sont réservées aux tachycardies bien tolérées."},{"t":"Une tachycardie régulière à QRS larges est d'origine supraventriculaire jusqu'à preuve du contraire.","ok":false,"why":"C'est l'inverse : elle est ventriculaire jusqu'à preuve du contraire."}],"explanation":"Irrégulière → FA ; régulière à QRS larges → TV jusqu'à preuve du contraire (ou TSV + bloc) ; régulière à QRS fins → TSV. Mauvaise tolérance → cardioversion électrique externe.","src":"p. 405"},{"id":"231-qcm-509","type":"QRM","rank":"A","objective":"231-obj-18","tags":["tachycardie ventriculaire","mécanisme"],"difficulty":2,"stem":"Concernant la tachycardie ventriculaire (TV), quelles propositions sont exactes ?","options":[{"t":"Sur cardiopathie, son mécanisme le plus fréquent est une réentrée autour d'une zone de fibrose post-infarctus.","ok":true,"why":"La réentrée est le mécanisme le plus fréquent sur cardiopathie, autour d'une fibrose post-infarctus."},{"t":"Sur cœur sain, elle peut relever d'un automatisme anormal.","ok":true,"why":"L'automatisme anormal est cité comme mécanisme sur cœur sain."},{"t":"Elle peut évoluer vers la fibrillation ventriculaire puis l'asystolie.","ok":true,"why":"Le cours décrit la séquence TV → FV → asystolie."},{"t":"Un QRS positif en aVR (axe extrême) est fréquent dans les blocs de branche banals.","ok":false,"why":"Un QRS positif en aVR n'est jamais vu dans un BBD ou un BBG : c'est un argument en faveur de la TV."},{"t":"Elle naît au-dessus de la bifurcation hissienne.","ok":false,"why":"Les tachycardies ventriculaires naissent sous la bifurcation hissienne, d'où des QRS larges."}],"explanation":"La TV naît sous la bifurcation hissienne (QRS larges), par réentrée sur fibrose ou automatisme anormal sur cœur sain ; elle peut dégénérer en FV puis asystolie. L'axe extrême (QRS positif en aVR) plaide en sa faveur.","src":"p. 398-400"},{"id":"231-qcm-510","type":"QRM","rank":"B","objective":"231-obj-23","tags":["péricardite","évolution"],"difficulty":2,"stem":"Concernant l'évolution électrocardiographique d'une péricardite aiguë, quelles propositions sont exactes ?","options":[{"t":"La phase 1, avec sus-décalage du ST, est brève.","ok":true,"why":"Le cours qualifie la phase 1 de brève."},{"t":"En phase 2, les ondes T s'aplatissent partout, avec un ST isoélectrique.","ok":true,"why":"Phase 2 : T plates partout, ST isoélectrique."},{"t":"En phase 3, les ondes T deviennent négatives de façon persistante.","ok":true,"why":"Phase 3 : T négatives persistantes."},{"t":"La phase 4 correspond à un retour progressif à la normale.","ok":true,"why":"Phase 4 : retour progressif à la normale."},{"t":"Devant un sus-décalage du ST, l'absence de miroir suffit à conclure à une péricardite plutôt qu'à un SCA ST+.","ok":false,"why":"Le cours met en garde : ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque."}],"explanation":"La péricardite évolue en 4 phases : sus-ST bref, T plates avec ST isoélectrique, T négatives persistantes, puis normalisation. L'absence de miroir n'élimine pas à elle seule un SCA ST+.","src":"p. 409"},{"id":"231-qcm-511","type":"QRM","rank":"A","objective":"231-obj-24","tags":["SCA","onde Q","séquelles"],"difficulty":2,"stem":"Concernant les ondes Q de nécrose et l'évolution de l'ECG après un SCA avec sus-décalage du ST, quelles propositions sont exactes ?","options":[{"t":"Les ondes Q de nécrose apparaissent en principe vers la 6e heure.","ok":true,"why":"Elles apparaissent en principe vers la 6e heure, parfois plus tôt."},{"t":"La présence d'ondes Q signifie qu'une reperfusion est devenue inutile.","ok":false,"why":"Le cours précise que leur présence ne signifie pas qu'une reperfusion serait inutile."},{"t":"Un rabotage (écrêtement) de l'onde R, surtout en V2-V3, est un équivalent d'onde Q de nécrose.","ok":true,"why":"Le rabotage de l'onde R est cité comme équivalent, surtout en V2-V3."},{"t":"Après 48 heures apparaît une onde T négative « ischémique », parfois très prolongée.","ok":true,"why":"C'est l'évolution décrite après 48 h."},{"t":"Un sus-décalage du ST persistant indéfiniment doit faire évoquer un anévrisme de la paroi infarcie.","ok":true,"why":"La persistance indéfinie du sus-ST évoque un anévrisme de la paroi infarcie."}],"explanation":"Ondes Q vers la 6e heure (sans remettre en cause la reperfusion), rabotage de R comme équivalent, T négative ischémique après 48 h, sus-ST persistant en cas d'anévrisme.","src":"p. 411-412"},{"id":"231-qcm-512","type":"QRM","rank":"B","objective":"231-obj-26","tags":["prothèses rythmiques","stimulation"],"difficulty":2,"stem":"Concernant les prothèses rythmiques cardiaques et leur aspect ECG, quelles propositions sont exactes ?","options":[{"t":"Un défibrillateur assure toujours une fonction de pacemaker, sauf s'il est sous-cutané.","ok":true,"why":"Le défibrillateur fait toujours pacemaker, sauf le défibrillateur sous-cutané."},{"t":"La resynchronisation cardiaque est indiquée pour un BBG désynchronisant le VG avec insuffisance cardiaque.","ok":true,"why":"C'est l'indication de la resynchronisation dans le tableau des prothèses."},{"t":"Un spike de stimulation bipolaire est habituellement plus visible qu'un spike unipolaire.","ok":false,"why":"C'est l'inverse : le spike unipolaire est bien visible, le spike bipolaire peu visible."},{"t":"En stimulation atriale pour dysfonction sinusale, une onde P suit le spike.","ok":true,"why":"Dysfonction sinusale → stimulation atriale : une onde P suit le spike."},{"t":"Le défibrillateur agit en stimulant localement quelques myocytes.","ok":false,"why":"Le défibrillateur délivre un champ électrique réinitialisant tous les myocytes ; la stimulation locale de quelques myocytes est le principe du pacemaker."}],"explanation":"Pacemaker : stimulation locale ; défibrillateur : champ électrique global (fait aussi pacemaker, sauf sous-cutané) ; resynchronisation : BBG désynchronisant avec IC. Le spike unipolaire est plus visible que le bipolaire.","src":"p. 413-414"},{"id":"231-qcm-513","type":"QRM","rank":"A","objective":"231-obj-27","tags":["indications","monitorage"],"difficulty":1,"stem":"Parmi les situations suivantes, lesquelles sont citées comme indications d'un monitorage ECG continu (cardioscope) ?","options":[{"t":"Transfert médicalisé.","ok":true,"why":"Toute urgence, réanimation et transfert médicalisé relèvent du monitorage."},{"t":"Syncope avec cause rythmique suspectée.","ok":true,"why":"Indication citée du monitorage."},{"t":"Salle de réveil postanesthésique.","ok":true,"why":"Le peropératoire et la salle de réveil sont des indications du monitorage."},{"t":"Documentation de palpitations survenant quelques fois par mois chez un patient ambulatoire.","ok":false,"why":"Les symptômes rares relèvent d'un ECG ambulatoire de longue durée ou d'enregistreurs d'événements, pas d'un cardioscope."},{"t":"Enquête familiale d'une cardiopathie héréditaire.","ok":false,"why":"Les enquêtes familiales sont une indication de l'ECG conventionnel 12 dérivations, pas du monitorage continu."}],"explanation":"Le cardioscope s'utilise en urgence, réanimation, transfert médicalisé, soins intensifs cardiologiques, syncope d'origine rythmique suspectée, peropératoire/réveil et certaines séances de réadaptation.","src":"p. 414-415"},{"id":"231-qcm-514","type":"QRM","rank":"B","objective":"231-obj-28","tags":["Holter","examens complémentaires"],"difficulty":2,"stem":"Concernant la méthode Holter et les enregistrements ECG de longue durée, quelles propositions sont exactes ?","options":[{"t":"Le Holter enregistre 2 à 12 dérivations simultanées.","ok":true,"why":"ECG de longue durée sur 2 à 12 dérivations simultanées."},{"t":"La lecture du Holter se fait en temps réel, pendant l'enregistrement.","ok":false,"why":"Le Holter est enregistré sur support numérique avec lecture différée."},{"t":"Un Holter de 24 h peut servir à évaluer l'efficacité d'un traitement bradycardisant.","ok":true,"why":"C'est une indication citée du Holter de 24 h."},{"t":"Il permet d'évaluer le risque rythmique, par exemple des salves de TV asymptomatiques après infarctus.","ok":true,"why":"Évaluation du risque rythmique (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies)."},{"t":"Le Holter implantable est indiqué dans les syncopes inexpliquées et la recherche de FA silencieuse.","ok":true,"why":"Holter implantable : suivi jusqu'à 3 ans pour syncopes inexpliquées et FA silencieuse."}],"explanation":"Le Holter (2-12 dérivations, 24-96 h, lecture différée) documente des symptômes épisodiques, contrôle les bradycardisants et les pacemakers et évalue le risque rythmique ; le Holter implantable couvre jusqu'à 3 ans.","src":"p. 415"},{"id":"231-qcm-515","type":"QRM","rank":"A","objective":"231-obj-06","tags":["axe","hémibloc","piège"],"difficulty":3,"stem":"Un ECG montre un QRS négatif en D1. Quelles propositions sont exactes ?","options":[{"t":"Il faut d'abord évoquer une inversion des électrodes frontales, surtout si l'onde P est également négative en D1.","ok":true,"why":"Le cours recommande de penser d'abord à une inversion des électrodes (P alors négative en D1) avant l'HBPG."},{"t":"L'hémibloc postérieur gauche ne se retient qu'en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral.","ok":true,"why":"Ce sont les conditions posées pour retenir l'HBPG."},{"t":"L'hémibloc postérieur gauche est fréquent car sa branche est superficielle et fine.","ok":false,"why":"L'HBPG est rare (branche profonde) ; c'est l'HBAG qui est fréquent (branche superficielle et fine)."},{"t":"Une hypertrophie ventriculaire droite peut s'accompagner d'une déviation axiale droite.","ok":true,"why":"Le signe le plus précoce d'HVD est un axe > 110° (90° en pratique)."},{"t":"Au cours d'une embolie pulmonaire, un aspect S1Q3T3 peut s'associer à une déviation axiale droite.","ok":true,"why":"L'EP peut donner un aspect S1Q3T3 avec déviation axiale droite."}],"explanation":"Devant un D1 négatif : éliminer d'abord une inversion d'électrodes, puis discuter HBPG (rare, diagnostic d'exclusion), HVD, morphologie longiligne ou embolie pulmonaire (S1Q3T3).","src":"p. 382, 407"},{"id":"231-qru-501","type":"QRU","rank":"B","objective":"231-obj-04","tags":["HVD"],"difficulty":2,"stem":"Quel est le signe électrocardiographique le plus précoce d'une hypertrophie ventriculaire droite ?","options":[{"t":"Une déviation axiale droite (axe > 110°, 90° en pratique).","ok":true,"why":"Le cours cite l'axe > 110° comme signe le plus précoce d'HVD."},{"t":"Une onde R > 6 mm en V1.","ok":false,"why":"C'est un autre critère d'HVD, mais pas le plus précoce."},{"t":"Une onde T négative asymétrique en V1.","ok":false,"why":"Elle s'observe dans les formes sévères."},{"t":"Un microvoltage.","ok":false,"why":"Le microvoltage est fréquemment associé chez le BPCO, ce n'est pas le signe le plus précoce."},{"t":"Un indice de Sokolow ≥ 35 mm.","ok":false,"why":"L'indice de Sokolow est un critère d'hypertrophie ventriculaire gauche."}],"explanation":"Signe le plus précoce d'HVD : axe > 110° (90° en pratique) ; autres signes : R > 6 mm en V1, S > 7 mm en V5-V6, HAD, microvoltage (BPCO), T négative en V1 dans les formes sévères.","src":"p. 407"},{"id":"231-qru-503","type":"QRU","rank":"A","objective":"231-obj-05","tags":["HVG"],"difficulty":2,"stem":"Dans l'hypertrophie ventriculaire gauche, quelle est habituellement la durée des QRS ?","options":[{"t":"Un peu élargis mais le plus souvent inférieurs à 120 ms.","ok":true,"why":"Le cours décrit des QRS un peu élargis (masse, fibrose) mais le plus souvent < 120 ms."},{"t":"Constamment supérieurs à 120 ms, par définition.","ok":false,"why":"Les QRS restent le plus souvent < 120 ms dans l'HVG."},{"t":"Toujours inférieurs à 70 ms.","ok":false,"why":"Une durée < 70 ms serait inférieure à la normale (70-110 ms)."},{"t":"Supérieurs à 160 ms avec aspect RsR' en V1.","ok":false,"why":"L'aspect RsR' en V1 avec QRS large évoque un BBD complet."},{"t":"Variables « en accordéon » d'un battement à l'autre.","ok":false,"why":"Des QRS de largeur variable en accordéon évoquent une FA préexcitée."}],"explanation":"Dans l'HVG, les QRS sont un peu élargis (masse, fibrose) mais restent le plus souvent < 120 ms, avec une déviation axiale gauche modeste.","src":"p. 406"},{"id":"231-qroc-501","type":"QROC","rank":"A","objective":"231-obj-01","tags":["dérivations","activité atriale"],"difficulty":2,"question":"Avec les dérivations de Lewis, dans quelle dérivation l'activité atriale est-elle bien lue ?","answer":"D1","accept":["dérivation D1"],"keywords":["D1"],"explanation":"Électrode rouge sur la fourchette sternale, électrode jaune au 5e espace intercostal droit : l'activité atriale est alors bien lue en D1.","src":"p. 371"},{"id":"231-qroc-504","type":"QROC","rank":"A","objective":"231-obj-17","tags":["extrasystoles"],"difficulty":1,"question":"Comment nomme-t-on la succession rythmée d'un battement normal et d'une extrasystole (1 battement sur 2) ?","answer":"Bigéminisme","accept":["bigéminisme extrasystolique","bigeminisme"],"keywords":["bigemin"],"explanation":"Extrasystoles rythmées : bigéminisme (1 battement sur 2), trigéminisme (1 sur 3).","src":"p. 397"},{"id":"231-qroc-506","type":"QROC","rank":"A","objective":"231-obj-24","tags":["sus-décalage ST","séquelles"],"difficulty":2,"question":"Quelle complication doit évoquer un sus-décalage du ST persistant indéfiniment après un infarctus ?","answer":"Anévrisme ventriculaire","accept":["anévrisme de la paroi infarcie","anévrisme du VG","anévrisme"],"keywords":["anevrism"],"explanation":"Le sus-décalage régresse vite après reperfusion, en plusieurs jours sans reperfusion, et persiste indéfiniment en cas d'anévrisme de la paroi infarcie.","src":"p. 411-412"},{"id":"231-qroc-507","type":"QROC","rank":"B","objective":"231-obj-04","tags":["HVD"],"difficulty":2,"question":"Quelle amplitude de l'onde R en V1 constitue un critère d'hypertrophie ventriculaire droite ?","answer":"Supérieure à 6 mm","accept":["> 6 mm","plus de 6 mm","R > 6 mm"],"keywords":["6 mm"],"explanation":"Critères d'HVD : axe > 110° (le plus précoce), R > 6 mm en V1, S > 7 mm en V5-V6.","src":"p. 407"},{"id":"231-qroc-508","type":"QROC","rank":"A","objective":"231-obj-27","tags":["dérivations","SCA"],"difficulty":1,"question":"Quelles dérivations droites complètent les précordiales chez l'enfant ou en cas de suspicion de SCA ?","answer":"V3R et V4R","accept":["V3R V4R","V3R-V4R"],"keywords":["V3R","V4R"],"explanation":"Les précordiales V1 à V9 sont complétées par V3R et V4R chez l'enfant ou en cas de suspicion de SCA (ECG 18 dérivations).","src":"p. 371"},{"id":"231-qroc-509","type":"QROC","rank":"B","objective":"231-obj-16","tags":["manœuvres vagales"],"difficulty":1,"question":"Quelle manœuvre vagale consiste en une expiration forcée à glotte fermée ?","answer":"Manœuvre de Valsalva","accept":["Valsalva"],"keywords":["valsalva"],"explanation":"Manœuvres vagales : Valsalva (expiration forcée à glotte fermée), compression carotidienne unilatérale, grand verre d'eau froide.","src":"p. 390"},{"id":"231-qroc-601","type":"QROC","rank":"A","objective":"231-obj-27","tags":["urgence","biologie"],"difficulty":2,"question":"Quels troubles hydroélectrolytiques justifient la réalisation d'un ECG en urgence ?","answer":"Les dyskaliémies et les dyscalcémies (potassium, calcium)","accept":["dyskaliémie et dyscalcémie","potassium et calcium","K et Ca"],"keywords":["kali","calc"],"explanation":"Parmi les principales indications de l'ECG en urgence figurent les défaillances d'organe, la douleur thoracique, les palpitations, la syncope et les troubles hydroélectrolytiques portant sur le potassium et le calcium.","src":"p. 368"},{"id":"231-qroc-602","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi le QRS est-il large dans un bloc de branche, une extrasystole ventriculaire ou une stimulation cardiaque ?","answer":"L'influx se propage de proche en proche, hors du réseau spécialisé","accept":["de proche en proche","conduction lente de proche en proche","hors du réseau de conduction"],"keywords":["proche"],"explanation":"Le QRS est fin quand l'influx emprunte le réseau spécialisé (His, branches, Purkinje) ; il est large quand l'influx se propage lentement de proche en proche, comme dans un BBG, une stimulation, une extrasystole ventriculaire ou une tachycardie ventriculaire.","src":"p. 370, 398"},{"id":"231-qroc-603","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"question":"Quelles dérivations explorent le territoire latéral du ventricule gauche ?","answer":"D1 et aVL (hautes), V5 et V6 (basses)","accept":["D1, aVL, V5, V6","D1 aVL V5 V6","DI, aVL, V5, V6"],"keywords":["avl","v5","v6"],"explanation":"Les dérivations latérales sont D1 et aVL (latérales hautes) et V5, V6 (latérales basses) ; les inférieures sont D2, D3 et aVF, les antéroseptales V1 à V3, l'apicale V4.","src":"p. 374"},{"id":"231-qroc-604","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle est la durée normale de l'onde P, en pratique ?","answer":"Moins de 120 ms","accept":["< 120 ms","inférieure à 120 ms","120 ms"],"keywords":["120"],"explanation":"Dans un ECG normal, l'onde P dure moins de 120 ms (110 ms en théorie), avec une amplitude < 2,5 mm en D2 ; le PR normal est de 120 à 200 ms.","src":"p. 375, 377"},{"id":"231-qroc-605","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle formule permet de calculer la fréquence cardiaque à partir de l'intervalle RR exprimé en secondes ?","answer":"FC = 60 / période (intervalle RR)","accept":["60/RR","60 / RR","60 divisé par l'intervalle RR"],"keywords":["60"],"explanation":"La période est l'intervalle RR (entre deux QRS) en secondes et FC = 60 / période. En pratique, FC = 300 / nombre de grands carreaux séparant deux QRS.","src":"p. 376"},{"id":"231-qroc-606","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":1,"question":"Pourquoi les athlètes présentent-ils souvent une bradycardie sinusale physiologique ?","answer":"Un tonus vagal important","accept":["tonus vagal","tonus parasympathique important","hypertonie vagale"],"keywords":["vagal"],"explanation":"La fréquence du nœud sinusal dépend du tonus sympathique et parasympathique : le tonus vagal important de l'athlète explique sa bradycardie sinusale physiologique, et la fréquence sinusale du sujet jeune peut varier avec la respiration.","src":"p. 376"},{"id":"231-qroc-607","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":2,"question":"Quel aspect présente le QRS en V6 dans un bloc complet de branche droite ?","answer":"Un aspect qRs avec onde S traînante, arrondie","accept":["onde S traînante","S traînante","S traînante arrondie"],"keywords":["traîn"],"explanation":"Le BBD complet associe un QRS > 120 ms, un QRS globalement positif en V1 avec aspect RsR' et, en V6, un aspect qRs avec onde S traînante, le plus souvent arrondie.","src":"p. 378"},{"id":"231-qroc-608","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":1,"question":"Comment nomme-t-on le double pic du QRS observé en V6, D1 et aVL dans un bloc complet de branche gauche ?","answer":"Un notch","accept":["notch","le notch"],"keywords":["notch"],"explanation":"Dans le BBG complet, le QRS est négatif en V1 (rS ou QS) et présente en V6, D1 et aVL un notch (double pic : activation du septum puis de la paroi latérale tardive), avec le plus souvent une onde R exclusive.","src":"p. 380"},{"id":"231-qroc-609","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Quelle déviation axiale caractérise l'hémibloc postérieur gauche ?","answer":"Une déviation axiale droite au-delà de +90° (aspect S1Q3)","accept":["axe droit","déviation axiale droite","déviation à droite","au-delà de +90°"],"keywords":["droit"],"explanation":"L'HBPG, rare car la branche postérieure est profonde, donne une déviation axiale du QRS à droite (> +90°, négativité en D1), à condition d'éliminer une pathologie du ventricule droit, une morphologie longiligne ou un infarctus latéral. Devant un D1 négatif, on pense d'abord à une inversion des électrodes frontales.","src":"p. 382-383"},{"id":"231-qroc-611","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG"],"difficulty":2,"question":"Quel aspect caractérise le bloc atrioventriculaire du 2e degré de type Mobitz 2 ?","answer":"PR constant, puis une onde P bloquée de façon inopinée","accept":["PR constant puis onde P bloquée","onde P bloquée inopinée","onde P bloquée brutale"],"keywords":["constant","puis"],"explanation":"Dans le Mobitz 2, le PR reste constant puis une onde P est bloquée de façon inopinée, contrairement au Mobitz 1 où le PR s'allonge progressivement ; ce bloc est de siège infrahissien.","src":"p. 385"},{"id":"231-qroc-612","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG"],"difficulty":3,"question":"Dans un BAV 2/1, quel aspect des QRS oriente vers un siège infrahissien ?","answer":"Des QRS larges","accept":["QRS larges","QRS élargis"],"keywords":["larges"],"explanation":"Dans un BAV 2/1, des QRS larges orientent vers un siège infrahissien ; des QRS fins, surtout s'il existe du Mobitz 1 à d'autres moments, orientent vers un siège suprahissien.","src":"p. 385"},{"id":"231-qroc-613","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","définition"],"difficulty":2,"question":"Que signifie le terme « irrégulièrement irréguliers » pour les QRS d'une fibrillation atriale ?","answer":"Les intervalles RR ne sont pas multiples d'une valeur commune","accept":["RR non multiples","pas multiples d'une valeur commune","intervalles RR non multiples"],"keywords":["multiple"],"explanation":"Dans la FA, tachycardie entre 100 et 200/min, les QRS sont « irrégulièrement irréguliers » : les intervalles RR ne sont pas multiples d'une valeur commune ; en l'absence de trouble de conduction, les QRS sont fins.","src":"p. 392"},{"id":"231-qroc-614","type":"QROC","rank":"B","objective":"231-obj-11","tags":["ECG"],"difficulty":2,"question":"Comment nomme-t-on l'alternance de bradycardie sinusale et de tachycardie par fibrillation atriale ?","answer":"Le syndrome tachycardie-bradycardie (maladie de l'oreillette)","accept":["syndrome tachycardie-bradycardie","maladie de l'oreillette","maladie rythmique atriale","syndrome tachy-brady"],"keywords":["oreillette"],"explanation":"L'alternance de FA (tachycardie) et de dysfonction sinusale (bradycardie) réalise le syndrome tachycardie-bradycardie, ou maladie de l'oreillette ; des pauses de régularisation peuvent s'observer à l'arrêt de la FA.","src":"p. 393"},{"id":"231-qroc-615","type":"QROC","rank":"B","objective":"231-obj-13","tags":["ECG"],"difficulty":2,"question":"Quel aspect donne l'association d'une fibrillation atriale et d'un bloc de branche ?","answer":"Une tachycardie irrégulière à QRS larges","accept":["tachycardie irrégulière à QRS larges","QRS larges irréguliers"],"keywords":["irrégul","larges"],"explanation":"Un bloc de branche est fréquent dans la FA, préexistant ou fonctionnel (apparaissant seulement en tachycardie) : l'ECG montre alors une tachycardie irrégulière à QRS larges.","src":"p. 393"},{"id":"231-qroc-616","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":2,"question":"Quel aspect de la ligne de base différencie le flutter atrial de la tachycardie atriale focale ?","answer":"Le flutter n'a pas de retour à la ligne isoélectrique","accept":["pas de retour à la ligne isoélectrique","absence de retour à la ligne de base","sans retour à la ligne isoélectrique"],"keywords":["isoélectr"],"explanation":"Dans le flutter, l'activité atriale est monomorphe et permanente (boucle de réentrée), sans retour à la ligne isoélectrique dans au moins une dérivation ; dans la tachycardie atriale focale, la ligne de base est retrouvée entre les ondes P.","src":"p. 393, 395"},{"id":"231-qroc-617","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"question":"Quel aspect décrit l'enchaînement des ondes F du flutter atrial ?","answer":"Sinusoïdal, en toit d'usine ou en dents de scie","accept":["dents de scie","toit d'usine","sinusoïdal"],"keywords":["scie"],"explanation":"Le flutter produit une activité atriale rapide et monomorphe, le plus souvent à 300/min ; les ondes F successives dessinent une ligne sinusoïdale, en toit d'usine ou en dents de scie, que seule une manœuvre vagale révèle parfois.","src":"p. 393"},{"id":"231-qroc-618","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi l'activité atriale est-elle souvent invisible dans une tachycardie par réentrée intranodale ?","answer":"Les activations atriale et ventriculaire sont quasi synchrones","accept":["quasi synchrones","activation atriale et ventriculaire quasi synchrone","activations simultanées"],"keywords":["synchron"],"explanation":"Dans la réentrée intranodale, l'activation des oreillettes et celle des ventricules sont quasi synchrones : l'activité atriale n'est souvent pas visible, ou seulement devinée dans le segment ST, sur une tachycardie très régulière à QRS fins.","src":"p. 395"},{"id":"231-qroc-619","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG"],"difficulty":2,"question":"Quel aspect ECG caractérise une extrasystole ventriculaire ?","answer":"Un QRS large prématuré, avec ou sans onde P' rétrograde","accept":["QRS large","QRS large prématuré","QRS élargi"],"keywords":["large"],"explanation":"L'extrasystole ventriculaire est un QRS large survenant prématurément, avec ou sans onde P' rétrograde ; l'extrasystole atriale donne une onde P précoce de morphologie différente de la P sinusale suivie d'un QRS fin.","src":"p. 397"},{"id":"231-qroc-620","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","étiologie"],"difficulty":2,"question":"Que doivent faire rechercher des extrasystoles fréquentes ou polymorphes ?","answer":"Une cardiopathie","accept":["cardiopathie","cardiopathie sous-jacente"],"keywords":["cardiopath"],"explanation":"Les extrasystoles sont fréquentes et peuvent être physiologiques sur cœur sain ; leur charge (nombre sur 24 heures) augmente avec l'âge et la cardiopathie, et des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie.","src":"p. 397"},{"id":"231-qroc-621","type":"QROC","rank":"A","objective":"231-obj-18","tags":["urgence","ECG"],"difficulty":1,"question":"Que faut-il faire dès la suspicion d'une tachycardie ventriculaire ?","answer":"Donner l'alerte (faire le 15) et se préparer à une réanimation","accept":["donner l'alerte","faire le 15","appeler le 15","15"],"keywords":["alerte"],"explanation":"Une TV (tachycardie > 100/min avec QRS > 120 ms sur au moins 3 battements) est un état électrique instable qui peut dégénérer en FV puis en asystolie : sa suspicion impose de donner l'alerte (faire le 15) et de se préparer à une réanimation.","src":"p. 399"},{"id":"231-qroc-622","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":2,"question":"Comment nomme-t-on, dans une tachycardie à QRS larges, l'aspect de QRS entièrement positifs ou entièrement négatifs de V1 à V6, en faveur d'une TV ?","answer":"La concordance (positive ou négative) dans les précordiales","accept":["concordance","concordance positive","concordance négative"],"keywords":["concordan"],"explanation":"Une concordance positive (QRS entièrement positifs) ou négative (QS) de V1 à V6 est un argument en faveur d'une TV, comme une cardiopathie sous-jacente, une déviation axiale extrême ou des QRS larges d'aspect différent d'un bloc de branche habituel.","src":"p. 400"},{"id":"231-qroc-623","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":3,"question":"Dans une tachycardie à QRS larges, quel aspect du QRS en aVR est un argument en faveur d'une TV ?","answer":"Un QRS positif en aVR (axe extrême)","accept":["QRS positif en aVR","positivité exclusive en aVR","déviation axiale extrême"],"keywords":["positif"],"explanation":"Un QRS positif en aVR correspond à une déviation axiale extrême, que l'on ne rencontre ni dans un BBD ni dans un BBG : c'est un argument en faveur d'une TV.","src":"p. 400, 402"},{"id":"231-qroc-624","type":"QROC","rank":"A","objective":"231-obj-19","tags":["ECG","urgence"],"difficulty":2,"question":"Quel aspect ECG caractérise la fibrillation ventriculaire ?","answer":"Une tachycardie irrégulière à QRS larges polymorphes","accept":["QRS larges polymorphes","larges fuseaux"],"keywords":["irrégul","polymorph"],"explanation":"La FV est une urgence absolue : tachycardie irrégulière à QRS larges polymorphes, avec perte de connaissance en quelques secondes (débit cardiaque nul) et pouls carotidien aboli ; elle impose un choc électrique immédiat.","src":"p. 402-403"},{"id":"231-qroc-625","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","étiologie"],"difficulty":1,"question":"Quelles sont les trois grandes causes d'allongement de l'intervalle QT ?","answer":"Médicamenteuse, congénitale, ionique","accept":["médicaments, génétique, troubles ioniques","médicamenteuse, congénitale et ionique"],"keywords":["médicament","congénit","ioni"],"explanation":"Un QT allongé peut être d'origine médicamenteuse (association de médicaments allongeant le QT), congénitale (syndrome du QT long congénital, maladie génétique) ou ionique (kaliémie, calcémie, magnésémie).","src":"p. 368, 404"},{"id":"231-qroc-626","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","biologie"],"difficulty":2,"question":"Quels sont les deux troubles ioniques, en dehors de l'hypokaliémie, qui allongent le QT ?","answer":"L'hypocalcémie et l'hypomagnésémie","accept":["hypocalcémie et hypomagnésémie","hypoCa et hypoMg"],"keywords":["hypocalc","hypomagn"],"explanation":"Outre l'hypokaliémie, l'hypocalcémie et l'hypomagnésémie allongent le QT et exposent aux torsades de pointes.","src":"p. 404"},{"id":"231-qroc-627","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","urgence"],"difficulty":2,"question":"Devant un QT allongé sur l'ECG, quels deux éléments faut-il vérifier pour éviter une mort subite ?","answer":"Les médicaments responsables et le ionogramme","accept":["médicaments et ionogramme","médicaments et ionogramme sanguin"],"keywords":["médicament","ionogramme"],"explanation":"Un QT allongé doit alerter : on recherche les médicaments responsables et on contrôle le ionogramme afin de corriger l'allongement du QT et d'éviter une mort subite.","src":"p. 404"},{"id":"231-qroc-628","type":"QROC","rank":"B","objective":"231-obj-20","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle mesure portant sur la fréquence cardiaque fait partie de la prise en charge des torsades de pointes ?","answer":"Accélérer la fréquence cardiaque","accept":["accélérer la fréquence cardiaque","accélérer la FC","augmenter la fréquence cardiaque"],"keywords":["accél"],"explanation":"Face à une torsade de pointes, on rétablit l'équilibre ionique, on accélère le rythme cardiaque et on interrompt tout médicament qui allonge le QT.","src":"p. 404"},{"id":"231-qroc-629","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG"],"difficulty":2,"question":"Dans l'hypertrophie ventriculaire gauche sévère, dans quelles dérivations observe-t-on une onde T négative avec sous-décalage du ST ?","answer":"Les dérivations latérales : D1, aVL, V5, V6","accept":["D1, aVL, V5, V6","latérales"],"keywords":["avl","v5"],"explanation":"Dans la forme sévère de l'HVG, la repolarisation est secondairement anormale (onde T négative, sous-décalage du ST) dans les dérivations latérales D1, aVL, V5, V6, avec disparition de l'onde Q septale dans ces mêmes dérivations.","src":"p. 406"},{"id":"231-qroc-630","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","pièges"],"difficulty":2,"question":"Quel élément est absent du sus-décalage du ST de la péricardite aiguë, contrairement au SCA avec sus-décalage du ST ?","answer":"L'image en miroir","accept":["miroir","image en miroir","sous-décalage en miroir"],"keywords":["miroir"],"explanation":"Le sus-décalage de la péricardite est diffus, concave vers le haut, concordant, sans image en miroir. Attention : l'image en miroir peut aussi manquer dans un SCA avec sus-décalage, donc son absence ne suffit pas à conclure à une péricardite.","src":"p. 409"},{"id":"231-qroc-631","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","pièges"],"difficulty":3,"question":"Dans quelle situation rythmique ne faut-il pas bloquer le NAV (massage, adénosine) pour démasquer une préexcitation ?","answer":"En cas de fibrillation atriale","accept":["en cas de FA","fibrillation atriale"],"keywords":["fibrillation"],"explanation":"Bloquer le NAV force l'influx à passer par la voie accessoire et démasque une préexcitation minime, mais il ne faut pas le faire en cas de FA : une FA rapide conduite par une voie accessoire perméable donne une tachycardie irrégulière à QRS larges (« super-Wolff ») pouvant dégénérer en FV.","src":"p. 410-411"},{"id":"231-qroc-632","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Combien de dérivations faut-il enregistrer devant toute douleur thoracique, pour ne pas méconnaître un sus-décalage postérieur ?","answer":"18 dérivations","accept":["18","ECG 18 dérivations"],"keywords":["18"],"explanation":"Un sous-décalage du ST en V1-V3 peut être le miroir d'un sus-décalage postérieur (V7-V9) : on réalise donc un ECG 18 dérivations devant toute douleur thoracique.","src":"p. 411"},{"id":"231-qroc-633","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Dans quelles dérivations observe-t-on le sus-décalage du ST de la repolarisation précoce ?","answer":"Les dérivations inférolatérales","accept":["inférolatérales","inféro-latérales","inférieures et latérales"],"keywords":["latéral"],"explanation":"La repolarisation précoce est l'une des cinq étiologies de sus-décalage du ST à connaître (SCA avec sus-décalage, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite) ; son sus-décalage siège dans les dérivations inférolatérales.","src":"p. 412"},{"id":"231-qroc-634","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel sus-décalage minimal du ST est exigé dans les dérivations autres que V1 à V3 pour être significatif ?","answer":"1 mm","accept":["1 mm","≥ 1 mm","un millimètre"],"keywords":["1 mm"],"explanation":"Pour être significatif, le sus-décalage du ST doit mesurer au moins 2 mm en V1-V3 et au moins 1 mm dans les autres dérivations, et être présent sur deux dérivations adjacentes ou plus.","src":"p. 412"},{"id":"231-qroc-635","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":1,"question":"Combien de dérivations voisines doivent présenter le sus-décalage du ST pour qu'il soit significatif ?","answer":"Au moins 2 dérivations adjacentes","accept":["2 dérivations","deux dérivations","au moins 2 dérivations","au moins deux dérivations","2 dérivations contiguës"],"keywords":["adjacent"],"explanation":"Un sus-décalage du ST n'est retenu que s'il touche au moins deux dérivations adjacentes, avec un seuil de 2 mm en V1-V3 et de 1 mm ailleurs.","src":"p. 412"},{"id":"231-qroc-636","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","physiopathologie"],"difficulty":2,"question":"À quel type de courant de lésion correspond un sous-décalage du segment ST dans un SCA sans sus-décalage ?","answer":"Un courant de lésion sous-endocardique","accept":["sous-endocardique","lésion sous-endocardique"],"keywords":["endocard"],"explanation":"Dans un SCA sans sus-décalage, on peut observer un sous-décalage du ST (courant de lésion sous-endocardique), une inversion des ondes T, une pseudo-normalisation d'ondes T négatives, un aplatissement des ondes T, voire un ECG normal.","src":"p. 412"},{"id":"231-qroc-637","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quel type d'ischémie traduit une inversion des ondes T dans un SCA sans sus-décalage du ST ?","answer":"Une ischémie sous-épicardique","accept":["sous-épicardique","ischémie sous-épicardique"],"keywords":["épicard"],"explanation":"L'inversion des ondes T d'un SCA sans sus-décalage traduit une ischémie sous-épicardique, alors que le sous-décalage du ST correspond à un courant de lésion sous-endocardique.","src":"p. 412"},{"id":"231-qroc-638","type":"QROC","rank":"B","objective":"231-obj-26","tags":["traitement","ECG"],"difficulty":2,"question":"Quels types de bloc atrioventriculaire constituent une indication de pacemaker même en l'absence de symptôme ?","answer":"Les BAV infrahissiens (BAV2 Mobitz 2 et BAV3)","accept":["infrahissiens","BAV infrahissiens","Mobitz 2 et BAV3","Mobitz 2 et BAV 3"],"keywords":["mobitz"],"explanation":"Les BAV infrahissiens (BAV2 Mobitz 2 et BAV3) sont une indication de pacemaker même asymptomatiques ; pour la dysfonction sinusale, le BAV2 Mobitz 1 et la bradycardie sinusale, la stimulation concerne les formes symptomatiques.","src":"p. 412"},{"id":"231-qroc-639","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique","ECG"],"difficulty":2,"question":"À quelle condition un Holter ECG de 24 à 96 heures est-il pertinent devant des palpitations épisodiques, quand l'ECG standard n'a pas fait le diagnostic ?","answer":"S'il est probable que les symptômes se répètent pendant l'enregistrement","accept":["probabilité que les symptômes se répètent","symptômes fréquents","si les symptômes se répètent"],"keywords":["répèt"],"explanation":"Le Holter s'adresse aux malaises, syncopes, pertes de connaissance ou palpitations épisodiques quand l'ECG de repos n'a pas permis de conclure, à condition que les symptômes aient une bonne chance de survenir pendant l'enregistrement ; pour des symptômes rares, on recourt à des enregistrements plus longs (jusqu'à 21 jours) ou à des enregistreurs d'événements.","src":"p. 415"}],"edn":[{"id":"231-kfp-01","type":"KFP","rank":"A","objective":"231-obj-15","difficulty":2,"scenario":"Une femme de 32 ans, sans antécédent, consulte aux urgences pour des palpitations à début et fin brutaux, sans douleur thoracique ni lipothymie. L'ECG objective une tachycardie régulière à QRS fins à 190 bpm, sans onde P clairement identifiable. La pression artérielle est à 110/70 mmHg, sans signe de mauvaise tolérance hémodynamique.","questions":[{"stem":"Parmi les éléments suivants, lesquels orientent vers une tachycardie jonctionnelle plutôt qu'une tachycardie sinusale ?","max":2,"options":["Début et fin brutaux de la tachycardie","Variation progressive de la fréquence cardiaque","Onde P sinusale bien visible avant chaque QRS","Absence d'activité atriale clairement identifiable","Contexte fébrile expliquant l'accélération","Accélération progressive puis décélération progressive de la fréquence","Antécédent connu de cardiopathie ischémique","Fréquence cardiaque variant en fonction de la respiration"],"correct":[0,3],"explanation":"Le début et la fin brutaux, ainsi que l'absence d'activité atriale sinusale identifiable, orientent vers une tachycardie supraventriculaire non sinusale (jonctionnelle) ; la tachycardie sinusale varie au contraire progressivement et garde une onde P sinusale visible."},{"stem":"Quelle est la prise en charge immédiate la plus appropriée devant cette tachycardie jonctionnelle bien tolérée ?","max":1,"options":["Cardioversion électrique externe immédiate","Manœuvre vagale, puis adénosine IV en cas d'échec","Bêtabloquant intraveineux d'emblée","Amiodarone intraveineuse d'emblée","Digoxine intraveineuse","Surveillance simple sans aucun geste diagnostique","Choc électrique externe synchronisé d'emblée","Massage cardiaque externe"],"correct":[1],"explanation":"Devant une tachycardie régulière à QRS fins bien tolérée hémodynamiquement, la première étape est une manœuvre vagale, puis l'adénosine IV en cas d'échec ; la cardioversion électrique est réservée aux mauvaises tolérances hémodynamiques."},{"stem":"Quel mécanisme électrophysiologique explique l'efficacité attendue de la manœuvre vagale ou de l'adénosine dans ce contexte ?","max":1,"options":["Blocage atrioventriculaire transitoire interrompant la réentrée dépendante du NAV","Effet inotrope négatif direct sur le myocarde ventriculaire","Vasodilatation coronaire","Effet antiarythmique de classe I sur les canaux sodiques","Stimulation sympathique du nœud sinusal","Diminution de la précharge cardiaque","Effet sur les canaux potassiques ventriculaires","Blocage exclusif d'une voie accessoire, sans effet sur le NAV"],"correct":[0],"explanation":"Les manœuvres vagales et l'adénosine créent un bloc atrioventriculaire transitoire en intensifiant le filtre du NAV, ce qui interrompt la boucle de réentrée dépendante du NAV et arrête la tachycardie jonctionnelle."}],"src":"p. 390, 395-397"},{"id":"231-kfp-02","type":"KFP","rank":"A","objective":"231-obj-08","difficulty":2,"scenario":"Un homme de 78 ans consulte pour des lipothymies répétées depuis un mois. L'ECG per-critique montre une fréquence cardiaque des QRS à 38 bpm, avec des ondes P régulières à une fréquence de 75 bpm, plus nombreuses que les QRS, sans relation constante entre onde P et QRS.","questions":[{"stem":"Quelle structure du système de conduction est probablement en cause dans cette bradycardie ?","max":1,"options":["Le nœud sinusal","Le nœud atrioventriculaire","Le nerf vague isolément","Le faisceau de His seul, sans atteinte nodale","Une voie accessoire","L'oreillette gauche","Le système nerveux sympathique","La veine cave supérieure"],"correct":[1],"explanation":"Des ondes P régulières à fréquence normale mais plus nombreuses que les QRS traduisent un problème de passage au ventricule, donc une atteinte du nœud atrioventriculaire (BAV), et non du nœud sinusal."},{"stem":"Quelle caractéristique des ondes P permet d'orienter vers ce diagnostic plutôt que vers une dysfonction sinusale ?","max":1,"options":["Ondes P régulières à fréquence normale, plus nombreuses que les QRS","Ondes P trop lentes ou inexistantes","Onde P rétrograde négative en D2","Ondes P absentes avec tracé plat","Pauses sinusales itératives","Ondes P de morphologie variable d'un cycle à l'autre","Ondes P bloquées de façon totalement aléatoire","Absence totale d'activité atriale identifiable"],"correct":[0],"explanation":"Dans l'algorithme diagnostique devant une bradycardie, des ondes P régulières à fréquence normale mais plus nombreuses que les QRS orientent vers un problème de passage au ventricule (BAV), alors que des ondes P trop lentes ou absentes orienteraient vers une dysfonction sinusale."},{"stem":"Compte tenu du tableau clinique et électrique, quelles affirmations sont exactes ?","max":2,"options":["Il s'agit probablement d'un bloc atrioventriculaire de haut degré ou complet","Une indication de pacemaker doit être discutée en l'absence de cause réversible","Le traitement de première intention est un bêtabloquant","Il n'y a aucune urgence à explorer ce trouble","Une origine fonctionnelle par hypertonie vagale explique toujours ce tableau chez le sujet âgé","Une cause médicamenteuse bradycardisante doit être recherchée mais ne change pas la prise en charge","Le monitorage ECG n'est pas indiqué dans ce contexte","Aucun bilan ionique n'est nécessaire"],"correct":[0,1],"explanation":"Le tableau évoque un bloc atrioventriculaire de haut degré ou complet symptomatique ; en l'absence de cause réversible identifiée (médicamenteuse, ionique), une indication de pacemaker doit être discutée, comme le rappelle le livre pour les BAV infrahissiens même sans symptôme et a fortiori lorsqu'il existe des symptômes."}],"src":"p. 385-389"},{"id":"231-kfp-03","type":"KFP","rank":"A","objective":"231-obj-05","difficulty":2,"scenario":"Un homme de 62 ans, hypertendu depuis quinze ans et mal suivi, consulte pour un bilan cardiologique systématique. L'ECG montre une onde S en V1 à 22 mm, une onde R en V5 à 20 mm, une onde T négative en D1, aVL et V6, et un discret sus-décalage du segment ST en V1-V2.","questions":[{"stem":"Quel diagnostic évoquez-vous en priorité devant ce tracé ?","max":1,"options":["Hypertrophie ventriculaire gauche avec anomalies secondaires de la repolarisation","Syndrome coronarien aigu du territoire antérieur","Péricardite aiguë","Bloc de branche gauche isolé","Embolie pulmonaire","Hyperkaliémie","Torsade de pointes","Fibrillation ventriculaire"],"correct":[0],"explanation":"L'association d'une grande amplitude des QRS en précordiales et d'ondes T négatives latérales (D1, aVL, V6) est typique d'une hypertrophie ventriculaire gauche avec anomalies secondaires de la repolarisation, l'étiologie la plus fréquente étant l'HTA."},{"stem":"Quel indice, calculé à partir des amplitudes mesurées, permet de retenir ce diagnostic ?","max":1,"options":["L'indice de Sokolow (onde S en V1 ou V2 + onde R en V5 ou V6), supérieur à 35 mm","La durée du QRS supérieure à 120 ms","Un intervalle PR raccourci inférieur à 120 ms","Un axe du QRS entre -30° et +90°","Un rapport R/S supérieur à 1 en V1","La présence d'une onde delta","Un intervalle QT allongé","Une onde P biphasique en V1"],"correct":[0],"explanation":"L'indice de Sokolow (somme de l'onde S en V1/V2 et de l'onde R en V5/V6), normalement inférieur à 35 mm, est l'indice le plus utilisé pour le diagnostic d'hypertrophie ventriculaire gauche ; ici 22 + 20 = 42 mm, nettement au-delà du seuil."},{"stem":"Concernant les pièges d'interprétation de ce tracé, quelles affirmations sont exactes ?","max":3,"options":["Le sus-décalage en V1-V2 peut mimer à tort un syndrome coronarien aigu (pseudonécrose)","L'hypertrophie ventriculaire gauche électrique peut donner un aspect QS trompeur en V1-V2","Ce tracé impose systématiquement une coronarographie en urgence","Le rétrécissement aortique est l'étiologie la plus fréquente de l'HVG, avant l'HTA","L'HTA est l'étiologie la plus fréquente de l'hypertrophie ventriculaire gauche","Une onde T négative dans ce contexte est toujours synonyme d'ischémie aiguë","Le diagnostic d'HVG élimine formellement toute coronaropathie associée","L'indice de Sokolow n'a aucune valeur diagnostique dans l'HVG"],"correct":[0,1,4],"explanation":"Une HVG électrique importante peut donner un aspect QS et un pseudo-sus-décalage en V1-V2 mimant une nécrose ou un SCA ; l'étiologie la plus fréquente de l'HVG est l'HTA, puis le rétrécissement aortique."}],"src":"p. 406-407"},{"id":"231-kfp-04","type":"KFP","rank":"A","objective":"231-obj-21","difficulty":2,"scenario":"Une femme de 70 ans, traitée par fluoxétine et hydrochlorothiazide, consulte pour une asthénie profonde. Le ionogramme sanguin retrouve une kaliémie à 2,8 mmol/L. L'ECG montre un allongement de l'intervalle QT, une onde U visible après l'onde T, et des ondes T aplaties diffuses.","questions":[{"stem":"Quel trouble ionique explique le mieux ces anomalies électrocardiographiques ?","max":1,"options":["Hypokaliémie","Hyperkaliémie","Hypercalcémie","Hypocalcémie","Hypermagnésémie","Hypernatrémie","Hyponatrémie isolée","Acidose métabolique isolée"],"correct":[0],"explanation":"L'hypokaliémie se caractérise par une onde T plate ou négative diffuse, un ST sous-décalé, un allongement du QT avec apparition d'une onde U, ce qui correspond exactement au tracé décrit."},{"stem":"Quel trouble du rythme grave ce contexte fait-il craindre en priorité ?","max":1,"options":["Torsade de pointes","Flutter atrial typique","Bloc de branche droit isolé","Extrasystole atriale isolée","Tachycardie sinusale","Rythme jonctionnel accéléré","Hémibloc antérieur gauche isolé","Bloc atrioventriculaire du 1er degré isolé"],"correct":[0],"explanation":"L'allongement du QT lié à l'hypokaliémie expose au risque de torsade de pointes, forme particulière de tachycardie ventriculaire polymorphe pouvant dégénérer en fibrillation ventriculaire."},{"stem":"Quels éléments de la prise en charge sont appropriés dans ce contexte ?","max":3,"options":["Correction de l'hypokaliémie","Réévaluation des médicaments allongeant le QT, notamment la fluoxétine","Poursuite du traitement bradycardisant sans aucune modification","Accélération de la fréquence cardiaque en cas de torsade de pointes avérée","Absence de nécessité de surveillance ECG particulière","Introduction d'un antiarythmique de classe I en première intention","Arrêt de toute surveillance après la seule correction ionique","Contre-indication formelle à toute perfusion de magnésium"],"correct":[0,1,3],"explanation":"La prise en charge d'un QT long avec trouble ionique associe la correction des troubles ioniques, l'arrêt des médicaments allongeant le QT, et l'accélération de la fréquence cardiaque en cas de torsade de pointes avérée."}],"src":"p. 408-409"},{"id":"231-tcs-01","type":"TCS","rank":"A","objective":"231-obj-18","difficulty":3,"vignette":"Un homme de 68 ans, aux antécédents d'infarctus du myocarde ancien, est admis pour une tachycardie régulière à QRS larges à 160 bpm, bien tolérée sur le plan hémodynamique.","items":[{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que vous constatez une dissociation ventriculo-atriale, avec davantage de QRS que d'ondes P","panel":[0,0,1,2,12],"explanation":"Une dissociation ventriculo-atriale avec plus de QRS que d'ondes P est un argument de certitude en faveur d'une TV : la tachycardie ne peut alors venir que du ventricule."},{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que vous constatez des complexes de fusion intercalés dans le tracé","panel":[0,0,1,3,11],"explanation":"Les complexes de fusion, résultant de la compétition entre l'activation par la TV et l'influx sinusal, ne peuvent exister qu'en cas de dissociation ventriculo-atriale : c'est un argument de certitude pour la TV."},{"hypothesis":"Si vous pensiez à une tachycardie supraventriculaire avec bloc de branche fonctionnel","newInfo":"et que vous constatez une concordance négative des QRS (QS) de V1 à V6","panel":[10,3,1,1,0],"explanation":"La concordance négative (QS de V1 à V6) est un argument en faveur d'une TV et non d'une simple aberration de conduction sur tachycardie supraventriculaire."},{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que le patient présente une cardiopathie ischémique séquellaire connue","panel":[0,1,2,9,3],"explanation":"La présence d'une cardiopathie sous-jacente est un argument en faveur d'une TV, la réentrée autour d'une zone de fibrose étant le mécanisme le plus fréquent, mais ce n'est pas un argument de certitude à lui seul."}],"src":"p. 398-402"},{"id":"231-tcs-02","type":"TCS","rank":"A","objective":"231-obj-10","difficulty":3,"vignette":"Une femme de 75 ans consulte pour des lipothymies répétées. Son ECG per-critique révèle une fréquence cardiaque à 42 bpm.","items":[{"hypothesis":"Si vous pensiez à une dysfonction sinusale","newInfo":"et que vous constatez des ondes P régulières à une fréquence de 80 bpm, plus nombreuses que les QRS","panel":[9,4,1,1,0],"explanation":"Des ondes P régulières à fréquence normale, plus nombreuses que les QRS, orientent vers un problème de passage au ventricule (BAV) et non vers une dysfonction sinusale, où les ondes P seraient trop lentes ou absentes."},{"hypothesis":"Si vous pensiez à un bloc atrioventriculaire","newInfo":"et que vous constatez ce même tableau (ondes P régulières à 80 bpm, plus nombreuses que les QRS)","panel":[0,0,1,3,11],"explanation":"Ce tableau est caractéristique d'un bloc atrioventriculaire : le nœud atrioventriculaire ne transmet plus correctement aux ventricules des ondes P pourtant régulières et de fréquence normale."},{"hypothesis":"Si vous pensiez à un bloc atrioventriculaire de siège nodal (suprahissien)","newInfo":"et que l'échappement ventriculaire observé est à QRS fins, régulier et lent","panel":[0,1,2,9,3],"explanation":"Un échappement à QRS fins, régulier et lent, traduit un bloc de siège nodal (suprahissien), ce qui précise le siège du bloc atrioventriculaire déjà évoqué."},{"hypothesis":"Si vous pensiez à une dysfonction sinusale","newInfo":"et qu'une pause est observée, de durée égale au double de l'intervalle PP normal, sans aucune onde P pendant la pause","panel":[0,0,1,2,12],"explanation":"Une pause de durée double du cycle PP normal, par disparition complète d'une onde P, est l'aspect typique du bloc sinoatrial du 2e degré, argument fort en faveur de la dysfonction sinusale."}],"src":"p. 387-389"},{"id":"231-tcs-03","type":"TCS","rank":"A","objective":"231-obj-13","difficulty":3,"vignette":"Un homme de 60 ans, sans antécédent notable, consulte pour des palpitations. Son ECG montre une tachycardie à QRS fins à 140 bpm.","items":[{"hypothesis":"Si vous pensiez à une fibrillation atriale","newInfo":"et que les intervalles RR sont irrégulièrement irréguliers, sans onde P identifiable","panel":[0,0,1,2,12],"explanation":"Des intervalles RR irrégulièrement irréguliers sans onde P identifiable sont l'aspect typique de la fibrillation atriale."},{"hypothesis":"Si vous pensiez à un flutter atrial","newInfo":"et que l'activité atriale est monomorphe à 300 bpm en dents de scie, avec une conduction ventriculaire régulière à 150 bpm","panel":[0,0,1,2,12],"explanation":"Une activité atriale monomorphe et organisée à 300 bpm en dents de scie, avec une conduction 2/1 régulière (150 bpm), est caractéristique du flutter atrial."},{"hypothesis":"Si vous pensiez à une fibrillation atriale","newInfo":"et que la manœuvre vagale démasque une activité atriale organisée en dents de scie, sans jamais arrêter la tachycardie","panel":[9,4,1,1,0],"explanation":"Une activité atriale organisée en dents de scie, démasquée par la manœuvre vagale, oriente vers un flutter atrial et non vers une fibrillation atriale, dont l'activité atriale est au contraire anarchique."},{"hypothesis":"Si vous pensiez à une tachycardie jonctionnelle","newInfo":"et que la manœuvre vagale interrompt brutalement la tachycardie, avec retour en rythme sinusal","panel":[0,0,1,2,12],"explanation":"L'arrêt brutal de la tachycardie par manœuvre vagale, lié au blocage de la réentrée dépendante du NAV, est caractéristique d'une tachycardie jonctionnelle."}],"src":"p. 390-395"},{"id":"231-tcs-04","type":"TCS","rank":"B","objective":"231-obj-25","difficulty":3,"vignette":"Une femme de 28 ans, connue porteuse d'un syndrome de Wolff-Parkinson-White, consulte pour des palpitations très rapides et irrégulières.","items":[{"hypothesis":"Si vous pensiez à une fibrillation atriale conduite par la voie accessoire (« super-Wolff »)","newInfo":"et que l'ECG montre une tachycardie irrégulière à QRS larges de largeur variable","panel":[0,0,1,2,12],"explanation":"Une tachycardie irrégulière à QRS larges de largeur variable (« en accordéon ») chez un patient porteur d'un WPW en fibrillation atriale est l'aspect typique du super-Wolff, lié à l'absence de propriété décrémentielle de la voie accessoire."},{"hypothesis":"Si vous pensiez à ce diagnostic (super-Wolff)","newInfo":"et que vous envisagiez d'administrer de l'adénosine intraveineuse pour ralentir la fréquence ventriculaire","panel":[9,4,1,1,0],"explanation":"L'adénosine est contre-indiquée en cas de fibrillation atriale associée à une préexcitation : le blocage du NAV force l'influx à passer exclusivement par la voie accessoire, pouvant accélérer paradoxalement la fréquence ventriculaire."},{"hypothesis":"Si vous pensiez à une tachycardie jonctionnelle par réentrée sur la voie accessoire (rythme réciproque)","newInfo":"et que le tracé en dehors des crises retrouve un PR court avec un empâtement du pied du QRS","panel":[0,1,2,9,3],"explanation":"Un PR court avec empâtement du pied du QRS (onde delta) traduit la préexcitation ventriculaire par la voie accessoire, argument en faveur du terrain propice aux tachycardies jonctionnelles par réentrée, sans préjuger du mécanisme exact de la crise actuelle."}],"src":"p. 410-411"},{"id":"231-kfp-51","type":"KFP","rank":"A","objective":"231-obj-06","difficulty":2,"scenario":"Un homme de 74 ans est amené aux urgences pour une perte de connaissance brève sans prodrome, survenue en position assise, avec reprise de conscience immédiate. À l'arrivée, il est asymptomatique, PA 135/80 mmHg. L'ECG montre un rythme sinusal à 72 bpm, un PR à 180 ms, des QRS à 140 ms avec un aspect RsR' en V1 et une onde S traînante en V6, ainsi qu'un axe du QRS à –60° avec D2 négatif.","questions":[{"stem":"Quelles anomalies retenez-vous sur cet ECG ?","max":3,"options":["Bloc de branche droit complet","Hémibloc antérieur gauche","Bloc bifasciculaire","Bloc de branche gauche complet","Hémibloc postérieur gauche","BAV du 1er degré","BAV du 2e degré Mobitz 2","Rythme jonctionnel"],"correct":[0,1,2],"explanation":"QRS > 120 ms avec RsR' en V1 et S traînante en V6 = BBD complet ; axe au-delà de –30° avec D2 négatif = HBAG ; l'association réalise un bloc bifasciculaire. Le PR à 180 ms est normal (120-200 ms)."},{"stem":"Quelle conduite adoptez-vous ?","max":3,"options":["Hospitalisation en cardiologie","Surveillance par télémétrie","Retour à domicile, le rythme étant sinusal","Test à l'adénosine IV","Compression carotidienne diagnostique","Évaluation de l'indication d'un pacemaker","Prescription d'un bêtabloquant","Holter ambulatoire de 24 h à la place de l'hospitalisation"],"correct":[0,1,5],"explanation":"Syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie, en raison du risque de BAV complet infrahissien intermittent ; toute syncope impose de réévaluer l'indication du pacemaker."},{"stem":"Au cours de la surveillance, quels aspects ECG justifieraient l'implantation d'un pacemaker même en l'absence de symptôme ?","max":2,"options":["BAV du 2e degré Mobitz 2","BAV du 3e degré","BAV du 1er degré isolé à 220 ms","Bradycardie sinusale asymptomatique à 55 bpm","Extrasystoles atriales isolées","Hémibloc antérieur gauche isolé"],"correct":[0,1],"explanation":"Les BAV infrahissiens (Mobitz 2, BAV3) justifient un pacemaker même sans symptôme ; une bradycardie sinusale ne relève d'un pacemaker que si elle est symptomatique, et un hémibloc isolé est une atteinte débutante à faible risque."}],"src":"p. 378-383, 412"},{"id":"231-kfp-52","type":"KFP","rank":"B","objective":"231-obj-23","difficulty":2,"scenario":"Un homme de 32 ans, sans antécédent ni facteur de risque cardiovasculaire, consulte aux urgences pour une douleur thoracique évoluant depuis 24 heures. L'ECG montre un rythme sinusal à 95 bpm et un sus-décalage du segment ST dans la plupart des dérivations des deux plans, sans onde Q.","questions":[{"stem":"Quelles caractéristiques ECG sont en faveur d'une péricardite aiguë en phase initiale ?","max":4,"options":["Sus-décalage du ST diffus","Sus-décalage du ST concave vers le haut","Absence d'image en miroir","Sous-décalage du segment PQ (PR)","Onde de Pardee avec sous-décalage en miroir","Sus-décalage limité à D2, D3, aVF avec sous-décalage en D1 et aVL","Rabotage de l'onde R en V2-V3","Allongement du PR à 240 ms"],"correct":[0,1,2,3],"explanation":"La phase 1 de la péricardite associe un sus-ST diffus, concordant, concave vers le haut, sans miroir, un sous-décalage de PQ et un microvoltage. Pardee avec miroir, sus-ST territorial et rabotage de R orientent vers un SCA."},{"stem":"Parmi les causes suivantes, lesquelles font partie des cinq étiologies de sus-décalage du ST citées par le cours ?","max":5,"options":["SCA avec sus-décalage du ST","Anévrisme ventriculaire","Repolarisation précoce","Angor de Prinzmetal","Péricardite","Hypokaliémie","Hypertrophie atriale gauche","Extrasystoles atriales"],"correct":[0,1,2,3,4],"explanation":"Les cinq étiologies de sus-ST sont le SCA ST+, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite ; l'hypokaliémie donne au contraire un sous-décalage du ST."},{"stem":"Le diagnostic de péricardite aiguë est retenu. Quelles évolutions ECG attendez-vous ensuite ?","max":3,"options":["Ondes T plates partout avec ST isoélectrique","Ondes T négatives persistantes","Retour progressif à la normale","Apparition d'ondes Q de nécrose","Apparition d'une onde de Pardee","Apparition d'une onde delta","BAV complet","Aspect S1Q3T3"],"correct":[0,1,2],"explanation":"Après la phase 1 brève : phase 2 (T plates, ST isoélectrique), phase 3 (T négatives persistantes), phase 4 (retour progressif à la normale)."}],"src":"p. 409, 411-412"},{"id":"231-tcs-51","type":"TCS","rank":"A","objective":"231-obj-24","difficulty":3,"vignette":"Un homme de 55 ans consulte aux urgences pour une douleur thoracique. L'ECG montre un sus-décalage du segment ST dans plusieurs dérivations.","items":[{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que vous constatez un sous-décalage du ST en miroir dans les dérivations opposées,","panel":[0,0,1,4,10],"explanation":"La présence d'un miroir caractérise le SCA ST+ (onde de Pardee avec miroir) : l'hypothèse est fortement renforcée."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage est diffus, concave vers le haut, sans miroir, avec un sous-décalage de PQ,","panel":[7,6,2,0,0],"explanation":"Cet ensemble évoque la phase 1 d'une péricardite aiguë, ce qui rend le SCA moins probable (sans l'exclure formellement, l'absence de miroir seule ne suffisant pas)."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage n'intéresse que V1-V2 chez un patient présentant une HVG électrique marquée,","panel":[2,8,4,1,0],"explanation":"L'HVG marquée est un diagnostic différentiel classique du sus-ST en V1-V2 (pseudo-sus-décalage) : l'hypothèse de SCA est affaiblie."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage, localisé en D2, D3 et aVF, englobe l'onde T (onde de Pardee),","panel":[0,0,1,6,8],"explanation":"Un sus-décalage territorial englobant la T (onde de Pardee) sur des dérivations adjacentes est typique du SCA ST+ : l'hypothèse est renforcée."}],"src":"p. 406, 409, 411-412"},{"id":"231-tcs-52","type":"TCS","rank":"A","objective":"231-obj-21","difficulty":2,"vignette":"Un homme de 70 ans, insuffisant rénal chronique, est hospitalisé pour une asthénie. Un ECG est réalisé avant l'obtention du ionogramme sanguin.","items":[{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre des ondes T amples, pointues et symétriques,","panel":[0,0,0,4,11],"explanation":"Les T amples, pointues et symétriques sont le signe typique de l'hyperkaliémie."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre des ondes T plates avec sous-décalage du ST et une onde U,","panel":[10,4,1,0,0],"explanation":"T plates, sous-ST et onde U sont les signes de l'hypokaliémie : l'hypothèse d'hyperkaliémie est fortement affaiblie."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre un allongement du PR et un élargissement des QRS,","panel":[0,0,1,7,7],"explanation":"PR allongé et QRS élargi font partie des anomalies ECG de l'hyperkaliémie."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre un échappement jonctionnel par dysfonction sinusale,","panel":[0,1,4,7,3],"explanation":"La dysfonction sinusale avec échappement jonctionnel figure parmi les troubles rythmiques de l'hyperkaliémie, mais n'est pas spécifique : renforcement modéré."}],"src":"p. 408"}],"trees":[{"id":"231-tree-01","title":"Vérifier qu'un ECG est normal","rank":"A","objective":"231-obj-01","intro":"md La normalité d'un ECG s'affirme par une lecture systématique en quatre temps : rythme, conduction, repolarisation, morphologie.","root":"n1","nodes":{"n1":{"type":"question","text":"Rythme sinusal : onde P positive en D1/D2, un QRS après chaque P et une P avant chaque QRS ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Fréquence entre 60 et 100 bpm ?","note":"md FC = 300 / nombre de grands carreaux séparant deux QRS.","options":[{"label":"Oui","to":"n3"},{"label":"< 60 bpm","to":"e2"},{"label":"> 100 bpm","to":"e3"}]},"n3":{"type":"question","text":"Conduction normale : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe entre -30° et +90° ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"e4"}]},"n4":{"type":"question","text":"Repolarisation normale : point J et ST isoélectriques, T positive sauf aVR/V1, QT < 450 ms ?","options":[{"label":"Oui","to":"n5"},{"label":"Non","to":"e5"}]},"n5":{"type":"action","text":"Vérifier la morphologie : indice de Sokolow < 35 mm, transition R/S progressive de V1 à V6, absence d'onde Q de nécrose.","to":"e6"},"e1":{"type":"end","tone":"warn","text":"Rythme non sinusal : analyser le trouble du rythme ou de conduction avant de conclure."},"e2":{"type":"end","tone":"info","text":"Bradycardie : rechercher une dysfonction sinusale ou un bloc atrioventriculaire."},"e3":{"type":"end","tone":"info","text":"Tachycardie : différencier tachycardie sinusale et trouble du rythme supraventriculaire."},"e4":{"type":"end","tone":"warn","text":"Anomalie de conduction : suspecter un bloc de branche, un hémibloc ou un trouble atrioventriculaire."},"e5":{"type":"end","tone":"warn","text":"Anomalie de repolarisation : orienter vers ischémie, péricardite, hypertrophie ou trouble ionique."},"e6":{"type":"end","tone":"ok","text":"ECG normal si la morphologie est également sans anomalie."}},"src":"p. 377-378"},{"id":"231-tree-02","title":"Analyser une bradycardie","rank":"A","objective":"231-obj-10","intro":"md Devant une fréquence des QRS inférieure à 50 bpm, seules deux structures peuvent être en cause : le nœud sinusal ou le nœud atrioventriculaire.","root":"n1","nodes":{"n1":{"type":"question","text":"Aspect des ondes P sur le tracé ?","options":[{"label":"Régulières, fréquence normale (ou tachycardes type FA/flutter), plus nombreuses que de QRS","to":"n2"},{"label":"Trop lentes ou absentes","to":"n3"}]},"n2":{"type":"action","text":"Le passage de l'oreillette au ventricule est en cause : bloc atrioventriculaire (BAV).","to":"n2b"},"n2b":{"type":"question","text":"QRS d'échappement fins ou larges ?","note":"md Un échappement à QRS fins traduit un bloc nodal (suprahissien) ; un échappement large oriente vers un bloc infrahissien.","options":[{"label":"Fins","to":"e1"},{"label":"Larges","to":"e2"}]},"n3":{"type":"action","text":"Le nœud sinusal est en cause : dysfonction sinusale.","to":"n3b"},"n3b":{"type":"question","text":"Pause avec disparition complète du complexe P-QRS-T (multiple de l'intervalle PP) ?","options":[{"label":"Oui","to":"e3"},{"label":"Non, échappement jonctionnel sans onde P visible devant le QRS","to":"e4"}]},"e1":{"type":"end","tone":"info","text":"BAV probablement suprahissien (nodal), mieux toléré."},"e2":{"type":"end","tone":"danger","text":"BAV probablement infrahissien : risque de syncope, voire de mort subite ; discuter un pacemaker."},"e3":{"type":"end","tone":"warn","text":"Bloc sino-atrial du 2e degré : pause correspondant au double de l'intervalle PP normal."},"e4":{"type":"end","tone":"warn","text":"Dysfonction sinusale marquée avec échappement jonctionnel (activité atriale parfois rétrograde, cachée dans le segment ST)."}},"src":"p. 388-389"},{"id":"231-tree-03","title":"Décrypter une tachycardie","rank":"A","objective":"231-obj-12","intro":"md La démarche associe l'analyse de la régularité et de la largeur des QRS aux manœuvres vagales ou à l'adénosine.","root":"n1","nodes":{"n1":{"type":"question","text":"QRS réguliers ou irréguliers ?","options":[{"label":"Irréguliers","to":"e1"},{"label":"Réguliers","to":"n2"}]},"n2":{"type":"question","text":"QRS fins ou larges ?","options":[{"label":"Larges","to":"n3"},{"label":"Fins","to":"n4"}]},"n3":{"type":"question","text":"Tolérance hémodynamique mauvaise ?","note":"md Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n3b"}]},"n3b":{"type":"action","text":"Rechercher une dissociation ventriculo-atriale, des complexes de fusion/capture ou une déviation extrême en aVR.","to":"e3"},"n4":{"type":"question","text":"Tolérance hémodynamique mauvaise ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n5"}]},"n5":{"type":"action","text":"Réaliser des manœuvres vagales, puis de l'adénosine IV en cas d'échec (contre-indiquées si asthme, hypotension ou FA sur voie accessoire).","to":"n6"},"n6":{"type":"question","text":"Effet obtenu ?","options":[{"label":"Démasque une activité atriale organisée sous-jacente","to":"e4"},{"label":"Arrête brutalement la tachycardie","to":"e5"},{"label":"Aucun effet","to":"e6"}]},"e1":{"type":"end","tone":"warn","text":"Fibrillation atriale (diagnostic différentiel : salves d'extrasystoles atriales)."},"e2":{"type":"end","tone":"danger","text":"Cardioversion électrique externe en urgence."},"e3":{"type":"end","tone":"warn","text":"Tachycardie ventriculaire jusqu'à preuve du contraire."},"e4":{"type":"end","tone":"info","text":"Flutter ou tachycardie atriale focale démasqués par le ralentissement de la conduction au NAV."},"e5":{"type":"end","tone":"ok","text":"Tachycardie jonctionnelle (réentrée dépendante du NAV, ex. maladie de Bouveret)."},"e6":{"type":"end","tone":"info","text":"Tachycardie indépendante du NAV : tachycardie sinusale ou tachycardie atriale focale."}},"src":"p. 405-406"},{"id":"231-tree-04","title":"Devant un sus-décalage du segment ST","rank":"A","objective":"231-obj-24","intro":"md Cinq étiologies principales partagent un sus-décalage de ST ; deux diagnostics différentiels y ressemblent sans en être.","root":"n1","nodes":{"n1":{"type":"question","text":"Sus-décalage diffus, concave vers le haut, sans miroir, avec sous-décalage de PQ ?","options":[{"label":"Oui","to":"e1"},{"label":"Non","to":"n2"}]},"n2":{"type":"question","text":"Sus-décalage systématisé à un territoire, avec miroir (onde de Pardee) ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"question","text":"Douleur thoracique aiguë avec contexte évocateur d'ischémie ?","options":[{"label":"Oui","to":"e2"},{"label":"Non, séquelle d'infarctus connue","to":"e3"},{"label":"Non, épisodes douloureux régressifs","to":"e4"}]},"n4":{"type":"question","text":"Sus-décalage dans les dérivations inféro-latérales, sujet jeune asymptomatique ?","options":[{"label":"Oui","to":"e5"},{"label":"Non","to":"n5"}]},"n5":{"type":"action","text":"Rechercher un bloc de branche gauche, une stimulation ventriculaire ou une hypertrophie ventriculaire gauche marquée.","to":"e6"},"e1":{"type":"end","tone":"info","text":"Péricardite aiguë (ne pas conclure à tort en cas de sus-décalage ischémique sans miroir visible)."},"e2":{"type":"end","tone":"danger","text":"Syndrome coronarien aigu avec sus-décalage du ST : prise en charge urgente."},"e3":{"type":"end","tone":"info","text":"Anévrisme ventriculaire (sus-décalage persistant sur séquelle marquée)."},"e4":{"type":"end","tone":"info","text":"Angor de Prinzmetal (spasme coronarien)."},"e5":{"type":"end","tone":"ok","text":"Repolarisation précoce, variante bénigne."},"e6":{"type":"end","tone":"warn","text":"Diagnostic différentiel : discordance appropriée d'un bloc de branche gauche/pacemaker, ou pseudonécrose d'une HVG sévère."}},"src":"p. 411-412"},{"id":"231-tree-05","title":"Poser l'indication d'un pacemaker devant un trouble de conduction","rank":"B","objective":"231-obj-08","intro":"md L'indication dépend du siège du trouble (nœud sinusal, nodal ou infrahissien) et de sa gravité potentielle.","root":"n1","nodes":{"n1":{"type":"question","text":"Bradycardie symptomatique par dysfonction sinusale, BAV2 Mobitz 1 ou bradycardie sinusale ?","options":[{"label":"Oui","to":"e1"},{"label":"Non","to":"n2"}]},"n2":{"type":"question","text":"BAV2 Mobitz 2 ou BAV3 (infrahissien) ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n3"}]},"n3":{"type":"question","text":"Bloc bifasciculaire (BBD + hémibloc, ou BBG complet) avec syncope ?","options":[{"label":"Oui","to":"e3"},{"label":"Non","to":"e5"}]},"e1":{"type":"end","tone":"warn","text":"Indication de pacemaker (bradycardie symptomatique)."},"e2":{"type":"end","tone":"danger","text":"Indication de pacemaker même en l'absence de symptôme (bloc infrahissien à haut risque)."},"e3":{"type":"end","tone":"danger","text":"Hospitalisation en cardiologie avec télémétrie : risque de BAV complet infrahissien, pacemaker à discuter en urgence."},"e5":{"type":"end","tone":"ok","text":"Pas d'indication de pacemaker à ce stade ; surveillance du trouble de conduction."}},"src":"p. 383, 412-413"},{"id":"231-tree-06","title":"Conduite devant un QT allongé","rank":"A","objective":"231-obj-22","intro":"md L'allongement du QT expose à la torsade de pointes ; la démarche associe recherche de cause et correction en urgence si le trouble du rythme est déjà présent.","root":"n1","nodes":{"n1":{"type":"question","text":"QT corrigé (formule de Bazett) allongé au-delà des valeurs normales ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Cause évidente retrouvée : médicament, hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"action","text":"Corriger la cause : arrêt du médicament en cause, correction du trouble ionique.","to":"n5"},"n4":{"type":"action","text":"Évoquer un syndrome du QT long congénital ; avis spécialisé.","to":"n5"},"n5":{"type":"question","text":"Torsade de pointes ou fibrillation ventriculaire déjà survenue ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"e3"}]},"e1":{"type":"end","tone":"ok","text":"QT normal."},"e2":{"type":"end","tone":"danger","text":"Urgence : accélérer la fréquence cardiaque, corriger les troubles ioniques, arrêter tout médicament allongeant le QT."},"e3":{"type":"end","tone":"warn","text":"Surveillance rapprochée du QT et éviction des médicaments allongeant le QT pour prévenir une mort subite."}},"src":"p. 404"},{"id":"231-tree-07","title":"Diagnostiquer un bloc de branche","rank":"A","objective":"231-obj-06","intro":"md L'analyse suit un ordre fixe : rythme atrial, durée du QRS, aspect en V1 puis en V6.","root":"n1","nodes":{"n1":{"type":"question","text":"Rythme atrial déjà caractérisé (pour ne pas méconnaître une tachycardie supraventriculaire associée) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Durée du QRS > 120 ms ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n2b"}]},"n2b":{"type":"question","text":"QRS entre 110 et 120 ms ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"e3"}]},"n3":{"type":"question","text":"En V1, QRS globalement positif (aspect RsR') ?","options":[{"label":"Oui","to":"e4"},{"label":"Non","to":"n3b"}]},"n3b":{"type":"question","text":"QRS globalement négatif en V1 (rS ou QS) avec notch en V6, D1, aVL ?","options":[{"label":"Oui","to":"e5"},{"label":"Non","to":"e6"}]},"e1":{"type":"end","tone":"info","text":"Rechercher d'abord une tachycardie supraventriculaire associée avant de conclure à un simple trouble de conduction."},"e2":{"type":"end","tone":"info","text":"Bloc incomplet de branche : anomalie de faible intérêt sémiologique."},"e3":{"type":"end","tone":"ok","text":"QRS de durée normale (70-110 ms) : pas de bloc de branche."},"e4":{"type":"end","tone":"warn","text":"Bloc de branche droit complet (confirmer l'aspect qRs traînant en V6)."},"e5":{"type":"end","tone":"warn","text":"Bloc de branche gauche complet."},"e6":{"type":"end","tone":"info","text":"Vérifier l'axe (hémibloc) et rechercher une association réalisant un bloc bifasciculaire."}},"src":"p. 378-381"}],"treatments":{"data":[{"id":"231-tx-01","rank":"B","class":"Manœuvres vagales","molecules":[],"context":"Premier geste diagnostique et parfois thérapeutique devant une tachycardie à QRS fins bien tolérée.","indications":["Tachycardie supraventriculaire régulière bien tolérée (diagnostic et/ou réduction)","Démasquer une activité atriale (flutter, tachycardie atriale focale) en cas de doute diagnostique"],"contraindications":["Compression carotidienne unilatérale contre-indiquée si athérome carotidien marqué ou souffle carotidien","Compression oculaire bilatérale non recommandée (risque de décollement de rétine chez le myope)"],"sideEffects":[],"monitoring":["Scope pendant la manœuvre"],"interactions":[],"pearls":["Manœuvre de Valsalva : expiration forcée à glotte fermée","Boire un grand verre d'eau froide","Utiles pour le diagnostic différentiel des tachycardies, pas seulement pour les traiter"],"src":"p. 390"},{"id":"231-tx-02","rank":"B","class":"Ralentisseur du NAV d'action flash (adénosine)","molecules":["Adénosine"],"context":"Utilisée en cas d'échec des manœuvres vagales pour créer un bloc atrioventriculaire transitoire.","indications":["Tachycardie supraventriculaire non élucidée par les manœuvres vagales","Réduction d'une tachycardie jonctionnelle par réentrée dépendante du NAV"],"contraindications":["Asthme (risque de bronchospasme intense, même chez le non-asthmatique)","Hypotension artérielle","Fibrillation atriale associée à une voie accessoire à conduction rapide (« super-Wolff »)"],"sideEffects":["Bronchospasme transitoire (rare)"],"monitoring":["Scope pendant l'injection"],"interactions":[],"pearls":["Administration en flash intraveineux","Durée d'effet d'une dizaine de secondes","Mécanisme vagomimétique via les récepteurs purinergiques"],"src":"p. 390, 411"},{"id":"231-tx-04","rank":"A","class":"Cardioversion électrique externe","molecules":[],"context":"Geste d'urgence devant une arythmie mal tolérée hémodynamiquement ou une fibrillation ventriculaire.","indications":["Fibrillation ventriculaire : geste à réaliser en priorité absolue avant tout autre","Tachycardie (régulière ou irrégulière, fine ou large) mal tolérée sur le plan hémodynamique"],"contraindications":[],"sideEffects":[],"monitoring":["Massage cardiaque en attendant la délivrance du choc électrique en cas de fibrillation ventriculaire"],"interactions":[],"pearls":[],"src":"p. 372, 405-406"},{"id":"231-tx-05","rank":"B","class":"Stimulateur cardiaque (pacemaker)","molecules":[],"context":"Traite les bradycardies symptomatiques et certains blocs de conduction à haut risque évolutif.","indications":["Bradycardie symptomatique : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale","BAV infrahissien (Mobitz 2, BAV3), même en l'absence de symptôme","Bloc bifasciculaire associé à une syncope (après réévaluation)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le spike de stimulation dure 0,4 à 1 ms, très court par rapport à tout signal physiologique","En cas de stimulation ventriculaire droite, le QRS est large avec un aspect de bloc de branche gauche"],"src":"p. 383, 412-414"},{"id":"231-tx-06","rank":"B","class":"Défibrillateur implantable","molecules":[],"context":"Prévention de la mort subite par tachycardie ou fibrillation ventriculaire.","indications":["Risque de tachycardie ou de fibrillation ventriculaire"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Assure toujours aussi la fonction pacemaker, sauf modèle sous-cutané","Peut être associé à la resynchronisation (défibrillateur de resynchronisation)"],"src":"p. 412"},{"id":"231-tx-07","rank":"B","class":"Resynchronisation cardiaque","molecules":[],"context":"Corrige la désynchronisation des parois ventriculaires liée à un bloc de branche gauche complet évolutif.","indications":["Bloc de branche gauche complet contribuant à créer ou aggraver une insuffisance cardiaque"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Assure toujours la fonction pacemaker","Peut être associée à un défibrillateur"],"src":"p. 383, 412"},{"id":"231-tx-08","rank":"B","class":"Ablation par radiofréquence","molecules":[],"context":"Traitement curatif de certaines arythmies par réentrée, après confirmation lors d'une exploration électrophysiologique.","indications":["Flutter atrial (confirmation puis ablation de l'isthme cavotricuspide pour le flutter typique)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 394"},{"id":"231-tx-09","rank":"A","class":"Correction des troubles ioniques","molecules":[],"context":"Prise en charge étiologique d'un allongement du QT ou d'une torsade de pointes.","indications":["Hypokaliémie","Hypocalcémie","Hypomagnésémie","Allongement du QT documenté"],"contraindications":[],"sideEffects":[],"monitoring":["Ionogramme","Surveillance ECG du QT"],"interactions":[],"pearls":["À associer à l'arrêt des médicaments allongeant le QT et à l'accélération de la fréquence cardiaque"],"src":"p. 404"},{"id":"231-tx-10","rank":"A","class":"Arrêt des médicaments à risque rythmique","molecules":[],"context":"Cause réversible fréquente d'un allongement du QT, d'une bradycardie ou d'un trouble de conduction.","indications":["Médicament allongeant le QT en cas de torsade de pointes ou de QT long","Médicament bradycardisant en cas de bradycardie ou de bloc atrioventriculaire symptomatique"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 404, 412"}],"strategies":[{"id":"231-strat-01","rank":"A","title":"Prise en charge immédiate d'une tachycardie","content":"md 1. Évaluer la tolérance hémodynamique en premier lieu.\n2. Si mauvaise tolérance : cardioversion électrique externe sans délai.\n3. Si bonne tolérance : analyser la régularité puis la largeur des QRS.\n4. QRS larges réguliers → traiter comme une tachycardie ventriculaire jusqu'à preuve du contraire ; rechercher dissociation ventriculo-atriale, fusions/captures.\n5. QRS fins → manœuvres vagales, puis adénosine IV en flash si échec (sauf asthme, hypotension ou FA sur voie accessoire).\n6. Interpréter l'effet obtenu : arrêt brutal (tachycardie jonctionnelle), démasquage d'une activité atriale organisée (flutter, tachycardie atriale focale) ou absence d'effet (tachycardie sinusale).\n7. QRS irréguliers → fibrillation atriale dans la grande majorité des cas.","src":"p. 405-406"},{"id":"231-strat-02","rank":"B","title":"Conduite devant un allongement du QT ou une torsade de pointes","content":"md 1. Confirmer l'allongement du QT corrigé (formule de Bazett), sans inclure une éventuelle onde U dans la mesure.\n2. Rechercher une cause : médicament allongeant le QT, hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, ou forme congénitale.\n3. En cas de torsade de pointes ou de fibrillation ventriculaire déjà présente : corriger les troubles ioniques et accélérer la fréquence cardiaque en urgence.\n4. Dans tous les cas : arrêter les médicaments allongeant le QT en cause.\n5. Surveiller le QT après correction.","src":"p. 404"},{"id":"231-strat-03","rank":"B","title":"Choix de l'électroentraînement selon le trouble rythmique","content":"md 1. Problème hémodynamique lié à une bradycardie → pacemaker.\n2. Problème rythmique lié à un risque de tachycardie ou de fibrillation ventriculaire → défibrillateur (qui assure aussi la fonction pacemaker, sauf modèle sous-cutané).\n3. Bloc de branche gauche désynchronisant les parois du ventricule gauche avec insuffisance cardiaque → resynchronisation cardiaque.\n4. Les trois fonctions peuvent être associées (défibrillateur de resynchronisation) selon le profil du patient.","src":"p. 383, 412-414"}]},"cases":[{"id":"231-case-01","title":"M. Lefranc, 34 ans, palpitations brutales en pleine réunion","rank":"A","summary":"Crise de palpitations régulières et rapides chez un homme jeune sans cardiopathie, explorée pas à pas jusqu'au diagnostic de tachycardie jonctionnelle.","difficulty":2,"timeline":["Appel et premier contact","ECG per-critique","Manœuvres et traitement","Diagnostic","Exploration","Suivi"],"steps":[{"id":"231-case-01-s01","phase":0,"narrative":"md M. Lefranc, 34 ans, sans antécédent connu, ressent depuis vingt minutes des palpitations « qui ont démarré d'un coup », régulières, à une fréquence qu'il estime très rapide. Il n'a ni douleur thoracique ni dyspnée franche. Un collègue prend son pouls : régulier, très rapide, difficile à compter.","question":{"type":"QRM","stem":"Quels éléments, s'ils étaient présents, orienteraient plutôt vers une tachycardie sinusale que vers un trouble du rythme supraventriculaire ?","options":[{"t":"Une fréquence qui varie progressivement dans le temps plutôt que par paliers brusques","ok":true,"why":"La tachycardie sinusale varie progressivement, contrairement au trouble du rythme qui évolue « en marches d'escalier »."},{"t":"Un contexte de fièvre, de douleur ou de stress évident","ok":true,"why":"Une tachycardie sinusale s'explique par une cause qui augmente le métabolisme ; en son absence chez un sujet au repos, l'hypothèse doit être réévaluée."},{"t":"Un début et une fin brutaux, en quelques secondes","ok":false,"why":"C'est au contraire un argument pour un trouble du rythme supraventriculaire (début/fin brusques)."},{"t":"Une onde P sinusale bien visible devant chaque QRS, positive en D1, D2, D3, aVF","ok":true,"why":"C'est la définition électrique du rythme sinusal, quelle que soit la fréquence."},{"t":"Une fréquence stable autour de 190 bpm au repos strict","ok":false,"why":"Une fréquence aussi élevée et stable au repos est inhabituelle pour une simple tachycardie sinusale."}],"explanation":"md La distinction repose sur l'allure de la fréquence (progressive vs par paliers), le contexte clinique et la morphologie de l'onde P."},"reveal":"md Le collègue appelle les secours ; un premier ECG est réalisé dès l'arrivée de l'équipe.","src":"p. 390-391"},{"id":"231-case-01-s02","phase":1,"narrative":"md L'ECG montre une tachycardie régulière à QRS fins, à 195 bpm, sans onde P clairement identifiable avant les QRS. Le patient reste conscient, coloré, tension artérielle à 118/74 mmHg.","question":{"type":"QROC","question":"Quel est le premier geste, simple et non invasif, à proposer devant cette tachycardie régulière à QRS fins bien tolérée ?","answer":"Manœuvres vagales","accept":["manoeuvre vagale","manœuvre vagale","manoeuvres vagales"],"keywords":["vagal","Valsalva"],"explanation":"md Les manœuvres vagales (Valsalva, eau froide, compression carotidienne unilatérale en l'absence de souffle) sont le premier geste, à la fois diagnostique et parfois thérapeutique."},"reveal":"md Une manœuvre de Valsalva est tentée en premier lieu.","src":"p. 390, 405"},{"id":"231-case-01-s03","phase":2,"narrative":"md La manœuvre de Valsalva ne modifie pas le tracé. Le patient reste stable hémodynamiquement.","question":{"type":"QRM","stem":"Le patient étant stable et la manœuvre de Valsalva inefficace, quelles propositions sont exactes pour la suite de la prise en charge ?","options":[{"t":"L'adénosine en flash intraveineux est l'étape suivante logique","ok":true,"why":"En cas d'échec des manœuvres vagales chez un patient stable, l'adénosine IV en flash est l'étape suivante pour créer un bloc atrioventriculaire transitoire diagnostique et souvent thérapeutique."},{"t":"Une cardioversion électrique externe immédiate est indiquée","ok":false,"why":"Réservée aux tachycardies mal tolérées hémodynamiquement, ce qui n'est pas le cas ici."},{"t":"Une autre manœuvre vagale (compression carotidienne unilatérale ou eau froide) peut encore être tentée avant l'adénosine","ok":true,"why":"Les manœuvres vagales regroupent plusieurs techniques (Valsalva, eau froide, compression carotidienne unilatérale en l'absence de souffle) qui peuvent être essayées successivement."},{"t":"La compression oculaire bilatérale est une alternative recommandée","ok":false,"why":"Cette manœuvre n'est plus recommandée en raison du risque de décollement de rétine chez le myope."},{"t":"Une simple surveillance sans aucun geste supplémentaire est suffisante","ok":false,"why":"La tachycardie doit être documentée et si possible réduite ou expliquée, pas seulement surveillée."}],"explanation":"md Après échec d'une première manœuvre vagale, une autre manœuvre vagale peut être tentée, puis l'adénosine IV en flash chez un patient stable ; la compression oculaire bilatérale est proscrite."},"reveal":"md L'équipe tente une compression carotidienne unilatérale, sans succès, puis prépare l'injection d'adénosine.","src":"p. 390"},{"id":"231-case-01-s04","phase":2,"narrative":"md Interrogatoire rapide avant l'injection d'adénosine : pas d'asthme connu, tension artérielle correcte, pas d'antécédent de préexcitation connue.","question":{"type":"QRM","stem":"Quelles situations contre-indiquent l'utilisation de l'adénosine intraveineuse ?","options":[{"t":"Asthme","ok":true,"why":"Risque de bronchospasme intense transitoire, même chez un sujet non asthmatique connu."},{"t":"Hypotension artérielle","ok":true,"why":"C'est une contre-indication explicitement mentionnée."},{"t":"Fibrillation atriale associée à une voie accessoire à conduction rapide (« super-Wolff »)","ok":true,"why":"C'est la seule autre contre-indication citée, avec l'asthme."},{"t":"Grossesse au premier trimestre","ok":false,"why":"N'est pas mentionnée comme contre-indication dans le chapitre."},{"t":"Âge supérieur à 65 ans","ok":false,"why":"N'est pas une contre-indication retenue ici."}],"explanation":"md Les contre-indications retenues sont l'asthme, l'hypotension artérielle et la FA sur voie accessoire à conduction rapide."},"reveal":"md Aucune contre-indication n'étant retrouvée, l'adénosine est injectée en flash intraveineux.","src":"p. 390, 411"},{"id":"231-case-01-s05","phase":3,"narrative":"md Quelques secondes après l'injection, la tachycardie s'arrête brutalement et le tracé revient à un rythme sinusal régulier à 78 bpm.","question":{"type":"QRU","stem":"Quel diagnostic est le plus probable devant cet arrêt brutal de la tachycardie après adénosine ?","options":[{"t":"Flutter atrial démasqué par le ralentissement du NAV","ok":false,"why":"Dans le flutter, l'adénosine démasque l'activité atriale (ondes F) mais n'arrête pas l'arythmie car celle-ci ne dépend pas du NAV."},{"t":"Tachycardie sinusale","ok":false,"why":"Une tachycardie sinusale n'est pas interrompue par l'adénosine, elle ralentit transitoirement puis reprend."},{"t":"Tachycardie jonctionnelle par réentrée dépendante du NAV","ok":true,"why":"L'arrêt brutal de la tachycardie par l'adénosine signe une arythmie dont le circuit emprunte le NAV, typique des tachycardies jonctionnelles (dont la réentrée intranodale)."},{"t":"Tachycardie ventriculaire","ok":false,"why":"Le tracé initial était à QRS fins, incompatible avec une origine ventriculaire."},{"t":"Tachycardie atriale focale","ok":false,"why":"L'adénosine n'a en général aucun effet sur ce mécanisme indépendant du NAV."}],"explanation":"md L'arrêt franc de la tachycardie par blocage du NAV signe une arythmie dont le circuit de réentrée dépend du nœud atrioventriculaire."},"reveal":"md Le diagnostic retenu est une tachycardie jonctionnelle, très probablement par réentrée intranodale.","src":"p. 405-406"},{"id":"231-case-01-s06","phase":3,"narrative":"md Le patient est rassuré ; l'épisode a duré environ vingt-cinq minutes au total.","question":{"type":"QRM","stem":"Quelles affirmations concernant les deux formes de tachycardies jonctionnelles décrites dans ce chapitre sont exactes ?","options":[{"t":"La réentrée intranodale est un mécanisme de réentrée au sein du nœud atrioventriculaire","ok":true,"why":"C'est la première forme de tachycardie jonctionnelle."},{"t":"La réentrée par voie accessoire fait intervenir le faisceau de Kent","ok":true,"why":"La seconde forme correspond à une réentrée par le faisceau de Kent, voie accessoire entre oreillette et ventricule."},{"t":"Les tachycardies jonctionnelles sont typiquement irrégulières","ok":false,"why":"Elles sont au contraire très régulières, souvent autour de 200 bpm."},{"t":"Dans la réentrée intranodale, l'activité atriale est souvent invisible ou devinée dans le segment ST","ok":true,"why":"L'activation atriale et ventriculaire y est quasi synchrone, rendant l'onde P difficile à voir."},{"t":"Ces deux mécanismes naissent en dessous de la bifurcation hissienne","ok":false,"why":"Les tachycardies jonctionnelles naissent au niveau de la jonction atrioventriculaire, au-dessus de cette bifurcation, à la différence des tachycardies ventriculaires."}],"explanation":"md Les deux formes de tachycardies jonctionnelles sont la réentrée intranodale (réentrée dans le NAV, activité atriale souvent invisible) et le rythme réciproque par voie accessoire (faisceau de Kent) ; elles sont très régulières, souvent autour de 200 bpm."},"reveal":"md Le patient est orienté vers une consultation de rythmologie pour discuter la suite de la prise en charge.","src":"p. 395"},{"id":"231-case-01-s07","phase":4,"narrative":"md En consultation, le cardiologue rythmologue propose une exploration électrophysiologique en cas de récidive gênante.","question":{"type":"QRU","stem":"Quel traitement, mentionné pour les arythmies par réentrée, peut être proposé après confirmation du mécanisme lors d'une exploration électrophysiologique ?","options":[{"t":"Ablation par radiofréquence","ok":true,"why":"C'est le traitement curatif des arythmies par réentrée confirmées en exploration électrophysiologique, comme pour le flutter."},{"t":"Implantation d'un défibrillateur","ok":false,"why":"Réservé au risque de tachycardie ou fibrillation ventriculaire, non à cette arythmie supraventriculaire bénigne."},{"t":"Implantation d'un pacemaker","ok":false,"why":"Indiqué dans les bradycardies ou blocs de conduction, pas dans cette tachycardie jonctionnelle."},{"t":"Resynchronisation cardiaque","ok":false,"why":"Concerne la désynchronisation ventriculaire liée à un bloc de branche gauche, sans rapport avec ce tableau."},{"t":"Coronarographie","ok":false,"why":"Aucun argument pour une origine coronarienne dans ce tableau."}],"explanation":"md L'ablation par radiofréquence, après repérage électrophysiologique du circuit, est le traitement curatif des arythmies par réentrée."},"reveal":"md Le patient choisit une simple surveillance dans un premier temps, avec consigne de refaire les manœuvres vagales en cas de récidive.","src":"p. 394"},{"id":"231-case-01-s08","phase":5,"narrative":"md Six mois plus tard, M. Lefranc revient en consultation : aucune récidive de palpitations n'est survenue.","question":{"type":"QROC","question":"Quelle conduite pratique doit-on lui rappeler en cas de nouvelle crise de palpitations régulières bien tolérées ?","answer":"Réaliser une manœuvre vagale (Valsalva, eau froide)","accept":["manoeuvre vagale","valsalva"],"keywords":["manœuvre vagale","Valsalva"],"explanation":"md Les manœuvres vagales restent le premier réflexe simple, disponible en autonomie, devant une récidive bien tolérée."},"reveal":"md Le patient repart rassuré, avec les coordonnées du service en cas de récidive prolongée ou mal tolérée.","src":"p. 390"},{"id":"231-case-01-s09","phase":5,"narrative":"md M. Lefranc demande si le fait d'avoir eu une seule crise, bien tolérée et rapidement résolue par l'adénosine, change le pronostic à long terme.","question":{"type":"QRM","stem":"Concernant le pronostic après une tachycardie jonctionnelle bien tolérée et rapidement réduite par l'adénosine, quelles affirmations sont exactes ?","options":[{"t":"Il s'agit d'un trouble du rythme fréquent, habituellement sans gravité immédiate","ok":true,"why":"C'est la description cohérente avec le chapitre pour les tachycardies jonctionnelles."},{"t":"Une ablation par radiofréquence peut être discutée en cas de récidives gênantes après exploration électrophysiologique","ok":true,"why":"C'est le traitement curatif proposé en cas de récidive gênante, après confirmation du mécanisme."},{"t":"Une évolution vers une fibrillation ventriculaire est habituelle à moyen terme","ok":false,"why":"Rien de tel n'est décrit pour ce mécanisme, qui naît au-dessus de la bifurcation hissienne."},{"t":"Une implantation de défibrillateur est systématique après un premier épisode","ok":false,"why":"Aucune indication de défibrillateur n'est décrite pour ce mécanisme supraventriculaire."},{"t":"Les manœuvres vagales restent un réflexe utile en cas de récidive bien tolérée","ok":true,"why":"Les manœuvres vagales restent le premier geste simple à proposer en cas de récidive bien tolérée."}],"explanation":"md Les tachycardies jonctionnelles par réentrée intranodale sont fréquentes, habituellement bénignes, traitées par manœuvres vagales, adénosine, et éventuellement ablation en cas de récidives gênantes."},"reveal":"md Le patient est rassuré sur le caractère bénin de l'épisode.","src":"p. 395"},{"id":"231-case-01-s10","phase":5,"narrative":"md Avant de conclure la consultation, le cardiologue résume les deux formes de tachycardies jonctionnelles évoquées dans le dossier.","question":{"type":"QROC","question":"Quel est le nom de la voie électrique surnuméraire à l'origine des tachycardies jonctionnelles par rythme réciproque (l'autre grand mécanisme, non retrouvé ici) ?","answer":"Le faisceau de Kent (voie accessoire)","accept":["faisceau de kent","voie accessoire"],"keywords":["Kent","voie accessoire"],"explanation":"md Le second mécanisme des tachycardies jonctionnelles est la réentrée par une voie accessoire, le faisceau de Kent, reliant l'oreillette au ventricule en dehors du NAV."},"reveal":"md Le dossier de M. Lefranc est clôturé après ce rappel physiopathologique.","src":"p. 396"}]},{"id":"231-case-02","title":"Mme Auger, 79 ans, malaise avec perte de connaissance brève","rank":"A","summary":"Syncope chez une patiente âgée révélant une bradycardie profonde ; la démarche distingue dysfonction sinusale et bloc atrioventriculaire jusqu'à la décision d'appareillage.","difficulty":2,"timeline":["Admission aux urgences","Premier ECG","Analyse du mécanisme","Bilan étiologique","Décision et implantation","Suivi post-implantation"],"steps":[{"id":"231-case-02-s01","phase":0,"narrative":"md Mme Auger, 79 ans, traitée pour une hypertension artérielle, est amenée aux urgences après une brève perte de connaissance survenue en se levant, sans mouvement anormal ni morsure de langue. Elle est consciente à l'arrivée, un peu fatiguée. Le pouls est estimé à environ 35 bpm, régulier.","question":{"type":"QRM","stem":"Devant cette bradycardie extrême, quelles sont les deux structures dont le dysfonctionnement peut en être responsable ?","options":[{"t":"Le nœud sinusal","ok":true,"why":"Une dysfonction sinusale est l'une des deux causes possibles d'une bradycardie marquée."},{"t":"Le nœud atrioventriculaire","ok":true,"why":"Un bloc atrioventriculaire de haut degré est l'autre cause possible d'une bradycardie marquée."},{"t":"Le faisceau de His isolément, en l'absence de toute autre atteinte","ok":false,"why":"Ce n'est pas la formulation retenue ; le trouble atrioventriculaire est envisagé de façon globale (nœud atrioventriculaire)."},{"t":"Le nœud atrioventriculaire ou le nœud sinusal, à distinguer par l'analyse des ondes P","ok":true,"why":"C'est la démarche proposée : l'aspect des ondes P oriente vers l'une ou l'autre structure."},{"t":"Le muscle ventriculaire lui-même, indépendamment de toute structure de conduction","ok":false,"why":"Ce n'est pas la cause d'une bradycardie décrite dans le chapitre."}],"explanation":"md Seules deux structures peuvent, en dysfonctionnant, entraîner une bradycardie : le nœud sinusal (dysfonction sinusale) ou le nœud atrioventriculaire (BAV)."},"reveal":"md Un ECG 12 dérivations est réalisé immédiatement.","src":"p. 389"},{"id":"231-case-02-s02","phase":1,"narrative":"md L'ECG montre des ondes P régulières à une fréquence proche de 75 bpm, mais on compte davantage d'ondes P que de complexes QRS, ceux-ci survenant de façon indépendante à environ 34 bpm.","question":{"type":"QRU","stem":"Quel diagnostic électrique cette dissociation entre une activité atriale normale et des QRS plus rares et indépendants évoque-t-elle ?","options":[{"t":"Dysfonction sinusale","ok":false,"why":"Dans la dysfonction sinusale, ce sont les ondes P elles-mêmes qui sont trop lentes ou absentes ; ici elles sont normales en fréquence."},{"t":"Bloc atrioventriculaire complet (BAV3)","ok":true,"why":"Des ondes P régulières à fréquence normale mais dissociées de QRS plus lents et réguliers signent un bloc atrioventriculaire complet avec rythme d'échappement."},{"t":"Fibrillation atriale à conduction lente","ok":false,"why":"L'activité atriale décrite ici est organisée et régulière, pas anarchique."},{"t":"Extrasystoles atriales bloquées itératives","ok":false,"why":"Ne rend pas compte d'une dissociation aussi complète et régulière."},{"t":"Tachycardie atriale focale avec bloc","ok":false,"why":"La fréquence atriale ici est normale, non tachycarde."}],"explanation":"md La présence de plus d'ondes P que de QRS, avec des ondes P régulières à fréquence normale, oriente vers un problème de passage au ventricule : le bloc atrioventriculaire."},"reveal":"md Le diagnostic de bloc atrioventriculaire complet est retenu ; l'équipe analyse la largeur de l'échappement.","src":"p. 389"},{"id":"231-case-02-s03","phase":2,"narrative":"md Les QRS d'échappement sont larges (150 ms), à une fréquence régulière d'environ 34 bpm.","question":{"type":"QROC","question":"Un échappement à QRS larges dans ce contexte de BAV oriente vers quel siège probable du bloc ?","answer":"Infrahissien","accept":["infra-hissien","sous hissien","bas situé"],"keywords":["infrahissien"],"explanation":"md Un échappement à QRS fins traduit un bloc nodal (suprahissien), alors qu'un échappement à QRS larges oriente vers un bloc infrahissien, de plus mauvais pronostic."},"reveal":"md L'équipe considère ce BAV comme probablement infrahissien.","src":"p. 387, 389"},{"id":"231-case-02-s04","phase":2,"narrative":"md La patiente reste stable hémodynamiquement mais somnolente.","question":{"type":"QRM","stem":"Quelles sont les conséquences potentielles d'un bloc atrioventriculaire infrahissien non traité ?","options":[{"t":"Syncopes à répétition","ok":true,"why":"C'est une conséquence directement citée pour les blocs de conduction à haut risque."},{"t":"Mort subite","ok":true,"why":"Le risque de mort subite est explicitement mentionné pour ces blocs de haut degré."},{"t":"Fibrillation atriale obligatoire à court terme","ok":false,"why":"Aucun lien de causalité direct de ce type n'est décrit."},{"t":"Aggravation en bloc atrioventriculaire complet si le trouble était initialement incomplet","ok":true,"why":"Les blocs de haut risque annoncent une évolution possible vers le BAV infrahissien complet."},{"t":"Hypertrophie ventriculaire gauche immédiate","ok":false,"why":"Ce n'est pas une conséquence rythmique directe d'un BAV."}],"explanation":"md Un bloc atrioventriculaire infrahissien expose à des syncopes et à la mort subite, ce qui justifie une prise en charge rapide."},"reveal":"md Une hospitalisation en unité de soins intensifs cardiologiques est décidée, avec scope.","src":"p. 384, 389"},{"id":"231-case-02-s05","phase":3,"narrative":"md Avant toute décision d'appareillage définitif, le bilan recherche une cause réversible : ionogramme sanguin normal (kaliémie à 4,2 mmol/L), pas de médicament bradycardisant dans le traitement habituel de la patiente.","question":{"type":"QRM","stem":"Pourquoi est-il utile de rechercher une dyskaliémie ou un médicament bradycardisant avant de conclure à une indication définitive de pacemaker ?","options":[{"t":"Une hyperkaliémie peut elle-même provoquer un bloc atrioventriculaire ou une dysfonction sinusale","ok":true,"why":"L'hyperkaliémie s'accompagne notamment d'un allongement du PR, d'un élargissement du QRS, d'un BAV ou d'une dysfonction sinusale."},{"t":"Une hypokaliémie explique classiquement les blocs atrioventriculaires de haut degré","ok":false,"why":"L'hypokaliémie se traduit surtout par une onde T plate, un QT allongé et un risque de torsade de pointes, pas typiquement par un BAV."},{"t":"Un médicament bradycardisant peut être une cause réversible de bradycardie ou de bloc","ok":true,"why":"Il faut éliminer une cause pharmacologique réversible avant de poser une indication définitive d'appareillage."},{"t":"Ces éléments n'ont aucune incidence sur la décision thérapeutique","ok":false,"why":"Au contraire, ils orientent directement la décision d'implantation ou de simple correction d'une cause réversible."},{"t":"La correction d'une cause réversible peut éviter une implantation de pacemaker","ok":true,"why":"C'est l'intérêt principal de cette recherche systématique."}],"explanation":"md Avant toute décision d'appareillage, il faut écarter une cause réversible (dyskaliémie, médicament bradycardisant), en particulier l'hyperkaliémie qui peut mimer ou aggraver un trouble de conduction."},"reveal":"md Aucune cause réversible n'étant retrouvée, l'indication de pacemaker est confirmée.","src":"p. 408-409, 412"},{"id":"231-case-02-s06","phase":4,"narrative":"md Le bilan étant négatif, la décision d'implanter un stimulateur cardiaque est prise.","question":{"type":"QRU","stem":"Compte tenu du siège probablement infrahissien du bloc, quelle affirmation concernant l'indication de pacemaker est exacte ?","options":[{"t":"L'indication est posée même si la patiente était restée asymptomatique","ok":true,"why":"Les BAV infrahissiens (Mobitz 2, BAV3) sont une indication de pacemaker même en l'absence de symptôme."},{"t":"L'indication ne se discute qu'en présence de symptômes répétés","ok":false,"why":"C'est le cas pour la dysfonction sinusale ou le BAV2 Mobitz 1, pas pour le BAV infrahissien de haut degré."},{"t":"Un simple traitement médicamenteux suffit à corriger ce trouble","ok":false,"why":"Aucun traitement médicamenteux curatif de ce trouble structurel n'est décrit."},{"t":"Il faut attendre une deuxième syncope avant d'implanter","ok":false,"why":"Ce n'est pas la logique retenue pour un bloc infrahissien de haut risque."},{"t":"Seule une surveillance ambulatoire par holter est proposée","ok":false,"why":"Insuffisant devant un bloc de haut degré symptomatique et à risque de mort subite."}],"explanation":"md Les blocs atrioventriculaires infrahissiens (Mobitz 2, BAV3) constituent une indication de pacemaker même sans symptôme, du fait du risque de mort subite."},"reveal":"md Un pacemaker double chambre est implanté sans complication.","src":"p. 384, 412"},{"id":"231-case-02-s07","phase":5,"narrative":"md L'ECG post-implantation montre un spike de stimulation suivi d'un QRS large avec un aspect de bloc de branche gauche.","question":{"type":"QROC","question":"Pourquoi la stimulation ventriculaire droite donne-t-elle un aspect de bloc de branche gauche à l'ECG ?","answer":"Parce que l'influx stimulé se propage de proche en proche depuis le ventricule droit vers le ventricule gauche, sans emprunter le réseau de conduction rapide","accept":["conduction de proche en proche","propagation lente depuis le ventricule droit"],"keywords":["proche en proche","ventricule droit","conduction lente"],"explanation":"md La stimulation ventriculaire droite se transmet lentement de proche en proche au reste des ventricules, contrairement à la conduction rapide du réseau de His-Purkinje, ce qui donne un aspect de bloc de branche gauche."},"reveal":"md Le boîtier est programmé et la patiente reçoit les consignes de suivi.","src":"p. 413-414"},{"id":"231-case-02-s09","phase":5,"narrative":"md Au contrôle du premier mois, le fonctionnement du pacemaker est normal ; Mme Auger n'a pas eu de nouveau malaise.","question":{"type":"QRU","stem":"Si un nouvel épisode de malaise survenait malgré le pacemaker bien fonctionnel, quelle démarche diagnostique reste pertinente pour en préciser la cause ?","options":[{"t":"Un enregistrement Holter ou l'interrogation de la mémoire du pacemaker, à la recherche d'un autre mécanisme (rythmique ou non)","ok":true,"why":"Le monitorage ECG prolongé et l'interrogation du dispositif restent les outils de choix pour documenter un symptôme épisodique, même chez un patient appareillé."},{"t":"Aucune exploration supplémentaire n'est jamais utile chez un patient porteur de pacemaker","ok":false,"why":"Le pacemaker corrige la bradycardie mais n'exclut pas une autre cause de malaise."},{"t":"Une nouvelle implantation systématique d'un deuxième dispositif","ok":false,"why":"Ce n'est pas la démarche proposée devant un malaise chez un patient déjà appareillé."},{"t":"Un scanner cérébral systématique en première intention","ok":false,"why":"N'est pas la démarche rythmologique décrite dans ce chapitre."},{"t":"Un arrêt du pacemaker pour réévaluer le rythme spontané","ok":false,"why":"Geste dangereux et non recommandé pour explorer un malaise."}],"explanation":"md Même appareillé, un patient présentant un nouveau malaise doit bénéficier d'une évaluation rythmique (Holter, mémoire du dispositif) pour rechercher une autre cause."},"reveal":"md Aucun nouvel épisode n'est survenu ; la surveillance se poursuit.","src":"p. 414, 415"},{"id":"231-case-02-s10","phase":5,"narrative":"md Un an plus tard, Mme Auger va bien et se demande si elle pourra un jour se passer de son pacemaker.","question":{"type":"QROC","question":"Que peut-on lui répondre concernant le caractère définitif de l'indication posée initialement (BAV infrahissien sans cause réversible retrouvée) ?","answer":"L'indication reste définitive, aucune cause réversible n'ayant été retrouvée","accept":["indication definitive","pas de cause reversible donc indication permanente"],"keywords":["définitive","pas de cause réversible"],"explanation":"md Le bilan initial n'ayant retrouvé aucune cause réversible (kaliémie normale, pas de médicament en cause), l'indication de pacemaker posée pour ce BAV infrahissien reste définitive."},"reveal":"md Mme Auger poursuit son suivi cardiologique annuel.","src":"p. 384, 412"}]},{"id":"231-case-03","title":"M. Costa, 56 ans, douleur thoracique et bloc de branche gauche connu","rank":"A","summary":"Douleur thoracique aiguë chez un patient porteur d'un bloc de branche gauche complet, illustrant le piège de la discordance appropriée et les diagnostics différentiels du sus-décalage de ST.","difficulty":3,"timeline":["Arrivée aux urgences","Premier ECG","Analyse du tracé","Décision de prise en charge","Explorations et évolution","Suivi à distance"],"steps":[{"id":"231-case-03-s01","phase":0,"narrative":"md M. Costa, 56 ans, hypertendu et fumeur, se présente aux urgences pour une douleur thoracique constrictive apparue il y a quarante minutes, toujours présente. Il est connu porteur d'un bloc de branche gauche complet ancien, retrouvé sur un ECG systématique deux ans plus tôt.","question":{"type":"QRM","stem":"Quels éléments faut-il vérifier dans l'ordre pour caractériser ce bloc de branche sur l'ECG réalisé aux urgences ?","options":[{"t":"Le rythme atrial, en premier lieu","ok":true,"why":"Il faut toujours commencer par décrire le rythme atrial avant de décrire un trouble de conduction, pour ne pas méconnaître une tachycardie supraventriculaire associée."},{"t":"La durée du QRS (> 120 ms pour un bloc complet)","ok":true,"why":"C'est le deuxième critère à vérifier."},{"t":"L'aspect du QRS en V1 (positif ou négatif)","ok":true,"why":"Un QRS positif en V1 oriente vers un bloc droit, négatif vers un bloc gauche."},{"t":"La présence obligatoire d'un sus-décalage du segment ST en D2","ok":false,"why":"Ce n'est pas un critère de diagnostic du bloc de branche lui-même."},{"t":"L'aspect inverse en V6","ok":true,"why":"La vérification de l'aspect en V6, inverse de celui de V1, complète l'analyse."}],"explanation":"md La démarche recommandée est : rythme atrial, durée du QRS, aspect en V1, puis aspect inverse en V6."},"reveal":"md L'ECG confirme un bloc de branche gauche complet inchangé, avec un rythme sinusal sous-jacent.","src":"p. 381"},{"id":"231-case-03-s02","phase":1,"narrative":"md Le tracé montre en V1-V2 un segment ST légèrement sus-décalé, avec une onde T positive, dans un contexte de QRS négatif à cet endroit (aspect de bloc de branche gauche).","question":{"type":"QRM","stem":"Que faut-il savoir sur ce sus-décalage observé en V1-V2 chez ce patient porteur d'un bloc de branche gauche ?","options":[{"t":"Il peut correspondre à une « discordance appropriée », physiologique dans le bloc de branche gauche","ok":true,"why":"Quand le QRS est négatif, un petit sus-décalage de ST avec T positive est la discordance attendue et n'est pas en soi pathologique."},{"t":"Il élimine formellement un syndrome coronarien aigu","ok":false,"why":"Au contraire, l'interprétation de la repolarisation est difficile en présence d'un bloc de branche gauche et ne permet pas d'éliminer un SCA."},{"t":"Il peut faire évoquer à tort un syndrome coronarien aigu avec sus-décalage du ST","ok":true,"why":"C'est explicitement le piège décrit : la discordance appropriée peut mimer un authentique sus-décalage ischémique."},{"t":"Il doit systématiquement faire différer toute évaluation cardiologique en l'absence de troponine élevée","ok":false,"why":"C'est l'inverse : devant une douleur persistante avec bloc de branche gauche, l'évaluation cardiologique doit être rapide sans attendre le dosage de troponine."},{"t":"Sa signification dépend fortement de la présentation clinique associée","ok":true,"why":"En présence d'un bloc de branche gauche, la clinique prend une importance cruciale pour l'interprétation de la repolarisation."}],"explanation":"md La discordance appropriée du bloc de branche gauche peut mimer un authentique sus-décalage ischémique ; la clinique devient alors déterminante."},"reveal":"md Devant la persistance de la douleur, le cardiologue de garde est appelé sans délai.","src":"p. 381"},{"id":"231-case-03-s03","phase":2,"narrative":"md Le cardiologue examine le patient : douleur constrictive inchangée, non sensible à un test à la trinitrine, pas de signe de choc.","question":{"type":"QRU","stem":"Quelle est la conduite recommandée par le chapitre devant une douleur thoracique persistante avec bloc de branche gauche, avant même le résultat de la troponine ?","options":[{"t":"Attendre le résultat de la troponine avant toute évaluation spécialisée","ok":false,"why":"C'est justement ce qu'il ne faut pas faire : l'évaluation cardiologique doit être rapide sans attendre ce dosage."},{"t":"Évoquer un possible infarctus antérieur et faire évaluer rapidement le patient par un cardiologue, en recherchant des arguments cliniques et échographiques complémentaires","ok":true,"why":"C'est la conduite recommandée : évaluation rapide, analyse sémiologique de la douleur, réponse à la trinitrine, recherche de signes de choc, échocardiographie."},{"t":"Rassurer le patient car le bloc de branche gauche est connu et ancien","ok":false,"why":"Le caractère ancien du bloc ne permet pas d'éliminer un authentique infarctus en cours."},{"t":"Réaliser uniquement une surveillance scope sans autre exploration","ok":false,"why":"Insuffisant devant une douleur persistante avec ce trouble de conduction."},{"t":"Différer toute prise en charge de 24 heures pour un nouvel ECG de contrôle","ok":false,"why":"Le contexte impose une évaluation rapide, pas un délai de 24 heures."}],"explanation":"md Devant une douleur thoracique persistante avec bloc de branche gauche, il faut évoquer un infarctus antérieur et faire évaluer le patient en urgence par un cardiologue, sans attendre la troponine."},"reveal":"md Une échographie cardiaque est réalisée au lit du patient.","src":"p. 381"},{"id":"231-case-03-s04","phase":2,"narrative":"md L'échocardiographie retrouve un trouble de la cinétique segmentaire antérieur, absent sur un examen antérieur.","question":{"type":"QROC","question":"Quels éléments cliniques, en dehors de l'imagerie, peuvent aider à distinguer un authentique syndrome coronarien aigu chez ce patient porteur de bloc de branche gauche ?","answer":"L'analyse sémiologique de la douleur (caractère, effet de la trinitrine) et la recherche de signes de choc","accept":["semiologie de la douleur et signes de choc","effet de la trinitrine et signes de choc"],"keywords":["trinitrine","signes de choc","sémiologie"],"explanation":"md Le chapitre insiste sur l'analyse sémiologique de la douleur, dont l'effet de la trinitrine, et la recherche de signes de choc pour orienter le diagnostic dans ce contexte difficile."},"reveal":"md Devant ce faisceau d'arguments, le patient est pris en charge comme un syndrome coronarien aigu.","src":"p. 381"},{"id":"231-case-03-s05","phase":3,"narrative":"md Le patient est transféré en urgence en salle de coronarographie, en dehors de tout nouveau détail médicamenteux précisé ici.","question":{"type":"QRM","stem":"Parmi les cinq étiologies classiques d'un sus-décalage du segment ST citées dans ce chapitre, lesquelles sont exactes ?","options":[{"t":"Syndrome coronarien aigu avec sus-décalage du ST","ok":true,"why":"C'est la première étiologie citée, avec une image en miroir typique (onde de Pardee)."},{"t":"Anévrisme ventriculaire","ok":true,"why":"Le sus-décalage peut persister après un infarctus en cas de séquelle marquée avec anévrisme."},{"t":"Repolarisation précoce","ok":true,"why":"Sus-décalage bénin dans les dérivations inféro-latérales, notamment chez le sujet jeune."},{"t":"Angor de Prinzmetal","ok":true,"why":"Spasme coronarien pouvant donner un sus-décalage ressemblant à celui du SCA."},{"t":"Hypertrophie atriale gauche","ok":false,"why":"N'est pas citée parmi les cinq étiologies du sus-décalage de ST ; c'est un diagnostic différentiel portant sur l'onde P, pas le segment ST."}],"explanation":"md Les cinq étiologies citées sont le SCA avec sus-décalage, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite."},"reveal":"md La coronarographie retrouve une occlusion coronaire, traitée en urgence par le cardiologue interventionnel.","src":"p. 412"},{"id":"231-case-03-s06","phase":4,"narrative":"md Quelques jours plus tard, un ECG de contrôle montre un sus-décalage résiduel persistant en antérieur, alors que le patient est asymptomatique.","question":{"type":"QRU","stem":"Quelle explication est la plus probable devant ce sus-décalage résiduel persistant, asymptomatique, après un infarctus antérieur étendu ?","options":[{"t":"Récidive ischémique silencieuse systématique","ok":false,"why":"N'est pas l'explication retenue pour un sus-décalage résiduel chronique asymptomatique."},{"t":"Anévrisme ventriculaire sur séquelle d'infarctus marquée","ok":true,"why":"Le sus-décalage peut persister indéfiniment lorsque la séquelle d'infarctus entraîne un anévrisme de la paroi ventriculaire."},{"t":"Nouvelle péricardite aiguë associée","ok":false,"why":"Le sus-décalage de la péricardite est diffus et concave, non systématisé au territoire infarci comme ici."},{"t":"Artéfact technique sans signification","ok":false,"why":"Le chapitre décrit une explication physiopathologique précise pour ce tableau, pas un simple artéfact."},{"t":"Repolarisation précoce apparue secondairement","ok":false,"why":"N'est pas cohérent avec le contexte de séquelle d'infarctus étendu."}],"explanation":"md Un sus-décalage persistant après un infarctus avec séquelle marquée évoque un anévrisme ventriculaire."},"reveal":"md Une surveillance cardiologique régulière est organisée, avec réévaluation de la fonction ventriculaire gauche.","src":"p. 412"},{"id":"231-case-03-s07","phase":5,"narrative":"md Un an plus tard, le patient est stable, sans récidive douloureuse. L'ECG de suivi reste inchangé.","question":{"type":"QROC","question":"Quel type de dispositif serait à discuter si ce bloc de branche gauche s'accompagnait secondairement de signes d'insuffisance cardiaque liés à une désynchronisation ventriculaire ?","answer":"Une resynchronisation cardiaque","accept":["resynchronisation","stimulation biventriculaire"],"keywords":["resynchronisation"],"explanation":"md Un bloc de branche gauche complet peut contribuer à une désynchronisation des parois ventriculaires ; sa correction par resynchronisation cardiaque est indiquée en cas de signes d'insuffisance cardiaque associés."},"reveal":"md Le patient reste pour l'instant sans indication de resynchronisation, sa fonction ventriculaire étant stable au dernier contrôle.","src":"p. 383"},{"id":"231-case-03-s08","phase":5,"narrative":"md Lors d'une consultation ultérieure, M. Costa demande pourquoi il fallait absolument faire un ECG 18 dérivations lors de son passage aux urgences, alors que son bloc de branche gauche compliquait déjà l'interprétation.","question":{"type":"QROC","question":"Quelle anomalie postérieure pourrait passer inaperçue sur un ECG 12 dérivations standard devant une douleur thoracique, justifiant des dérivations supplémentaires ?","answer":"Un sus-décalage de ST en territoire postérieur (V7-V9), qui se traduit en miroir par un sous-décalage en V1-V3","accept":["infarctus posterieur avec miroir anterieur","sus decalage v7 v9"],"keywords":["V7","V8","V9","miroir"],"explanation":"md Un sous-décalage en antérieur (V1-V3) peut être le simple miroir d'un sus-décalage postérieur (V7-V9), ce qui justifie de réaliser un ECG 18 dérivations devant toute douleur thoracique."},"reveal":"md L'équipe confirme que ce complément n'a finalement pas été nécessaire dans son cas, l'atteinte antérieure étant déjà évidente.","src":"p. 411"},{"id":"231-case-03-s09","phase":5,"narrative":"md Le patient s'interroge également sur la surveillance rythmique qui lui a été proposée après sa sortie, en dehors de tout traitement médicamenteux détaillé ici.","question":{"type":"QRU","stem":"Quel examen, décrit dans ce chapitre, permettrait de détecter d'éventuelles salves de tachycardie ventriculaire asymptomatiques après un infarctus étendu ?","options":[{"t":"Un enregistrement Holter de 24 heures","ok":true,"why":"L'enregistrement Holter de 24 heures est utilisé pour évaluer le risque rythmique en détectant des salves de tachycardie ventriculaire asymptomatiques après infarctus."},{"t":"Une échographie transthoracique isolée","ok":false,"why":"L'échographie évalue la fonction et la cinétique, pas directement le risque rythmique."},{"t":"Un massage sino-carotidien","ok":false,"why":"Cette manœuvre sert à explorer une tachycardie ou une dysfonction sinusale, pas à dépister des salves de TV."},{"t":"Une radiographie thoracique de contrôle","ok":false,"why":"N'apporte pas d'information rythmique."},{"t":"Un dosage isolé de la troponine à distance","ok":false,"why":"N'a pas d'utilité pour dépister un trouble du rythme asymptomatique à distance."}],"explanation":"md Le Holter de 24 heures permet notamment d'évaluer le risque rythmique après un infarctus, en recherchant des salves de tachycardie ventriculaire asymptomatiques."},"reveal":"md Un Holter de contrôle est programmé à distance, sans anomalie majeure retrouvée.","src":"p. 415"},{"id":"231-case-03-s10","phase":5,"narrative":"md Deux ans après l'épisode initial, M. Costa reste asymptomatique et poursuit un suivi cardiologique régulier.","question":{"type":"QRM","stem":"Quels éléments de ce dossier illustrent la difficulté d'interpréter un ECG en présence d'un bloc de branche gauche ?","options":[{"t":"La discordance appropriée pouvant mimer un sus-décalage ischémique","ok":true,"why":"C'est le piège central illustré par ce dossier."},{"t":"La nécessité de s'appuyer davantage sur la clinique et l'échographie que sur le seul tracé","ok":true,"why":"Le chapitre insiste sur l'importance de la présentation clinique dans ce contexte."},{"t":"L'impossibilité totale de jamais diagnostiquer un infarctus chez un patient porteur de bloc de branche gauche","ok":false,"why":"Le diagnostic reste possible, mais nécessite une démarche clinique et paraclinique adaptée, pas une impossibilité totale."},{"t":"Le fait qu'un bloc de branche gauche complet ancien puisse rendre l'analyse de la repolarisation antérieure peu fiable","ok":true,"why":"C'est explicitement souligné dans le chapitre concernant l'interprétation du territoire antérieur en présence d'un BBG."},{"t":"Le fait que la troponine devienne totalement inutile dans ce contexte","ok":false,"why":"La troponine garde son utilité, simplement son résultat ne doit pas être attendu avant l'évaluation initiale."}],"explanation":"md Ce dossier illustre le piège de la discordance appropriée, l'importance de la clinique et de l'échographie, et la difficulté persistante d'analyser la repolarisation antérieure en présence d'un bloc de branche gauche."},"reveal":"md Le dossier de M. Costa est clôturé, avec un dernier rappel sur la vigilance à conserver devant toute nouvelle douleur thoracique.","src":"p. 381"}]},{"id":"231-case-51","title":"Mme B., 71 ans, palpitations régulières depuis la veille","rank":"A","summary":"Tachycardie régulière à QRS fins à 150 bpm : démarche diagnostique, manœuvres vagales, reconnaissance d'un flutter atrial typique et de sa conduction ventriculaire, puis documentation de palpitations épisodiques.","difficulty":2,"timeline":["Accueil","ECG initial","BAV transitoire","Diagnostic","Évolution","Suivi"],"steps":[{"phase":0,"narrative":"Mme B., 71 ans, consulte aux urgences pour des palpitations régulières et rapides apparues la veille. Elle est consciente, PA 125/75 mmHg, sans signe d'insuffisance cardiaque.","question":{"type":"QRM","stem":"Concernant l'enregistrement ECG dans ce contexte, quelles propositions sont exactes ?","options":[{"t":"Les palpitations sont une indication d'ECG 12 dérivations.","ok":true,"why":"Les palpitations figurent parmi les symptômes justifiant un ECG conventionnel."},{"t":"Un monitorage ECG continu est indiqué aux urgences.","ok":true,"why":"Toute urgence relève d'un monitorage par cardioscope."},{"t":"Les électrodes précordiales doivent être équidistantes.","ok":true,"why":"C'est la règle de placement rappelée par le cours."},{"t":"V1 et V2 doivent être placées en regard des foyers auscultatoires aortique et pulmonaire.","ok":false,"why":"C'est l'erreur classique (V1-V2 trop hautes et écartées), source de pseudonécrose ou d'atypie de repolarisation antérieure."},{"t":"L'ECG peut être différé à une consultation de cardiologie programmée.","ok":false,"why":"Des palpitations aux urgences imposent un ECG immédiat."}],"explanation":"Palpitations = indication d'ECG 12 dérivations, et toute urgence justifie un monitorage. Les précordiales doivent être équidistantes, en évitant de placer V1-V2 trop haut."},"reveal":"Un monitorage est installé et un ECG 12 dérivations est enregistré.","src":"p. 371, 414","id":"231-case-51-s01"},{"phase":1,"narrative":"L'ECG montre une tachycardie régulière à 150 bpm, à QRS fins (90 ms). L'activité atriale n'est pas clairement analysable.","question":{"type":"QRU","stem":"Selon l'algorithme devant une tachycardie, à quelle origine rattachez-vous cette tachycardie ?","options":[{"t":"Supraventriculaire","ok":true,"why":"Une tachycardie régulière à QRS fins est supraventriculaire."},{"t":"Ventriculaire jusqu'à preuve du contraire","ok":false,"why":"Cette règle s'applique aux tachycardies régulières à QRS larges."},{"t":"Fibrillation atriale","ok":false,"why":"La FA donne une tachycardie irrégulière."},{"t":"Fibrillation ventriculaire","ok":false,"why":"La FV est une tachycardie irrégulière à QRS larges polymorphes avec perte de connaissance."},{"t":"Bloc atrioventriculaire","ok":false,"why":"Un BAV donne une bradycardie, pas une tachycardie."}],"explanation":"Irrégulière → FA ; régulière à QRS larges → TV jusqu'à preuve du contraire ; régulière à QRS fins → supraventriculaire."},"reveal":"Il s'agit d'une tachycardie supraventriculaire dont le mécanisme reste à préciser.","src":"p. 389, 405","id":"231-case-51-s02"},{"phase":1,"narrative":"Vous discutez les hypothèses diagnostiques.","question":{"type":"QRM","stem":"Quels diagnostics évoquez-vous devant cette tachycardie régulière à QRS fins à 150 bpm ?","options":[{"t":"Tachycardie sinusale","ok":true,"why":"Diagnostic différentiel à évoquer : la manœuvre vagale peut démasquer une activité sinusale (au repos, sans cause d'hypermétabolisme, elle est toutefois peu probable)."},{"t":"Flutter atrial conduit en 2/1","ok":true,"why":"Le flutter donne classiquement une fréquence ventriculaire de 150 bpm en 2/1."},{"t":"Tachycardie jonctionnelle","ok":true,"why":"Tachycardie très régulière, autour de 200 bpm (130-260) : 150 bpm est compatible."},{"t":"Tachycardie atriale focale","ok":true,"why":"Tachycardie régulière à QRS fins, faisant partie des TSV."},{"t":"Fibrillation ventriculaire","ok":false,"why":"La FV est irrégulière à QRS larges et entraîne un arrêt cardiaque."}],"explanation":"Devant une tachycardie régulière à QRS fins, on discute tachycardie sinusale, flutter, TAF et tachycardie jonctionnelle ; la manœuvre vagale aide à trancher."},"reveal":"La patiente étant stable, vous décidez de créer un bloc atrioventriculaire transitoire.","src":"p. 389-396, 405","id":"231-case-51-s03"},{"phase":2,"narrative":"Avant la manœuvre, vous auscultez les carotides : pas de souffle.","question":{"type":"QRM","stem":"Concernant les manœuvres vagales, quelles propositions sont exactes ?","options":[{"t":"La manœuvre de Valsalva est une expiration forcée à glotte fermée.","ok":true,"why":"C'est la définition donnée par le cours."},{"t":"La compression carotidienne doit être unilatérale.","ok":true,"why":"Le cours décrit une compression carotidienne unilatérale."},{"t":"La compression carotidienne est contre-indiquée en cas de souffle carotidien ou d'athérome important.","ok":true,"why":"Ce sont les contre-indications citées."},{"t":"Boire un grand verre d'eau froide est une manœuvre vagale possible.","ok":true,"why":"Elle figure parmi les manœuvres vagales citées."},{"t":"La compression oculaire bilatérale est la manœuvre recommandée en 1re intention.","ok":false,"why":"Elle n'est plus recommandée (risque de décollement de rétine chez le myope)."}],"explanation":"Manœuvres vagales : Valsalva, compression carotidienne unilatérale (hors athérome ou souffle), grand verre d'eau froide ; la compression oculaire n'est plus recommandée."},"reveal":"La manœuvre de Valsalva ralentit transitoirement la fréquence ventriculaire.","src":"p. 390","id":"231-case-51-s04"},{"phase":2,"narrative":"Vous envisagez l'adénosine si une nouvelle manœuvre est nécessaire.","question":{"type":"QRU","stem":"Parmi les antécédents suivants, lequel contre-indiquerait l'adénosine IV chez cette patiente ?","options":[{"t":"Un asthme","ok":true,"why":"L'asthme contre-indique l'adénosine (bronchospasme intense transitoire possible)."},{"t":"Une hypercholestérolémie traitée","ok":false,"why":"Ce n'est pas une contre-indication citée (asthme, hypotension, FA préexcitée)."},{"t":"Une hypothyroïdie substituée","ok":false,"why":"Ce n'est pas une contre-indication citée."},{"t":"Une cataracte opérée","ok":false,"why":"Ce n'est pas une contre-indication citée."},{"t":"Un âge supérieur à 70 ans","ok":false,"why":"L'âge n'est pas une contre-indication citée."}],"explanation":"L'adénosine, injectée en flash IV avec un effet d'une dizaine de secondes, est contre-indiquée en cas d'asthme, d'hypotension et de FA préexcitée."},"reveal":"Aucune contre-indication n'est retrouvée, mais la manœuvre vagale a suffi à démasquer l'activité atriale.","src":"p. 390","id":"231-case-51-s05"},{"phase":3,"narrative":"Pendant le ralentissement, on observe une activité atriale monomorphe à 300/min, en dents de scie, sans retour à la ligne isoélectrique en D2, D3 et aVF.","question":{"type":"QROC","question":"Quel est votre diagnostic ?","answer":"Flutter atrial","accept":["flutter","flutter auriculaire"],"keywords":["flutter"],"explanation":"Activité atriale monomorphe vers 300 bpm, sans retour à la ligne isoélectrique, en toit d'usine / dents de scie, démasquée par la manœuvre vagale : flutter atrial."},"reveal":"Le diagnostic de flutter atrial est retenu.","src":"p. 393-394","id":"231-case-51-s06"},{"phase":3,"narrative":"Les ondes F sont négatives en D2, D3 et aVF, positives en V1 et négatives en V6.","question":{"type":"QRU","stem":"De quel type de flutter s'agit-il ?","options":[{"t":"Flutter typique (commun) antihoraire","ok":true,"why":"F négatives en D2, D3, aVF, positives en V1, négatives en V6 = flutter typique antihoraire."},{"t":"Flutter typique horaire","ok":false,"why":"Dans la forme horaire, les polarités sont inversées."},{"t":"Flutter atypique gauche","ok":false,"why":"Les flutters atypiques ont des ondes F variables et une fréquence de 120 à 320 bpm."},{"t":"Tachycardie atriale focale","ok":false,"why":"La TAF comporte un retour à la ligne de base entre les P dans toutes les dérivations."},{"t":"Tachycardie jonctionnelle par réentrée intranodale","ok":false,"why":"Elle serait réduite par la manœuvre vagale, sans démasquer d'ondes F."}],"explanation":"Le flutter typique antihoraire emprunte l'isthme cavotricuspide : F négatives en inférieur, positives en V1, négatives en V6."},"reveal":"Il s'agit d'un flutter d'aspect typique antihoraire.","src":"p. 394","id":"231-case-51-s07"},{"phase":3,"narrative":"Vous confrontez la fréquence atriale (300/min) et la fréquence ventriculaire initiale (150 bpm).","question":{"type":"QROC","question":"Quel rapport de conduction atrioventriculaire explique cette fréquence ventriculaire ?","answer":"Conduction 2/1","accept":["2/1","2 pour 1","deux pour un"],"keywords":["2/1"],"explanation":"Le ventricule bat classiquement à 150 bpm en 2/1, 100 bpm en 3/1, 75 bpm en 4/1, grâce au filtre du NAV."},"reveal":"Le flutter était conduit en 2/1.","src":"p. 389, 394","id":"231-case-51-s08"},{"phase":4,"narrative":"Sous traitement ralentisseur, un nouvel ECG montre des ondes F persistantes à 300/min, avec une fréquence ventriculaire devenue irrégulière.","question":{"type":"QRU","stem":"Comment interprétez-vous cette irrégularité ventriculaire ?","options":[{"t":"Flutter à conduction variable","ok":true,"why":"Le flutter est régulier le plus souvent, sinon à conduction variable (alternance 2/1-3/1…)."},{"t":"Transformation en fibrillation ventriculaire","ok":false,"why":"La FV donne des QRS larges polymorphes avec arrêt cardiaque."},{"t":"Tachycardie ventriculaire","ok":false,"why":"Les QRS restent fins et l'activité atriale organisée persiste."},{"t":"BAV du 3e degré","ok":false,"why":"Un BAV complet associé à une arythmie atriale donne un rythme ventriculaire lent et régulier."},{"t":"Extrasystoles ventriculaires","ok":false,"why":"Elles donneraient des QRS larges prématurés."}],"explanation":"Selon la fréquence atriale et l'intensité du filtre nodal (âge, tonus vagal, ralentisseurs), la conduction peut devenir variable, rendant le rythme ventriculaire irrégulier."},"reveal":"La fréquence ventriculaire est contrôlée ; la prise en charge spécialisée est organisée.","src":"p. 389, 394","id":"231-case-51-s09"},{"phase":5,"narrative":"Plusieurs mois plus tard, en rythme sinusal, Mme B. décrit des palpitations brèves survenant de façon épisodique. L'ECG de repos est normal.","question":{"type":"QRM","stem":"Quels moyens de documentation sont adaptés ?","options":[{"t":"Holter ECG de 24 à 96 h si les symptômes ont une probabilité de récidiver pendant l'enregistrement","ok":true,"why":"C'est l'indication du Holter quand l'ECG standard n'a rien montré."},{"t":"ECG ambulatoire de très longue durée (jusqu'à 21 jours) si les symptômes sont rares","ok":true,"why":"Indiqué en cas de symptômes rares."},{"t":"Enregistreur d'événements, y compris une montre connectée ECG","ok":true,"why":"Ces outils sont très utiles pour documenter des palpitations peu fréquentes."},{"t":"Répéter un ECG de repos, qui suffit toujours à conclure","ok":false,"why":"L'ECG standard n'a rien montré : il faut un enregistrement de longue durée."},{"t":"Hospitalisation systématique en réanimation sous monitorage","ok":false,"why":"Ce n'est pas une indication citée du monitorage pour des palpitations épisodiques bien tolérées."}],"explanation":"Symptômes épisodiques avec ECG normal : Holter 24-96 h ; symptômes rares : ECG ambulatoire jusqu'à 21 jours, enregistreurs d'événements ou objets connectés."},"reveal":"Un Holter est programmé et la patiente est éduquée à l'enregistrement de ses symptômes.","src":"p. 415","id":"231-case-51-s10"}]}],"ecg":{"data":[{"id":"231-ecg-01","title":"ECG normal de l'adulte","rank":"A","objective":"231-obj-01","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tracé normal de repos, repolarisation physiologique."},"findings":["Rythme sinusal régulier à 72/min (onde P positive en D1, D2, D3, aVF, une P avant chaque QRS et un QRS après chaque P)","Onde P de durée et d'amplitude normales","PR constant à 160 ms (120-200 ms)","QRS fins à 80 ms, axe normal autour de 60°","Ondes T positives dans toutes les dérivations sauf en aVR","QT/QTc dans les limites de la normale (< 450 ms)"],"diagnosis":"ECG normal","teaching":"**Méthode de lecture systématique (à appliquer à chaque ECG) :**\n1. *Rythme* : sinusal si onde P positive en D1/D2/D3/aVF, une P avant chaque QRS et un QRS après chaque P, fréquence 60-100/min.\n2. *Conduction* : durée de P < 120 ms, PR entre 120 et 200 ms, QRS fins entre 70 et 110 ms avec un axe entre -30° et +90°.\n3. *Repolarisation* : point J et segment ST isoélectriques, ondes T positives sauf en aVR (et parfois V1, D3, aVL), QT < 450 ms.\n4. *Morphologie* : amplitude des ondes P et des QRS normales (indice de Sokolow < 35 mm), transition de l'onde R normale de V1 à V6, absence d'onde Q de nécrose (> 1/3 du QRS et > 40 ms).\n\n**Piège classique** : chez le sujet jeune, un léger sus-décalage du point J de V1 à V4 avec pente ascendante (repolarisation précoce physiologique) ne doit pas être pris pour une anomalie.","quiz":{"stem":"Quelle est la conclusion de cet ECG ?","options":["ECG normal","Bloc atrioventriculaire du 1er degré","Hypertrophie ventriculaire gauche","Bloc de branche droit incomplet"],"correct":0},"src":"p. 376-378"},{"id":"231-ecg-02","title":"Bloc atrioventriculaire du 1er degré","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":66,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.24,"avBlock":"1","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement fixe et constant du PR, sans onde P bloquée."},"findings":["Rythme sinusal régulier","Chaque onde P est suivie d'un QRS (conduction 1/1)","PR allongé et constant à 240 ms (> 200 ms)","QRS fins, morphologie normale par ailleurs","Aucune onde P bloquée"],"diagnosis":"Bloc atrioventriculaire du 1er degré","teaching":"**Définition** : ralentissement de la conduction atrioventriculaire sans interruption — toutes les ondes P sont conduites, mais avec un PR fixe et allongé (> 200 ms).\n\n**Diagnostic différentiel** : à distinguer d'un BAV du 2e degré Mobitz 1 (allongement progressif du PR puis onde P bloquée).\n\n**Conduite à tenir** : généralement bénin et asymptomatique ; rechercher un contexte de bradycardie fonctionnelle (sportif) ou un traitement ralentisseur du NAV. Surveillance simple en l'absence de bloc de branche associé.","quiz":{"stem":"Quel est le mécanisme du bloc atrioventriculaire du premier degré ?","options":["Un ralentissement de la conduction atrioventriculaire sans blocage complet","Un blocage intermittent d'une onde P sur deux","Une dissociation complète entre oreillettes et ventricules","Un allongement progressif du PR jusqu'à une onde P bloquée"],"correct":0},"src":"p. 385-386"},{"id":"231-ecg-03","title":"Bloc atrioventriculaire du 2e degré, Mobitz 1 (Wenckebach)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":60,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.18,"avBlock":"2m1","ratio":"3:2","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement progressif du PR à chaque cycle jusqu'à une onde P bloquée, puis reprise du cycle (périodicité de Wenckebach)."},"findings":["Rythme atrial sinusal régulier","Allongement progressif du PR d'un battement à l'autre","Une onde P bloquée termine la séquence (non suivie de QRS)","QRS fins, cycle qui se répète de façon périodique","Rythme ventriculaire irrégulier du fait des ondes P bloquées"],"diagnosis":"Bloc atrioventriculaire du 2e degré, Mobitz 1 (Luciani-Wenckebach)","teaching":"**Critères** : allongement progressif du PR jusqu'à une onde P bloquée, puis reprise du cycle avec un PR redevenu court.\n\n**Localisation** : le plus souvent suprahissien (nodal), de meilleur pronostic que le Mobitz 2.\n\n**Conduite à tenir** : pacemaker seulement si bradycardie symptomatique ; sinon simple surveillance.","quiz":{"stem":"Quel signe caractérise le bloc atrioventriculaire du 2e degré Mobitz 1 ?","options":["Un allongement progressif du PR avant l'onde P bloquée","Un PR constant puis une onde P bloquée inopinée","Une onde P bloquée sur deux de façon fixe","Une dissociation atrioventriculaire complète"],"correct":0},"src":"p. 385-386"},{"id":"231-ecg-04","title":"Bloc atrioventriculaire du 2e degré, Mobitz 2 (infrahissien)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":55,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"2m2","ratio":"3:2","qrs":{"dur":0.13,"bbb":"rbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"PR constant puis onde P bloquée inopinée, QRS larges évoquant une atteinte infrahissienne."},"findings":["Rythme atrial sinusal régulier","PR constant sur les battements conduits","Onde P bloquée inopinée, sans allongement préalable du PR","QRS larges (atteinte infrahissienne associée)","Risque évolutif vers le bloc atrioventriculaire complet"],"diagnosis":"Bloc atrioventriculaire du 2e degré, Mobitz 2","teaching":"**Critères** : PR fixe puis blocage brutal d'une onde P sans allongement préalable ; souvent associé à des QRS larges (atteinte infrahissienne).\n\n**Pronostic** : à haut risque de bloc atrioventriculaire complet.\n\n**Conduite à tenir** : indication de pacemaker même en l'absence de symptôme.","quiz":{"stem":"Quelle caractéristique oriente vers un Mobitz 2 plutôt qu'un Mobitz 1 ?","options":["Un PR constant avant l'onde P bloquée","Un allongement progressif du PR","Une fréquence atriale irrégulière","L'absence totale d'onde P"],"correct":0},"src":"p. 385-386"},{"id":"231-ecg-05","title":"Bloc atrioventriculaire complet (3e degré)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":38,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"3","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Dissociation atrioventriculaire complète : ondes P régulières indépendantes des QRS ; échappement jonctionnel à QRS fins, régulier et lent."},"findings":["Ondes P régulières à fréquence normale, sans relation avec les QRS (dissociation atrioventriculaire)","QRS fins, réguliers et lents (échappement jonctionnel nodal)","Fréquence ventriculaire basse, autour de 40/min","Plus d'ondes P que de QRS","Aucune amélioration de la fréquence à l'effort"],"diagnosis":"Bloc atrioventriculaire complet (3e degré) à QRS fins","teaching":"**Critères** : dissociation atrioventriculaire complète, ondes P régulières indépendantes des QRS, échappement jonctionnel (QRS fins) ou ventriculaire (QRS larges, plus lent, moins stable).\n\n**Diagnostic différentiel** : à ne pas confondre avec la dissociation par tachycardie ventriculaire (ici bradycardie).\n\n**Conduite à tenir** : indication de pacemaker, même en l'absence de symptôme.","quiz":{"stem":"Quel élément affirme le diagnostic de bloc atrioventriculaire complet ?","options":["Une dissociation complète entre ondes P régulières et QRS","Un allongement progressif du PR","Une onde P bloquée sur deux de façon fixe","Un PR court avec onde delta"],"correct":0},"src":"p. 387"},{"id":"231-ecg-06","title":"Bloc de branche droit complet","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":78,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.14,"bbb":"rbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":1.6,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Aspect RsR' en V1, onde S traînante et arrondie en V6."},"findings":["Rythme sinusal régulier","Durée du QRS > 120 ms","Aspect RsR' en V1 (QRS globalement positif)","Onde S empâtée et arrondie en V6","Discordance appropriée : onde T négative en V1"],"diagnosis":"Bloc de branche droit complet","teaching":"**Critères** : QRS > 120 ms, aspect RsR' en V1 (QRS globalement positif), aspect qRs avec onde S traînante en V6.\n\n**Méthode** : vérifier d'abord le rythme atrial, puis la durée du QRS, puis la polarité en V1 (positive = droit), puis l'aspect inverse en V6.\n\n**Piège** : la discordance appropriée entre QRS et repolarisation (onde T négative si QRS positif) ne doit pas être confondue avec une ischémie.","quiz":{"stem":"Quel aspect en V1 oriente vers un bloc de branche droit complet ?","options":["QRS globalement positif avec aspect RsR'","QRS globalement négatif avec aspect rS","Onde delta avec PR court","Sus-décalage concave diffus du ST"],"correct":0},"src":"p. 379"},{"id":"231-ecg-07","title":"Bloc de branche gauche complet","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":80,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.15,"bbb":"lbbb","lvh":false,"rvh":false,"delta":false,"axis":-10,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"V1":1,"V2":1},"dep":{},"shape":"concave"},"t":{"inverted":["I","aVL","V5","V6"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"QRS globalement négatif en V1 (rS ou QS), notch en V6/D1/aVL avec onde R exclusive ; discordance appropriée ST/T."},"findings":["Rythme sinusal régulier","Durée du QRS > 120 ms","QRS globalement négatif en V1 (aspect rS ou QS)","Notch (double pic) en V6, D1 et aVL avec onde R exclusive","Discordance appropriée : sus-décalage de ST en V1-V2, onde T négative en D1/aVL/V5/V6"],"diagnosis":"Bloc de branche gauche complet","teaching":"**Critères** : QRS > 120 ms, QRS négatif en V1, notch en V6/D1/aVL.\n\n**Piège majeur** : la discordance appropriée (ST ascendant en V1-V2) peut simuler un syndrome coronarien aigu avec sus-décalage du ST. Devant une douleur thoracique persistante avec BBG, il faut évoquer un infarctus antérieur et demander un avis cardiologique rapide sans attendre la troponine.\n\n**Conséquence hémodynamique** : un BBG complet désynchronise la contraction ventriculaire gauche et peut créer ou aggraver une insuffisance cardiaque, justifiant une resynchronisation cardiaque si l'insuffisance cardiaque apparaît.","quiz":{"stem":"Devant une douleur thoracique persistante avec un bloc de branche gauche complet, que faut-il faire ?","options":["Évoquer un infarctus et demander un avis cardiologique rapide sans attendre la troponine","Éliminer d'emblée le diagnostic de syndrome coronarien car le BBG masque tout","Attendre le résultat de la troponine avant toute décision","Considérer ce tracé comme un équivalent de péricardite aiguë"],"correct":0},"src":"p. 380-381"},{"id":"231-ecg-08","title":"Hémibloc antérieur gauche","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":74,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.11,"bbb":"lahb","lvh":false,"rvh":false,"delta":false,"axis":-60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Déviation axiale gauche au-delà de -30°, négativité de DII."},"findings":["Rythme sinusal régulier","Élargissement modéré du QRS (autour de 110 ms)","Déviation axiale gauche au-delà de -30° (négativité de DII et DIII)","Absence d'autre cause de déviation axiale gauche"],"diagnosis":"Hémibloc antérieur gauche","teaching":"**Critères** : élargissement modéré du QRS et déviation axiale gauche au-delà de -30° (négativité de DII).\n\n**Fréquence** : c'est l'hémibloc le plus fréquent car la branche antérieure gauche est fine et superficielle, donc fragile.\n\n**Valeur** : isolé, il traduit une atteinte débutante du réseau de conduction avec un faible risque de bloc atrioventriculaire infrahissien.","quiz":{"stem":"Quel signe définit l'hémibloc antérieur gauche ?","options":["Une déviation axiale gauche au-delà de -30° avec négativité de DII","Un QRS globalement positif en V1","Un PR court avec onde delta","Une onde P bloquée sur deux"],"correct":0},"src":"p. 382"},{"id":"231-ecg-09","title":"Bloc bifasciculaire (hémibloc antérieur gauche + bloc de branche droit)","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.13,"bbb":"bifascicular","lvh":false,"rvh":false,"delta":false,"axis":-60,"qWaves":[],"lowVoltage":false,"rsRatioV1":1.5,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Association d'un axe hypergauche (HBAG) et d'un aspect RsR' en V1 (BBD)."},"findings":["Rythme sinusal régulier","QRS > 120 ms","Axe hypergauche avec négativité en DII, DIII, aVF (hémibloc antérieur gauche)","Aspect RsR' en V1 (bloc de branche droit complet)"],"diagnosis":"Bloc bifasciculaire (hémibloc antérieur gauche + bloc de branche droit)","teaching":"**Sémiologie** : addition des critères de l'hémibloc et du bloc de branche droit.\n\n**Risque** : atteinte de deux des trois fascicules, avec un risque non négligeable de bloc atrioventriculaire complet infrahissien intermittent, pouvant se manifester par des syncopes voire une mort subite.\n\n**Conduite à tenir** : toute syncope associée à un bloc bifasciculaire impose une hospitalisation en cardiologie avec télémétrie.","quiz":{"stem":"Que faut-il faire devant une syncope associée à un bloc bifasciculaire ?","options":["Hospitaliser en cardiologie sous télémétrie","Rassurer et renvoyer le patient à domicile","Prescrire un traitement bêtabloquant en urgence","Réaliser uniquement un holter en ambulatoire différé"],"correct":0},"src":"p. 383"},{"id":"231-ecg-10","title":"Dysfonction sinusale (pause par bloc sino-atrial)","rank":"A","objective":"231-obj-10","ecg":{"rhythm":"sinusBrady","rate":46,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":2.0,"pacer":{"mode":"none"},"notes":"Pause correspondant au double de l'intervalle PP/RR normal, par manque intermittent d'une onde P (bloc sino-atrial du 2e degré)."},"findings":["Bradycardie sinusale de base","Pause avec absence complète d'un complexe P-QRS-T","La pause correspond au double de l'intervalle PP habituel","Reprise ensuite d'un rythme sinusal normal","Peut évoluer vers un échappement jonctionnel si la pause se prolonge"],"diagnosis":"Dysfonction sinusale (bloc sino-atrial du 2e degré)","teaching":"**Mécanismes** : ondes P trop lentes, onde P manquante isolée (bloc sino-atrial), pause sinusale, ou onde P inexistante remplacée par une activité rétrograde (échappement jonctionnel).\n\n**Piège devant une bradycardie** : regarder les ondes P — si elles sont régulières à fréquence normale (ou tachycardes comme en FA/flutter) avec plus d'ondes P que de QRS, le problème est le passage au ventricule (BAV) ; si les ondes P sont trop lentes ou absentes, le problème vient du nœud sinusal.\n\n**Conduite à tenir** : pacemaker si bradycardie symptomatique.","quiz":{"stem":"Devant une bradycardie, quel élément oriente vers une dysfonction sinusale plutôt qu'un bloc atrioventriculaire ?","options":["Des ondes P trop lentes ou absentes","Plus d'ondes P que de QRS à fréquence atriale normale","Un PR court avec onde delta","Un QRS large en dents de scie"],"correct":0},"src":"p. 387-389"},{"id":"231-ecg-11","title":"Fibrillation atriale","rank":"A","objective":"231-obj-13","ecg":{"rhythm":"af","rate":128,"irregular":true,"p":{"present":false,"amp":0.05,"dur":0.0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.0,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Trémulation ou mailles anarchiques de la ligne de base, intervalles RR irrégulièrement irréguliers."},"findings":["Absence d'onde P, activité atriale anarchique (mailles amples ou fine trémulation)","Intervalles RR irrégulièrement irréguliers (non multiples d'une valeur commune)","QRS fins en l'absence de bloc de branche associé","Fréquence ventriculaire entre 100 et 200/min","Aucune relation constante entre activité atriale et QRS"],"diagnosis":"Fibrillation atriale","teaching":"**Critères** : tachycardie irrégulière à QRS fins (sauf bloc de branche associé), sans onde P identifiable.\n\n**Formes particulières** : association à un bloc atrioventriculaire complet (activité ventriculaire devenant lente et régulière), alternance avec une dysfonction sinusale (« maladie de l'oreillette »), ou association à un bloc de branche fonctionnel donnant une tachycardie irrégulière à QRS larges.\n\n**Conduite à tenir** : la fibrillation atriale est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins.","quiz":{"stem":"Quel est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins ?","options":["La fibrillation atriale","Le flutter atrial","La tachycardie jonctionnelle","La tachycardie ventriculaire"],"correct":0},"src":"p. 391-393"},{"id":"231-ecg-12","title":"Flutter atrial typique (antihoraire)","rank":"A","objective":"231-obj-14","ecg":{"rhythm":"flutter","rate":150,"irregular":false,"p":{"present":true,"amp":0.1,"dur":0.0,"inverted":["II","III","aVF"],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"2:1","ratio":"2:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Ondes F en dents de scie à ~300/min, négatives en II/III/aVF, positives en V1, sans retour à la ligne isoélectrique."},"findings":["Activité atriale monomorphe rapide, environ 300/min (ondes F)","Aspect en dents de scie, négatif en II, III, aVF, positif en V1, négatif en V6","Absence de retour à la ligne isoélectrique entre les ondes F","Conduction atrioventriculaire le plus souvent 2/1, donnant une cadence ventriculaire régulière à 150/min","Activité atriale démasquée par une manœuvre vagale"],"diagnosis":"Flutter atrial typique (antihoraire)","teaching":"**Mécanisme** : réentrée autour de l'isthme cavotricuspide, activation atriale organisée en circuit (par opposition au caractère fibrillatoire de la FA).\n\n**Cadence ventriculaire** : le plus souvent 150/min (conduction 2/1), parfois 100/min (3/1) ou à conduction variable.\n\n**Diagnostic** : les manœuvres vagales ou l'adénosine, en bloquant transitoirement le NAV, démasquent les ondes F sans arrêter le flutter (le circuit ne dépend pas du NAV).","quiz":{"stem":"Quel est l'effet d'une manœuvre vagale sur un flutter atrial ?","options":["Elle démasque l'activité atriale sans arrêter l'arythmie","Elle arrête définitivement le flutter","Elle n'a strictement aucun effet visible","Elle transforme le flutter en tachycardie ventriculaire"],"correct":0},"src":"p. 393-395"},{"id":"231-ecg-13","title":"Tachycardie jonctionnelle par réentrée intranodale (maladie de Bouveret)","rank":"A","objective":"231-obj-15","ecg":{"rhythm":"svt","rate":190,"irregular":false,"p":{"present":false,"amp":0.0,"dur":0.0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Activité atriale non visible ou devinée dans le segment ST, activation atriale et ventriculaire quasi synchrone."},"findings":["Tachycardie très régulière à QRS fins, autour de 190/min","Absence d'onde P visible (activation atriale rétrograde quasi synchrone du QRS)","Début et fin brusques, non progressifs","Réduction par manœuvres vagales ou adénosine IV"],"diagnosis":"Tachycardie jonctionnelle par réentrée intranodale","teaching":"**Mécanisme** : réentrée au sein du nœud atrioventriculaire ; activation atriale et ventriculaire quasi synchrone, d'où une onde P invisible ou devinée dans le segment ST (maladie de Bouveret).\n\n**Diagnostic différentiel** : l'autre forme est la tachycardie par rythme réciproque, réentrée par une voie accessoire (faisceau de Kent).\n\n**Conduite à tenir** : manœuvres vagales ou adénosine IV en première intention, efficaces car la réentrée dépend du NAV.","quiz":{"stem":"Pourquoi l'adénosine est-elle efficace pour arrêter une tachycardie jonctionnelle par réentrée intranodale ?","options":["Parce que la réentrée dépend du nœud atrioventriculaire, qu'elle bloque transitoirement","Parce qu'elle a un effet inotrope négatif puissant","Parce qu'elle dépolarise directement le foyer atrial","Parce qu'elle accélère la conduction dans la voie accessoire"],"correct":0},"src":"p. 395-397"},{"id":"231-ecg-14","title":"Extrasystoles ventriculaires","rank":"A","objective":"231-obj-17","ecg":{"rhythm":"sinus","rate":70,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"pvc","every":6,"bigeminy":false,"run":1},"pause":0,"pacer":{"mode":"none"},"notes":"Battement prématuré à QRS large, non précédé d'onde P, suivi d'une pause compensatrice."},"findings":["Rythme de fond sinusal régulier","Battement prématuré à QRS large, non précédé d'une onde P","Pause compensatrice après l'extrasystole","Morphologie du QRS différente de celle du rythme de base","Onde T souvent de polarité opposée au QRS de l'extrasystole"],"diagnosis":"Extrasystoles ventriculaires","teaching":"**Définition** : activation prématurée par rapport au rythme attendu ; fréquentes et physiologiques sur cœur sain, leur charge augmentant avec l'âge et les cardiopathies.\n\n**Diagnostic différentiel** : extrasystole atriale (onde P prématurée puis QRS fin) et extrasystole jonctionnelle (QRS fin ± onde P' rétrograde), toutes deux à QRS fins, contrairement à l'extrasystole ventriculaire (QRS large).\n\n**Conduite à tenir** : des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie sous-jacente.","quiz":{"stem":"Quel critère distingue une extrasystole ventriculaire d'une extrasystole atriale ?","options":["Un QRS large non précédé d'une onde P","Une onde P prématurée suivie d'un QRS fin","Un PR progressivement allongé","Une fréquence cardiaque supérieure à 150/min"],"correct":0},"src":"p. 397-398"},{"id":"231-ecg-15","title":"Tachycardie ventriculaire monomorphe","rank":"A","objective":"231-obj-18","ecg":{"rhythm":"vt","rate":180,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.16,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":-100,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Dissociation ventriculo-atriale, complexes de fusion/capture, concordance des précordiales, axe extrême."},"findings":["Tachycardie régulière à QRS larges (> 120 ms), autour de 180/min","Dissociation ventriculo-atriale (plus de QRS que d'ondes P)","Complexes de fusion et de capture intercalés dans le tracé","Axe extrême avec positivité exclusive en aVR","Cardiopathie sous-jacente fréquemment retrouvée"],"diagnosis":"Tachycardie ventriculaire monomorphe","teaching":"**Règle d'or** : toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.\n\n**Arguments de certitude** : dissociation ventriculo-atriale, complexes de capture (QRS fin précédé d'une onde P) ou de fusion (QRS intermédiaire).\n\n**Arguments en faveur** : cardiopathie sous-jacente, concordance positive ou négative de V1 à V6, déviation axiale extrême (positivité en aVR), morphologie différente d'un bloc de branche habituel.\n\n**Conduite à tenir** : urgence — alerter (SAMU), se préparer à une réanimation ; distinguer TV non soutenue (≤ 30 s) de TV soutenue (> 30 s).","quiz":{"stem":"Face à une tachycardie régulière à QRS larges, quelle est l'attitude par défaut ?","options":["La considérer comme une tachycardie ventriculaire jusqu'à preuve du contraire","L'attribuer d'emblée à une tachycardie supraventriculaire avec bloc de branche","Réaliser un massage sino-carotidien immédiat sans surveillance","Attendre le résultat de la troponine avant toute décision"],"correct":0},"src":"p. 398-402"},{"id":"231-ecg-16","title":"Fibrillation ventriculaire","rank":"A","objective":"231-obj-19","ecg":{"rhythm":"vf","rate":280,"irregular":true,"p":{"present":false,"amp":0,"dur":0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.2,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tracé totalement anarchique, oscillations de taille et de forme variables, sans QRS identifiable."},"findings":["Activité ventriculaire totalement anarchique","Absence de QRS, de segment ST et d'onde T identifiables","Oscillations de taille et de forme variables (larges puis fines)","Absence d'activité mécanique efficace : arrêt cardiocirculatoire"],"diagnosis":"Fibrillation ventriculaire","teaching":"**Reconnaissance** : tracé anarchique sans complexe identifiable, urgence absolue.\n\n**Conduite à tenir** : cardioversion électrique (choc électrique) immédiate avant tout autre geste, massage cardiaque en attendant le choc.\n\n**Diagnostic différentiel** : parfois indiscernable d'une torsade de pointes installée ; seuls le QT long préalable et le contexte (ischémie/cardiopathie évoluée pour la FV) permettent de trancher.","quiz":{"stem":"Quelle est la conduite à tenir immédiate devant une fibrillation ventriculaire ?","options":["Cardioversion électrique immédiate et massage cardiaque en attendant le choc","Manœuvre vagale puis adénosine IV","Surveillance scope sans geste immédiat","Correction ionique puis réévaluation à 24 heures"],"correct":0},"src":"p. 402-403"},{"id":"231-ecg-17","title":"Torsades de pointes sur QT long","rank":"B","objective":"231-obj-20","ecg":{"rhythm":"torsades","rate":220,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.54,"u":true,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tachycardie ventriculaire polymorphe avec torsion des QRS autour de la ligne isoélectrique, survenant sur un QT long."},"findings":["QT long avant le trouble du rythme (souvent > 500 ms)","Tachycardie ventriculaire polymorphe à QRS d'amplitude et de polarité variables","Aspect de torsion des QRS autour de la ligne isoélectrique","Peut s'arrêter spontanément ou dégénérer en fibrillation ventriculaire","Rechercher une hypokaliémie, une hypocalcémie, une hypomagnésémie ou un médicament allongeant le QT"],"diagnosis":"Torsades de pointes","teaching":"**Reconnaissance** : forme particulière de tachycardie ventriculaire polymorphe, parfois indiscernable d'une fibrillation ventriculaire une fois installée ; seuls le QT long préexistant et le contexte orientent le diagnostic.\n\n**Étiologies** : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, médicaments allongeant le QT, syndrome du QT long congénital.\n\n**Conduite à tenir** : corriger les troubles ioniques, accélérer la fréquence cardiaque, arrêter les médicaments allongeant le QT.","quiz":{"stem":"Quel élément permet de différencier une torsade de pointes d'une fibrillation ventriculaire ?","options":["La présence d'un QT long avant le trouble du rythme et le contexte clinique","La largeur du QRS pendant l'arythmie","La fréquence cardiaque pendant l'arythmie","La présence d'ondes P visibles pendant l'arythmie"],"correct":0},"src":"p. 403-404"},{"id":"231-ecg-18","title":"Hyperkaliémie","rank":"A","objective":"231-obj-21","ecg":{"rhythm":"sinusBrady","rate":52,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.24,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.14,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":[],"peaked":true,"flat":false,"amp":0.9},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Ondes T amples, pointues et symétriques ; allongement du PR ; élargissement du QRS ; risque de BAV, TV, dysfonction sinusale."},"findings":["Ondes T amples, pointues et symétriques (« en tente »)","Allongement de l'intervalle PR","Élargissement progressif du QRS","Bradycardie ou dysfonction sinusale possible","Risque de bloc atrioventriculaire ou de tachycardie ventriculaire"],"diagnosis":"Hyperkaliémie","teaching":"**Signes ECG (par ordre d'apparition avec l'aggravation)** : ondes T amples, pointues et symétriques ; allongement du PR ; élargissement du QRS ; puis bloc atrioventriculaire, tachycardie ventriculaire ou dysfonction sinusale.\n\n**Conduite à tenir** : toute anomalie évocatrice impose un contrôle urgent de la kaliémie et un traitement adapté (risque de trouble du rythme grave).","quiz":{"stem":"Quel est le signe ECG le plus précoce de l'hyperkaliémie ?","options":["Des ondes T amples, pointues et symétriques","Un allongement isolé du QT","Une onde U proéminente","Un sus-décalage diffus du segment ST"],"correct":0},"src":"p. 408-409"},{"id":"231-ecg-19","title":"Hypokaliémie","rank":"A","objective":"231-obj-21","ecg":{"rhythm":"sinus","rate":82,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{"V2":0.5,"V3":0.5},"shape":"horizontal"},"t":{"inverted":[],"peaked":false,"flat":true,"amp":0.1},"qt":0.48,"u":true,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Onde T plate ou négative diffuse, sous-décalage de ST, allongement du QT et onde U."},"findings":["Onde T plate ou négative, de façon diffuse","Sous-décalage du segment ST","QRS de durée normale","Allongement de l'intervalle QT","Apparition d'une onde U (à ne pas inclure dans la mesure du QT)"],"diagnosis":"Hypokaliémie","teaching":"**Signes ECG** : onde T plate ou négative diffuse avec sous-décalage de ST, QRS normal, allongement du QT et apparition d'une onde U.\n\n**Risque rythmique** : extrasystoles, tachycardie ventriculaire, torsades de pointes, fibrillation ventriculaire.\n\n**Conduite à tenir** : correction de la kaliémie, recherche et traitement de la cause.","quiz":{"stem":"Quelle onde supplémentaire peut apparaître en cas d'hypokaliémie, sans devoir être incluse dans la mesure du QT ?","options":["L'onde U","L'onde delta","L'onde F","L'onde Q pathologique"],"correct":0},"src":"p. 408"},{"id":"231-ecg-20","title":"Allongement de l'intervalle QT","rank":"A","objective":"231-obj-22","ecg":{"rhythm":"sinus","rate":64,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.52,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement isolé du QT, à corréler au contexte médicamenteux, ionique ou génétique."},"findings":["Rythme sinusal régulier","QT corrigé nettement allongé (> 480-500 ms)","QRS et PR de durée normale","Absence d'anomalie ionique visible sur ce tracé isolé","Rechercher une cause médicamenteuse, ionique (hypokaliémie, hypocalcémie, hypomagnésémie) ou génétique"],"diagnosis":"Allongement de l'intervalle QT","teaching":"**Mesure** : du début du Q à la fin de l'onde T, dans la dérivation où l'onde T est la plus ample (souvent V2-V3), corrigé par la formule de Bazett pour une fréquence de 60/min.\n\n**Étiologies** : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, médicaments allongeant le QT, syndrome du QT long congénital.\n\n**Conduite à tenir** : tout QT allongé impose de vérifier les traitements en cours et le ionogramme, afin de prévenir le risque de torsades de pointes et de mort subite.","quiz":{"stem":"Quelle formule est utilisée pour corriger le QT en fonction de la fréquence cardiaque ?","options":["La formule de Bazett","L'indice de Sokolow","La règle des grands carreaux","La formule de Wenckebach"],"correct":0},"src":"p. 404"},{"id":"231-ecg-21","title":"Péricardite aiguë (stade 1)","rank":"B","objective":"231-obj-23","ecg":{"rhythm":"sinus","rate":92,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":true,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"I":1,"II":1.5,"III":1,"aVF":1,"V5":1.5,"V6":1.5},"dep":{},"shape":"concave"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":true,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sus-décalage diffus concave vers le haut, sans image en miroir, sous-décalage du segment PQ, microvoltage possible."},"findings":["Sus-décalage du segment ST diffus, concave vers le haut, concordant","Absence d'image en miroir","Sous-décalage du segment PQ (PR)","Microvoltage possible, d'autant plus marqué que l'épanchement est abondant","Absence de territoire coronaire systématisé"],"diagnosis":"Péricardite aiguë (stade 1)","teaching":"**Évolution en 4 phases** : phase 1 (sus-décalage diffus concave sans miroir, sous-décalage de PQ, microvoltage), phase 2 (onde T plate, ST isoélectrique), phase 3 (onde T négative persistante), phase 4 (retour à la normale).\n\n**Piège** : ne pas conclure à tort à une péricardite devant un syndrome coronarien aigu avec sus-décalage de ST, car l'image en miroir peut manquer dans les deux cas ; le caractère diffus, concave et concordant, avec sous-décalage de PQ, oriente vers la péricardite.","quiz":{"stem":"Quel aspect du segment ST évoque une péricardite aiguë au stade initial ?","options":["Un sus-décalage diffus, concave vers le haut, sans image en miroir","Un sus-décalage localisé, convexe, avec miroir net","Un sous-décalage horizontal localisé","Une onde de Pardee systématisée à un territoire"],"correct":0},"src":"p. 409-410"},{"id":"231-ecg-22","title":"Syndrome coronarien aigu avec sus-décalage du ST (territoire inférieur)","rank":"A","objective":"231-obj-24","ecg":{"rhythm":"sinus","rate":88,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":["III"],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"II":3,"III":3.5,"aVF":3},"dep":{"I":1,"aVL":1},"shape":"convex"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sus-décalage convexe englobant l'onde T (onde de Pardee) dans le territoire inférieur, miroir en D1-aVL."},"findings":["Sus-décalage du segment ST ≥ 1 mm sur au moins 2 dérivations inférieures adjacentes (II, III, aVF)","Sus-décalage convexe englobant l'onde T (onde de Pardee)","Image en miroir en D1 et aVL (sous-décalage)","Onde Q de nécrose débutante possible en D3","Territoire inférieur : occlusion probable de la coronaire droite"],"diagnosis":"Syndrome coronarien aigu avec sus-décalage du ST (territoire inférieur)","teaching":"**Critères de sus-décalage significatif** : au moins 2 mm en V1-V3, au moins 1 mm dans les autres dérivations, sur au moins 2 dérivations adjacentes.\n\n**Méthode** : traquer d'abord le sus-décalage (qui indique le territoire occlus), puis chercher le miroir sous forme de sous-décalage, jamais l'inverse.\n\n**Ondes Q de nécrose** : apparaissent en général vers la 6e heure, mais peuvent être précoces ; leur présence ne doit pas faire renoncer à une reperfusion jugée utile.\n\n**Diagnostics différentiels du sus-décalage** : anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite, bloc de branche gauche, hypertrophie ventriculaire gauche marquée.","quiz":{"stem":"Quelle est la démarche correcte pour interpréter un sus-décalage du ST évocateur de SCA ?","options":["Repérer le sus-décalage qui indique le territoire occlus, puis chercher le miroir sous forme de sous-décalage","Repérer d'abord le sous-décalage puis en déduire le territoire occlus","Ignorer le miroir car il est toujours présent","Considérer que l'absence de miroir élimine le diagnostic"],"correct":0},"src":"p. 411-412"},{"id":"231-ecg-23","title":"Syndrome coronarien aigu sans sus-décalage du ST","rank":"A","objective":"231-obj-24","ecg":{"rhythm":"sinus","rate":94,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{"V4":1.5,"V5":2,"V6":1.5},"shape":"horizontal"},"t":{"inverted":["V4","V5","V6"],"peaked":false,"flat":false,"amp":0.2},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sous-décalage horizontal antérolatéral avec ondes T négatives ; un ECG normal n'élimine pas le diagnostic."},"findings":["Sous-décalage du segment ST horizontal dans le territoire antérolatéral","Ondes T négatives associées possibles","QRS fins, durée normale","Absence de sus-décalage du segment ST","Un ECG strictement normal n'élimine pas le diagnostic"],"diagnosis":"Syndrome coronarien aigu sans sus-décalage du ST","teaching":"**Aspects possibles** : sous-décalage de ST (lésion sous-endocardique), inversion des ondes T (ischémie sous-épicardique), pseudo-normalisation d'ondes T antérieurement négatives, aplatissement des ondes T, ou ECG normal.\n\n**Piège** : les anomalies peuvent être masquées par un pacemaker.\n\n**Conduite à tenir** : un ECG strictement normal ne permet jamais d'éliminer un syndrome coronarien aigu ; le diagnostic repose sur la clinique et la biologie (troponine).","quiz":{"stem":"Un ECG parfaitement normal permet-il d'éliminer un syndrome coronarien aigu sans sus-décalage du ST ?","options":["Non, un ECG normal est possible dans ce cadre","Oui, cela élimine formellement le diagnostic","Seulement si la fréquence cardiaque est basse","Seulement chez le sujet jeune"],"correct":0},"src":"p. 412-413"},{"id":"231-ecg-24","title":"Préexcitation ventriculaire (Wolff-Parkinson-White)","rank":"B","objective":"231-obj-25","ecg":{"rhythm":"wpw","rate":76,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.1,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.12,"bbb":"none","lvh":false,"rvh":false,"delta":true,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["V1","V2"],"peaked":false,"flat":false,"amp":0.2},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"PR court, empâtement du pied du QRS (onde delta), anomalies de repolarisation dans le territoire de la voie accessoire."},"findings":["PR court (< 120 ms)","Empâtement du pied du QRS (onde delta)","QRS légèrement élargi","Anomalies de repolarisation dans le territoire de la voie accessoire","Risque de tachycardie jonctionnelle par réentrée sur la voie accessoire"],"diagnosis":"Préexcitation ventriculaire (syndrome de Wolff-Parkinson-White si symptomatique)","teaching":"**Mécanisme** : une voie accessoire (faisceau de Kent) relie directement l'oreillette au ventricule, en compétition avec le nœud atrioventriculaire, entraînant une préexcitation.\n\n**Diagnostic** : PR court, onde delta, anomalies de repolarisation associées.\n\n**Danger** : en cas de fibrillation atriale associée, la voie accessoire (dépourvue de propriété décrémentielle) peut conduire très rapidement aux ventricules, donnant une tachycardie irrégulière à QRS larges « en accordéon », à haut risque de fibrillation ventriculaire (« super-Wolff »). L'adénosine et le blocage du NAV sont contre-indiqués en cas de FA sur voie accessoire.","quiz":{"stem":"Quel est le risque particulier d'une fibrillation atriale chez un patient porteur d'un Wolff-Parkinson-White ?","options":["Une conduction très rapide par la voie accessoire pouvant dégénérer en fibrillation ventriculaire","Un ralentissement bénéfique de la conduction par la voie accessoire","Un bloc atrioventriculaire complet immédiat","Aucun risque particulier par rapport à une FA habituelle"],"correct":0},"src":"p. 410-411"},{"id":"231-ecg-25","title":"Rythme électro-entraîné (pacemaker) ventriculaire","rank":"B","objective":"231-obj-26","ecg":{"rhythm":"paced","rate":70,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.16,"bbb":"lbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"VVI"},"notes":"Spike de stimulation pathognomonique précédant chaque QRS ; aspect de bloc de branche gauche du fait de la stimulation ventriculaire droite."},"findings":["Spike de stimulation (très bref, 0,4 à 1 ms) précédant chaque QRS","QRS larges avec aspect de bloc de branche gauche (stimulation ventriculaire droite)","Rythme régulier imposé par le boîtier","Absence d'onde P propre visible avant le spike en mode ventriculaire seul","Fréquence proche de la fréquence programmée du boîtier"],"diagnosis":"Rythme électro-entraîné (pacemaker) ventriculaire","teaching":"**Reconnaissance** : le spike de stimulation est pathognomonique car il n'existe rien de physiologique d'aussi bref sur un ECG.\n\n**En cas de dysfonction sinusale** : le pacemaker stimule l'oreillette (onde P après le spike).\n\n**En cas de BAV** : le pacemaker écoute l'oreillette et stimule le ventricule après un délai AV programmé (QRS large après le spike, aspect de bloc de branche gauche car la stimulation ventriculaire droite se propage de proche en proche).\n\n**Piège** : les anomalies ischémiques peuvent être masquées par la stimulation.","quiz":{"stem":"Pourquoi un QRS stimulé par un pacemaker ventriculaire droit a-t-il un aspect de bloc de branche gauche ?","options":["Parce que la stimulation ventriculaire droite se propage lentement de proche en proche vers le ventricule gauche","Parce que le pacemaker stimule simultanément les deux ventricules","Parce que le nœud atrioventriculaire est systématiquement détruit","Parce que la sonde est toujours positionnée dans le ventricule gauche"],"correct":0},"src":"p. 413-414"},{"id":"231-ecg-26","title":"Hypertrophie ventriculaire gauche","rank":"A","objective":"231-obj-05","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.1,"bbb":"none","lvh":true,"rvh":false,"delta":false,"axis":-15,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.15,"pathologicR":[]},"st":{"elev":{"V1":1,"V2":1},"dep":{},"shape":"normal"},"t":{"inverted":["I","aVL","V6"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Indice de Sokolow (S en V1/V2 + R en V5/V6) à 40 mm, très au-delà du seuil de 35 mm ; déviation axiale gauche modeste ; pseudo sus-décalage de ST en V1-V2 (piège de pseudonécrose) ; onde T négative en D1, aVL, V6 par anomalie secondaire de la repolarisation."},"findings":["Rythme sinusal régulier","Grande amplitude des QRS en précordiales : indice de Sokolow (S en V1/V2 + R en V5/V6) nettement supérieur à 35 mm","Déviation axiale gauche modeste","QRS le plus souvent inférieur à 120 ms malgré la masse myocardique augmentée","Onde T négative et sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6)","Pseudo sus-décalage du ST et aspect QS trompeur possibles en V1-V2"],"diagnosis":"Hypertrophie ventriculaire gauche avec anomalies secondaires de la repolarisation","teaching":"**Diagnostic** : l'indice de Sokolow (amplitude de l'onde S en V1 ou V2 additionnée à celle de l'onde R en V5 ou V6) est l'indice le plus utilisé, normal en dessous de 35 mm.\n\n**Forme sévère** : onde T négative souvent associée à un sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6), par anomalie secondaire de la repolarisation, avec disparition de l'onde Q septale physiologique dans ces mêmes dérivations. La déviation axiale est modeste, vers la gauche ; les QRS peuvent être un peu élargis du fait de la masse myocardique et de la fibrose intramyocardique, mais restent le plus souvent inférieurs à 120 ms.\n\n**Piège** : une HVG électrique importante peut donner en V1-V2 un aspect QS mimant une séquelle de nécrose (pseudonécrose) et/ou un pseudo sus-décalage du segment ST.\n\n**Étiologies** : l'hypertension artérielle est la plus fréquente, suivie du rétrécissement aortique.","quiz":{"stem":"Quel indice ECG permet de retenir le diagnostic d'hypertrophie ventriculaire gauche ?","options":["L'indice de Sokolow (S en V1/V2 + R en V5/V6), supérieur à 35 mm","L'aspect S1Q3T3","Le sous-décalage du segment PQ","L'allongement isolé du QT"],"correct":0},"src":"p. 406-407"}],"method":"**Démarche systématique de lecture d'un ECG (à appliquer dans cet ordre) :**\n\n1. **Fréquence** : rapide (FC = 300 / nombre de grands carreaux séparant deux QRS) ; distinguer bradycardie (< 60/min) et tachycardie (> 100/min).\n2. **Rythme** : déterminer s'il est sinusal (onde P positive en D1/D2/D3/aVF, une P avant chaque QRS, un QRS après chaque P) ou non.\n3. **Conduction** : mesurer les intervalles PR (120-200 ms), la durée du QRS (70-110 ms) et le QT (corrigé par la formule de Bazett), et déterminer l'axe du QRS (polarité de D1 et aVF pour situer le cadran).\n4. **En cas de bradycardie** : regarder les ondes P — si elles sont régulières à fréquence normale (ou tachycardes comme en FA/flutter) avec plus d'ondes P que de QRS, le problème est le passage au ventricule (bloc atrioventriculaire) ; si elles sont trop lentes ou absentes, le problème vient du nœud sinusal (dysfonction sinusale).\n5. **En cas de bloc de branche** : le diagnostic repose sur la durée du QRS et la polarité en V1 (globalement positif = droit, globalement négatif = gauche) ; le diagnostic d'hémibloc repose sur l'axe du QRS. Les blocs de branche isolés ne donnent pas de bradycardie.\n6. **En cas de tachycardie** : examiner la largeur des QRS (fins ou larges) et la régularité, puis s'aider le plus souvent des manœuvres vagales ou de l'adénosine IV (bloc atrioventriculaire transitoire) pour démasquer l'activité atriale ou arrêter une tachycardie dépendante du NAV. La fibrillation atriale est le seul diagnostic possible devant une tachycardie complètement irrégulière à QRS fins ; toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire, et ne doit jamais être confondue avec un simple bloc de branche.\n7. **Repolarisation** : analyser le segment ST (isoélectrique en dehors des dérivations aVR/V1) et les ondes T (positives partout sauf en aVR, parfois V1/D3/aVL) ; traquer un sus-décalage pour localiser un territoire occlus, puis chercher le miroir (sous-décalage) — jamais l'inverse.\n8. **Morphologie** : amplitude des ondes P et des QRS (indice de Sokolow < 35 mm), transition normale de l'onde R de V1 à V6, absence d'onde Q de nécrose (> 1/3 du QRS et > 40 ms)."},"echo":{"data":[]},"flash":{"id":"231-ff","sections":[{"key":"identite","title":"Carte d'identité flash","src":"p. 375-377, 406","fields":[{"label":"Définition / seuil chiffré","value":"25 mm/s : 1 mm = 40 ms, grand carreau = 200 ms ; FC 60-100/min (= 300 / nb de grands carreaux) · P < 120 ms · **PR 120-200 ms** · **QRS 70-110 ms** · axe −30° à +90° · QTc (Bazett) < 450 ms · Sokolow (S V1/V2 + R V5/V6) < 35 mm"},{"label":"Lecture systématique en 4 temps","value":"Être **systématique** : rythme (sinusal : P + en D1-D2, QRS après chaque P, P avant chaque QRS) → conduction (PR, QRS, axe) → repolarisation (ST isoélectrique, T + sauf aVR/V1, QT sans onde U) → morphologie (Sokolow, transition V1-V6, pas de Q de nécrose)"}]},{"key":"pattern","title":"Le pattern de reconnaissance","src":"p. 374-375, 378-386, 399-400, 405-406","fields":[{"label":"Dérivations & territoires (où regarder)","value":"Antéroseptal V1-V3 · apical V4 · latéral D1-aVL (haut), V5-V6 (bas) · inférieur D2-D3-aVF · postérieur V7-V9 · VD : V1-V2, V3R-V4R ; D1 + et aVF + = axe normal ; HVG sévère : T négatives + sous-ST latéraux (D1, aVL, V5-V6)"},{"label":"Triptyque : tachycardie > 100/min","value":"**Irrégulière** = FA (DD : ESA) · régulière à **QRS larges** = TV jusqu'à preuve du contraire (certitude : dissociation VA = plus de QRS que de P, captures, fusions) · régulière à QRS fins = supraventriculaire"},{"label":"Signe discriminant : blocs et BAV","value":"QRS > 120 ms : V1 positif (RsR') = **BBD**, négatif (rS/QS, notch D1-aVL-V6) = **BBG** · hémibloc : axe < −30° (HBAG, fréquent), > +90° (HBPG, rare) · BAV1 PR > 200 ms · Mobitz 1 PR ↑ puis P bloquée · Mobitz 2 PR fixe puis P bloquée · BAV3 dissociation AV"}]},{"key":"gravite","title":"Le tri vital & la gravité","src":"p. 398-399, 402-405, 408, 411-412","fields":[{"label":"Alerte rouge immédiate","value":"**FV** : tachycardie irrégulière à QRS larges polymorphes, perte de connaissance en secondes · **TV** : FC > 100, QRS > 120 ms, ≥ 3 battements (prémonitoire d'arrêt cardiaque) · sus-ST significatif · QT long (torsade) · hyperK : QRS large, BAV, TV"},{"label":"Sus-ST et Q : critères chiffrés, 5 causes","value":"Sus-ST significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes ; sous-ST V1-V3 : chercher V7-V9 (ECG 18D) ; Q de nécrose ≥ 1/3 du QRS et > 30-40 ms ; 5 causes : SCA, anévrisme, repolarisation précoce, Prinzmetal, péricardite"}]},{"key":"paraclinique","title":"Le paraclinique de certitude","src":"p. 373, 377, 381-383, 389, 392-395, 406, 411, 414","fields":[{"label":"1re intention en urgence (timing)","value":"**ECG 12D** si douleur thoracique, palpitations, dyspnée, malaise ou syncope, dyskaliémie/dyscalcémie ; obligatoire dans le bilan d'HTA ; préop > 65 ans ou à risque ; 18D devant toute douleur thoracique"},{"label":"Signes de certitude des rythmes","value":"Bradycardie : plus de P que de QRS = BAV ; P lentes/absentes = dysfonction sinusale · FA : 100-200/min, irrégulièrement irrégulière · flutter : F monomorphes ≈ 300/min **sans retour isoélectrique** (ventricules 150 = 2/1) · Bouveret : très régulière ≈ 200/min"},{"label":"Piège paraclinique à éviter","value":"V1-V2 trop hautes ou HVG (QS, pseudo sus-ST) → fausse nécrose ; D1 négatif = inversion des électrodes avant HBPG ; **BBG** : discordance appropriée ≠ SCA, mais douleur thoracique persistante → infarctus antérieur sans attendre la troponine ; U exclue du QT"}]},{"key":"orientation","title":"L'aiguillage clinique","src":"p. 376-377, 381, 383-384, 390-391, 397, 414","fields":[{"label":"Ambulatoire : rythmes sinusaux et variantes","value":"Tachycardie sinusale : P + en D1-D2-D3-aVF, FC variable (TSV : marches d'escalier) · athlète : bradycardie vagale · jeune homme : point J sus-décalé V1-V4 normal · ESA = P précoce + QRS fin, ESV = QRS large ; fréquentes ou polymorphes → chercher cardiopathie"},{"label":"Hospitalisation conventionnelle","value":"Syncope + bloc bifasciculaire (BBG complet, ou BBD + hémibloc) → **hospitalisation en cardiologie avec télémétrie** (risque de BAV complet infrahissien) ; BAV infrahissien (Mobitz 2, BAV3) → pacemaker même asymptomatique"},{"label":"USIC / soins intensifs / réanimation","value":"**Scope** : urgence, réanimation, transfert médicalisé ; USIC pour pathologie aiguë (SCA) ; syncope de cause rythmique suspectée ; per-op et salle de réveil ; certains exercices de réadaptation cardiaque"}]},{"key":"traitement","title":"Le pack thérapeutique de 1re intention","src":"p. 390, 399, 402, 404-405, 408","fields":[{"label":"Geste salvateur / conditionnement","value":"**FV** : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant ; suspicion de TV : alerter (15), préparer la réanimation ; tachycardie mal tolérée : cardioversion électrique externe"},{"label":"Molécule(s) reine(s) (DCI, voie, dose si cotée)","value":"Tachycardie bien tolérée : manœuvres vagales (Valsalva, compression carotidienne unilatérale, eau froide), puis **adénosine** IV en flash (effet ≈ 10 s) : démasque flutter/TAF/sinusale, arrête une jonctionnelle, sans effet sur une TV"},{"label":"Mesure non pharmacologique / étiologique","value":"QT long (médicaments, hypoK/hypoCa/hypoMg, bradycardie extrême, congénital) : corriger les ions, accélérer la FC, arrêter les médicaments ; hypoK : T plates, sous-ST, onde U ; **hyperK** : T amples pointues, PR long, QRS large"}]},{"key":"securite","title":"Les fautes graves & la sécurité","src":"p. 378, 381, 390, 398, 404, 409-411, 415","fields":[{"label":"Contre-indications absolues","value":"**Adénosine** : asthme, hypotension, FA préexcitée (super-Wolff) ; compression carotidienne : athérome important ou souffle carotidien ; compression oculaire bilatérale abandonnée (décollement de rétine du myope)"},{"label":"Fautes graves de lecture","value":"Décrire d'abord le rythme atrial (TSV + bloc de branche fréquents) ; QRS large : bloc de branche (sans conséquence immédiate) ≠ **TV** (mortelle) ; lésion ≠ miroir ; SCA ST+ sans miroir ≠ péricardite ; QT long : vérifier médicaments et ionogramme"}]}],"src":"p. 368-415"},"pareto":{"id":"231-pareto","points":[{"id":"231-par-01","rank":"A","cat":"examen","text":"Lecture systématique : **rythme** (P positive en D1-D2, QRS après chaque P) → **conduction** (PR, QRS, axe) → **repolarisation** (ST isoélectrique, T positive sauf aVR/V1, QT) → morphologie (Sokolow, pas de Q de nécrose)","src":"p. 377"},{"id":"231-par-02","rank":"A","cat":"chiffre","text":"ECG normal : FC **60-100**/min · P < 120 ms · PR **120-200 ms** · QRS **70-110 ms** · axe −30° à +90° · QTc < 450 ms · Sokolow < 35 mm · à 25 mm/s, 1 mm = 40 ms","src":"p. 375-377"},{"id":"231-par-03","rank":"A","cat":"clinique","text":"Tachycardie > 100/min : **irrégulière** = FA ; régulière à QRS **larges** = TV jusqu'à preuve du contraire ; régulière à QRS fins = supraventriculaire → manœuvres vagales puis adénosine","src":"p. 399, 405"},{"id":"231-par-04","rank":"A","cat":"gravité","text":"**TV** : FC > 100 + QRS > 120 ms sur ≥ 3 battements → alerter (15) ; mal tolérée = **cardioversion électrique** ; certitude : dissociation ventriculoatriale (plus de QRS que de P), captures, fusions","src":"p. 399-401, 405"},{"id":"231-par-05","rank":"A","cat":"gravité","text":"**FV** : tachycardie irrégulière à QRS larges polymorphes, perte de connaissance en quelques secondes → **choc électrique** immédiat, massage cardiaque en attendant","src":"p. 402-403"},{"id":"231-par-06","rank":"A","cat":"clinique","text":"QRS > 120 ms : V1 positif (RsR') = **BBD** ; V1 négatif (rS/QS) avec notch en V6/D1/aVL = **BBG** ; hémibloc : axe < −30° = HBAG (fréquent), > +90° = HBPG (rare)","src":"p. 378-382"},{"id":"231-par-07","rank":"A","cat":"clinique","text":"**BAV1** : PR > 200 ms · Mobitz 1 : PR s'allonge puis P bloquée · **Mobitz 2** : PR fixe puis P bloquée · **BAV3** : dissociation AV · bradycardie : plus de P que de QRS = BAV, P lentes ou absentes = dysfonction sinusale","src":"p. 385-389"},{"id":"231-par-08","rank":"A","cat":"clinique","text":"**FA** : QRS fins irrégulièrement irréguliers, 100-200/min, trémulation sans onde P · **flutter** : ondes F monomorphes ≈ 300/min **sans retour isoélectrique**, ventricules à 150/min (2/1)","src":"p. 392-394"},{"id":"231-par-09","rank":"A","cat":"traitement","text":"**Bouveret** (jonctionnelle) : très régulière ≈ 200/min, QRS fins, P souvent invisible ; réduite par manœuvres vagales ou **adénosine** IV (flash, effet ≈ 10 s ; contre-indiquée si asthme) · WPW : PR court + onde delta","src":"p. 390, 395-397, 410"},{"id":"231-par-10","rank":"A","cat":"clinique","text":"SCA ST+ : sus-décalage ≥ **2 mm** en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes ; chercher le miroir ; sous-décalage en V1-V3 → ECG **18 dérivations** (V7-V9) ; onde de Pardee","src":"p. 411-412"},{"id":"231-par-11","rank":"A","cat":"piège","text":"5 causes de sus-décalage du ST : SCA ST+, anévrisme ventriculaire, repolarisation précoce, **Prinzmetal**, **péricardite** (diffuse, concave, sans miroir) · BBG : discordance appropriée, pas de faux SCA","src":"p. 381, 412"},{"id":"231-par-12","rank":"A","cat":"gravité","text":"**Hypokaliémie** : T plate, sous-ST, onde U, QT long (torsades) · **hyperkaliémie** : T ample pointue symétrique, PR long, QRS large, BAV · QT long : vérifier médicaments et ionogramme","src":"p. 404, 408"},{"id":"231-par-13","rank":"A","cat":"clinique","text":"**HVG** : **Sokolow** = S V1/V2 + R V5/V6 (normal < 35 mm) ; forme sévère : T négative + sous-ST en D1, aVL, V5-V6 ; pseudonécrose possible en V1-V2 ; 1re cause : **HTA**","src":"p. 406-407"},{"id":"231-par-14","rank":"B","cat":"gravité","text":"Syncope + **bloc bifasciculaire** (BBG complet, BBD + hémibloc) → hospitalisation avec télémétrie ; BAV infrahissien (Mobitz 2, BAV3) → **pacemaker** même sans symptôme","src":"p. 383-385, 412"},{"id":"231-par-15","rank":"A","cat":"examen","text":"ECG 12D : douleur thoracique, palpitations, malaise/syncope, dyspnée, dyskaliémie/dyscalcémie ; obligatoire dans le bilan d'**HTA** ; préopératoire si > **65 ans** ; scope en urgence ou réanimation","src":"p. 368, 414"}]},"extra":{"semio":[{"title":"ECG normal : lecture systématique en 4 temps","rank":"A","content":"1. **Rythme** : sinusal — P **positive en D1, D2** (et en inférieur), un QRS après chaque P, une P avant chaque QRS ; FC **60–100 bpm**.\n2. **Conduction** : P < 120 ms, **PR 120–200 ms**, **QRS fins 70–110 ms**, axe **–30° à +90°** (positif en D1 et D2).\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale de V1 à V6 (R croît, S décroît — vérifie aussi la pose des électrodes), pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n> Chez le jeune, surtout l'homme, un **point J sus-décalé de V1 à V4** avec ST jonctionnel ascendant est une **repolarisation physiologique**.\n\n- Piège de pose : **V1-V2 trop hautes et trop écartées** → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.","src":"p. 371-378"},{"title":"Blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","content":"**Toujours décrire d'abord le rythme atrial** (TSV + bloc de branche : association non rare).\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| QRS | **> 120 ms** | **> 120 ms** |\n| V1 | globalement **positif**, **RsR'** | globalement **négatif**, **rS ou QS** |\n| V6 | **qRs**, S traînante arrondie | **notch** (double pic), R souvent exclusive (aussi D1, aVL) |\n\n- **Discordance appropriée** : T de polarité inverse du QRS ; dans le BBG, le ST ascendant en V1-V2 peut **mimer un SCA ST+**.\n- **Blocs incomplets** [B] : mêmes aspects, QRS **110–120 ms**. **Bloc fonctionnel** [B] : n'apparaît qu'en **tachycardie** ou en **bradycardie** (à partir d'une fréquence donnée).\n- **HBAG** (fréquent) : axe au-delà de **–30°**, **D2 négatif**. **HBPG** (rare) : axe > **+90°**, **D1 négatif**, aspect **S1Q3** (hors pathologie du VD, sujet longiligne, infarctus latéral).\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n\n> D1 négatif : penser d'abord à une **inversion des électrodes** (P négative en D1) avant l'HBPG.","src":"p. 378-385"},{"title":"Blocs atrioventriculaires et dysfonction sinusale","rank":"A","content":"Dans un BAV, les **ondes P sont régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| Mobitz 1 (Luciani-Wenckebach) | PR s'allonge progressivement puis P bloquée | **suprahissien** |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| Mobitz 2 | PR constant puis P bloquée inopinée | **infrahissien** |\n| BAV3 | dissociation AV complète (P bien vues en V1) | échappement à QRS fins = bloc **nodal** |\n\n> Une P « bloquée » plus précoce que les autres = **extrasystole atriale bloquée**.\n\n**Dysfonction sinusale**\n- **Asystole** (tracé plat) ; **pauses** = **BSA du 2e degré** [B] : pause = **double du PP (RR)**, sans P-QRS-T.\n- **Échappement jonctionnel** : pas de P devant le QRS, parfois P **rétrograde** dans le ST, **négative en D2**.\n- Aspects : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.","src":"p. 385-389"},{"title":"Tachycardies supraventriculaires et extrasystoles","rank":"A","content":"- QRS **fins (< 120 ms)** le plus souvent, larges si bloc de branche associé.\n- **Tachycardie sinusale** : P positives en **D1, D2, D3, aVF** ; FC **variant progressivement** (une TSV varie en **« marches d'escalier »**) ; au repos sans hypermétabolisme (fièvre, stress, douleur), une tachycardie marquée n'est pas sinusale.\n- **FA** : QRS **« irrégulièrement irréguliers »**, **100–200 bpm** ; ligne de base à **mailles amples** ou **fine trémulation**.\n  - [B] FA + **BAV complet** → rythme **lent et régulier** ; **maladie de l'oreillette** → alternance FA / bradycardie sinusale, **pauses de régularisation** ; FA + bloc de branche → tachycardie **irrégulière à QRS larges**.\n- **Flutter** : activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation, ondes **F en toit d'usine / dents de scie** ; ventricules classiquement à **150 bpm (2/1)**.\n  - **Typique antihoraire** : F **négatives en D2, D3, aVF**, **positives en V1**, **négatives en V6** (horaire : inversées).\n- **TAF** : la manœuvre vagale ou l'adénosine **démasque l'activité atriale** sans arrêter la tachycardie.\n- **Jonctionnelle (Bouveret)** : **très régulière**, ≈ **200 bpm** ; réentrée intranodale (P invisible ou devinée dans le ST) ou rythme réciproque par voie accessoire (faisceau de Kent).\n\n#### Extrasystoles\n- Activation **prématurée** d'une cavité ; fréquentes, physiologiques sur cœur sain. **Fréquentes ou polymorphes → rechercher une cardiopathie.**\n- **Atriale** : **P précoce de morphologie différente** puis **QRS fin** ; P parfois cachée dans la T précédente (dont elle modifie la polarité).\n- **Jonctionnelle** : QRS fin ± P' rétrograde ; rare (atteinte de la jonction nodohissienne).\n- **Ventriculaire** : **QRS large** ± P' rétrograde.\n- Répétitives : **doublets, triplets, salves**. Rythmées : **bigéminisme** (1 battement sur 2), **trigéminisme** (1 sur 3).","src":"p. 389-398"},{"title":"Troubles du rythme ventriculaire : TV, FV, torsades","rank":"A","content":"- QRS **larges** car naissance **sous la bifurcation hissienne** (conduction de proche en proche).\n- **TV** : **toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire**. Suspicion : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n  - **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P), complexes de **capture** (QRS fin précédé d'une P) et de **fusion**.\n  - **En faveur** : cardiopathie +++, **concordance** positive ou négative de V1 à V6, **axe extrême** (QRS positif en aVR), aspect atypique de bloc de branche.\n- **FV** : tachycardie **irrégulière à QRS larges polymorphes** ; perte de connaissance en quelques secondes, pouls carotidien aboli = **arrêt cardiaque**.\n- **Torsade de pointes** [B] : TV **polymorphe** sur **QT long préalable**, s'arrêtant spontanément ou dégénérant en FV ; possible à QT normal (2 ESV, la 2e sur la T de la 1re).","src":"p. 398-405"},{"title":"Hypertrophies atriales et ventriculaires","rank":"A","content":"- **HAD** [B] : P **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2**.\n- **HAG** [B] : P **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1**.\n- **HVG** : **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** ; forme sévère : **T négative ± sous-ST latéraux** (D1, aVL, V5, V6) et **disparition de la q septale** ; déviation axiale gauche modeste ; QRS le plus souvent **< 120 ms**.\n  - Pièges : **QS en V1-V2** (pseudonécrose), **pseudo sus-décalage du ST** en V1-V2.\n- **HVD** [B] : **axe > 110°** (90° en pratique, signe le plus précoce), **R > 6 mm en V1**, **S > 7 mm en V5-V6**, HAD, **microvoltage** (BPCO), BBD souvent associé ; T négative asymétrique en V1 dans les formes sévères.\n- **Embolie pulmonaire** : **S1Q3T3**, déviation axiale droite, FA possible.","src":"p. 406-408"},{"title":"Dyskaliémies, QT long, péricardite, préexcitation","rank":"A","content":"| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| T | **plate ou négative**, diffuse, **sous-ST** | **ample, pointue, symétrique** |\n| PR / QRS | – / normal | **PR allongé** / **QRS élargi** |\n| QT / U | **QT long**, **onde U** | – |\n| Rythme | ESV, TV, **torsade**, FV | **BAV**, TV, **dysfonction sinusale** |\n\n- **QT long** : risque de **torsade de pointes** (causes médicamenteuses, ioniques, bradycardie extrême, congénitale).\n- **Péricardite aiguë** [B], phase 1 : **microvoltage**, **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ**.\n- **Préexcitation** [B] : **PR court < 120 ms**, **onde delta** (empâtement du pied du QRS), troubles de repolarisation dans le territoire de la voie. En FA : tachycardie **irrégulière, très rapide, QRS de largeur variable « en accordéon »** (super-Wolff).","src":"p. 408-411"},{"title":"Maladie coronarienne et SCA à l'ECG","rank":"A","content":"- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → inférieur).\n- **SCA ST+** : traquer le **sus-décalage** (territoire de l'artère occluse) **puis** le **miroir**. Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes** ; englobant la T = **onde de Pardee**.\n- Sous-ST V1-V3 = possible miroir d'un sus-ST **postérieur (V7-V9)** → **ECG 18 dérivations**.\n- **Onde Q de nécrose** : ≥ 1/3 (ou 1/4) du QRS et > 30–40 ms, vers la **6e heure** ; équivalent : **rabotage de l'onde R** (V2-V3).\n- Après 48 h : **T négative « ischémique »**. Persistance du sus-ST : **anévrisme**.\n- **SCA sans ST+** : **sous-ST**, **inversion des T**, **pseudo-normalisation**, **aplatissement** des T, ou **ECG normal**.\n- Un **pacemaker** peut masquer les anomalies ischémiques.","src":"p. 411-412"},{"title":"Signes de gravité et situations urgentes à l'ECG","rank":"A","content":"- **FV** : urgence absolue → **choc électrique immédiat**, massage en attendant.\n- **Tachycardie régulière à QRS larges** = TV jusqu'à preuve du contraire ; **mauvaise tolérance hémodynamique → cardioversion électrique externe**.\n- **SCA ST+** (sus-ST significatif + miroir) ; **BBG complet + douleur thoracique** → éliminer un SCA ST+ **sans attendre la troponine**.\n- **Syncope + bloc bifasciculaire** → hospitalisation en cardiologie **avec télémétrie**.\n- **BAV infrahissiens** (Mobitz 2, BAV3) → pacemaker **même sans symptôme**.\n- **Hyperkaliémie** (T amples pointues, PR long, QRS large ; BAV, TV) ; **QT long** (torsade de pointes).\n- **FA préexcitée** (super-Wolff) : risque de **FV**.","src":"p. 381-412"},{"title":"Stimulateur cardiaque : reconnaître l'électroentraînement","rank":"B","content":"- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation.\n- **Unipolaire** : spike bien visible ; **bipolaire** : spike peu visible.\n- Stimulation **atriale** (dysfonction sinusale) : **onde P après le spike**.\n- Stimulation **ventriculaire** (BAV) : après un **délai AV programmé**, **QRS large d'aspect BBG** (stimulation du VD).\n- Les anomalies **ischémiques** peuvent être masquées.","src":"p. 412-414"}],"criteres":[{"title":"Valeurs normales de l'ECG de l'adulte","rank":"A","content":"| Paramètre | Normale |\n|---|---|\n| FC | **60–100 bpm** |\n| Durée de P | **< 120 ms** (théorique < 110 ms) |\n| Axe de P | **60°** (maximum en D2) |\n| Amplitude de P | **< 2,5 mm en D2** |\n| PR | **120–200 ms** inclus |\n| QRS | **70–110 ms** |\n| Axe QRS | **–30° à +90°** |\n| Onde Q physiologique | **< 1/3 du QRS et < 40 ms** |\n| QTc | **< 450 ms** à 60 bpm (en pratique 470–480 ms) |\n| Sokolow | **< 35 mm** |\n\n- **Étalonnage** : 25 mm/s → 1 mm = **40 ms**, grand carreau = **200 ms** ; 1 mm = **0,1 mV**.\n- **FC = 300 / nombre de grands carreaux** entre deux QRS.\n- **QTc de Bazett** = QT / √RR (s), mesuré par la tangente à T, **sans l'onde U**.","src":"p. 375-378"},{"title":"Axe du QRS : méthode rapide D1 / aVF","rank":"A","content":"| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si **D2 positif** (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n- Double triaxe de **Bailey** : 30° en 30°, sens horaire, D1 = 0°.\n- Cœur **vertical** (filiforme) → axe proche de 90° ; **horizontal** (obèse, cardiomégalie) → proche de 0°.\n- Axe anormal : **hémibloc** gauche ou anomalie morphologique marquée d'un ventricule.","src":"p. 375"},{"title":"Territoires ECG","rank":"A","content":"| Territoire | Dérivations |\n|---|---|\n| Antéroseptal | **V1, V2, V3** |\n| Apical | **V4** |\n| Latéral haut | **D1, aVL** |\n| Latéral bas | **V5, V6** |\n| Inférieur | **D2, D3, aVF** |\n| Postérieur | **V7, V8, V9** |\n| Ventricule droit | **V1, V2, V3R, V4R** |\n\n- **ECG 18 dérivations** (V7-V9, V3R-V4R) devant toute douleur thoracique.","src":"p. 371-375"},{"title":"Algorithme devant une bradycardie (FC des QRS < 50 bpm)","rank":"A","content":"Seules deux structures en cause : **nœud sinusal** ou **NAV**.\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale (ou FA, flutter, TAF) avec **plus de P que de QRS** → **BAV**.\n3. P **trop lentes ou absentes** → **dysfonction sinusale**.","src":"p. 389"},{"title":"Algorithme devant une tachycardie (FC > 100 bpm)","rank":"A","content":"1. **Irrégulière** → **FA** (différentiel : ESA).\n2. **Régulière à QRS larges** → **ventriculaire** jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → **supraventriculaire**.\n\n- **Mauvaise tolérance hémodynamique** → **cardioversion électrique externe**.\n- Bonne tolérance → **manœuvres vagales ± adénosine** (BAV transitoire) :\n  - **démasque l'activité atriale** → sinusale, flutter, TAF ;\n  - **arrête la tachycardie** → jonctionnelle ;\n  - **aucun effet** → TV ; certitude si dissociation AV.","src":"p. 405"},{"title":"Critères de la tachycardie ventriculaire","rank":"A","content":"- **Suspicion** : FC **> 100 bpm** + QRS **> 120 ms** sur **≥ 3 battements consécutifs**.\n- **Non soutenue** : 3 battements à 30 s ; **soutenue** : **> 30 s** ; préciser monomorphe / polymorphe.\n- **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P) ; **captures** et **fusions** (seulement s'il y a dissociation).\n- **En faveur** : cardiopathie sous-jacente, **concordance** V1-V6, **axe extrême** (QRS positif en aVR, jamais vu dans un BBD/BBG), aspect atypique de bloc.","src":"p. 398-400"},{"title":"Sus-décalage du ST : critères et diagnostic différentiel","rank":"A","content":"**Sus-ST significatif** : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**.\n\n**Cinq étiologies**\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après infarctus).\n3. **Repolarisation précoce** (inférolatérale).\n4. **Angor de Prinzmetal** (spasme).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\nDifférentiels : **BBG ou stimulation ventriculaire** (sus-ST approprié) ; **HVG marquée** (sus-ST V1-V2).\n\n> Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.","src":"p. 409-412"},{"title":"Critères des hypertrophies","rank":"B","content":"| Anomalie | Critères |\n|---|---|\n| HAD | P **> 2,5 mm en D2** ou **> 2 mm en V1-V2** |\n| HAG | P **> 110 ms** (120 en pratique), composante négative **> 40 ms en V1** |\n| HVG | **Sokolow** S(V1/V2) + R(V5/V6), normal **< 35 mm** |\n| HVD | axe **> 110°** (90° en pratique), **R > 6 mm V1**, **S > 7 mm V5-V6** |","src":"p. 406-407"},{"title":"Tachycardie sinusale vs TSV ; manœuvres vagales et adénosine","rank":"B","content":"- **Sinusale** : P positives en D1, D2, D3, aVF ; FC variable **progressivement** ; contexte d'hypermétabolisme.\n- **TSV** : variation en **marches d'escalier**.\n- **Manœuvres vagales** : Valsalva, compression carotidienne **unilatérale** (CI si athérome important ou souffle carotidien), grand verre d'eau froide ; compression oculaire **n'est plus recommandée**.\n- **Adénosine IV en flash** (effet ≈ **dizaine de secondes**) : CI **asthme**, **hypotension**, **FA préexcitée**.","src":"p. 390-391"},{"title":"Indications de l'ECG, du monitorage et du Holter","rank":"A","content":"**Monitorage (cardioscope)** : urgence, réanimation, transfert médicalisé ; soins intensifs cardiologiques ; syncope de cause rythmique suspectée ; peropératoire et SSPI ; certains exercices de réadaptation.\n\n**ECG 12 dérivations ou plus** : bilans de santé ; aptitude professionnelle ou sportive ; **préopératoire > 65 ans**, patients ou interventions à risque ; enquêtes familiales ; **symptômes** (palpitations, douleur thoracique, dyspnée, malaise, perte de connaissance, syncope) ; **obligatoire dans le bilan de l'HTA** ; pathologies cardiaques ou à risque CV (diabète, AVC).\n\n**Holter** [B] : **2 à 12 dérivations**, **24 à 96 h** ; symptômes **épisodiques** non documentés par l'ECG standard ; efficacité des bradycardisants, réglage des pacemakers, risque rythmique. Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, enregistreurs d'événements ; **Holter implantable jusqu'à 3 ans** (syncopes inexpliquées, FA silencieuse).","src":"p. 414-415"}],"chiffres":[{"theme":"Examens","label":"Vitesse de déroulement standard de l'ECG","value":"25 mm/s","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Durée d'un petit carreau (1 mm) à 25 mm/s","value":"40 ms","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Durée d'un grand carreau (5 mm) à 25 mm/s","value":"200 ms","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Étalonnage d'amplitude","value":"1 mm = 0,1 mV","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Calcul rapide de la FC","value":"300 / nombre de grands carreaux (1 = 300, 2 = 150 bpm)","rank":"A","src":"p. 376"},{"theme":"Examens","label":"Graduation du double triaxe de Bailey","value":"30° en 30°, sens horaire, D1 = 0°","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Dérivations précordiales","value":"V1 à V9 + V3R et V4R (enfant, suspicion de SCA)","rank":"A","src":"p. 371"},{"theme":"Examens","label":"ECG devant une douleur thoracique","value":"18 dérivations (V7-V9, V3R-V4R)","rank":"A","src":"p. 411-414"},{"theme":"Seuils et définitions","label":"Fréquence cardiaque normale de repos (adulte)","value":"60–100 bpm","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Bradycardie (adulte)","value":"< 60 bpm","rank":"A","src":"p. 376"},{"theme":"Seuils et définitions","label":"Tachycardie (adulte)","value":"> 100 bpm","rank":"A","src":"p. 376"},{"theme":"Seuils et définitions","label":"Durée normale de l'onde P","value":"< 120 ms (théorique < 110 ms)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Axe normal de l'onde P","value":"60° (maximum en D2)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Amplitude normale de l'onde P","value":"< 2,5 mm en D2","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Intervalle PR normal","value":"120–200 ms (inclus)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Durée normale du QRS","value":"70–110 ms","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Axe normal du QRS","value":"–30° à +90° (théorique –45° à +110°)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Onde Q physiologique","value":"< 1/3 du QRS et < 40 ms","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"QT corrigé normal","value":"< 450 ms à 60 bpm (en pratique 470–480 ms)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Formule de Bazett","value":"QTc = QT / √RR (RR en s)","rank":"A","src":"p. 377"},{"theme":"Seuils et définitions","label":"Indice de Sokolow normal","value":"S (V1/V2) + R (V5/V6) < 35 mm","rank":"A","src":"p. 406"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc de branche complet","value":"> 120 ms","rank":"A","src":"p. 378"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc de branche incomplet","value":"110–120 ms","rank":"B","src":"p. 381"},{"theme":"Diagnostic","label":"Durée du QRS dans un hémibloc","value":"> 110 ms (> 120 ms si bloc de branche associé ou cardiopathie marquée)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Axe de l'hémibloc antérieur gauche","value":"au-delà de –30° (D2 négatif)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Axe de l'hémibloc postérieur gauche","value":"> +90° (D1 négatif, S1Q3)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc bifasciculaire","value":"> 120 ms","rank":"A","src":"p. 383"},{"theme":"Diagnostic","label":"Définition du BAV1","value":"PR constant > 200 ms, sans P bloquée","rank":"A","src":"p. 386"},{"theme":"Diagnostic","label":"BAV 2/1","value":"1 onde P bloquée sur 2","rank":"A","src":"p. 385"},{"theme":"Diagnostic","label":"Seuil de bradycardie de l'algorithme diagnostique","value":"FC des QRS < 50 bpm","rank":"A","src":"p. 389"},{"theme":"Diagnostic","label":"Pause du bloc sinoatrial du 2e degré","value":"double de l'intervalle PP (RR) normal","rank":"B","src":"p. 387"},{"theme":"Diagnostic","label":"Largeur des QRS d'une TSV","value":"< 120 ms le plus souvent","rank":"A","src":"p. 389"},{"theme":"Diagnostic","label":"Fréquence ventriculaire de la FA","value":"100–200 bpm","rank":"A","src":"p. 392"},{"theme":"Diagnostic","label":"Fréquence atriale du flutter","value":"≈ 300 bpm (240–340)","rank":"A","src":"p. 393"},{"theme":"Diagnostic","label":"Fréquence atriale d'un flutter atypique","value":"120–320 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 2/1","value":"150 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 3/1","value":"100 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 4/1","value":"75 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence des tachycardies jonctionnelles","value":"≈ 200 bpm (130–260)","rank":"A","src":"p. 395"},{"theme":"Diagnostic","label":"Bigéminisme / trigéminisme","value":"1 battement sur 2 / 1 battement sur 3","rank":"A","src":"p. 397"},{"theme":"Diagnostic","label":"Critères de suspicion de TV","value":"FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs","rank":"A","src":"p. 399"},{"theme":"Diagnostic","label":"TV non soutenue","value":"3 battements à 30 s","rank":"A","src":"p. 399"},{"theme":"Diagnostic","label":"TV soutenue","value":"> 30 s","rank":"A","src":"p. 399"},{"theme":"Pronostic","label":"Part des morts subites précédées d'une TV","value":"> la moitié","rank":"A","src":"p. 398"},{"theme":"Examens","label":"Durée d'effet de l'adénosine IV (flash)","value":"une dizaine de secondes","rank":"B","src":"p. 390"},{"theme":"Diagnostic","label":"Hypertrophie atriale droite","value":"P > 2,5 mm en D2 ou > 2 mm en V1-V2","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"Hypertrophie atriale gauche : durée de P","value":"> 110 ms (120 ms en pratique)","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"Hypertrophie atriale gauche : composante négative de P en V1","value":"> 40 ms","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"QRS dans l'HVG","value":"le plus souvent < 120 ms","rank":"A","src":"p. 406"},{"theme":"Diagnostic","label":"HVD : axe (signe le plus précoce)","value":"> 110° (90° en pratique)","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"HVD : onde R en V1","value":"> 6 mm","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"HVD : onde S en V5-V6","value":"> 7 mm","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"PR de la préexcitation","value":"< 120 ms","rank":"B","src":"p. 410"},{"theme":"Seuils et définitions","label":"Sus-ST significatif en V1-V3","value":"≥ 2 mm","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Sus-ST significatif hors V1-V3","value":"≥ 1 mm","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Nombre de dérivations pour un sus-ST significatif","value":"≥ 2 dérivations adjacentes","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Onde Q de nécrose : amplitude","value":"≥ 1/3 (ou 1/4) du QRS","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Onde Q de nécrose : durée","value":"> 30–40 ms","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Délai d'apparition des ondes Q de nécrose","value":"vers la 6e heure","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Délai d'apparition de la T négative ischémique","value":"après 48 h","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Nombre de phases ECG de la péricardite aiguë","value":"4","rank":"B","src":"p. 409"},{"theme":"Seuils et définitions","label":"T négatives pathologiques dans un territoire","value":"2 T négatives dans un même territoire","rank":"A","src":"p. 411"},{"theme":"Diagnostic","label":"Durée du spike de stimulation","value":"0,4 à 1 ms","rank":"B","src":"p. 413"},{"theme":"Examens","label":"Nombre de dérivations du Holter","value":"2 à 12","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Durée d'enregistrement du Holter","value":"24 à 96 h maximum","rank":"B","src":"p. 415"},{"theme":"Examens","label":"ECG ambulatoire de très longue durée","value":"jusqu'à 21 jours","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Durée de suivi du Holter implantable","value":"jusqu'à 3 ans","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Âge de l'ECG préopératoire","value":"> 65 ans (ou patient / intervention à risque)","rank":"A","src":"p. 414"}],"physio":[{"theme":"Mécanismes","title":"Rythmes d'échappement","rank":"A","content":"1. En cas de **dysfonction sinusale marquée**, un **rythme d'échappement jonctionnel** apparaît : l'onde P n'est plus visible devant le QRS (parfois rétrograde).\n2. Dans le **BAV complet**, la fréquence cardiaque devient **lente et régulière** grâce à un rythme d'échappement de mécanisme automatique.\n3. Échappement à **QRS fins** = bloc **nodal** (suprahissien) ; échappements à **QRS larges** = blocs atrioventriculaires **bas situés**.\n4. La **bradycardie extrême** des échappements bas situés allonge le QT et expose à la **torsade de pointes**.","src":"p. 387-388, 392, 404"},{"theme":"Mécanismes","title":"Électrogenèse : de l'influx à l'onde ECG","rank":"A","content":"- L'ECG enregistre la **somme des potentiels d'action** : **P** (oreillettes), **QRS** (ventricules), **T** (repolarisation).\n- Front de dépolarisation **vers** l'électrode → onde **positive** ; s'en **éloignant** → **négative** ; perpendiculaire → **isodiphasique**.\n- **T concordante** au QRS normal : dépolarisation **endocarde → épicarde**, repolarisation en sens inverse.\n- Le reste du plan de l'anneau est isolant : **le NAV est le seul passage AV physiologique** (p. 410).\n- QRS **fins** si l'influx emprunte le réseau spécialisé ; **larges** s'il chemine de proche en proche (BBG, stimulation, ESV, TV).\n- **Genèse du QRS** [B] : activation septale (petite **q** latérale, petit **r** en V1), puis vers la jambe gauche et l'avant (grande **R** en V3-V4 et D2), puis vers le haut et l'arrière (petite **S**).","src":"p. 368-377"},{"theme":"Conséquences hémodynamiques","title":"Filtre du NAV : conduction décrémentielle","rank":"A","content":"1. Au-delà d'une certaine fréquence atriale, le ventricule ne suit plus en 1/1 : **2/1**, alternance **1/1-2/1** ou **2/1-3/1** (conduction variable).\n2. L'intensité du filtre dépend de l'**âge**, du **tonus vagal**, des **ralentisseurs du NAV**.\n3. Sans ce filtre, **toute FA donnerait une FV** et un flutter à 300 bpm une tachycardie ventriculaire à 300 bpm.\n4. **Créer un BAV transitoire** (manœuvres vagales, **adénosine** via les récepteurs **purinergiques**) démasque l'activité atriale ou arrête une réentrée dépendante du NAV.\n\n→ La **voie accessoire** (Kent) n'a **pas de propriété décrémentielle** : en FA, conduction très rapide (super-Wolff) → **FV**.","src":"p. 389-411"},{"theme":"Mécanismes","title":"Réentrée, hyperautomatisme et troubles du rythme","rank":"A","content":"- **TSV** : réentrée, hyperautomatisme, mécanismes complexes ; au-delà de la bifurcation hissienne = trouble **ventriculaire**.\n- **Flutter** : boucle de **réentrée** autour d'un obstacle, activation « organisée » (≠ FA fibrillatoire) ; typique par l'**isthme cavotricuspide**.\n- **Jonctionnelle** : réentrée **intranodale** (dans le NAV) ou **rythme réciproque** par voie accessoire (faisceau de Kent).\n- **TV** : **réentrée** autour d'une **fibrose post-infarctus** (le plus fréquent sur cardiopathie) ; **automatisme anormal** sur cœur sain. Évolution **TV → FV → asystolie**.","src":"p. 389-400"},{"theme":"Mécanismes","title":"Blocs de branche : repolarisation secondaire et désynchronisation","rank":"B","content":"1. Interruption d'une branche → activation ventriculaire **de proche en proche** → **QRS larges**.\n2. **Trouble de repolarisation secondaire** → **discordance appropriée** de T (peut mimer un SCA ST+ dans le BBG).\n3. **BBG complet** → **désynchronisation du VG** pouvant créer ou aggraver une cardiopathie → correction (**resynchronisation**) indiquée si insuffisance cardiaque.\n4. **Bloc bifasciculaire** → risque de **BAV complet infrahissien intermittent** (syncope, mort subite).\n5. **Bloc fonctionnel** : n'apparaît qu'à partir d'une fréquence donnée (en **tachycardie** ou en **bradycardie**).","src":"p. 378-385"},{"theme":"Facteurs déclenchants","title":"QT long et torsades de pointes","rank":"B","content":"- Causes : **bradycardie extrême**, **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- QT long → **torsade de pointes** → arrêt spontané ou **FV**.\n- Traitement logique : **corriger les ions**, **accélérer la fréquence cardiaque**, **arrêter les médicaments** en cause.","src":"p. 403-410"},{"theme":"Histoire naturelle","title":"Évolution ECG du SCA ST+ et de la péricardite","rank":"A","content":"**SCA ST+**\n1. Sus-ST (± onde de Pardee) avec miroir.\n2. Ondes Q vers la **6e heure**.\n3. Régression rapide si reperfusion ; plusieurs jours sinon ; **persistance indéfinie** si **anévrisme**.\n4. Après **48 h** : T négative « ischémique », parfois très prolongée.\n\n**Péricardite aiguë (4 phases)**\n1. Microvoltage, sus-ST diffus concave sans miroir, sous-décalage de PQ.\n2. T plates, ST isoélectrique.\n3. T négatives persistantes.\n4. Retour progressif à la normale.","src":"p. 409-412"}],"parcours":[{"title":"Tachycardie aux urgences : de l'ECG au diagnostic du trouble du rythme","rank":"A","patient":"Homme de 68 ans, aux antécédents d'infarctus du myocarde ancien, amené aux urgences pour des palpitations rapides débutées il y a 2 heures. Il est conscient. Le scope affiche une tachycardie à 160 bpm.","steps":[{"phase":"Régulation / pré-hospitalier","title":"Monitorer et donner l'alerte","question":"Le patient est pris en charge par le SAMU puis arrive aux urgences : quelle surveillance ECG mets-tu en place et quel signe sur le scope doit déclencher l'alerte ?","answer":"- **Monitorage ECG (cardioscope)** indiqué dans : toute **urgence**, la réanimation et tout **transfert médicalisé** ; la **syncope** à cause rythmique suspectée ; la surveillance en **soins intensifs cardiologiques**.\n- **ECG 12 dérivations** indiqué devant des **palpitations** (symptôme = indication de l'ECG conventionnel).\n- **Alerte** (15, préparer la réanimation) si suspicion de **TV** : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs**.\n- La TV est un état **instable, prémonitoire de l'arrêt cardiaque** (> la moitié des morts subites) : **TV → FV → asystolie**.","cas":[{"si":"Si le scope montre une tachycardie irrégulière à QRS larges polymorphes avec perte de connaissance","alors":"**Fibrillation ventriculaire** = arrêt cardiaque (pouls carotidien aboli) → **choc électrique immédiat avant tout autre geste**, **massage cardiaque en attendant**."}],"pieges":["Attendre l'ECG 12 dérivations pour donner l'alerte devant ≥ 3 complexes larges et rapides au scope."],"src":"p. 398-399, 402-403, 414"},{"phase":"Accueil & gravité","title":"Évaluer la tolérance hémodynamique","question":"Avant même d'analyser finement le tracé, quelle est la première question à te poser et quelle en est la conséquence thérapeutique ?","answer":"- Première question : la tachycardie est-elle **bien ou mal tolérée sur le plan hémodynamique** ?\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe**, quel que soit le mécanisme.\n- **Bonne tolérance** → on a le temps de faire le diagnostic : ECG 12 dérivations, puis **manœuvres vagales ± adénosine** si le diagnostic n'est pas évident.\n- La **FV** est une **urgence absolue** : perte de connaissance en quelques secondes (débit nul), pouls carotidien aboli.","cas":[{"si":"Si FV (arrêt cardiaque)","alors":"**Choc électrique immédiat** avant tout autre geste ; **massage cardiaque** en attendant le défibrillateur."},{"si":"Si tachycardie mal tolérée (quel que soit le type)","alors":"**Cardioversion électrique externe**."}],"pieges":["Retarder le choc électrique d'une FV pour réaliser d'autres gestes."],"src":"p. 402-405"},{"phase":"Examens complémentaires","title":"Réaliser un ECG 12 (voire 18) dérivations de qualité","question":"Comment réalises-tu et vérifies-tu techniquement l'ECG, et comment calcules-tu rapidement la fréquence ?","answer":"- **Dérivations frontales** : D1, D2, D3 + aVR, aVL, aVF. **Précordiales** : **V1 à V9**, complétées par **V3R-V4R** (enfant ou suspicion de SCA) ; électrodes précordiales **équidistantes**.\n- **Étalonnage** : **25 mm/s** → 1 mm = **40 ms**, grand carreau (5 mm) = **200 ms** ; **1 mm = 0,1 mV**.\n- **FC = 300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…), ou FC = 60 / RR (s).\n- Pour démasquer une activité atriale peu visible : **dérivations de Lewis** (électrode rouge sur la fourchette sternale, jaune au 5e espace intercostal droit ; lecture en **D1**).","cas":[{"si":"Si D1 est négatif","alors":"Penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1)."}],"pieges":["V1 et V2 posées trop haut et trop écartées (confusion avec les foyers aortique et pulmonaire) → faux aspect de pseudonécrose ou d'atypie de repolarisation antérieure."],"src":"p. 371-376"},{"phase":"Diagnostic positif","title":"Classer la tachycardie : l'algorithme","question":"L'ECG montre une tachycardie (> 100 bpm). Quel algorithme appliques-tu pour l'orienter ?","answer":"Toujours **décrire d'abord le rythme atrial**, puis :\n\n| Aspect | Orientation |\n|---|---|\n| **Irrégulière** | **FA** (diagnostic différentiel : ESA) |\n| **Régulière à QRS larges** (> 120 ms) | **Ventriculaire jusqu'à preuve du contraire** (ou TSV + bloc de branche) |\n| **Régulière à QRS fins** (< 120 ms) | **Supraventriculaire** |\n\n- TSV = activation trop rapide des oreillettes ou de la jonction ; QRS fins le plus souvent, **larges si bloc de branche associé**.\n- Les tachycardies ventriculaires naissent **sous la bifurcation hissienne** → conduction de proche en proche → **QRS large**.","cas":[{"si":"Si tachycardie irrégulière à QRS larges","alors":"Évoquer une **FA + bloc de branche** (préexistant ou fonctionnel), une **FV** (QRS polymorphes, arrêt cardiaque) ou une **FA préexcitée** (QRS de largeur variable « en accordéon »)."},{"si":"Si FA avec rythme ventriculaire lent et régulier","alors":"**FA + BAV complet** (échappement automatique)."}],"pieges":["Conclure à une TSV avec bloc de branche devant une tachycardie régulière à QRS larges sans avoir éliminé une TV."],"src":"p. 378, 389, 392, 398, 405"},{"phase":"Diagnostic positif","title":"Affirmer la tachycardie ventriculaire","question":"La tachycardie est régulière à QRS larges (140 ms). Quels arguments ECG affirment ou orientent vers une TV ?","answer":"**Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.**\n\n- **Arguments de certitude** :\n  - **dissociation ventriculoatriale** : **plus de QRS que de P** (≠ dissociation AV du BAV3) ;\n  - complexes de **capture** (QRS fin précédé d'une P) et de **fusion** (QRS intermédiaire), possibles seulement s'il y a dissociation.\n- **Arguments en faveur** :\n  - **cardiopathie sous-jacente** +++ ;\n  - **concordance** positive ou négative de V1 à V6 ;\n  - **axe extrême** (QRS positif en aVR, jamais vu dans un BBD/BBG) ;\n  - QRS larges d'aspect **atypique** de bloc de branche.\n- Préciser : **non soutenue** (3 battements à 30 s) ou **soutenue** (> 30 s) ; **monomorphe** ou **polymorphe**.\n- Mécanismes : **réentrée** (le plus fréquent sur cardiopathie, autour d'une fibrose post-infarctus) ; **automatisme anormal** (cœur sain).","cas":[{"si":"Si les manœuvres vagales / l'adénosine n'ont aucun effet","alors":"Orientation vers une **TV** (indépendante du NAV) ; certitude si dissociation AV."}],"pieges":["Confondre la dissociation ventriculoatriale de la TV (plus de QRS que de P) avec la dissociation AV du BAV3 (plus de P que de QRS)."],"src":"p. 398-400, 405"},{"phase":"Diagnostic différentiel","title":"Tachycardie sinusale ou TSV non sinusale ?","question":"Devant une tachycardie régulière à QRS fins, comment distingues-tu une tachycardie sinusale d'une TSV non sinusale ?","answer":"- **P sinusales** : positives en **D1, D2, D3 et aVF**.\n- **Variation de fréquence** : **progressive** pour la sinusale (courbe de scope, télémétrie, holter, massage sinocarotidien) ; en **« marches d'escalier »** pour une TSV.\n- **Contexte** : au repos, une tachycardie marquée **sans cause d'hypermétabolisme** (fièvre, stress, douleur) **n'est pas sinusale**.\n- Seuils adulte : tachycardie **> 100 bpm** (attention au nouveau-né).","cas":[],"pieges":["Retenir une tachycardie sinusale chez un patient au repos sans fièvre, stress ni douleur."],"src":"p. 376, 390-391"},{"phase":"Traitement en urgence","title":"Créer un BAV transitoire : manœuvres vagales puis adénosine","question":"La tachycardie est bien tolérée et le diagnostic n'est pas évident. Que fais-tu, comment, et comment interprètes-tu la réponse ?","answer":"1. **Manœuvres vagales** :\n   - **Valsalva** (expiration forcée à glotte fermée) ;\n   - **compression carotidienne unilatérale** ;\n   - **grand verre d'eau froide**.\n2. Si échec : **adénosine IV en flash** (vagomimétique via les récepteurs purinergiques), effet d'une **dizaine de secondes**.\n\n| Réponse | Diagnostic |\n|---|---|\n| **Démasque l'activité atriale** | sinusale, **flutter**, **TAF** |\n| **Arrête la tachycardie** | **jonctionnelle** (réentrée dépendante du NAV) |\n| **Aucun effet** | **TV** (indépendante du NAV) ; certitude si dissociation AV |\n\n- Intérêt double : **diagnostic différentiel** des tachycardies et **réduction des tachycardies jonctionnelles**.","cas":[{"si":"Si athérome important ou souffle carotidien","alors":"**Compression carotidienne contre-indiquée**."},{"si":"Si asthme","alors":"**Adénosine contre-indiquée** (bronchospasme intense transitoire possible, même chez le non asthmatique)."},{"si":"Si hypotension","alors":"**Adénosine contre-indiquée**."},{"si":"Si FA préexcitée (super-Wolff)","alors":"**Adénosine contre-indiquée** ; ne **jamais** bloquer le NAV en cas de FA sur voie accessoire."}],"pieges":["Proposer une compression oculaire bilatérale : elle n'est plus recommandée (décollement de rétine du myope).","Faire une compression carotidienne bilatérale : elle est unilatérale."],"src":"p. 390, 405, 411"},{"phase":"Diagnostic étiologique","title":"Identifier la tachycardie supraventriculaire","question":"Quels sont les aspects ECG des différentes TSV que tu peux démasquer ?","answer":"| TSV | Aspect ECG |\n|---|---|\n| **FA** | activation atriale **anarchique**, pas de P ; **100–200 bpm** ; QRS **« irrégulièrement irréguliers »** ; ligne de base à **mailles amples** ou **fine trémulation** |\n| **Flutter typique antihoraire** | activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** ; ondes **F** en dents de scie **négatives en D2, D3, aVF, positives en V1, négatives en V6** ; circuit par l'**isthme cavotricuspide** ; ventricules classiquement à **150 bpm (2/1)**, ou 100 (3/1), 75… |\n| **Flutter atypique** | isthme non impliqué, **120–320 bpm**, F variables |\n| **TAF** | activité atriale **démasquée** par la manœuvre vagale ou l'adénosine, sans arrêt de la tachycardie |\n| **Tachycardie jonctionnelle (Bouveret)** | **très régulière**, ≈ **200 bpm (130–260)** |\n\nTachycardies jonctionnelles :\n- **réentrée intranodale** (réentrée dans le NAV) : activité atriale invisible ou devinée dans le ST ;\n- **rythme réciproque** : réentrée par une **voie accessoire (faisceau de Kent)**.","cas":[{"si":"Si flutter typique horaire","alors":"Polarités des ondes F **inversées**."},{"si":"Si flutter conduit en 1/1 ou 2/1","alors":"La manœuvre vagale **ralentit** et **démasque les F**."},{"si":"Si alternance FA / bradycardie sinusale avec pauses à l'arrêt de la FA","alors":"**Maladie de l'oreillette** (syndrome tachycardie-bradycardie)."},{"si":"Si ESA fréquentes ou polymorphes (ou ESV)","alors":"**Rechercher une cardiopathie**."}],"pieges":["Confondre une FA à grosses mailles avec un flutter : le flutter est monomorphe et organisé.","Parler de flutter typique avec certitude : on parle de flutter « d'aspect » typique/atypique, le diagnostic formel se fait par la fréquence ou l'exploration électrophysiologique."],"src":"p. 392-397"},{"phase":"Diagnostic étiologique","title":"Rechercher une préexcitation (Wolff-Parkinson-White)","question":"Sur l'ECG en rythme sinusal après réduction, que cherches-tu pour évoquer une voie accessoire et quel est le risque ?","answer":"- **Voie accessoire (faisceau de Kent)** : fibre musculaire AV ectopique conduisant typiquement dans les deux sens, en compétition avec le NAV.\n- **Préexcitation** : **PR court < 120 ms**, **onde delta** (empâtement du pied du QRS), **troubles de repolarisation** dans le territoire de la voie.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- **Risque de mort subite** si période réfractaire courte (pas de propriété décrémentielle) : en FA → tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** (super-Wolff) → **FV**.","cas":[{"si":"Si préexcitation minime à démasquer","alors":"Bloquer le NAV (massage, adénosine) force le passage par la voie accessoire — **jamais en cas de FA**."}],"pieges":["Injecter de l'adénosine dans une FA préexcitée."],"src":"p. 410-411"},{"phase":"Traitement spécifique","title":"Torsade de pointes et QT long","question":"Le patient présente une TV polymorphe s'arrêtant spontanément ; l'ECG de base montre un QT long. Que fais-tu ?","answer":"- **Torsade de pointes** : TV **polymorphe** s'arrêtant spontanément ou dégénérant en **FV** ; installée, elle est indiscernable d'une FV → diagnostic sur le **QT long préalable** et le contexte.\n- **Mesure du QT** : du début de Q à la fin de T, dans la dérivation où T est la plus ample (souvent V2-V3), par la **tangente** ; **jamais d'onde U**. **Bazett** : QTc = QT / √RR (s). Normal **< 450 ms à 60 bpm** (en pratique 470–480 ms).\n- **Causes de QT long** : **bradycardie extrême** (échappements des BAV bas situés, intoxication aux bradycardisants), **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- **Tout QT allongé → vérifier les médicaments et le ionogramme.**\n- **Prise en charge** : **corriger les ions**, **accélérer la fréquence cardiaque**, **arrêter les médicaments en cause**.\n\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | plate ou négative, diffuse, avec sous-ST | ample, pointue, symétrique |\n| PR | – | allongé |\n| QRS | normal | élargi |\n| QT / U | QT allongé, onde U | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | BAV, TV, dysfonction sinusale |","cas":[{"si":"Si QT normal","alors":"Une torsade reste possible, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re."}],"pieges":["Inclure l'onde U dans la mesure du QT.","Ralentir la fréquence cardiaque d'une torsade : il faut au contraire l'accélérer."],"src":"p. 377, 403-404, 408-409"},{"phase":"Suivi","title":"Documenter les récidives et protéger le patient","question":"À distance, comment documentes-tu des palpitations épisodiques et quelle prothèse protège d'une TV/FV ?","answer":"- **Holter ECG** : **2 à 12 dérivations**, **24 à 96 h maximum**, lecture différée ; pour palpitations, malaises, syncopes **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, **enregistreurs d'événements** (outils dédiés, montres connectées ECG).\n- **Holter implantable** : jusqu'à **3 ans** (syncopes inexpliquées, FA silencieuse).\n- Holter 24 h pour évaluer le **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).\n- **TV / FV → défibrillateur** (fait toujours pacemaker, sauf sous-cutané).\n- **Flutter** : exploration électrophysiologique avant **ablation par radiofréquence**.","cas":[],"pieges":["Prescrire un Holter de 24 h pour des symptômes très rares : préférer un enregistrement de longue durée, un enregistreur d'événements ou un Holter implantable."],"src":"p. 394, 413-415"}]},{"title":"Bradycardie et syncope : BAV, dysfonction sinusale et blocs de branche","rank":"A","patient":"Femme de 79 ans, hypertendue, amenée aux urgences après un malaise avec perte de connaissance brève. À l'arrivée, elle est consciente, le pouls est lent à 38 bpm.","steps":[{"phase":"Régulation / pré-hospitalier","title":"Monitorer la syncope","question":"Quelle surveillance mets-tu en place dès la prise en charge ?","answer":"- **Monitorage ECG (cardioscope)** : **urgence**, **transfert médicalisé**, **syncope avec cause rythmique suspectée**.\n- **ECG 12 dérivations** : indiqué devant **malaise, perte de connaissance, syncope** ; en urgence aussi devant les **troubles hydroélectrolytiques (K, Ca)**.","cas":[],"pieges":[],"src":"p. 414"},{"phase":"Accueil & gravité","title":"Rechercher les signes de gravité","question":"Quels éléments ECG dois-tu repérer d'emblée pour juger de la gravité ?","answer":"- **Asystole** (tracé plat).\n- **Échappement à QRS larges** (bloc bas situé) : plus grave qu'un échappement jonctionnel à QRS fins (bloc nodal).\n- **BAV infrahissien** (BAV2 Mobitz 2, BAV3 ; le BAV 2/1 à QRS larges est infrahissien) : indication de **pacemaker même sans symptôme**.\n- **Bradycardie extrême** (échappements des BAV bas situés) : cause de **QT long → torsade de pointes**.\n- **Bloc bifasciculaire + syncope** : risque de **BAV complet infrahissien intermittent** (syncope, mort subite).","cas":[{"si":"Si bradycardie extrême avec QT long","alors":"Risque de torsade de pointes : **corriger les ions**, **accélérer la fréquence cardiaque**, arrêter les médicaments en cause."}],"pieges":[],"src":"p. 383, 387, 403-404, 412"},{"phase":"Interrogatoire","title":"Rechercher une cause médicamenteuse ou physiologique","question":"Que recherches-tu à l'interrogatoire devant cette bradycardie ?","answer":"- **Médicaments bradycardisants** : **intoxication aux bradycardisants** (cause de bradycardie extrême) ; **bêtabloquants**.\n- Médicaments allongeant le **QT** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…).\n- Contexte physiologique : **bradycardie sinusale de l'athlète** (tonus vagal).\n- Symptômes : malaises, lipothymies, syncopes (épisodiques ?), palpitations (syndrome tachycardie-bradycardie).","cas":[],"pieges":["Oublier que la bradycardie sinusale de l'athlète est physiologique."],"src":"p. 369-371, 376, 403-404"},{"phase":"Examens complémentaires","title":"ECG et ionogramme","question":"Quels examens demandes-tu en urgence ?","answer":"- **ECG 12 dérivations** (per-critique si possible).\n- **Ionogramme** (kaliémie, calcémie) : l'**hyperkaliémie** donne **BAV**, **dysfonction sinusale** (échappement jonctionnel), TV, avec **T amples, pointues, symétriques**, **PR allongé**, **QRS élargi**.\n- Tout QT allongé → vérifier **médicaments et ionogramme**.","cas":[{"si":"Si T amples pointues symétriques + PR long + QRS large","alors":"Évoquer une **hyperkaliémie**."}],"pieges":[],"src":"p. 403-404, 408, 414"},{"phase":"Diagnostic positif","title":"Algorithme devant une bradycardie","question":"La FC des QRS est à 38 bpm. Quel raisonnement appliques-tu ?","answer":"Bradycardie = **FC des QRS < 50 bpm** dans l'algorithme. Seules **deux structures** peuvent être en cause : le **nœud sinusal** ou le **NAV**.\n\n1. **Regarder les ondes P.**\n2. P **régulières à fréquence normale** (ou activité atriale rapide : FA, flutter, TAF) avec **plus de P que de QRS** → problème de passage au ventricule → **BAV**.\n3. P **trop lentes ou absentes** → problème du nœud sinusal → **dysfonction sinusale**.\n\n- Les bradycardies sont des **troubles de la conduction** (le terme « trouble du rythme » désigne les tachycardies).","cas":[],"pieges":[],"src":"p. 389-390"},{"phase":"Diagnostic positif","title":"Identifier le type de BAV et son siège","question":"Les P sont régulières à 75/min, plus nombreuses que les QRS. Comment caractérises-tu le BAV ?","answer":"Dans un BAV, les P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| **BAV1** | PR **constant > 200 ms**, aucune P bloquée | – |\n| **Mobitz 1** (Luciani-Wenckebach) | PR s'**allonge progressivement** puis une P est bloquée | **suprahissien** |\n| **BAV 2/1** | une P bloquée sur deux | **infrahissien si QRS larges** ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| **Mobitz 2** | PR **constant** puis P bloquée **inopinée** | **infrahissien** |\n| **BAV3** | **dissociation AV complète**, P dissociées (bien vues en V1) | échappement à **QRS fins = bloc nodal** (suprahissien) |\n\n- Le PR explore **toute la conduction**, de la sortie du nœud sinusal au réseau de Purkinje (normal **120–200 ms**).","cas":[{"si":"Si la P « bloquée » est plus précoce que les autres","alors":"C'est une **extrasystole atriale bloquée**, pas un BAV."},{"si":"Si FA ou flutter avec rythme ventriculaire lent et régulier","alors":"**BAV du 3e degré associé** (échappement automatique)."}],"pieges":["Parler de rythme sinusal dans un BAV3 : des P sinusales régulières non conduites ne sont plus un rythme sinusal."],"src":"p. 376, 385-387, 392"},{"phase":"Diagnostic différentiel","title":"Reconnaître une dysfonction sinusale","question":"Si les P sont lentes ou absentes, quels aspects de dysfonction sinusale dois-tu reconnaître ?","answer":"- **Asystole** : tracé plat.\n- **Bloc sinoatrial du 2e degré** : pause par absence intermittente de P, égale au **double de l'intervalle PP (RR)** normal, avec absence complète de **P-QRS-T**.\n- **Échappement jonctionnel** (dysfonction marquée) : P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2** (activation atriale de bas en haut).\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- **Maladie de l'oreillette** (syndrome tachycardie-bradycardie) : alternance **FA / bradycardie sinusale**, **pauses de régularisation** à l'arrêt de la FA.","cas":[],"pieges":["Oublier que des T négatives dans toutes les précordiales sont pathologiques : éliminer d'abord une ischémie."],"src":"p. 387-389, 392"},{"phase":"Diagnostic positif","title":"Analyser les blocs de branche et hémiblocs","question":"Les QRS sont larges. Comment reconnais-tu un bloc de branche, un hémibloc ou un bloc bifasciculaire ?","answer":"Ordre de lecture : **rythme** → QRS **> 120 ms** ? → V1 positif (BBD) ou négatif (BBG) → aspect inverse en V6.\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | QRS **positif**, **RsR'** | QRS **négatif**, **rS ou QS** |\n| V6 | **qRs**, S traînante arrondie | **notch**, R souvent exclusive (aussi D1, aVL) |\n\n- **Incomplet** : QRS **110–120 ms**. **Fonctionnel** : n'apparaît qu'en tachycardie ou en bradycardie.\n- **Hémiblocs** : QRS **> 110 ms** + déviation axiale :\n  - **HBAG** (fréquent) : axe au-delà de **–30°** (D2 négatif) ;\n  - **HBPG** (rare) : axe **> +90°** (D1 négatif, S1Q3), en l'absence de pathologie du VD, morphologie longiligne ou infarctus latéral.\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n- **Discordance appropriée** : T de polarité inverse du QRS.","cas":[],"pieges":["Conclure à un HBPG devant un D1 négatif sans éliminer une inversion d'électrodes (P alors négative en D1)."],"src":"p. 378-383"},{"phase":"Évaluation du risque / pronostic","title":"Estimer le risque de BAV complet","question":"Quel pronostic associes-tu à chaque type de bloc intraventriculaire ?","answer":"- **Hémibloc isolé ou bloc incomplet** : atteinte débutante, **risque de BAV infrahissien faible**.\n- **Bloc bifasciculaire** (BBG complet, ou BBD + hémibloc) : risque de **BAV complet infrahissien intermittent** (syncope, mort subite).\n- **BBG complet** → désynchronisation du VG pouvant créer ou aggraver une cardiopathie.","cas":[{"si":"Si syncope + bloc bifasciculaire","alors":"**Hospitalisation en cardiologie avec télémétrie**."}],"pieges":[],"src":"p. 383"},{"phase":"Hospitalisation & surveillance","title":"Surveiller et documenter","question":"Comment organises-tu la surveillance et la documentation des épisodes ?","answer":"- **Télémétrie / monitorage** en cardiologie (syncope + bloc bifasciculaire, syncope à cause rythmique suspectée).\n- **Holter** (24 à 96 h) si malaises, syncopes épisodiques non documentés par l'ECG standard et susceptibles de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, enregistreurs d'événements.\n- **Holter implantable** (jusqu'à **3 ans**) : **syncopes inexpliquées**.\n- Holter 24 h aussi pour l'**efficacité des bradycardisants**.","cas":[],"pieges":[],"src":"p. 383, 414-415"},{"phase":"Traitement spécifique","title":"Poser l'indication d'une prothèse rythmique","question":"Quelles sont les indications de pacemaker et des autres prothèses ?","answer":"- **Pacemaker** :\n  - **bradycardies symptomatiques** : dysfonction sinusale, **BAV2 Mobitz 1**, bradycardie sinusale ;\n  - **BAV infrahissiens** (Mobitz 2, BAV3) : **même sans symptôme** ;\n- Toute **syncope** sur bloc → réévaluer l'indication de pacemaker.\n\n| Problème | Prothèse |\n|---|---|\n| Bradycardie | **pacemaker** |\n| TV / FV | **défibrillateur** (fait toujours pacemaker, sauf sous-cutané) |\n| BBG désynchronisant + insuffisance cardiaque | **resynchronisation cardiaque** |","cas":[],"pieges":["Attendre des symptômes pour appareiller un BAV infrahissien."],"src":"p. 384-385, 413-414"},{"phase":"Suivi","title":"Lire l'ECG d'un patient appareillé","question":"Au suivi, comment reconnais-tu l'ECG d'un patient stimulé et comment le surveilles-tu ?","answer":"- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation ; bien visible en **unipolaire**, peu visible en **bipolaire**.\n- **Stimulation atriale** (dysfonction sinusale) : une **onde P suit le spike**.\n- **Stimulation ventriculaire** (BAV) : le pacemaker écoute l'oreillette et stimule le ventricule après un **délai AV programmé** → **QRS large d'aspect BBG** après le spike.\n- **Holter 24 h** : surveillance et réglage des **pacemakers**.","cas":[],"pieges":["Oublier que le pacemaker peut masquer des anomalies ischémiques.","Interpréter le sus-ST des dérivations à QRS négatif d'un rythme stimulé comme un SCA."],"src":"p. 412-415"}]},{"title":"Douleur thoracique : lire l'ECG en urgence (SCA, péricardite, BBG, HVG, embolie pulmonaire)","rank":"A","patient":"Homme de 56 ans, fumeur et hypertendu, appelle le 15 pour une douleur thoracique constrictive persistante depuis 1 heure. Il est porteur d'un bloc de branche gauche connu.","steps":[{"phase":"Régulation / pré-hospitalier","title":"ECG et monitorage immédiats","question":"Quels examens ECG réalises-tu dès la prise en charge ?","answer":"- **Monitorage ECG** : urgence, transfert médicalisé, puis **soins intensifs cardiologiques** pour pathologie aiguë (syndrome coronarien).\n- **ECG 18 dérivations** devant **toute douleur thoracique** : 12 dérivations + **V7-V9** (postérieur) + **V3R-V4R** (VD).","cas":[],"pieges":["Se contenter de 12 dérivations devant une douleur thoracique : un SCA postérieur peut n'apparaître qu'en V7-V9."],"src":"p. 371, 411, 414"},{"phase":"Examens complémentaires","title":"Lire l'ECG de façon systématique","question":"Quelle démarche systématique appliques-tu à la lecture et quelles sont les valeurs normales ?","answer":"1. **Rythme** : sinusal (P + en D1, D2 ; un QRS après chaque P, une P avant chaque QRS), **60–100 bpm**.\n2. **Conduction** : P < 120 ms, **PR 120–200 ms**, **QRS 70–110 ms**, axe **–30° à +90°**.\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1** (parfois D3, aVL) ; **QTc < 450 ms**.\n4. **Morphologie** : amplitudes normales (**Sokolow < 35 mm**), transition normale V1→V6, **pas d'onde Q de nécrose** (> 40 ms et > 1/3 du QRS).\n\n| Territoire | Dérivations |\n|---|---|\n| Antéroseptal | V1, V2, V3 |\n| Apical | V4 |\n| Latéral haut | D1, aVL |\n| Latéral bas | V5, V6 |\n| Inférieur | D2, D3, aVF |\n| Postérieur | V7, V8, V9 |\n| VD | V1, V2, V3R, V4R |","cas":[],"pieges":["Ne pas vérifier la bonne pose des électrodes (transition V1-V6) avant d'interpréter une pseudonécrose antérieure."],"src":"p. 372-377"},{"phase":"Diagnostic positif","title":"Reconnaître un SCA avec sus-décalage de ST","question":"Comment affirmes-tu un SCA ST+ sur l'ECG ?","answer":"- **Traquer d'abord le sus-décalage** (il désigne le territoire de la **coronaire occluse**), **puis** chercher le **miroir** (sous-décalage) — pas l'inverse.\n- **Sus-ST significatif** : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**.\n- S'il englobe la T : **onde de Pardee**.\n- **Deux T négatives dans un même territoire = pathologique**.","cas":[{"si":"Si sous-ST en V1-V3","alors":"Peut être le **miroir d'un sus-ST postérieur** → enregistrer **V7-V9**."}],"pieges":["Partir du sous-décalage pour chercher le sus-décalage."],"src":"p. 411-412"},{"phase":"Diagnostic positif","title":"Douleur thoracique sur bloc de branche gauche","question":"Le patient a un BBG complet et une douleur persistante. Comment interprètes-tu le ST et que fais-tu ?","answer":"- Dans le BBG, la **discordance appropriée** donne un **ST ascendant en V1-V2** (T positive et petit sus-ST dans les dérivations à QRS négatif) qui peut **mimer un SCA ST+**.\n- **Douleur thoracique persistante + BBG** : évoquer l'**infarctus antérieur** et obtenir une **évaluation cardiologique rapide sans attendre la troponine** :\n  - sémiologie de la douleur ;\n  - effet de la **TNT** ;\n  - **signes de choc** ;\n  - **ETT**.\n- **BBG complet + douleur thoracique aiguë** → **éliminer un SCA ST+** (échographie ± **coronarographie**).","cas":[{"si":"Si rythme électroentraîné (stimulation ventriculaire)","alors":"Même sus-ST approprié dans les dérivations à QRS négatif ; les anomalies ischémiques peuvent être **masquées** par le pacemaker."}],"pieges":["Attendre le résultat de la troponine devant une douleur persistante sur BBG."],"src":"p. 381, 411-413"},{"phase":"Diagnostic différentiel","title":"Les cinq causes de sus-décalage du ST","question":"Quelles sont les causes de sus-décalage du ST et les faux positifs à connaître ?","answer":"1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après un infarctus à séquelle marquée).\n3. **Repolarisation précoce** (dérivations inférolatérales).\n4. **Angor de Prinzmetal** (spasme coronarien).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\nDiagnostics différentiels : **BBG ou stimulation ventriculaire** (sus-ST approprié) ; **HVG marquée** (sus-ST en V1-V2).","cas":[{"si":"Si sujet jeune, surtout homme, avec point J sus-décalé de V1 à V4 et ST ascendant","alors":"**Repolarisation physiologique**."}],"pieges":[],"src":"p. 377, 412"},{"phase":"Diagnostic différentiel","title":"Péricardite aiguë ou SCA ?","question":"Comment distingues-tu une péricardite aiguë d'un SCA sur l'ECG ?","answer":"Péricardite : **4 phases** :\n1. brève : **microvoltage** (proportionnel à l'épanchement), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)** ;\n2. T plates partout, ST isoélectrique ;\n3. T **négatives** persistantes ;\n4. retour progressif à la normale.\n\nSCA ST+ : sus-ST désignant le **territoire de la coronaire occluse**, puis recherche du **miroir** (onde de Pardee avec miroir).","cas":[],"pieges":["Conclure à une péricardite devant un SCA ST+ dont le miroir manque."],"src":"p. 409"},{"phase":"Diagnostic positif","title":"SCA sans sus-décalage de ST","question":"L'ECG ne montre pas de sus-ST. Quelles anomalies peux-tu observer dans un SCA sans sus-décalage ?","answer":"- **Sous-décalage du ST** (lésion sous-endocardique).\n- **Inversion des T** (ischémie sous-épicardique).\n- **Pseudo-normalisation** de T auparavant négatives.\n- **Aplatissement** des T.\n- **ECG normal** possible.","cas":[{"si":"Si T négatives dans toutes les précordiales","alors":"Pathologique : éliminer d'abord une **ischémie**."},{"si":"Si patient porteur d'un pacemaker","alors":"Les anomalies peuvent être **masquées**."}],"pieges":["Éliminer un SCA sur un ECG normal."],"src":"p. 388, 412"},{"phase":"Hospitalisation & surveillance","title":"Suivre l'évolution ECG de l'infarctus","question":"En USIC, comment évolue l'ECG d'un SCA ST+ ?","answer":"- **Sus-ST** : régression **rapide si reperfusion** ; plusieurs jours sans reperfusion ; **persistance indéfinie** si **anévrisme** de la paroi infarcie.\n- **T négative « ischémique »** après **48 h**, parfois très prolongée.\n- **Ondes Q de nécrose** : en principe vers la **6e heure** (parfois plus tôt) ; critères **≥ 1/3 (ou 1/4) du QRS** et **> 30–40 ms** ; équivalent : **rabotage de l'onde R** (surtout V2-V3).\n- **Monitorage en soins intensifs cardiologiques** ; la **fibrose post-infarctus** est le substrat de la TV par réentrée.","cas":[],"pieges":["Considérer qu'une onde Q rend la reperfusion inutile : sa présence ne le signifie pas."],"src":"p. 398, 412, 414"},{"phase":"Diagnostic différentiel","title":"Hypertrophies et embolie pulmonaire","question":"Quels autres aspects ECG peuvent se discuter devant une douleur thoracique ou une dyspnée aiguë ?","answer":"- **HVG** : **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** ; forme sévère : T **négative** ± **sous-ST** latéraux (D1, aVL, V5, V6), disparition de la q septale ; QRS le plus souvent < 120 ms. Étiologies : **HTA**, puis **rétrécissement aortique**.\n- **Embolie pulmonaire** : hypertrophie VD aiguë → **S1Q3T3** (S en D1, Q en D3, T négative en D3), **déviation axiale droite**, FA possible.\n- **HVD** [B] : axe **> 110°** (90° en pratique), **R > 6 mm en V1**, **S > 7 mm en V5-V6**, souvent HAD, microvoltage (BPCO), BBD.\n- **HAD** : P > 2,5 mm en D2 ou > 2 mm en V1-V2 ; **HAG** : P > 110 ms (120 en pratique), composante négative > 40 ms en V1.","cas":[{"si":"Si HVG","alors":"Aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-ST** en V1-V2 pouvant mimer une séquelle d'infarctus ou un SCA."},{"si":"Si T négative asymétrique en V1 (parfois V2-V3) sur HVD sévère","alors":"Ne pas la confondre avec une ischémie."}],"pieges":[],"src":"p. 406-407"},{"phase":"Suivi","title":"Indications de l'ECG au long cours","question":"Après la sortie, dans quelles situations l'ECG est-il indiqué ?","answer":"- **Bilan initial et surveillance** des pathologies cardiaques, ou non cardiaques à risque cardiovasculaire (**diabète, AVC**).\n- **Obligatoire dans le bilan de l'HTA**.\n- **Bilan préopératoire** : patients **> 65 ans**, patients ou interventions à risque.\n- **Aptitude** professionnelle ou sportive ; **enquêtes familiales** de cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée, malaise, syncope.\n- **Monitorage** de certains exercices de **réadaptation cardiaque**.\n- **Holter 24 h** : évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus).","cas":[],"pieges":[],"src":"p. 414-415"}]}],"examens":[{"theme":"ECG & explorations électriques","title":"ECG 12 dérivations : réalisation, dérivations et territoires","rank":"A","content":"#### Indications\n- **Savoir réaliser un ECG 12 dérivations** (objectif de rang A).\n- Indications détaillées : voir la fiche « ECG conventionnel : indications ».\n\n#### Dérivations\n- **Frontales** (plan vertical) : **D1, D2, D3** (I, II, III) obtenues à partir des membres, complétées par les unipolaires **aVR, aVL, aVF**.\n- **Précordiales** (plan horizontal) : **V1 à V9**, complétées par **V3R et V4R** chez l'**enfant** ou en cas de **suspicion de SCA**.\n- Placement : électrodes précordiales **équidistantes**.\n\n#### Territoires explorés (localisation des infarctus)\n| Territoire | Dérivations |\n|---|---|\n| Antéroseptal (paroi antérieure du VG et septum) | V1, V2, V3 |\n| Apical | V4 |\n| Latéral haut | D1, aVL |\n| Latéral bas | V5, V6 |\n| Inférieur (diaphragmatique) | D2, D3, aVF |\n| Postérieur (face basale et inférieure du VG) | V7, V8, V9 |\n| Ventricule droit | V1, V2, V3R, V4R |\n\n#### Étalonnage\n- Vitesse **25 mm/s** : 1 mm = **40 ms** ; grand carreau (5 mm) = **200 ms**.\n- Amplitude : 1 mm = **0,1 mV**.\n\n#### Pièges\n- **V1 et V2 trop souvent placées trop haut et trop écartées** (confusion avec les foyers auscultatoires aortique et pulmonaire) → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.\n- **D1 négatif** : penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1).\n- La transition normale de V1 à V6 (R croît, S décroît) permet aussi de vérifier la **bonne pose des électrodes**.","src":"p. 371-375"},{"theme":"ECG & explorations électriques","title":"ECG 18 dérivations (V7-V9, V3R-V4R)","rank":"A","content":"#### Indications\n- **Devant toute douleur thoracique** : ECG 18 dérivations (**V7-V9, V3R-V4R**).\n- V3R et V4R : chez l'enfant ou en cas de suspicion de SCA.\n\n#### Ce qu'on recherche\n- **V7, V8, V9** : territoire **postérieur** (face basale et inférieure du VG).\n- **V1, V2, V3R, V4R** : **ventricule droit**.\n\n#### Pièges\n- Un **sous-décalage de ST en V1-V3** peut être le **miroir d'un sus-décalage postérieur (V7-V9)**.","src":"p. 371, 411, 414"},{"theme":"ECG & explorations électriques","title":"Dérivations de Lewis","rank":"A","content":"#### Indications\n- **Démasquer une activité atriale peu visible**.\n\n#### Technique\n- Électrode **rouge** (bras droit) sur la **fourchette sternale**.\n- Électrode **jaune** (bras gauche) au **5e espace intercostal droit**.\n- L'activité atriale est alors bien lue en **D1**.","src":"p. 371"},{"theme":"ECG & explorations électriques","title":"Lecture systématique et valeurs normales de l'ECG","rank":"A","content":"#### Valeurs normales (adulte)\n| Paramètre | Normale |\n|---|---|\n| Fréquence cardiaque | **60–100 bpm** (bradycardie < 60, tachycardie > 100) |\n| Durée de P | **< 120 ms** (théorique < 110 ms) |\n| Axe de P | **60°** (maximum en D2) |\n| Amplitude de P | **< 2,5 mm en D2** |\n| PR (début P → début QRS) | **120–200 ms** inclus |\n| Durée QRS | **70–110 ms** |\n| Axe QRS | **–30° à +90°** |\n| Onde Q physiologique | **< 1/3 du QRS et < 40 ms** |\n| QT corrigé | **< 450 ms à 60 bpm** (en pratique 470–480 ms) |\n\n#### Lecture systématique pour affirmer un ECG normal\n1. **Rythme** : sinusal (P + en D1, D2 ; un QRS après chaque P, une P avant chaque QRS), 60–100 bpm.\n2. **Conduction** : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe –30° à +90° (positif en D1 et D2).\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale V1 → V6, pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n#### Rythme sinusal\n- P **positive en D1 et en inférieur** (activation atriale de haut à droite vers bas à gauche).\n- Chaque P suivie d'un QRS **et** chaque QRS précédé d'une P. Des P sinusales régulières non conduites (BAV3) ne sont **plus** un rythme sinusal.\n\n#### Calcul de la fréquence\n- FC = 60 / RR (s) ; en pratique **FC = 300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…).\n\n#### Pièges\n- Bradycardie sinusale **physiologique de l'athlète** (tonus vagal) ; variation respiratoire chez le jeune ; valeurs de l'adulte : attention au **nouveau-né**.\n- Chez le jeune, surtout l'homme : **point J sus-décalé de V1 à V4 avec ST jonctionnel ascendant = repolarisation physiologique**.\n- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → inférieur).\n- Des **T négatives dans toutes les précordiales** sont pathologiques : éliminer d'abord une **ischémie**.","src":"p. 375-378"},{"theme":"ECG & explorations électriques","title":"Axe du QRS","rank":"A","content":"#### Mesure\n- Plan frontal, **double triaxe de Bailey** : dérivations graduées de **30° en 30°** dans le sens horaire, D1 à l'horizontale (0°).\n\n#### Méthode rapide (D1 et aVF)\n| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si **D2 positif** (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n#### Interprétation\n- **Axe normal : –30° à +90°** (de aVL à aVF ; valeurs théoriques –45° à +110°).\n- Cœur **vertical** (sujet filiforme) → axe proche de 90° ; cœur **horizontal** (obèse, cardiomégalie) → axe proche de 0°.\n- Axe anormal : **hémibloc** gauche ou anomalie morphologique marquée d'un ventricule.\n- Onde **isodiphasique** : composantes positive et négative d'égale importance.","src":"p. 375"},{"theme":"ECG & explorations électriques","title":"Mesure du QT et QT corrigé","rank":"A","content":"#### Mesure\n- Du **début de Q à la fin de T**, dans la dérivation où T est la plus ample et la plus longue (**souvent V2-V3**), par la **tangente** à l'onde T.\n- **Bazett** : **QTc = QT mesuré / √RR** (RR en secondes) → une seule norme, celle de 60 bpm (RR = 1 s).\n\n#### Interprétation\n- Normal : **QTc < 450 ms à 60 bpm** (en pratique 470–480 ms).\n- QT long → risque de **torsade de pointes**. Causes : **médicamenteuses** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **ioniques** (hypoK, hypoCa, hypoMg), **bradycardie extrême**, **congénitale** (syndrome du QT long).\n- Tout QT allongé → **vérifier les médicaments et le ionogramme**, corriger.\n\n#### Pièges\n- **Ne jamais inclure une onde U** dans le QT (onde U de l'hypokaliémie).","src":"p. 377, 403-404, 408"},{"theme":"ECG & explorations électriques","title":"ECG des blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","content":"#### Ce qu'on recherche\n- **Toujours décrire d'abord le rythme atrial** (TSV + bloc de branche n'est pas rare).\n- Ordre : rythme sinusal ? → **QRS > 120 ms** ? → **V1 positif (BBD) ou négatif (BBG)** → aspect inverse en V6.\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | globalement **positif**, **RsR'** | globalement **négatif**, **rS ou QS** |\n| V6 (et D1, aVL pour le BBG) | **qRs**, S traînante arrondie | **notch** (double pic), R souvent exclusive |\n\n- **Discordance appropriée** : T **discordante** du QRS (QRS négatif → T positive + petit sus-ST ; QRS positif → T négative + petit sous-ST).\n- **Blocs incomplets** (rang B) : mêmes anomalies avec QRS **110–120 ms**, faible intérêt sémiologique.\n- **Bloc fonctionnel** (rang B) : n'existe qu'à partir d'une fréquence donnée — en **tachycardie** ou en **bradycardie**.\n- **Hémiblocs** : QRS peu élargi (**> 110 ms**, > 120 ms si bloc de branche associé ou cardiopathie marquée) + **déviation axiale** :\n  - **HBAG** : axe au-delà de **–30°** (D2 négatif) ; **fréquent** ;\n  - **HBPG** : axe > **+90°** (D1 négatif, aspect **S1Q3**) en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral ; **rare**.\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n\n#### Interprétation / conséquences (rang B)\n- Hémibloc isolé ou bloc incomplet : risque de BAV infrahissien faible.\n- Bloc bifasciculaire (BBG complet, ou BBD + hémibloc) : risque de **BAV complet infrahissien intermittent**. **Syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie.**\n- BBG complet → **désynchronisation** du VG ; correction indiquée si insuffisance cardiaque.\n\n#### Pièges\n- Dans le BBG, le **ST ascendant en V1-V2 peut mimer un SCA ST+**.\n- **Douleur thoracique persistante + BBG** : évoquer l'**infarctus antérieur**, évaluation cardiologique rapide **sans attendre la troponine**.\n- **D1 négatif** : penser d'abord à une **inversion des électrodes** avant l'HBPG.","src":"p. 378-385"},{"theme":"ECG & explorations électriques","title":"ECG des blocs atrioventriculaires","rank":"A","content":"#### Ce qu'on recherche\n- Dans un BAV, les ondes P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| BAV2 Mobitz 1 (Luciani-Wenckebach) | PR **s'allonge progressivement** puis P bloquée | suprahissien |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| BAV2 Mobitz 2 | PR **constant** puis P bloquée inopinée | infrahissien |\n| BAV3 | **dissociation AV complète**, P dissociées (bien vues en V1) | échappement à QRS fins = bloc nodal (suprahissien) |\n\n- **BAV associés aux troubles du rythme** (rang B) : **FA + BAV complet** → rythme ventriculaire **lent et régulier** (échappement).\n\n#### Algorithme devant une bradycardie (FC des QRS < 50 bpm)\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale, ou activité atriale rapide (FA, flutter, TAF), avec **plus de P que de QRS** → **BAV**.\n3. P **trop lentes ou absentes** → **dysfonction sinusale**.\n\n#### Pièges\n- Une P « bloquée » **plus précoce** que les autres = **extrasystole atriale bloquée**.","src":"p. 385-389, 392"},{"theme":"ECG & explorations électriques","title":"ECG de la dysfonction sinusale","rank":"A","content":"#### Ce qu'on recherche\n- Cas simples : **asystole** (tracé plat) ; **pauses** par absence intermittente d'une onde P = **bloc sinoatrial du 2e degré** (rang B) : pause égale au **double de l'intervalle PP (RR)** normal, absence complète de P-QRS-T.\n- Dysfonction marquée : **échappement jonctionnel** ; P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2**.\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- **Maladie de l'oreillette** (rang B) : alternance FA / bradycardie sinusale, **pauses de régularisation** à l'arrêt de la FA.","src":"p. 369, 385-389, 392"},{"theme":"ECG & explorations électriques","title":"ECG des tachycardies supraventriculaires (sinusale, FA, flutter, TAF, jonctionnelle)","rank":"A","content":"#### Ce qu'on recherche\n- TSV : QRS **fins (< 120 ms)** le plus souvent ; larges si bloc de branche associé.\n- **Tachycardie sinusale** : P positives en **D1, D2, D3 et aVF** ; FC **variable progressivement** (vs TSV : **« marches d'escalier »**).\n- **Fibrillation atriale** : activation atriale anarchique, **100–200 bpm**, QRS **« irrégulièrement irréguliers »** ; ligne de base : **mailles amples** ou **fine trémulation**.\n- **Flutter** : activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation, ondes **F** en toit d'usine / dents de scie.\n  - **Typique antihoraire** (isthme cavotricuspide) : F **négatives en D2, D3, aVF, positives en V1, négatives en V6** ; typique horaire : polarités inversées.\n  - **Atypiques** : **120–320 bpm**, F variables.\n  - Ventricules : **150 bpm (2/1)**, 100 (3/1), 75… ; sinon **conduction variable**.\n- **Tachycardie atriale focale** : la manœuvre vagale ou l'adénosine **démasque l'activité atriale** sans arrêter la tachycardie.\n- **Tachycardie jonctionnelle (Bouveret)** : **très régulière ≈ 200 bpm (130–260)** ; réentrée intranodale (P invisible ou devinée dans le ST) ou rythme réciproque par voie accessoire (faisceau de Kent).\n- **Extrasystoles** : atriale (P précoce de morphologie différente + QRS fin), jonctionnelle (QRS fin ± P' rétrograde), ventriculaire (QRS large ± P' rétrograde) ; **bigéminisme**, **trigéminisme**, doublets, triplets, salves.\n\n#### Formes difficiles (rang B)\n- **FA + BAV complet** : rythme **lent et régulier**.\n- **FA + bloc de branche** : tachycardie **irrégulière à QRS larges**.\n\n#### Pièges\n- Au repos, une tachycardie marquée **sans cause d'hypermétabolisme** (fièvre, stress, douleur) **n'est pas sinusale**.\n- Parler de flutter « d'aspect » typique/atypique : diagnostic formel par la fréquence ou l'**exploration électrophysiologique**.\n- Extrasystoles **fréquentes ou polymorphes** → rechercher une cardiopathie.","src":"p. 389-398"},{"theme":"ECG & explorations électriques","title":"ECG des troubles du rythme ventriculaire (TV, FV, torsades)","rank":"A","content":"#### Ce qu'on recherche\n- **TV** : suspicion si **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n  - **Non soutenue** : 3 battements à 30 s ; **soutenue** : > 30 s ; monomorphe / polymorphe.\n  - **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P), complexes de **capture** (QRS fin précédé d'une P) et de **fusion**.\n  - **En faveur** : cardiopathie sous-jacente +++, **concordance** positive ou négative de V1 à V6, **axe extrême** (QRS positif en aVR), QRS larges d'aspect atypique de bloc de branche.\n- **FV** : tachycardie **irrégulière à QRS larges polymorphes** ; **urgence absolue** (choc électrique immédiat).\n- **Torsades de pointes** (rang B) : TV **polymorphe** s'arrêtant spontanément ou dégénérant en FV ; diagnostic sur le **QT long préalable** et le contexte.\n\n#### Algorithme devant une tachycardie (FC > 100 bpm)\n1. **Irrégulière** → **FA** (diagnostic différentiel : ESA).\n2. **Régulière à QRS larges** → ventriculaire jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → supraventriculaire.\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe**.\n\n#### Pièges\n- **Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.**\n- Dissociation **ventriculoatriale** de la TV (plus de QRS que de P) ≠ dissociation AV du BAV3.\n- Torsade possible **à QT normal**, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re.","src":"p. 398-405"},{"theme":"ECG & explorations électriques","title":"ECG des hypertrophies atriales et ventriculaires","rank":"A","content":"#### Ce qu'on recherche\n| | Critères |\n|---|---|\n| **HAD** (rang B) | P **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2** |\n| **HAG** (rang B) | P **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1** |\n| **HVG** | **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** |\n| **HVD** (rang B) | **axe > 110°** (90° en pratique) — signe le plus précoce ; **R > 6 mm en V1**, **S > 7 mm en V5-V6** |\n\n- **HVG sévère** : T **négative** ± **sous-ST** dans les latérales (D1, aVL, V5, V6) et **disparition de la q septale** ; déviation axiale gauche modeste ; QRS le plus souvent **< 120 ms**. Étiologies : **HTA** puis **rétrécissement aortique**.\n- **HVD** : association fréquente à une **HAD**, un **microvoltage** (BPCO), un **BBD** ; T négative asymétrique en V1 (parfois V2-V3) dans les formes sévères.\n- **Embolie pulmonaire** : **S1Q3T3** (S en D1, Q en D3, T négative en D3), déviation axiale droite, FA possible.\n\n#### Limites\n- HVD : intérêt modeste **à l'ère de l'échographie** ; utile chez le **BPCO** ou l'atteinte pulmonaire sévère.\n\n#### Pièges\n- HVG : aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-décalage du ST en V1-V2** mimant une séquelle d'infarctus ou un SCA.\n- HVD : T négative en V1-V3 à ne pas confondre avec une **ischémie** ; même aspect possible dans l'**HBPG** ou chez le sujet **longiligne**.","src":"p. 406-408"},{"theme":"ECG & explorations électriques","title":"ECG des dyskaliémies","rank":"A","content":"#### Ce qu'on recherche\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | **plate ou négative**, diffuse, **sous-ST** | **ample, pointue, symétrique** |\n| PR | – | **allongé** |\n| QRS | normal | **élargi** |\n| QT / U | **QT allongé**, **onde U** | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | **BAV**, TV, **dysfonction sinusale** (échappement jonctionnel) |\n\n#### Pièges\n- L'**onde U** est **exclue** de la mesure du QT.","src":"p. 408"},{"theme":"ECG & explorations électriques","title":"ECG de la péricardite aiguë","rank":"B","content":"#### Ce qu'on recherche : 4 phases\n1. Phase 1, brève : **microvoltage** (proportionnel à l'épanchement), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)**.\n2. T **plates** partout, ST isoélectrique.\n3. T **négatives** persistantes.\n4. Retour progressif à la normale.\n\n#### Pièges\n- **Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.**","src":"p. 409"},{"theme":"ECG & explorations électriques","title":"ECG de la préexcitation (Wolff-Parkinson-White)","rank":"B","content":"#### Ce qu'on recherche\n- **PR court < 120 ms**.\n- **Onde delta** : élargissement du QRS par empâtement de son pied.\n- **Troubles de repolarisation** dans le territoire de la voie.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- FA sur voie accessoire (**super-Wolff**) : tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** → risque de FV.\n\n#### Précautions\n- Bloquer le NAV (massage, adénosine) démasque une préexcitation minime — **jamais en cas de FA**.","src":"p. 410"},{"theme":"ECG & explorations électriques","title":"ECG de la maladie coronarienne et des SCA","rank":"A","content":"#### Ce qu'on recherche\n- **SCA ST+** : **traquer le sus-décalage** (territoire de la coronaire occluse), **puis** chercher le **miroir**.\n- Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes** ; englobant la T : **onde de Pardee**.\n- Évolution : régression rapide si reperfusion ; plusieurs jours sans ; persistance si **anévrisme** ; après **48 h**, **T négative « ischémique »**.\n- **Ondes Q de nécrose** : vers la **6e heure** ; **≥ 1/3 (ou 1/4) du QRS** et **> 30–40 ms** ; équivalent : **rabotage de l'onde R** (V2-V3).\n- **SCA sans sus-ST** : **sous-ST** (lésion sous-endocardique), **inversion des T** (ischémie sous-épicardique), **pseudo-normalisation**, **aplatissement** des T, ou **ECG normal**.\n\n#### Cinq étiologies de sus-décalage du ST\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire**.\n3. **Repolarisation précoce** (inférolatérale).\n4. **Angor de Prinzmetal**.\n5. **Péricardite** (diffus, concave, sans miroir).\n\n#### Pièges\n- Sous-ST en V1-V3 = possible **miroir d'un sus-ST postérieur** → **ECG 18 dérivations**.\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie ± coronarographie).\n- Faux sus-ST : **BBG ou stimulation ventriculaire** (dérivations à QRS négatif), **HVG marquée** (V1-V2).\n- Les ondes Q ne signifient pas qu'une reperfusion serait inutile.\n- Un **pacemaker** peut masquer les anomalies ischémiques.","src":"p. 411-412"},{"theme":"ECG & explorations électriques","title":"ECG du porteur de stimulateur cardiaque","rank":"B","content":"#### Ce qu'on recherche\n- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation (pacemaker ou sonde d'entraînement électrosystolique).\n- **Unipolaire** : spike bien visible ; **bipolaire** : spike peu visible.\n- Stimulation **atriale** (dysfonction sinusale) : une **onde P suit le spike**.\n- Stimulation **ventriculaire** (BAV, après un délai AV programmé) : **QRS large d'aspect BBG** après le spike.\n\n#### Pièges\n- Le pacemaker peut **masquer les anomalies ischémiques**.\n- Stimulation ventriculaire : sus-ST approprié dans les dérivations à QRS négatif (diagnostic différentiel du SCA ST+).","src":"p. 412-414"},{"theme":"ECG & explorations électriques","title":"ECG conventionnel : indications","rank":"A","content":"#### Indications\n- Systématique dans les **centres de santé** (bilans de santé).\n- **Aptitude** professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, professionnels).\n- **Bilan préopératoire** : patients **> 65 ans**, patients à risque, interventions à risque.\n- **Enquêtes familiales** de certaines cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée aiguë ou chronique, malaise, perte de connaissance, syncope.\n- **Obligatoire dans le bilan de l'HTA**.\n- Bilan initial et surveillance des pathologies cardiaques, ou non cardiaques à risque cardiovasculaire (diabète, AVC).\n- Urgence (objectif) : défaillance d'organe, douleur thoracique, palpitations, syncope, troubles hydroélectrolytiques (K, Ca).\n- **ECG 18 dérivations** devant une douleur thoracique.","src":"p. 414"},{"theme":"ECG & explorations électriques","title":"Monitorage ECG (cardioscope, télémétrie)","rank":"A","content":"#### Indications\n- Toute **urgence**, réanimation et **transfert médicalisé**.\n- Surveillance en **soins intensifs cardiologiques** (ex. syndrome coronarien).\n- **Syncope** avec cause rythmique suspectée ; **syncope + bloc bifasciculaire** → hospitalisation en cardiologie **avec télémétrie**.\n- **Peropératoire** et salle de réveil.\n- Certains exercices de **réadaptation cardiaque**.\n\n#### Ce qu'on recherche\n- La courbe de fréquence (scope, télémétrie, holter) distingue la **tachycardie sinusale** (variation progressive) d'une **TSV** (marches d'escalier).","src":"p. 383, 391, 414"},{"theme":"ECG & explorations électriques","title":"Holter ECG","rank":"B","content":"#### Indications\n- Malaises, syncopes, pertes de connaissance ou palpitations **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Holter de 24 h : efficacité des **bradycardisants**, surveillance et réglage des **pacemakers**, évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).\n\n#### Technique\n- ECG de longue durée, **2 à 12 dérivations** simultanées, **24 à 96 h maximum**, support numérique, **lecture différée**.\n\n#### Limites\n- Symptômes rares : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (voir fiche dédiée).","src":"p. 415"},{"theme":"ECG & explorations électriques","title":"Enregistrements ECG de très longue durée et objets connectés","rank":"B","content":"#### Indications\n- **Symptômes rares** : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (outils dédiés, montres connectées ECG).","src":"p. 415"},{"theme":"ECG & explorations électriques","title":"Holter implantable (moniteur ECG sous-cutané)","rank":"B","content":"#### Indications\n- **Syncopes inexpliquées**, **FA silencieuse**.\n\n#### Caractéristiques\n- Suivi **jusqu'à 3 ans**.","src":"p. 413-415"},{"theme":"ECG & explorations électriques","title":"Exploration électrophysiologique","rank":"B","content":"#### Indications (citées)\n- Diagnostic formel du type de **flutter** (typique/atypique), avant **ablation par radiofréquence**.","src":"p. 394"},{"theme":"Gestes & procédures","title":"Manœuvres vagales","rank":"B","content":"#### Indications\n- Créer un **BAV transitoire** : diagnostic différentiel des tachycardies, **réduction des tachycardies jonctionnelles**.\n- Démasquer les ondes **F** du flutter (utile en 1/1 ou 2/1) ; analyser une activité atriale difficile en FA.\n\n#### Technique\n- **Valsalva** (expiration forcée à glotte fermée).\n- **Compression carotidienne unilatérale**.\n- **Grand verre d'eau froide**.\n\n#### Résultats & interprétation\n- **Démasque l'activité atriale** → sinusale, flutter, TAF.\n- **Arrête la tachycardie** → jonctionnelle (réentrée dépendante du NAV).\n- **Aucun effet** → TV (indépendante du NAV) ; certitude si dissociation AV.\n\n#### Contre-indications\n- Compression carotidienne : **athérome important** ou **souffle carotidien**.\n- **Compression oculaire bilatérale : n'est plus recommandée** (décollement de rétine du myope).\n- Bloquer le NAV pour démasquer une préexcitation : **jamais en cas de FA**.","src":"p. 390, 405, 410"},{"theme":"Gestes & procédures","title":"Test à l'adénosine IV","rank":"B","content":"#### Indications\n- **Si échec des manœuvres vagales** : créer un BAV transitoire (diagnostic des tachycardies, réduction des tachycardies jonctionnelles, démasquer une préexcitation minime).\n\n#### Technique\n- Vagomimétique via les **récepteurs purinergiques**, en **flash IV**, effet d'une **dizaine de secondes**.\n\n#### Contre-indications\n- **Asthme** (bronchospasme intense transitoire possible **même chez le non asthmatique**).\n- **Hypotension**.\n- **FA préexcitée** (super-Wolff).","src":"p. 390, 410"},{"theme":"Gestes & procédures","title":"Choc électrique externe (cardioversion, défibrillation)","rank":"A","content":"#### Indications\n- Tachycardie **mal tolérée sur le plan hémodynamique** → **cardioversion électrique externe**.\n- **FV** : **choc électrique immédiat avant tout autre geste**, massage cardiaque en attendant.","src":"p. 402-405"},{"theme":"Gestes & procédures","title":"Implantation d'un stimulateur cardiaque (pacemaker)","rank":"B","content":"#### Indications\n- **Bradycardies symptomatiques** : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale.\n- **BAV infrahissiens** (BAV2 Mobitz 2, BAV3) : **même sans symptôme**.\n- Toute syncope sur bloc → réévaluer le pacemaker.\n\n#### Principe\n- Stimulation locale de quelques myocytes puis conduction de proche en proche.","src":"p. 384-385, 412-413"},{"theme":"Gestes & procédures","title":"Défibrillateur implantable et resynchronisation cardiaque","rank":"B","content":"#### Indications\n- **Défibrillateur** : **TV / FV** (champ électrique réinitialisant tous les myocytes) ; fait toujours pacemaker, **sauf sous-cutané**.\n- **Resynchronisation** : **BBG désynchronisant le VG avec insuffisance cardiaque** (stimulateur, donc toujours pacemaker).\n- Fonctions associables : **défibrillateur de resynchronisation**.","src":"p. 383, 413"},{"theme":"Biologie","title":"Ionogramme sanguin (kaliémie, calcémie, magnésémie)","rank":"A","content":"#### Indications\n- **Tout QT allongé** → vérifier les **médicaments et le ionogramme**.\n- Urgence ECG en cas de **troubles hydroélectrolytiques (K, Ca)**.\n\n#### Interprétation\n- Causes ioniques de QT long / torsade : **hypokaliémie**, **hypocalcémie**, **hypomagnésémie** → **corriger les ions**.\n- Traduction ECG des dyskaliémies : voir fiche « ECG des dyskaliémies ».","src":"p. 403-404, 408"},{"theme":"Biologie","title":"Troponine","rank":"A","content":"#### Pièges\n- **Douleur thoracique persistante + BBG** : évoquer l'infarctus antérieur et obtenir une évaluation cardiologique rapide **sans attendre la troponine** (sémiologie de la douleur, effet de la TNT, signes de choc, ETT).","src":"p. 381"},{"theme":"Imagerie","title":"Échocardiographie transthoracique","rank":"A","content":"#### Indications\n- **BBG + douleur thoracique** : ETT dans l'évaluation cardiologique rapide ; éliminer un SCA ST+ (échographie ± coronarographie).\n\n#### Limites\n- L'ECG de l'HVD a un **intérêt modeste à l'ère de l'échographie**.","src":"p. 381, 407, 411"},{"theme":"Gestes & procédures","title":"Coronarographie","rank":"A","content":"#### Indications\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie **± coronarographie**).","src":"p. 411"}]}});
